            >
              <Share2 className="w-4 h-4" />
              Share
            </button>
            {showShareTooltip && (
              <span className="absolute -top-9 left-1/2 -translate-x-1/2 text-[11px] bg-neutral-900 dark:bg-neutral-100 text-white dark:text-neutral-900 px-2.5 py-1 rounded-lg whitespace-nowrap">
                Link copied!
              </span>
            )}
          </div>
        </div>

        <div className="mt-16 pt-8 border-t border-neutral-200 dark:border-neutral-800">
          <Link to="/uncut" className="text-sm text-pink-500 dark:text-pink-400 hover:underline font-semibold">
            ← Back to Cohort Uncut
          </Link>
          <span className="mx-3 text-neutral-300 dark:text-neutral-700">·</span>
          <Link to="/" className="text-sm text-neutral-400 dark:text-neutral-600 hover:text-neutral-600 dark:hover:text-neutral-400 transition-colors">
            Homepage
          </Link>
        </div>
      </main>

      <ShareModal
        isOpen={isShareModalOpen}
        onClose={() => setIsShareModalOpen(false)}
        post={{
          id: 'introvert-guide',
          title: 'Why We Seek the Quiet: The Reluctant Introvert’s Guide to Campus Life',
          content: 'College is loud. Here is an honest perspective on finding peace, recharge spots, and meaningful connections in a world that never stops talking.',
          text: 'College is loud. Here is an honest perspective on finding peace, recharge spots, and meaningful connections in a world that never stops talking.',
          author: { name: 'Neha Deshmukh' },
          authorName: 'Neha Deshmukh',
          image: 'https://images.unsplash.com/photo-1499750310107-5fef28a66643?q=80&w=800&auto=format&fit=crop'
        }}
        shareUrl="https://cohortnow.online/uncut/introvert-guide"
        title="Why We Seek the Quiet | Cohort Uncut"
      />
    </div>
  );
}

