const isNewerVersion = (currentVer, manifestVer) => {
      if (!currentVer || currentVer === '') return true;
      if (!manifestVer) return false;
      const currentParts = currentVer.split('.').map(Number);
      const manifestParts = manifestVer.split('.').map(Number);
      const maxLength = Math.max(currentParts.length, manifestParts.length);
      for (let i = 0; i < maxLength; i++) {
        const currentPart = currentParts[i] || 0;
        const manifestPart = manifestParts[i] || 0;
        if (manifestPart > currentPart) return true;
        if (currentPart > manifestPart) return false;
      }
      return false;
    };

function AnalyticsTracker() {
  const location = useLocation();

  useEffect(() => {
    // Only send analytics page views in production to prevent local development pollution
    if (import.meta.env.PROD && typeof window.gtag === 'function') {
      window.gtag('config', 'G-P06KWK4X10', {
        page_path: location.pathname + location.search,
      });
    }
  }, [location]);

  return null;
}

const toggleSelectUser = (targetUser) => {
    if (sentMap[targetUser.uid]) return;
    if (selectedUsers.some((u) => u.uid === targetUser.uid)) {
      setSelectedUsers(selectedUsers.filter((u) => u.uid !== targetUser.uid));
    } else {
      setSelectedUsers([...selectedUsers, targetUser]);
    }
  };

const handleMarkAllRead = async () => {
    setList(prev => prev.map(notif => ({ ...notif, read: true })));
    showSuccess('All notifications marked as read.');

    const batch = writeBatch(db);
    list.forEach(n => {
      if (n.docId && !n.read) {
        const docRef = doc(db, 'notifications', n.docId);
        batch.update(docRef, { read: true });
      }
    });
    try {
      await batch.commit();
    } catch (e) {
      console.error('Failed to update all statuses in Firestore:', e);
    }
  };

export default async function handler(req, res) {
  try {
    const { storyId, id, title, desc, img } = req.query || {};

    let targetStoryId = storyId || id;
    if (!targetStoryId && req.url) {
      const match = req.url.match(/\/uncut\/([^/?#]+)/);
      if (match) targetStoryId = match[1];
    }

    const STORIES_MAP = {
      'seven-days-changed-us': {
        title: 'Seven Days that Changed us | Cohort Uncut',
        desc: 'Some things teach you more about yourself than anything else ever could. For us, building Cohort has been one of those things. Written by Team Cohort.',
        image: 'https://cohortnow.online/og-image.png'
      },
      'college-love': {
        title: 'College, Love Stories and the Dilemma | Cohort Uncut',
        desc: 'Why falling in love in college feels like choosing between who you are, who you want to become, and who you want beside you. Written by Sanya Sahani.',
        image: 'https://cohortnow.online/og-image.png'
      },
      '3am-coffee-club': {
        title: 'The 3 AM Coffee Club: A Love Letter to Late-Night Study Rooms | Cohort Uncut',
        desc: 'You know the feeling. It\'s 2:47 AM, the campus is dead silent, but Room 402 in the library is humming with life. A soft buzz of laptops, the rhythmic clicking of keyboards, and the quiet hiss of the coffee machine...',
        image: 'https://cohortnow.online/og-image.png'
      },
      'introvert-guide': {
        title: 'Why We Seek the Quiet: The Reluctant Introvert\'s Guide to Campus Life | Cohort Uncut',
        desc: 'From orientation week icebreakers to crowded hostel mess halls, college is an extrovert\'s playground. But for the 40% of us who recharge in silence, it can feel like a marathon with no finish line...',
        image: 'https://cohortnow.online/og-image.png'
      },
      'unwritten-rules': {
        title: 'The Unwritten Hallway Rules We All Silently Agree To | Cohort Uncut',
        desc: 'Every university has a student handbook, but the real rules are never written down. They are the unspoken social contracts we learn by trial and error...',
        image: 'https://cohortnow.online/og-image.png'
      }
    };

    const storyData = STORIES_MAP[targetStoryId] || {};

    const rawTitle = title ? decodeURIComponent(title) : (storyData.title || 'Cohort Uncut Story');
    const rawDesc = desc ? decodeURIComponent(desc) : (storyData.desc || 'Real campus stories, written by peers on Cohort Uncut.');
    const rawImage = img ? decodeURIComponent(img) : (storyData.image || 'https://cohortnow.online/og-image.png');

    const escapeHtml = (str) =>
      (str || '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');

    const safeTitle = escapeHtml(rawTitle);
    const safeDesc = escapeHtml(rawDesc);
    const safeImage = escapeHtml(rawImage);
    const canonicalUrl = `https://cohortnow.online/uncut/${targetStoryId || ''}`;

    const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>${safeTitle}</title>
  <meta name="description" content="${safeDesc}">
  <meta property="og:type" content="article">
  <meta property="og:url" content="${canonicalUrl}">
  <meta property="og:title" content="${safeTitle}">
  <meta property="og:description" content="${safeDesc}">
  <meta property="og:image" content="${safeImage}">
  <meta property="og:image:secure_url" content="${safeImage}">
  <meta property="og:image:width" content="1200">
  <meta property="og:image:height" content="630">
  <meta property="og:site_name" content="Cohort Uncut">
  <meta name="twitter:card" content="summary_large_image">
  <meta name="twitter:url" content="${canonicalUrl}">
  <meta name="twitter:title" content="${safeTitle}">
  <meta name="twitter:description" content="${safeDesc}">
  <meta name="twitter:image" content="${safeImage}">
</head>
<body>
  <p>Cohort Uncut Story Preview: ${safeTitle}</p>
</body>
</html>`;

    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    res.setHeader('Cache-Control', 's-maxage=3600, stale-while-revalidate=86400');
    return res.status(200).send(html);
  } catch (globalErr) {
    console.error('API Uncut OG Error:', globalErr);
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    return res.status(200).send(`<!DOCTYPE html><html><head><title>Cohort Uncut</title></head><body>Cohort Uncut</body></html>`);
  }
}

const handleChangePasswordSubmit = async (e) => {
    e.preventDefault();

    if (!oldPassword) {
      showError('Please enter your current (old) password.');
      return;
    }

    if (!newPassword || newPassword.length < 6) {
      showError('New password must be at least 6 characters long.');
      return;
    }

    if (newPassword !== confirmPassword) {
      showError('New password and confirm password do not match.');
      return;
    }

    setIsChangingPass(true);
    try {
      if (user?.email) {
        try {
          await login(user.email, oldPassword);
        } catch (authErr) {
          showError('Incorrect old password. If you forgot your password, click "Forgot old password?"');
          setIsChangingPass(false);
          return;
        }
      }

      await setPasswordForUser(newPassword);
      showSuccess('Password updated successfully! You can now log in using your new password.');
      setOldPassword('');
      setNewPassword('');
      setConfirmPassword('');
      setIsPasswordFormOpen(false);
    } catch (err) {
      console.error(err);
      showError(err.message || 'Failed to update password. Please try again.');
    } finally {
      setIsChangingPass(false);
    }
  };

