                          <div className="flex items-center gap-md min-w-0">
                            {comm.avatar ? (
                              <img
                                src={comm.avatar}
                                alt={comm.name}
                                className="w-12 h-12 rounded-2xl object-cover flex-shrink-0 shadow-sm"
