const handleRejectRequest = async (requestObj) => {
    if (!selectedRoom?.id || !requestObj?.uid) return;
    try {
      await updateDoc(doc(db, 'userCommunities', selectedRoom.id), {
        joinRequests: arrayRemove(requestObj)
      });
      setSelectedRoom(prev => ({
        ...prev,
        joinRequests: (prev.joinRequests || []).filter(r => (typeof r === 'string' ? r !== requestObj.uid : r.uid !== requestObj.uid))
      }));
      showSuccess('Join request rejected.');
    } catch (e) {
      console.error(e);
    }
  };

const handleMouseMove = (e) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = (e.clientX - rect.left - rect.width / 2) / rect.width;
    const y = (e.clientY - rect.top - rect.height / 2) / rect.height;
    setMousePos({ x, y });
  };

const clearAllHistory = () => {
    setSearchHistory([]);
    try {
      localStorage.removeItem('cohort_search_history');
    } catch (e) {}
  };

const fetchContacts = async () => {
      setLoadingUsers(true);
      try {
        const usersSnap = await getDocs(collection(db, 'users'));
        const list = [];
        usersSnap.forEach((d) => {
          const uid = d.id;
          if (
            user?.uid &&
            uid !== user.uid &&
            uid !== 'cohort_official' &&
            d.data()?.username !== 'cohort'
          ) {
            const data = d.data();
            list.push({
              uid,
              name: data.name || data.username || 'Campus Student',
              username: data.username || '',
              avatar:
                data.avatar ||
                `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(uid)}`,
              college: data.college || 'KIET'
            });
          }
        });

        setRecentUsers(list);
      } catch (err) {
        console.error('Error fetching share contacts:', err);
      } finally {
        setLoadingUsers(false);
      }
    };

const handleReshareWithThoughts = async () => {
    if (!reshareTargetPost || !thoughtCaption.trim()) return;
    const targetColl = reshareTargetPost.expiresAtMs ? 'confessions' : 'anonymousPosts';
    const rootOriginalPostId = reshareTargetPost.originalPostId || reshareTargetPost.id;
    const origAuthorName = reshareTargetPost.originalPost?.anonymousName || reshareTargetPost.anonymousName || 'Anonymous Fox';
    const origText = reshareTargetPost.originalPost?.text || reshareTargetPost.text;
    const myUid = user?.uid || 'anonymous_guest';
    const randomIndex = Math.floor(Math.random() * ANONYMOUS_NAMES.length);
    const chosenName = ANONYMOUS_NAMES[randomIndex];

    setIsSubmittingReshare(true);
    try {
      await addDoc(collection(db, targetColl), {
        authorUid: myUid,
        anonymousName: chosenName,
        isReshare: true,
        originalPostId: rootOriginalPostId,
        originalPost: {
          id: rootOriginalPostId,
          anonymousName: origAuthorName,
          text: origText,
          createdAt: reshareTargetPost.createdAt
        },
        resharedBy: {
          uid: myUid,
          name: chosenName
        },
        thought: thoughtCaption.trim(),
        text: thoughtCaption.trim(),
        likesCount: 0,
        likedUsers: [],
        commentsCount: 0,
        repostsCount: 0,
        resharedUsers: [],
        createdAt: new Date()
      });

      await updateDoc(doc(db, targetColl, rootOriginalPostId), {
        repostsCount: increment(1),
        resharedUsers: arrayUnion(myUid)
