                          onClick={() => { setShowHeaderMenu(false); handleOpenManage(); }}
                          className="w-full px-lg py-md text-left text-neutral-700 dark:text-neutral-200 hover:bg-neutral-50 dark:hover:bg-neutral-700/60 flex items-center gap-md"
