const fetchAndCalculateMatches = async () => {
    try {
      const usersSnap = await getDocs(collection(db, 'users'));
      const list = [];
      const currentSwiped = user?.makeAFriendProfile?.swiped || {};
      const currentAnswers = user?.makeAFriendProfile?.answers || answers;

      usersSnap.forEach((d) => {
        const data = d.data();
        const uid = d.id;

        // Skip current user, official Cohort account, already swiped profiles, and users who haven't completed the quiz
        if (
          uid === user.uid ||
          uid === 'cohort_official' ||
          (data.username || '').toLowerCase() === 'cohort' ||
          data.isOfficial === true ||
          currentSwiped[uid] ||
          !data.makeAFriendProfile?.completed
        ) {
          return;
        }

        // Resolve gender (use Firestore gender or deterministic fallback if undefined/prefer not to say)
        const resolvedGender = data.gender && data.gender !== 'Prefer not to say'
          ? data.gender
          : (uid.charCodeAt(0) % 2 === 0 ? 'Male' : 'Female');

        // Apply gender filter
        const matchesGender = () => {
          if (genderFilter === 'All') return true;
          return resolvedGender.toLowerCase() === genderFilter.toLowerCase();
        };

        if (!matchesGender()) {
          return;
        }

        // Apply campus filter
        const matchesCampus = () => {
          const myCollege = (user?.college || 'KIET').toLowerCase().trim();
          const theirCollege = (data.college || 'KIET').toLowerCase().trim();
          if (campusFilter === 'On Campus' || campusFilter === 'Same College') {
            return myCollege === theirCollege;
          } else if (campusFilter === 'Outside Campus') {
            return myCollege !== theirCollege;
          }
          return true; // 'All' or 'All Campuses'
        };

        if (!matchesCampus()) {
          return;
        }

        // Retrieve the user's completed makeAFriendProfile
        const targetProfile = data.makeAFriendProfile;
        const matchPct = calculateCompatibility(currentAnswers, targetProfile.answers, user.uid, uid, user.college, data.college);

        list.push({
          uid,
          id: uid,
          name: data.name || 'Anonymous Student',
          college: data.college || 'KIET',
          avatar: data.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(uid)}`,
          gender: resolvedGender,
          answers: targetProfile.answers,
          matchPercentage: matchPct,
          sharedInterests: getSharedInterests(currentAnswers, targetProfile.answers)
        });
      });

      // Sort by match percentage desc
      list.sort((a, b) => b.matchPercentage - a.matchPercentage);
      setProfiles(list);
      setCurrentProfileIndex(0);
    } catch (err) {
      console.error('Error fetching match profiles:', err);
      showError('Failed to fetch matched profiles.');
    }
  };

async function handler(req, res) {
  try {
    const { storyId, id, title, desc, img } = req.query || {};

    let targetStoryId = storyId || id;
    if (!targetStoryId && req.url) {
      const match = req.url.match(/\/uncut\/([^/?#]+)/);
      if (match) targetStoryId = match[1];
    }

    const STORIES_MAP = {
      'seven-days-changed-us': {
        title: 'Seven Days that Changed us | Cohort Uncut',
        desc: 'Some things teach you more about yourself than anything else ever could. For us, building Cohort has been one of those things. Written by Team Cohort.',
        image: 'https://cohortnow.online/og-image.png'
      },
      'college-love': {
        title: 'College, Love Stories and the Dilemma | Cohort Uncut',
        desc: 'Why falling in love in college feels like choosing between who you are, who you want to become, and who you want beside you. Written by Sanya Sahani.',
        image: 'https://cohortnow.online/og-image.png'
      },
      '3am-coffee-club': {
        title: 'The 3 AM Coffee Club: A Love Letter to Late-Night Study Rooms | Cohort Uncut',
        desc: 'You know the feeling. It\'s 2:47 AM, the campus is dead silent, but Room 402 in the library is humming with life. A soft buzz of laptops, the rhythmic clicking of keyboards, and the quiet hiss of the coffee machine...',
        image: 'https://cohortnow.online/og-image.png'
      },
      'introvert-guide': {
        title: 'Why We Seek the Quiet: The Reluctant Introvert\'s Guide to Campus Life | Cohort Uncut',
        desc: 'From orientation week icebreakers to crowded hostel mess halls, college is an extrovert\'s playground. But for the 40% of us who recharge in silence, it can feel like a marathon with no finish line...',
        image: 'https://cohortnow.online/og-image.png'
      },
      'unwritten-rules': {
        title: 'The Unwritten Hallway Rules We All Silently Agree To | Cohort Uncut',
        desc: 'Every university has a student handbook, but the real rules are never written down. They are the unspoken social contracts we learn by trial and error...',
        image: 'https://cohortnow.online/og-image.png'
      }
    };

    const storyData = STORIES_MAP[targetStoryId] || {};

    const rawTitle = title ? decodeURIComponent(title) : (storyData.title || 'Cohort Uncut Story');
    const rawDesc = desc ? decodeURIComponent(desc) : (storyData.desc || 'Real campus stories, written by peers on Cohort Uncut.');
    const rawImage = img ? decodeURIComponent(img) : (storyData.image || 'https://cohortnow.online/og-image.png');

    const escapeHtml = (str) =>
      (str || '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');

    const safeTitle = escapeHtml(rawTitle);
    const safeDesc = escapeHtml(rawDesc);
    const safeImage = escapeHtml(rawImage);
    const canonicalUrl = `https://cohortnow.online/uncut/${targetStoryId || ''}`;

    const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>${safeTitle}</title>
  <meta name="description" content="${safeDesc}">
  <meta property="og:type" content="article">
  <meta property="og:url" content="${canonicalUrl}">
  <meta property="og:title" content="${safeTitle}">
  <meta property="og:description" content="${safeDesc}">
  <meta property="og:image" content="${safeImage}">
  <meta property="og:image:secure_url" content="${safeImage}">
  <meta property="og:image:width" content="1200">
  <meta property="og:image:height" content="630">
  <meta property="og:site_name" content="Cohort Uncut">
  <meta name="twitter:card" content="summary_large_image">
  <meta name="twitter:url" content="${canonicalUrl}">
  <meta name="twitter:title" content="${safeTitle}">
  <meta name="twitter:description" content="${safeDesc}">
  <meta name="twitter:image" content="${safeImage}">
</head>
<body>
  <p>Cohort Uncut Story Preview: ${safeTitle}</p>
</body>
</html>`;

    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    res.setHeader('Cache-Control', 's-maxage=3600, stale-while-revalidate=86400');
    return res.status(200).send(html);
  } catch (globalErr) {
    console.error('API Uncut OG Error:', globalErr);
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    return res.status(200).send(`<!DOCTYPE html><html><head><title>Cohort Uncut</title></head><body>Cohort Uncut</body></html>`);
  }
}

export function CollegeSelector({ value, onChange, className = '' }) {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const containerRef = useRef(null);

  // Close dropdown on outside click
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (containerRef.current && !containerRef.current.contains(e.target)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Sync search input display with selected value when dropdown is closed
  useEffect(() => {
    if (!isOpen) {
      setSearchTerm(value || '');
    }
  }, [isOpen, value]);

  // Filter colleges based on user search term
  const filteredColleges = useMemo(() => {
    if (!searchTerm.trim()) return INDIAN_COLLEGES;
    const term = searchTerm.toLowerCase().trim();
    return INDIAN_COLLEGES.filter(c => c.toLowerCase().includes(term));
  }, [searchTerm]);

  const handleSelect = (collegeName) => {
    onChange(collegeName);
    setSearchTerm(collegeName);
    setIsOpen(false);
  };

  const handleInputChange = (e) => {
    const val = e.target.value;
    setSearchTerm(val);
    onChange(val);
    if (!isOpen) setIsOpen(true);
  };

  return (
    <div className={`space-y-1.5 relative ${className}`} ref={containerRef}>
      <label className="block font-semibold text-sm text-neutral-700 dark:text-neutral-300">
        College / University
      </label>

      {/* Clean Input Field */}
      <div className="relative">
        <GraduationCap className="w-4 h-4 text-neutral-400 dark:text-neutral-500 absolute left-3.5 top-1/2 -translate-y-1/2" />

        <input
          type="text"
          value={searchTerm}
          onFocus={() => setIsOpen(true)}
          onChange={handleInputChange}
          placeholder="Select or search college..."
          className="w-full pl-10 pr-9 py-2.5 rounded-xl bg-neutral-50 dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 text-sm text-neutral-900 dark:text-neutral-100 placeholder:text-neutral-400 focus:outline-none focus:border-purple-500 focus:ring-1 focus:ring-purple-500 transition-all font-medium"
        />

        {searchTerm ? (
          <button
            type="button"
            onClick={() => {
              setSearchTerm('');
              onChange('');
              setIsOpen(true);
            }}
            className="absolute right-3 top-1/2 -translate-y-1/2 text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-200 p-0.5"
          >
            <X className="w-3.5 h-3.5" />
          </button>
        ) : (
          <ChevronDown
            className={`w-4 h-4 text-neutral-400 dark:text-neutral-500 absolute right-3 top-1/2 -translate-y-1/2 transition-transform duration-200 pointer-events-none ${
              isOpen ? 'rotate-180 text-purple-500' : ''
            }`}
          />
        )}
      </div>

      {/* Floating Dropdown List */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: -4, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -4, scale: 0.98 }}
            transition={{ duration: 0.15 }}
            className="absolute left-0 right-0 top-full mt-1 z-50 max-h-60 overflow-y-auto rounded-xl bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 shadow-xl shadow-black/10 dark:shadow-black/40 divide-y divide-neutral-100 dark:divide-neutral-800/60"
          >
            {filteredColleges.length > 0 ? (
              filteredColleges.map((college, idx) => {
                const isSelected = value?.toLowerCase().trim() === college.toLowerCase().trim();
                return (
                  <button
                    key={idx}
                    type="button"
                    onClick={() => handleSelect(college)}
                    className={`w-full flex items-center justify-between px-3.5 py-2.5 text-left text-xs sm:text-sm transition-colors cursor-pointer ${
                      isSelected
                        ? 'bg-purple-500/10 text-purple-600 dark:text-purple-400 font-bold'
                        : 'text-neutral-700 dark:text-neutral-300 hover:bg-neutral-50 dark:hover:bg-neutral-800/60 font-medium'
                    }`}
                  >
                    <span className="truncate pr-2">{college}</span>
                    {isSelected && (
                      <Check className="w-4 h-4 text-purple-600 dark:text-purple-400 flex-shrink-0" />
                    )}
                  </button>
                );
              })
            ) : (
              <div className="px-3.5 py-3 text-xs text-neutral-400 dark:text-neutral-500 text-center">
                Press enter to use "{searchTerm}"
              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

export const UsernameModal = () => {
  const { user, updateUser, isAuthenticated, setPasswordForUser } = useAuth();
  const { showSuccess } = useNotification();

  const [usernameInput, setUsernameInput] = useState('');
  const [nameInput, setNameInput] = useState(user?.name || '');
  const [passwordInput, setPasswordInput] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [checking, setChecking] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');

  // Extended Onboarding States
  const [avatarFile, setAvatarFile] = useState(null);
  const [avatarPreviewUrl, setAvatarPreviewUrl] = useState(null);
  const [cropperSrc, setCropperSrc] = useState(null);

  const [collegeInput, setCollegeInput] = useState(user?.college || '');

  const [gender, setGender] = useState('Prefer not to say');
  const [year, setYear] = useState('1st Year');
  const [dob, setDob] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef(null);

  // Sync name input when user profile is loaded
  useEffect(() => {
    if (user) {
      setNameInput(user.name || '');
      setCollegeInput(user.college || '');
    }
  }, [user]);

  // Keep modal open if authenticated and either username or onboarding incomplete
  if (!isAuthenticated || !user || (user.username && user.onboarded)) {
    return null;
  }

  const handleCreateUsername = async (e) => {
    e.preventDefault();
    setErrorMsg('');

    const cleanName = nameInput.trim();
    if (!cleanName || cleanName.length < 2) {
      setErrorMsg('Display Name must be at least 2 characters long.');
      return;
    }

    const cleanUsername = usernameInput.trim().toLowerCase().replace(/[^a-z0-9_.]/g, '');

    if (!cleanUsername || cleanUsername.length < 3) {
      setErrorMsg('Username must be at least 3 characters long (letters, numbers, underscores).');
      return;
    }

    if (!user.hasPassword) {
      if (!passwordInput || passwordInput.length < 6) {
        setErrorMsg('Password must be at least 6 characters long.');
        return;
      }
    }

    if (!collegeInput.trim()) {
      setErrorMsg('Please select or enter your college / university name.');
      return;
    }

    if (!dob) {
      setErrorMsg('Please select your Date of Birth.');
      return;
    }

    setChecking(true);
    try {
      // Query Firestore users collection for existing username
      const q = query(collection(db, 'users'), where('username', '==', cleanUsername));
      const querySnapshot = await getDocs(q);

      let isTaken = false;
      querySnapshot.forEach((docSnap) => {
        if (docSnap.id !== user.uid) {
          isTaken = true;
        }
      });

      if (isTaken) {
        setErrorMsg(`Username "@${cleanUsername}" is already taken. Please try another.`);
        setChecking(false);
        return;
      }

      // 1. Set chosen password in Firebase Auth first if user does not have a password
      if (!user.hasPassword) {
        await setPasswordForUser(passwordInput);
      }

      // 2. Upload profile picture if selected
      let uploadedAvatarUrl = user.avatar || null;
      if (avatarFile) {
        setIsUploading(true);
        uploadedAvatarUrl = await uploadImageToCloudinary(avatarFile);
      }

      // 3. Update Firestore user document
      const userRef = doc(db, 'users', user.uid);
      const isCollege = isCollegeEmail(user.email);
      const isMatching = isCollege && verifyEmailMatchesCollege(user.email, collegeInput);

      const onboardingData = {
        name: cleanName,
        username: cleanUsername,
        avatar: uploadedAvatarUrl || avatarPreviewUrl || user.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${cleanUsername}`,
        college: collegeInput,
        gender: gender,
        year: year,
        dob: dob,
        onboarded: true,
        kycVerified: isMatching,
        kycEmail: isMatching ? user.email : null,
        kycGender: isMatching ? predictGenderFromName(user.email) : null
      };

      await updateDoc(userRef, onboardingData);
      await updateUser(onboardingData);
      showSuccess(`Welcome! Your unique username is @${cleanUsername}`);
    } catch (err) {
      console.error('Error during onboarding setup:', err);
      setErrorMsg(err.message || 'Failed to complete onboarding. Please try again.');
    } finally {
      setChecking(false);
      setIsUploading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto bg-black/70 backdrop-blur-md flex justify-center items-start sm:items-center p-md sm:p-lg py-xl">
      <div className="bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-3xl p-lg sm:p-xl max-w-md w-full shadow-2xl my-auto space-y-md sm:space-y-lg animate-in fade-in zoom-in duration-200">
        <div className="text-center space-y-sm">
          <div className="w-12 h-12 bg-primary-50 dark:bg-primary-950/50 rounded-xl flex items-center justify-center mx-auto text-primary-500 shadow-inner">
            <Sparkles className="w-6 h-6 animate-pulse" />
          </div>
          <h2 className="text-xl sm:text-2xl font-heading font-bold text-neutral-900 dark:text-white">
            Complete Your Profile Setup
          </h2>
          <p className="text-xs text-neutral-500 dark:text-neutral-400 max-w-sm mx-auto leading-relaxed">
            Welcome to Cohort! Let's set up your campus profile so classmates can connect with you directly.
          </p>
        </div>

        <form onSubmit={handleCreateUsername} className="space-y-md">
          {/* Avatar Upload */}
          <div className="flex flex-col items-center space-y-sm pb-xs">
            <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
              <img
                src={avatarPreviewUrl || user?.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(user?.email || 'user')}`}
                alt="Avatar"
                className="w-20 h-20 rounded-full border-4 border-primary-500 object-cover shadow-md group-hover:opacity-80 transition-opacity"
              />
              <div className="absolute inset-0 flex items-center justify-center bg-black/40 rounded-full opacity-0 group-hover:opacity-100 transition-opacity">
                <Camera className="w-5 h-5 text-white" />
              </div>
              <input
                type="file"
                ref={fileInputRef}
                onChange={(e) => {
                  const file = e.target.files[0];
                  if (file) {
                    setCropperSrc(URL.createObjectURL(file));
                  }
                }}
                accept="image/*"
                className="hidden"
              />
            </div>
            <div className="flex gap-sm">
