                  {/* Actions Footer */}
                  <div className="flex items-center gap-xl text-xs text-neutral-500 dark:text-neutral-400 border-t border-neutral-100 dark:border-neutral-800 pt-md">
                    <span className="flex items-center gap-md"><Heart className="w-4 h-4 text-rose-500 fill-rose-500" /> {post.likes}</span>
                    <span className="flex items-center gap-md"><MessageCircle className="w-4 h-4" /> {post.comments}</span>
                    <span className="flex items-center gap-md"><Share2 className="w-4 h-4" /> {post.shares}</span>
                  </div>
                </Card>
              </motion.div>
            ))}
          </motion.div>
        ) : (
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="text-center p-8 sm:p-10 border border-dashed border-neutral-300 dark:border-neutral-800/80 bg-white/80 dark:bg-neutral-900/80 backdrop-blur-xl max-w-md mx-auto rounded-3xl shadow-xl shadow-black/5 dark:shadow-black/30 text-neutral-900 dark:text-white"
          >
            <div className="w-16 h-16 rounded-2xl bg-neutral-100 dark:bg-neutral-800/60 border border-neutral-200 dark:border-neutral-700/60 flex items-center justify-center mx-auto mb-5 shadow-inner">
              <Bookmark className="w-8 h-8 text-neutral-400 dark:text-neutral-500 stroke-[1.8]" />
            </div>
            <h3 className="font-heading font-extrabold text-xl mb-2 text-neutral-900 dark:text-white">No Saved Posts</h3>
            <p className="text-xs sm:text-sm text-neutral-600 dark:text-neutral-400 leading-relaxed max-w-xs mx-auto font-medium">
              When you browse your campus feed on Home, click the bookmark icon to save important discussions for later reference.
            </p>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

export const createNotification = async ({
  recipientUid,
  senderUid,
  senderName,
  senderAvatar,
  type, // 'follow' | 'reply' | 'like' | 'reshare' | 'system' | 'community_invite'
  text,
  postId = null,
  commentId = null,
  communityId = null,
  communityName = null
}) => {
  if (!recipientUid || recipientUid === senderUid) return;

  try {
    await addDoc(collection(db, 'notifications'), {
      recipientUid,
      senderUid: senderUid || null,
      senderName: senderName || 'A Student',
      senderAvatar: senderAvatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(senderUid || 'user')}`,
      type: type || 'system',
      text: text || '',
      postId: postId || null,
      commentId: commentId || null,
      communityId: communityId || null,
      communityName: communityName || null,
      read: false,
      time: new Date(),
      createdAt: new Date().toISOString()
    });
  } catch (err) {
    console.error('Failed to create notification in Firestore:', err);
  }
};

const cancelLogout = () => {
    setIsLogoutModalOpen(false);
  };

const isMutual = (uId) => {
    const myFollowing = currentUser?.following || [];
    return myFollowing.includes(uId);
  };

const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [hasUnreadMessages, setHasUnreadMessages] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);
  const [isKycModalOpen, setIsKycModalOpen] = useState(false);

  const openKycModal = () => setIsKycModalOpen(true);
  const closeKycModal = () => setIsKycModalOpen(false);

  const setKycVerified = async (verifiedEmail, predictedGender = 'Neutral') => {
    await updateUser({
      kycVerified: true,
      kycEmail: verifiedEmail,
      kycGender: predictedGender
    });
  };

  const ensureCohortOfficialAndAutoFollow = async (currentProfile) => {
    if (!currentProfile || !currentProfile.uid) return;

    try {
      const cohortDocRef = doc(db, 'users', 'cohort_official');
      const cohortSnap = await getDoc(cohortDocRef);

      let cohortFollowers = [];
      if (!cohortSnap.exists()) {
        const cohortOfficialData = {
          uid: 'cohort_official',
          id: 'cohort_official',
          name: 'Cohort',
          username: 'cohort',
          email: 'cohort@official.com',
          college: 'Cohort Official Platform',
          isOfficial: true,
          bio: 'The official Cohort platform account. Connecting students across campuses. Follow for official feature updates, campus drops, and 24/7 support.',
          followers: currentProfile.uid !== 'cohort_official' ? [currentProfile.uid] : [],
          following: [],
          avatar: 'https://ui-avatars.com/api/?name=Cohort&background=9333ea&color=fff&bold=true&size=128',
          joinedDate: new Date().toISOString()
        };
        await setDoc(cohortDocRef, cohortOfficialData);
        cohortFollowers = cohortOfficialData.followers;
      } else {
        const data = cohortSnap.data();
        cohortFollowers = Array.isArray(data.followers) ? data.followers : [];
        if (currentProfile.uid !== 'cohort_official' && !cohortFollowers.includes(currentProfile.uid)) {
          cohortFollowers.push(currentProfile.uid);
          await updateDoc(cohortDocRef, { followers: cohortFollowers });
        }
      }

      // Auto-follow from current user perspective
      if (currentProfile.uid !== 'cohort_official') {
        const userFollowing = Array.isArray(currentProfile.following) ? currentProfile.following : [];
        if (!userFollowing.includes('cohort_official')) {
          const nextFollowing = [...userFollowing, 'cohort_official'];
          await updateDoc(doc(db, 'users', currentProfile.uid), { following: nextFollowing });
          setUser(prev => prev ? ({ ...prev, following: nextFollowing }) : prev);
        }
      }
    } catch (err) {
      console.error('Error in ensureCohortOfficialAndAutoFollow:', err);
    }
  };

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      setIsLoading(true);
      if (firebaseUser) {
        try {
          // Get user metadata from Firestore
          const docRef = doc(db, 'users', firebaseUser.uid);
          const docSnap = await getDoc(docRef);
          if (docSnap.exists()) {
            const profileData = {
              id: firebaseUser.uid,
              uid: firebaseUser.uid,
              ...docSnap.data()
            };
            setUser(profileData);
            localStorage.setItem(`user_profile_${firebaseUser.uid}`, JSON.stringify(profileData));
            setIsAuthenticated(true);
            ensureCohortOfficialAndAutoFollow(profileData);
          } else {
            // New Google user or profile missing in Firestore
            const displayName = firebaseUser.displayName || firebaseUser.email.split('@')[0];
            const newProfile = {
              name: displayName,
              email: firebaseUser.email,
              college: 'KIET',
              avatar: firebaseUser.photoURL || `https://ui-avatars.com/api/?name=${encodeURIComponent(displayName)}&background=0ea5e9&color=fff&bold=true&size=128`,
              joinedDate: new Date().toISOString()
            };
            await setDoc(docRef, newProfile);
            const profileData = {
              id: firebaseUser.uid,
              uid: firebaseUser.uid,
              ...newProfile
            };
            setUser(profileData);
            localStorage.setItem(`user_profile_${firebaseUser.uid}`, JSON.stringify(profileData));
            setIsAuthenticated(true);
            ensureCohortOfficialAndAutoFollow(profileData);
          }
        } catch (error) {
          console.error('Failed to retrieve user profile from Firestore:', error);
          const cached = localStorage.getItem(`user_profile_${firebaseUser.uid}`);
          if (cached) {
            setUser(JSON.parse(cached));
          } else {
            const displayName = firebaseUser.displayName || firebaseUser.email.split('@')[0];
            setUser({
              id: firebaseUser.uid,
              uid: firebaseUser.uid,
              email: firebaseUser.email,
              name: displayName,
              college: 'KIET',
              avatar: firebaseUser.photoURL || `https://ui-avatars.com/api/?name=${encodeURIComponent(displayName)}&background=0ea5e9&color=fff&bold=true&size=128`
            });
          }
          setIsAuthenticated(true);
        }
      } else {
        setUser(null);
        setIsAuthenticated(false);
      }
      setIsLoading(false);
    });

    return () => unsubscribe();
  }, []);

  // Real-time Firestore Listener for Unread Direct Messages & Count
  useEffect(() => {
    if (!user?.uid) {
      setHasUnreadMessages(false);
      setUnreadCount(0);
      return;
    }

    const unsub = onSnapshot(collection(db, 'messages'), (snapshot) => {
      const threads = [];

      snapshot.forEach(d => {
        const data = d.data();
        const isParticipant = (data.participants && data.participants.includes(user.uid)) ||
                              data.recipientUid === user.uid ||
                              data.createdBy === user.uid;

        if (isParticipant && data.hiddenFor?.[user.uid] !== true) {
          threads.push({
            id: d.id,
            ...data
          });
        }
      });

      // Deduplicate conversation threads for the same user pair (matching Messages.jsx logic)
      const uniqueThreadsMap = new Map();
      threads.forEach(t => {
        const otherUid = (t.participants || []).find(p => p !== user.uid) || t.recipientUid;
        const key = otherUid || t.name || t.id;
        if (!uniqueThreadsMap.has(key)) {
          uniqueThreadsMap.set(key, t);
        } else {
          const prev = uniqueThreadsMap.get(key);
          const tMsgCount = t.messages?.length || 0;
          const prevMsgCount = prev.messages?.length || 0;
          if (tMsgCount > prevMsgCount) {
            uniqueThreadsMap.set(key, t);
          }
        }
      });

      let totalUnread = 0;
      uniqueThreadsMap.forEach(t => {
        const msgs = t.messages || [];
        const unreadMsgsInThread = msgs.filter(m => {
          if (!m) return false;
          const senderId = m.senderUid || (typeof m.sender === 'object' ? m.sender?.uid : m.sender) || m.uid || m.authorUid;
          const isFromMe = (senderId && senderId === user.uid) ||
                           (typeof m.sender === 'string' && (m.sender === user.uid || m.sender === 'me')) ||
                           (m.senderName && m.senderName === user.name);
          const isFromOther = !isFromMe;
          const isRead = Array.isArray(m.readBy) && m.readBy.includes(user.uid);
          const isDeleted = Array.isArray(m.deletedFor) && m.deletedFor.includes(user.uid);
          return isFromOther && !isRead && !isDeleted;
        }).length;

        totalUnread += unreadMsgsInThread;
      });

      setUnreadCount(totalUnread);
      setHasUnreadMessages(totalUnread > 0);
    }, (err) => {
      console.error('Unread messages listener error:', err);
    });

    return () => unsub();
  }, [user?.uid, user?.name, user?.email]);

  // Register for push notifications on native mobile when logged in
  useEffect(() => {
    if (!user?.uid || !Capacitor.isNativePlatform()) return;

    const registerPush = async () => {
      try {
        const { PushNotifications } = await import('@capacitor/push-notifications');

        let permStatus = await PushNotifications.checkPermissions();
        if (permStatus.receive === 'prompt') {
          permStatus = await PushNotifications.requestPermissions();
        }

        if (permStatus.receive === 'granted') {
          await PushNotifications.register();

          await PushNotifications.addListener('registration', async (token) => {
            if (token?.value && user?.uid) {
              const userRef = doc(db, 'users', user.uid);
              await updateDoc(userRef, { fcmToken: token.value }).catch(err => {
                console.warn('Failed to save FCM token to Firestore:', err);
              });
            }
          });

          await PushNotifications.addListener('registrationError', (err) => {
            console.error('FCM registration error:', err);
          });
        }
      } catch (err) {
        console.warn('Push registration hook error:', err);
      }
    };

    registerPush();
  }, [user?.uid]);

  const loginWithGoogle = async () => {
    if (Capacitor.isNativePlatform()) {
      const result = await FirebaseAuthentication.signInWithGoogle();
      const idToken = result.credential?.idToken || result.idToken;
      if (!idToken) {
        throw new Error('Google Sign-In failed: No ID Token received from native SDK.');
      }
      const credential = GoogleAuthProvider.credential(idToken);
      const userCredential = await signInWithCredential(auth, credential);
      return userCredential.user;
    } else {
      const provider = new GoogleAuthProvider();
      provider.setCustomParameters({ prompt: 'select_account' });
      const result = await signInWithPopup(auth, provider);
      return result.user;
    }
  };

  const login = async (emailOrUsername, password) => {
    let emailToUse = emailOrUsername.trim();
    if (!emailToUse.includes('@')) {
      const cleanUsername = emailToUse.replace(/^@/, '').toLowerCase();
      try {
        const usersRef = collection(db, 'users');
        const q1 = query(usersRef, where('username', '==', cleanUsername));
        const snap1 = await getDocs(q1);
        if (!snap1.empty && snap1.docs[0].data()?.email) {
          emailToUse = snap1.docs[0].data().email;
        } else {
          const q2 = query(usersRef, where('usernameHandle', '==', cleanUsername));
          const snap2 = await getDocs(q2);
          if (!snap2.empty && snap2.docs[0].data()?.email) {
            emailToUse = snap2.docs[0].data().email;
          } else {
            emailToUse = `${cleanUsername}@student.edu`;
          }
        }
      } catch (err) {
        console.error('Username lookup error:', err);
        emailToUse = `${cleanUsername}@student.edu`;
      }
    }
    return signInWithEmailAndPassword(auth, emailToUse, password);
  };

  const setPasswordForUser = async (newPassword) => {
    if (!auth.currentUser) {
      console.error('[setPasswordForUser] No authenticated user found.');
      throw new Error("No authenticated user");
    }

    try {
      console.log('[setPasswordForUser] Attempting to update password for:', auth.currentUser.email);
      await updatePassword(auth.currentUser, newPassword);
      console.log('[setPasswordForUser] Password updated successfully on first try.');
    } catch (error) {
      console.warn('[setPasswordForUser] Update password failed. Error code:', error.code, 'Error message:', error.message);
      if (error.code === 'auth/requires-recent-login') {
        const tempPassword = localStorage.getItem('cohort_temp_signup_password');
        console.log('[setPasswordForUser] Found tempPassword in localStorage:', !!tempPassword);
        if (tempPassword) {
          try {
            const { EmailAuthProvider, reauthenticateWithCredential } = await import('firebase/auth');
            console.log('[setPasswordForUser] Re-authenticating with temp password...');
            const credential = EmailAuthProvider.credential(auth.currentUser.email, tempPassword);
            await reauthenticateWithCredential(auth.currentUser, credential);
            console.log('[setPasswordForUser] Re-authentication successful. Retrying password update...');
            await updatePassword(auth.currentUser, newPassword);
            console.log('[setPasswordForUser] Password updated successfully after re-authentication.');
            localStorage.removeItem('cohort_temp_signup_password');
          } catch (reauthErr) {
            console.error('[setPasswordForUser] Re-authentication or retried update failed:', reauthErr);
            throw reauthErr;
          }
        } else {
          console.error('[setPasswordForUser] auth/requires-recent-login occurred but no temporary signup password was found in localStorage.');
          throw error;
        }
      } else {
        throw error;
      }
    }

    const uid = auth.currentUser.uid;
    const docRef = doc(db, 'users', uid);
    await updateDoc(docRef, { hasPassword: true });
    setUser(prev => ({ ...prev, hasPassword: true }));

    // Clean up temporary password on success
    localStorage.removeItem('cohort_temp_signup_password');
  };

  const signup = async (userData) => {
    const { email, password, name, college } = userData;
    const userCredential = await createUserWithEmailAndPassword(auth, email, password);
    const uid = userCredential.user.uid;

    const isCollege = isCollegeEmail(email);
    const isMatching = isCollege && verifyEmailMatchesCollege(email, college || 'KIET');

    const profile = {
      name: name || 'Student',
      email: email,
      college: college || 'KIET',
      avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(name || email)}`,
      joinedDate: new Date().toISOString(),
      hasPassword: true,
      kycVerified: isMatching,
      kycEmail: isMatching ? email : null,
      kycGender: isMatching ? predictGenderFromName(email) : null
    };

    // Save profile metadata inside Firestore
    await setDoc(doc(db, 'users', uid), profile);
    setUser({ id: uid, uid, ...profile });
    setIsAuthenticated(true);
    return userCredential.user;
  };

  const requestLogout = () => {
    setIsLogoutModalOpen(true);
  };

  const cancelLogout = () => {
    setIsLogoutModalOpen(false);
  };

  const confirmLogout = async () => {
    setIsLogoutModalOpen(false);
    if (user?.uid) {
      localStorage.removeItem(`user_profile_${user.uid}`);
    }
    setUser(null);
    setIsAuthenticated(false);
    setHasUnreadMessages(false);
    return await signOut(auth);
  };

  const logout = () => {
    requestLogout();
  };

  const forceLogout = async () => {
    setIsLogoutModalOpen(false);
    if (auth.currentUser?.uid) {
      localStorage.removeItem(`user_profile_${auth.currentUser.uid}`);
    }
    setUser(null);
    setIsAuthenticated(false);
    setHasUnreadMessages(false);
    return await signOut(auth);
  };

  const syncUserProfileAcrossFirestore = async (uid, newName, newAvatar, newUsername) => {
    if (!uid) return;

    try {
      const batch = writeBatch(db);
      let batchCount = 0;

      // 1. Sync Posts where user is author or has comments
      const postsRef = collection(db, 'posts');
      const postsSnap = await getDocs(postsRef);

      postsSnap.forEach((docSnap) => {
        const post = docSnap.data();
        let postUpdated = false;
        const postRef = doc(db, 'posts', docSnap.id);
        const updatePayload = {};

        // Author sync
        if (post.author?.uid === uid || post.authorUid === uid) {
          if (newName) updatePayload['author.name'] = newName;
          if (newAvatar) updatePayload['author.avatar'] = newAvatar;
          if (newUsername) updatePayload['author.username'] = newUsername;
          postUpdated = true;
        }

        // Comments array sync
        if (Array.isArray(post.comments) && post.comments.length > 0) {
          let commentsUpdated = false;
          const updatedComments = post.comments.map(c => {
            if (c.authorUid === uid || c.author?.uid === uid || c.uid === uid) {
              commentsUpdated = true;
              return {
                ...c,
                authorName: newName || c.authorName,
                authorAvatar: newAvatar || c.authorAvatar,
                author: {
                  ...(c.author || {}),
                  name: newName || c.author?.name,
                  avatar: newAvatar || c.author?.avatar
                }
              };
            }
            return c;
          });

          if (commentsUpdated) {
            updatePayload.comments = updatedComments;
            postUpdated = true;
          }
        }

        if (postUpdated) {
          batch.update(postRef, updatePayload);
          batchCount++;
        }
      });

      // 2. Sync Messages / Conversations collection
      const messagesRef = collection(db, 'messages');
      const messagesSnap = await getDocs(messagesRef);

      messagesSnap.forEach((docSnap) => {
        const chat = docSnap.data();
        const chatRef = doc(db, 'messages', docSnap.id);
        let chatUpdated = false;
        const updatePayload = {};

        // Sync participant maps
        if (Array.isArray(chat.participants) && chat.participants.includes(uid)) {
          if (chat.participantNames) {
            updatePayload[`participantNames.${uid}`] = newName;
            chatUpdated = true;
          }
          if (chat.participantAvatars) {
            updatePayload[`participantAvatars.${uid}`] = newAvatar;
            chatUpdated = true;
          }
          if (chat.lastSenderUid === uid) {
            if (newName) updatePayload.lastSenderName = newName;
            if (newAvatar) updatePayload.lastSenderAvatar = newAvatar;
            chatUpdated = true;
          }
        }

        // Sync message array inside thread
        if (Array.isArray(chat.messages) && chat.messages.length > 0) {
          let msgsUpdated = false;
          const updatedMsgs = chat.messages.map(m => {
            if (m.senderUid === uid || m.sender?.uid === uid) {
              msgsUpdated = true;
              return {
                ...m,
                senderName: newName || m.senderName,
                senderAvatar: newAvatar || m.senderAvatar,
                sender: m.sender ? {
                  ...m.sender,
                  name: newName || m.sender.name,
                  avatar: newAvatar || m.sender.avatar
                } : undefined
              };
            }
            return m;
          });

          if (msgsUpdated) {
            updatePayload.messages = updatedMsgs;
            chatUpdated = true;
          }
        }

        if (chatUpdated) {
          batch.update(chatRef, updatePayload);
          batchCount++;
        }
      });

      // 3. Sync Community Messages collection
      const commMsgsRef = collection(db, 'community-messages');
      const commMsgsSnap = await getDocs(commMsgsRef);

      commMsgsSnap.forEach((docSnap) => {
        const msg = docSnap.data();
        if (msg.senderUid === uid || msg.sender?.uid === uid) {
          const msgRef = doc(db, 'community-messages', docSnap.id);
          const msgUpdate = {};
          if (newName) {
            msgUpdate.senderName = newName;
            msgUpdate['sender.name'] = newName;
          }
          if (newAvatar) {
            msgUpdate.senderAvatar = newAvatar;
            msgUpdate['sender.avatar'] = newAvatar;
          }
          batch.update(msgRef, msgUpdate);
          batchCount++;
        }
      });

      // 4. Sync Notifications
      const notifsRef = collection(db, 'notifications');
      const notifsSnap = await getDocs(notifsRef);

      notifsSnap.forEach((docSnap) => {
        const notif = docSnap.data();
        if (notif.senderUid === uid) {
          const notifRef = doc(db, 'notifications', docSnap.id);
          const notifUpdate = {};
          if (newName) notifUpdate.senderName = newName;
          if (newAvatar) notifUpdate.senderAvatar = newAvatar;
          batch.update(notifRef, notifUpdate);
          batchCount++;
        }
      });

      if (batchCount > 0) {
        await batch.commit();
        console.log(`Synced user profile across ${batchCount} Firestore documents.`);
      }
    } catch (err) {
      console.error('Error syncing profile across Firestore:', err);
    }
  };

  const updateUser = async (updates) => {
    if (!auth.currentUser) return;
    const uid = auth.currentUser.uid;
    const docRef = doc(db, 'users', uid);
    await updateDoc(docRef, updates);

    const newName = updates.name;
    const newAvatar = updates.avatar;
    const newUsername = updates.username;

    setUser(prev => {
      const updated = { ...prev, ...updates };
      localStorage.setItem(`user_profile_${uid}`, JSON.stringify(updated));
      return updated;
    });

    if (newName || newAvatar || newUsername) {
      syncUserProfileAcrossFirestore(uid, newName, newAvatar, newUsername);
    }
  };

  const requestPasswordReset = (email) => {
    return sendPasswordResetEmail(auth, email);
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        isAuthenticated,
        isLoading,
        hasUnreadMessages,
        setHasUnreadMessages,
        unreadCount,
        setUnreadCount,
        loginWithGoogle,
        login,
        signup,
        setPasswordForUser,
        logout,
        requestLogout,
        confirmLogout,
        cancelLogout,
        forceLogout,
        updateUser,
        requestPasswordReset,
        isKycModalOpen,
        openKycModal,
        closeKycModal,
        setKycVerified
      }}
    >
      {children}

      {/* Modern Logout Confirmation Modal */}
      {isLogoutModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6 overflow-y-auto animate-in fade-in duration-200">
          {/* Dark Glass Backdrop */}
          <div
            className="fixed inset-0 bg-black/75 backdrop-blur-md transition-opacity"
            onClick={cancelLogout}
          />

          {/* Elevated Glass Card */}
          <div className="relative bg-white/95 dark:bg-neutral-900/95 border border-neutral-200/80 dark:border-neutral-800/90 rounded-3xl shadow-2xl max-w-sm w-full p-6 text-center z-10 my-auto transform transition-all scale-100 backdrop-blur-2xl">
            {/* Icon Badge */}
            <div className="w-16 h-16 rounded-full bg-rose-500/15 text-rose-500 flex items-center justify-center mx-auto mb-4 border border-rose-500/30 shadow-md">
              <LogOut className="w-8 h-8 stroke-[2.5] animate-pulse" />
            </div>

            <h3 className="text-xl font-heading font-extrabold text-neutral-900 dark:text-white tracking-tight mb-2">
              Confirm Logout
            </h3>
            <p className="text-xs sm:text-sm text-neutral-600 dark:text-neutral-400 leading-relaxed mb-6">
              Are you sure you want to log out? You will need to log back in to access your campus messages and posts.
            </p>

            {/* Action Buttons */}
            <div className="flex items-center gap-3">
              <button
                type="button"
                onClick={cancelLogout}
                className="flex-1 py-2.5 px-4 rounded-xl border border-neutral-200 dark:border-neutral-700/80 text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800 font-bold text-xs transition-all cursor-pointer"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={confirmLogout}
                className="flex-1 py-2.5 px-4 rounded-xl bg-gradient-to-r from-rose-600 to-red-600 hover:from-rose-500 hover:to-red-500 text-white font-extrabold text-xs shadow-lg shadow-rose-500/25 active:scale-95 transition-all cursor-pointer"
              >
                Yes, Logout
              </button>
            </div>
          </div>
        </div>
      )}
    </AuthContext.Provider>
  );
};

export const Card = ({ children, className = '', variant = 'default', clickable = false, ...props }) => {
  const variants = {
    default: 'card',
    glass: 'glass',
    flat: 'bg-neutral-50 dark:bg-neutral-900 rounded-xl p-lg',
  };

  return (
    <div
      className={`${variants[variant]} ${clickable ? 'cursor-pointer hover:shadow-lg transition-shadow' : ''} ${className}`}
      {...props}
    >
      {children}
    </div>
  );
};

const handleVote = (option) => {
    if (voted) return;
    setVoted(true);
    setSelectedOpt(option);
    if (option === 'yes') {
      setPollVotes((prev) => ({ ...prev, yes: prev.yes + 1 }));
    } else {
      setPollVotes((prev) => ({ ...prev, no: prev.no + 1 }));
    }
  };

const PostCard = ({
  post,
  onVote,
  onRepost,
  onSave,
  isHighlighted,
  autoOpenComments = false,
  highlightedCommentId = null
}) => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { showSuccess } = useNotification();
  const [showComments, setShowComments] = useState(autoOpenComments || Boolean(highlightedCommentId));
  const [newComment, setNewComment] = useState('');
  const [comments, setComments] = useState([]);
  const [replyingToComment, setReplyingToComment] = useState(null);
  const [expandedReplies, setExpandedReplies] = useState({});
  const commentInputRef = useRef(null);

  useEffect(() => {
    if (autoOpenComments || highlightedCommentId) {
      setShowComments(true);
    }
  }, [autoOpenComments, highlightedCommentId]);

  const [showPostMenu, setShowPostMenu] = useState(false);
  const [isEditingPost, setIsEditingPost] = useState(false);
  const [editPostContent, setEditPostContent] = useState(post.content || '');
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [commentToDelete, setCommentToDelete] = useState(null);

  // LinkedIn-style Reshare State & Tracking
  const [showReshareModal, setShowReshareModal] = useState(false);
  const [reshareMode, setReshareMode] = useState(null); // null | 'thoughts'
  const [isShareModalOpen, setIsShareModalOpen] = useState(false);
  const [thoughtCaption, setThoughtCaption] = useState('');
  const [isSubmittingReshare, setIsSubmittingReshare] = useState(false);

  const [localReposts, setLocalReposts] = useState(post.reposts || 0);
  const [localResharedUsers, setLocalResharedUsers] = useState(post.resharedUsers || []);

  useEffect(() => {
    setLocalReposts(post.reposts || 0);
    setLocalResharedUsers(post.resharedUsers || []);
  }, [post.reposts, post.resharedUsers]);

  const isResharedByMe = Boolean(user?.uid && localResharedUsers.includes(user.uid));

  const isOfficialAdmin =
    (user?.username || '').toLowerCase() === 'cohort' ||
    (user?.name || '').toLowerCase() === 'cohort' ||
    user?.isOfficial === true ||
    user?.uid === 'cohort_official' ||
    user?.email === 'cohort@official.com';

  const isActualPostOwner = (post.author?.uid && post.author.uid === user?.uid) ||
                            (post.authorUid && post.authorUid === user?.uid) ||
                            (user?.name && post.author?.name === user?.name);

  const isPostOwner = isActualPostOwner || isOfficialAdmin;

  const isCohortOfficialPost =
    (post.author?.name || '').toLowerCase() === 'cohort' ||
    (post.author?.username || '').toLowerCase() === 'cohort' ||
    post.authorUid === 'cohort_official' ||
    post.author?.uid === 'cohort_official';

  // WhatsApp-style Poll Votes Breakdown Modal state
  const [viewVotesPoll, setViewVotesPoll] = useState(null);

  // Real-time resolution of post author profile from Firestore
  const [liveAuthorProfile, setLiveAuthorProfile] = useState(null);
  const targetAuthorUid = isCohortOfficialPost
    ? 'cohort_official'
    : (post.author?.uid || post.authorUid || post.uid);

  useEffect(() => {
    if (!targetAuthorUid) return;

    const unsub = onSnapshot(doc(db, 'users', targetAuthorUid), (snap) => {
      if (snap.exists()) {
        setLiveAuthorProfile(snap.data());
      }
    }, (err) => console.error('Error listening to post author profile:', err));

    return () => unsub();
  }, [targetAuthorUid]);

  const authorAvatar = isCohortOfficialPost
    ? (liveAuthorProfile?.avatar || post.author?.avatar)
    : ((isActualPostOwner && user?.avatar) || liveAuthorProfile?.avatar || post.author?.avatar);

  const authorName = isCohortOfficialPost
    ? 'Cohort'
    : ((isActualPostOwner && user?.name) || liveAuthorProfile?.name || post.author?.name || 'Student');

  // Social Proof Context State (Liked / Commented by someone you follow)
  const [socialContext, setSocialContext] = useState(null);

  useEffect(() => {
    if (!user?.uid) return;
    const myFollowing = Array.isArray(user?.following) ? user.following : [];
    if (myFollowing.length === 0) {
      setSocialContext(null);
      return;
    }

    // 1. Check if a followed user commented
    const followedComment = comments.find(c => {
      const cUid = c.authorUid || c.uid;
      const cName = c.author || c.authorName;
      const cUser = c.authorUsername;
      return (cUid && cUid !== user.uid && myFollowing.includes(cUid)) ||
             (cUser && cUser !== user.username && myFollowing.includes(cUser)) ||
             (cName && myFollowing.includes(cName));
    });

    if (followedComment) {
      setSocialContext({
        type: 'comment',
        userName: followedComment.author || 'A user you follow',
        userUid: followedComment.authorUid,
        text: 'commented on this'
      });
      return;
    }

    // 2. Check if a followed user liked/upvoted
    const upvoters = Array.isArray(post.upvotedUsers)
      ? post.upvotedUsers
      : (Array.isArray(post.likedUsers) ? post.likedUsers : []);

    const followedLikerItem = upvoters.find(item => {
      const uid = typeof item === 'string' ? item : item?.uid;
      return uid && uid !== user.uid && myFollowing.includes(uid);
    });

    if (followedLikerItem) {
      const likerUid = typeof followedLikerItem === 'string' ? followedLikerItem : followedLikerItem?.uid;
      getDoc(doc(db, 'users', likerUid)).then(snap => {
        if (snap.exists()) {
          const lData = snap.data();
          setSocialContext({
            type: 'like',
            userName: lData.name || lData.username || 'A user you follow',
            userUid: likerUid,
            text: 'liked this'
          });
        } else {
          setSocialContext({
            type: 'like',
            userName: 'A user you follow',
            userUid: likerUid,
            text: 'liked this'
          });
        }
      }).catch(() => {
        setSocialContext({
          type: 'like',
          userName: 'A user you follow',
          userUid: likerUid,
          text: 'liked this'
        });
      });
      return;
    }

    setSocialContext(null);
  }, [comments, post.upvotedUsers, post.likedUsers, user?.following, user?.uid, user?.username]);

  const handleSaveInlineEdit = async () => {
    if (!editPostContent.trim()) return;
    try {
      const postId = post.docId || post.id;
      await updateDoc(doc(db, 'posts', postId), { content: editPostContent.trim() });
      post.content = editPostContent.trim();
      setIsEditingPost(false);
      setShowPostMenu(false);
      showSuccess('Post updated successfully!');
    } catch (err) {
      console.error('Failed to edit post:', err);
    }
  };

  const confirmDeletePostDoc = async () => {
    try {
      const postId = post.docId || post.id;
      await deleteDoc(doc(db, 'posts', postId));

      // If deleting a reshare, decrement original post's reshare counter
      if (post.isReshare && post.originalPostId) {
        try {
          const origPostRef = doc(db, 'posts', post.originalPostId);
          await updateDoc(origPostRef, {
            reposts: increment(-1),
            resharedUsers: user?.uid ? arrayRemove(user.uid) : []
          });
        } catch (e) {
          console.error('Failed to decrement original post repost count:', e);
        }
      }

      setShowDeleteModal(false);
      setShowPostMenu(false);
      showSuccess('Post deleted permanently.');
    } catch (err) {
      console.error('Failed to delete post:', err);
    }
  };

  const handleUnreshare = async () => {
    const rootOriginalPostId = post.originalPostId || post.docId || post.id;
    const myUid = user?.uid;
    if (!myUid || !rootOriginalPostId) return;

    setIsSubmittingReshare(true);
    setLocalReposts(prev => Math.max(0, prev - 1));
    setLocalResharedUsers(prev => prev.filter(u => u !== myUid));

    try {
      // 1. Decrement repost count and remove UID from original post
      const origPostRef = doc(db, 'posts', rootOriginalPostId);
      await updateDoc(origPostRef, {
        reposts: increment(-1),
        resharedUsers: arrayRemove(myUid)
      });

      // 2. Query and delete the reshare document created by this user for rootOriginalPostId
      const q = query(
        collection(db, 'posts'),
        where('isReshare', '==', true),
        where('originalPostId', '==', rootOriginalPostId),
        where('resharedBy.uid', '==', myUid)
      );
      const snapshot = await getDocs(q);
      snapshot.forEach(async (docSnap) => {
        await deleteDoc(doc(db, 'posts', docSnap.id));
      });

      showSuccess('Reshare removed.');
      setShowReshareModal(false);
    } catch (err) {
      console.error('Failed to unreshare post:', err);
      setLocalReposts(post.reposts || 0);
      setLocalResharedUsers(post.resharedUsers || []);
    } finally {
      setIsSubmittingReshare(false);
    }
  };

  const handleReshareInstant = async () => {
    const rootOriginalPostId = post.originalPostId || post.docId || post.id;
    const origAuthor = post.originalPost?.author || post.author;
    const origContent = post.originalPost?.content || post.content;
    const origTimestamp = post.originalPost?.timestamp || post.timestamp;
    const myUid = user?.uid;

    setIsSubmittingReshare(true);
    setLocalReposts(prev => prev + 1);
    if (myUid) setLocalResharedUsers(prev => [...prev, myUid]);

    try {
      const reshareDocData = {
        isReshare: true,
        originalPostId: rootOriginalPostId,
        originalPost: {
          id: rootOriginalPostId,
          author: origAuthor,
          content: origContent,
          timestamp: origTimestamp
        },
        resharedBy: {
          uid: myUid || null,
          name: user?.name || 'Student',
          username: user?.username || null,
          avatar: user?.avatar || null
        },
        college: user?.college || 'KIET',
        author: {
          uid: myUid || null,
          name: user?.name || 'Student',
          username: user?.username || null,
          avatar: user?.avatar || null,
          role: user?.college || 'KIET',
          college: user?.college || 'KIET'
        },
        thought: '',
        content: '',
        timestamp: new Date(),
        upvotes: 0,
        downvotes: 0,
        upvotedUsers: [],
        downvotedUsers: [],
        comments: 0,
        reposts: 0,
        saved: false
      };

      await addDoc(collection(db, 'posts'), reshareDocData);

      // Increment reshare count and add user UID to root original post
      const origPostRef = doc(db, 'posts', rootOriginalPostId);
      await updateDoc(origPostRef, {
        reposts: increment(1),
        resharedUsers: myUid ? arrayUnion(myUid) : []
      });

      if (onRepost) onRepost(rootOriginalPostId);

      const origAuthorUid = origAuthor?.uid || post.author?.uid;
      if (origAuthorUid && origAuthorUid !== myUid) {
        createNotification({
          recipientUid: origAuthorUid,
          senderUid: myUid,
          senderName: user?.name || 'Student',
          senderAvatar: user?.avatar,
          type: 'reshare',
          text: 'reshared your post.',
          postId: rootOriginalPostId
        });
      }

      showSuccess('Post reshared successfully.');
      setShowReshareModal(false);
      setReshareMode(null);
    } catch (err) {
      console.error('Failed to reshare post:', err);
      setLocalReposts(post.reposts || 0);
      setLocalResharedUsers(post.resharedUsers || []);
    } finally {
      setIsSubmittingReshare(false);
    }
  };

  const handleReshareWithThoughtsSubmit = async () => {
    if (!thoughtCaption.trim()) return;
    const rootOriginalPostId = post.originalPostId || post.docId || post.id;
    const origAuthor = post.originalPost?.author || post.author;
    const origContent = post.originalPost?.content || post.content;
    const origTimestamp = post.originalPost?.timestamp || post.timestamp;
    const myUid = user?.uid;

    setIsSubmittingReshare(true);
    setLocalReposts(prev => prev + 1);
    if (myUid) setLocalResharedUsers(prev => [...prev, myUid]);

    try {
      const reshareDocData = {
        isReshare: true,
        originalPostId: rootOriginalPostId,
        originalPost: {
          id: rootOriginalPostId,
          author: origAuthor,
          content: origContent,
          timestamp: origTimestamp
        },
        resharedBy: {
          uid: myUid || null,
          name: user?.name || 'Student',
          username: user?.username || null,
          avatar: user?.avatar || null
        },
        college: user?.college || 'KIET',
        author: {
          uid: myUid || null,
          name: user?.name || 'Student',
          username: user?.username || null,
          avatar: user?.avatar || null,
          role: user?.college || 'KIET',
          college: user?.college || 'KIET'
        },
        thought: thoughtCaption.trim(),
        content: thoughtCaption.trim(),
        timestamp: new Date(),
        upvotes: 0,
        downvotes: 0,
        upvotedUsers: [],
        downvotedUsers: [],
        comments: 0,
        reposts: 0,
        saved: false
      };

      await addDoc(collection(db, 'posts'), reshareDocData);

      const origPostRef = doc(db, 'posts', rootOriginalPostId);
      await updateDoc(origPostRef, {
        reposts: increment(1),
        resharedUsers: myUid ? arrayUnion(myUid) : []
      });

      if (onRepost) onRepost(rootOriginalPostId);

      const origAuthorUid = origAuthor?.uid || post.author?.uid;
      if (origAuthorUid && origAuthorUid !== myUid) {
        createNotification({
          recipientUid: origAuthorUid,
          senderUid: myUid,
          senderName: user?.name || 'Student',
          senderAvatar: user?.avatar,
          type: 'reshare',
          text: 'reshared your post with their thoughts.',
          postId: rootOriginalPostId
        });
      }

      showSuccess('Post reshared with thoughts successfully.');
      setShowReshareModal(false);
      setReshareMode(null);
      setThoughtCaption('');
    } catch (err) {
      console.error('Failed to reshare post with thoughts:', err);
      setLocalReposts(post.reposts || 0);
      setLocalResharedUsers(post.resharedUsers || []);
    } finally {
      setIsSubmittingReshare(false);
    }
  };

  const confirmDeleteCommentDoc = async () => {
    if (!commentToDelete) return;
    const commentId = commentToDelete.id || commentToDelete;
    try {
      const postId = post.docId || post.id;
      await deleteDoc(doc(db, 'posts', postId, 'comments', commentId));

      const postRef = doc(db, 'posts', postId);
      await updateDoc(postRef, {
        comments: Math.max(0, (comments.length || 1) - 1)
      });

      setComments(prev => prev.filter(c => c.id !== commentId && c.parentId !== commentId));
      setCommentToDelete(null);
      showSuccess('Comment deleted successfully.');
    } catch (err) {
      console.error('Failed to delete comment:', err);
    }
  };

  // Subscribe to real-time comments subcollection for this post in Firestore
  useEffect(() => {
    if (!post?.docId && !post?.id) return;
    const postId = post.docId || post.id;
    const commentsRef = collection(db, 'posts', postId, 'comments');
    const q = query(commentsRef, orderBy('timestamp', 'asc'));

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const loaded = [];
      snapshot.forEach((d) => {
        const data = d.data();
        loaded.push({
          id: d.id,
          ...data,
          time: data.timestamp?.toDate ? formatRelativeTime(data.timestamp.toDate()) : 'Just now'
        });
      });
      setComments(loaded);
    }, (err) => {
      console.error('Error fetching comments from Firestore:', err);
    });

    return () => unsubscribe();
  }, [post?.id, post?.docId]);

  // Auto-scroll and highlight target comment when navigated from notification
  useEffect(() => {
    if (highlightedCommentId && comments.length > 0) {
      setShowComments(true);
      const targetComment = comments.find(c => c.id === highlightedCommentId);
      if (targetComment && targetComment.parentId) {
        // Expand the parent comment's replies accordion if nested
        setExpandedReplies(prev => ({ ...prev, [targetComment.parentId]: true }));
      }
      const scrollTimer = setTimeout(() => {
        const commentEl = document.getElementById(`comment-${highlightedCommentId}`);
        if (commentEl) {
          commentEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 300);
      return () => clearTimeout(scrollTimer);
    }
  }, [highlightedCommentId, comments]);

  const toggleReplies = (parentCommentId) => {
    setExpandedReplies(prev => ({
      ...prev,
      [parentCommentId]: !prev[parentCommentId]
    }));
  };

  const handleOpenAuthorProfile = (authorUid, authorName) => {
    if (authorUid) {
      navigate(`/profile?uid=${authorUid}`);
    } else if (authorName) {
      navigate(`/profile?name=${encodeURIComponent(authorName)}`);
    } else {
      navigate(`/profile`);
    }
  };

  const handleInitiateReplyToComment = (targetComment) => {
    const parentId = targetComment.parentId || targetComment.id;
    const usernameHandle = targetComment.authorUsername || targetComment.author?.replace(/\s+/g, '');

    setReplyingToComment({
      parentId: parentId,
      commentId: targetComment.id,
      authorUid: targetComment.authorUid,
      author: targetComment.author,
      username: usernameHandle
    });

    const tag = `@${usernameHandle} `;
    let updatedText = newComment;
    if (!newComment.includes(tag.trim())) {
      const cleanedText = newComment.replace(/^@\S+\s*/, '');
      updatedText = `${tag}${cleanedText}`;
      setNewComment(updatedText);
    }

    setTimeout(() => {
      if (commentInputRef.current) {
        const el = commentInputRef.current;
        el.focus();
        const len = updatedText.length;
        el.setSelectionRange(len, len);
      }
    }, 50);
  };

  const handleCancelReplyMode = () => {
    if (replyingToComment) {
      const username = replyingToComment.username;
      if (username) {
        const tagPattern = new RegExp(`^@${username}\\s*`, 'i');
        setNewComment(prev => prev.replace(tagPattern, ''));
      }
    }
    setReplyingToComment(null);
  };

  const handleToggleCommentLike = async (commentId) => {
    const targetComment = comments.find(c => c.id === commentId);
    if (!targetComment || !user?.uid) return;

    const currentLikedBy = targetComment.likedBy || [];
    const isAlreadyLiked = currentLikedBy.includes(user.uid);
    const updatedLikedBy = isAlreadyLiked
      ? currentLikedBy.filter(uid => uid !== user.uid)
      : [...currentLikedBy, user.uid];

    const updatedLikesCount = updatedLikedBy.length;

    // Optimistic UI update
    setComments(prev => prev.map(c => {
      if (c.id === commentId) {
        return {
          ...c,
          likedBy: updatedLikedBy,
          likes: updatedLikesCount
        };
      }
      return c;
    }));

    try {
      const postId = post.docId || post.id;
      const commentRef = doc(db, 'posts', postId, 'comments', commentId);
      await updateDoc(commentRef, {
        likedBy: updatedLikedBy,
        likes: updatedLikesCount
      });

      if (!isAlreadyLiked && targetComment.authorUid && targetComment.authorUid !== user.uid) {
        createNotification({
          recipientUid: targetComment.authorUid,
          senderUid: user.uid,
          senderName: user.name || 'Student',
          senderAvatar: user.avatar,
          type: 'like',
          text: `liked your comment: "${targetComment.text?.slice(0, 30)}..."`,
          postId: postId,
          commentId: commentId
        });
      }
    } catch (err) {
      console.error('Failed to update comment like:', err);
    }
  };

  const renderTaggedCommentText = (text) => {
    if (!text) return '';
    const tokens = text.split(/(\s+)/);
    return tokens.map((token, i) => {
      if (token.startsWith('@') && token.length > 1) {
        const cleanName = token.replace(/^@|\W+$/g, '');
        return (
          <span
            key={i}
            onClick={(e) => {
              e.stopPropagation();
              if (cleanName) navigate(`/profile?name=${encodeURIComponent(cleanName)}`);
            }}
            className="text-primary-500 font-bold hover:underline cursor-pointer mr-1 inline-block"
          >
            {token}
          </span>
        );
      }
      return token;
    });
  };

  const handleAddComment = async (e) => {
    if ((e.key === 'Enter' || e.type === 'click') && newComment.trim()) {
      const postId = post.docId || post.id;
      if (!postId) return;

      const textToSend = newComment.trim();
      const targetReply = replyingToComment;
      setNewComment('');
      setReplyingToComment(null);

      const parentId = targetReply?.parentId || null;
      const tempId = `temp_${Date.now()}`;

      const newCommentObj = {
        id: tempId,
        authorUid: user?.uid || null,
        authorUsername: user?.username || null,
        author: user?.name || user?.email?.split('@')[0] || 'Student',
        avatar: user?.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(user?.email || 'user')}`,
        text: textToSend,
        parentId: parentId,
        replyToAuthorUid: targetReply?.authorUid || null,
        replyToAuthorName: targetReply?.author || null,
        likes: 0,
        likedBy: [],
        timestamp: new Date(),
        time: 'Just now'
      };

      // Optimistic UI Update
      setComments(prev => [...prev, newCommentObj]);

      // Auto-expand parent replies so newly added reply is immediately visible
      if (parentId) {
        setExpandedReplies(prev => ({ ...prev, [parentId]: true }));
      }

      const commentData = {
        authorUid: newCommentObj.authorUid,
        authorUsername: newCommentObj.authorUsername,
        author: newCommentObj.author,
        avatar: newCommentObj.avatar,
        text: textToSend,
        parentId: parentId,
        replyToAuthorUid: targetReply?.authorUid || null,
        replyToAuthorName: targetReply?.author || null,
        likes: 0,
        likedBy: [],
        timestamp: new Date()
      };

      try {
        const newCommentRef = await addDoc(collection(db, 'posts', postId, 'comments'), commentData);

        const postRef = doc(db, 'posts', postId);
        await updateDoc(postRef, {
          comments: (comments.length || 0) + 1
        });

        const postAuthorUid = post.author?.uid || post.authorUid || post.uid;

        // 1. Dispatch Comment Notification to post author (if not self)
        if (postAuthorUid && postAuthorUid !== user?.uid) {
          createNotification({
            recipientUid: postAuthorUid,
            senderUid: user?.uid,
            senderName: user?.name || 'Student',
            senderAvatar: user?.avatar,
            type: 'reply',
            text: `commented: "${textToSend.slice(0, 35)}${textToSend.length > 35 ? '...' : ''}"`,
            postId: postId,
            commentId: newCommentRef.id
          });
        }

        // 2. Dispatch Reply Notification to the specific comment author tagged/replied to
        const commentAuthorUid = targetReply?.authorUid;
        if (
          commentAuthorUid &&
          commentAuthorUid !== user?.uid &&
          commentAuthorUid !== postAuthorUid
        ) {
          createNotification({
            recipientUid: commentAuthorUid,
            senderUid: user?.uid,
            senderName: user?.name || 'Student',
            senderAvatar: user?.avatar,
            type: 'reply',
            text: `replied to your comment: "${textToSend.slice(0, 35)}${textToSend.length > 35 ? '...' : ''}"`,
            postId: postId,
            commentId: newCommentRef.id
          });
        }
      } catch (err) {
        console.error('Failed to add reply comment in Firestore:', err);
      }
    }
  };

  const myUid = user?.uid || 'guest';
  const userVote = Array.isArray(post.upvotedUsers) && post.upvotedUsers.includes(myUid)
    ? 'up'
    : Array.isArray(post.downvotedUsers) && post.downvotedUsers.includes(myUid)
    ? 'down'
    : null;

  const upvotesCount = Array.isArray(post.upvotedUsers)
    ? post.upvotedUsers.length
    : (typeof post.upvotes === 'number' ? post.upvotes : 0);

  const downvotesCount = Array.isArray(post.downvotedUsers)
    ? post.downvotedUsers.length
    : (typeof post.downvotes === 'number' ? post.downvotes : 0);

  const topLevelComments = comments.filter(c => !c.parentId);



  return (
    <Card
      id={`post-${post.id || post.docId}`}
      className={`mb-lg transition-all duration-500 ease-out ${
        isHighlighted
          ? 'ring-2 ring-purple-500/60 dark:ring-purple-400/60 border-purple-500/80 shadow-md shadow-purple-500/20 rounded-2xl'
          : isCohortOfficialPost
          ? "border-purple-500/50 dark:border-purple-500/60 shadow-[0_0_15px_rgba(168,85,247,0.15)] bg-white dark:bg-neutral-900"
          : "border-neutral-100 dark:border-neutral-800 shadow-sm"
