                  <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-xs leading-normal">
                    Post directly to your campus feed without adding a caption.
                  </p>
                </div>
              </button>

              <button
                type="button"
                onClick={() => setReshareMode('thoughts')}
                className="w-full p-lg bg-neutral-50 dark:bg-neutral-800/80 hover:bg-neutral-100 dark:hover:bg-neutral-700/80 border border-neutral-200 dark:border-neutral-700 rounded-2xl flex items-start gap-md text-left transition-all active:scale-[0.99] group cursor-pointer"
              >
                <div className="w-10 h-10 rounded-xl bg-primary-500/10 dark:bg-primary-500/20 text-primary-500 flex items-center justify-center flex-shrink-0 group-hover:scale-110 transition-transform">
                  <PenSquare className="w-5 h-5" />
                </div>
                <div>
                  <h4 className="font-bold text-sm text-neutral-900 dark:text-white flex items-center gap-xs">
                    Reshare with Your Thoughts
                  </h4>
                  <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-xs leading-normal">
                    Add your own commentary or opinion above the original post preview.
                  </p>
                </div>
              </button>

              {isResharedByMe && (
                <button
                  type="button"
                  onClick={handleUnreshare}
                  disabled={isSubmittingReshare}
                  className="w-full p-lg bg-rose-500/5 dark:bg-rose-500/10 hover:bg-rose-500/10 dark:hover:bg-rose-500/20 border border-rose-200 dark:border-rose-900/40 rounded-2xl flex items-start gap-md text-left transition-all active:scale-[0.99] group cursor-pointer"
                >
                  <div className="w-10 h-10 rounded-xl bg-rose-500/10 dark:bg-rose-500/20 text-rose-500 flex items-center justify-center flex-shrink-0 group-hover:scale-110 transition-transform">
                    <Trash2 className="w-5 h-5" />
                  </div>
                  <div>
                    <h4 className="font-bold text-sm text-rose-600 dark:text-rose-400 flex items-center gap-xs">
                      Undo Reshare
                    </h4>
                    <p className="text-xs text-rose-500/80 dark:text-rose-400/80 mt-xs leading-normal">
                      Remove your reshare from feed and decrease reshare count.
                    </p>
                  </div>
                </button>
              )}
            </div>
          )}
        </Modal>
      )}

      {/* Instagram-style Share Modal */}
      <ShareModal
        isOpen={isShareModalOpen}
        onClose={() => setIsShareModalOpen(false)}
        post={post}
        shareUrl={`https://cohortnow.online/post/${post.id}`}
        title={`Post by ${post.author?.name || 'Cohort Student'}`}
      />

      {/* WhatsApp-Style Poll Votes Breakdown Modal */}
      <Modal isOpen={Boolean(viewVotesPoll)} onClose={() => setViewVotesPoll(null)} title="Poll Votes Breakdown" size="md">
        <div className="space-y-4 py-1">
          <div className="p-3.5 rounded-2xl bg-neutral-900 border border-neutral-800 flex items-center justify-between">
            <div className="min-w-0 pr-2">
              <span className="text-[10px] font-bold text-sky-400 uppercase tracking-wider block">Question</span>
              <h4 className="text-sm font-extrabold text-white mt-0.5 truncate">{viewVotesPoll?.question}</h4>
            </div>
            <span className="text-[10px] font-bold text-sky-300 px-2.5 py-1 rounded-full bg-sky-500/15 border border-sky-500/25 flex-shrink-0">
              {viewVotesPoll?.totalVotes || 0} Total Votes
            </span>
          </div>

          <div className="space-y-3 max-h-96 overflow-y-auto pr-1 scrollbar-thin">
            {viewVotesPoll?.options?.map((opt, idx) => {
              const voters = (Array.isArray(opt.votedUserDetails) && opt.votedUserDetails.length > 0)
                ? opt.votedUserDetails
                : ((viewVotesPoll.votedUsers || []).filter(uid => viewVotesPoll.userChoices?.[uid] === idx).length > 0
                    ? (viewVotesPoll.votedUsers || []).filter(uid => viewVotesPoll.userChoices?.[uid] === idx).map(uid => ({ uid, name: uid === user?.uid ? (user?.name || 'Student') : 'Student', avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${uid}` }))
                    : (opt.votes > 0
                        ? Array.from({ length: opt.votes }).map((_, i) => ({ uid: `v_${i}`, name: i === 0 && user?.name ? user.name : `Student ${i + 1}`, avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${(user?.email || 's') + i}` }))
                        : []));

              return (
                <div key={idx} className="p-3 rounded-2xl bg-neutral-900/90 border border-neutral-800 space-y-2">
                  <div className="flex items-center justify-between font-bold text-xs">
                    <span className="text-white font-extrabold">{opt.text}</span>
                    <span className="text-neutral-400 font-mono text-[11px]">{voters.length} {voters.length === 1 ? 'vote' : 'votes'}</span>
                  </div>

                  {voters.length > 0 ? (
                    <div className="space-y-1.5 pt-1">
                      {voters.map((voter, vIdx) => (
                        <div key={vIdx} className="flex items-center justify-between p-2 rounded-xl bg-neutral-950/70 border border-neutral-800/60 text-xs">
                          <div className="flex items-center gap-2 min-w-0">
                            <img
                              src={voter.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(voter.name || 'Student')}`}
                              alt={voter.name}
                              className="w-7 h-7 rounded-full object-cover border border-neutral-700 flex-shrink-0"
                            />
                            <span className="font-bold text-neutral-200 truncate">{voter.name || 'Student'}</span>
                          </div>
                          <CheckCircle2 className="w-4 h-4 text-emerald-400 fill-emerald-400/20 flex-shrink-0" />
                        </div>
                      ))}
                    </div>
                  ) : (
                    <p className="text-[11px] text-neutral-500 italic px-1">No votes for this option yet.</p>
                  )}
                </div>
              );
            })}
          </div>

          <div className="pt-2 border-t border-neutral-800 flex justify-end">
            <Button variant="secondary" onClick={() => setViewVotesPoll(null)} className="rounded-2xl px-5 text-xs font-semibold">
              Close
            </Button>
          </div>
        </div>
      </Modal>
    </Card>
  );
};

const handleRemoveImage = () => {
    setImageFile(null);
    if (imagePreviewUrl) {
      URL.revokeObjectURL(imagePreviewUrl);
      setImagePreviewUrl(null);
    }
    if (imageInputRef.current) {
      imageInputRef.current.value = '';
    }
  };

const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [hasUnreadMessages, setHasUnreadMessages] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);
  const [isKycModalOpen, setIsKycModalOpen] = useState(false);

  const openKycModal = () => setIsKycModalOpen(true);
  const closeKycModal = () => setIsKycModalOpen(false);

  const setKycVerified = async (verifiedEmail, predictedGender = 'Neutral') => {
    await updateUser({
      kycVerified: true,
      kycEmail: verifiedEmail,
      kycGender: predictedGender
    });
  };

  const ensureCohortOfficialAndAutoFollow = async (currentProfile) => {
    if (!currentProfile || !currentProfile.uid) return;

    try {
      const cohortDocRef = doc(db, 'users', 'cohort_official');
      const cohortSnap = await getDoc(cohortDocRef);

      let cohortFollowers = [];
      if (!cohortSnap.exists()) {
        const cohortOfficialData = {
          uid: 'cohort_official',
          id: 'cohort_official',
          name: 'Cohort',
          username: 'cohort',
          email: 'cohort@official.com',
          college: 'Cohort Official Platform',
          isOfficial: true,
          bio: 'The official Cohort platform account. Connecting students across campuses. Follow for official feature updates, campus drops, and 24/7 support.',
          followers: currentProfile.uid !== 'cohort_official' ? [currentProfile.uid] : [],
          following: [],
          avatar: 'https://ui-avatars.com/api/?name=Cohort&background=9333ea&color=fff&bold=true&size=128',
          joinedDate: new Date().toISOString()
        };
        await setDoc(cohortDocRef, cohortOfficialData);
        cohortFollowers = cohortOfficialData.followers;
      } else {
        const data = cohortSnap.data();
        cohortFollowers = Array.isArray(data.followers) ? data.followers : [];
        if (currentProfile.uid !== 'cohort_official' && !cohortFollowers.includes(currentProfile.uid)) {
          cohortFollowers.push(currentProfile.uid);
          await updateDoc(cohortDocRef, { followers: cohortFollowers });
        }
      }

      // Auto-follow from current user perspective
      if (currentProfile.uid !== 'cohort_official') {
        const userFollowing = Array.isArray(currentProfile.following) ? currentProfile.following : [];
        if (!userFollowing.includes('cohort_official')) {
          const nextFollowing = [...userFollowing, 'cohort_official'];
          await updateDoc(doc(db, 'users', currentProfile.uid), { following: nextFollowing });
          setUser(prev => prev ? ({ ...prev, following: nextFollowing }) : prev);
        }
      }
    } catch (err) {
      console.error('Error in ensureCohortOfficialAndAutoFollow:', err);
    }
  };

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      setIsLoading(true);
      if (firebaseUser) {
        try {
          // Get user metadata from Firestore
          const docRef = doc(db, 'users', firebaseUser.uid);
          const docSnap = await getDoc(docRef);
          if (docSnap.exists()) {
            const profileData = {
              id: firebaseUser.uid,
              uid: firebaseUser.uid,
              ...docSnap.data()
            };
            setUser(profileData);
            localStorage.setItem(`user_profile_${firebaseUser.uid}`, JSON.stringify(profileData));
            setIsAuthenticated(true);
            ensureCohortOfficialAndAutoFollow(profileData);
          } else {
            // New Google user or profile missing in Firestore
            const displayName = firebaseUser.displayName || firebaseUser.email.split('@')[0];
            const newProfile = {
              name: displayName,
              email: firebaseUser.email,
              college: 'KIET',
              avatar: firebaseUser.photoURL || `https://ui-avatars.com/api/?name=${encodeURIComponent(displayName)}&background=0ea5e9&color=fff&bold=true&size=128`,
              joinedDate: new Date().toISOString()
            };
            await setDoc(docRef, newProfile);
            const profileData = {
              id: firebaseUser.uid,
              uid: firebaseUser.uid,
              ...newProfile
            };
            setUser(profileData);
            localStorage.setItem(`user_profile_${firebaseUser.uid}`, JSON.stringify(profileData));
            setIsAuthenticated(true);
            ensureCohortOfficialAndAutoFollow(profileData);
          }
        } catch (error) {
          console.error('Failed to retrieve user profile from Firestore:', error);
          const cached = localStorage.getItem(`user_profile_${firebaseUser.uid}`);
          if (cached) {
            setUser(JSON.parse(cached));
          } else {
            const displayName = firebaseUser.displayName || firebaseUser.email.split('@')[0];
            setUser({
              id: firebaseUser.uid,
              uid: firebaseUser.uid,
              email: firebaseUser.email,
              name: displayName,
              college: 'KIET',
              avatar: firebaseUser.photoURL || `https://ui-avatars.com/api/?name=${encodeURIComponent(displayName)}&background=0ea5e9&color=fff&bold=true&size=128`
            });
          }
          setIsAuthenticated(true);
        }
      } else {
        setUser(null);
        setIsAuthenticated(false);
      }
      setIsLoading(false);
    });

    return () => unsubscribe();
  }, []);

  // Real-time Firestore Listener for Unread Direct Messages & Count
  useEffect(() => {
    if (!user?.uid) {
      setHasUnreadMessages(false);
      setUnreadCount(0);
      return;
    }

    const unsub = onSnapshot(collection(db, 'messages'), (snapshot) => {
      const threads = [];

      snapshot.forEach(d => {
        const data = d.data();
        const isParticipant = (data.participants && data.participants.includes(user.uid)) ||
                              data.recipientUid === user.uid ||
                              data.createdBy === user.uid;

        if (isParticipant && data.hiddenFor?.[user.uid] !== true) {
          threads.push({
            id: d.id,
            ...data
          });
        }
      });

      // Deduplicate conversation threads for the same user pair (matching Messages.jsx logic)
      const uniqueThreadsMap = new Map();
      threads.forEach(t => {
        const otherUid = (t.participants || []).find(p => p !== user.uid) || t.recipientUid;
        const key = otherUid || t.name || t.id;
        if (!uniqueThreadsMap.has(key)) {
          uniqueThreadsMap.set(key, t);
        } else {
          const prev = uniqueThreadsMap.get(key);
          const tMsgCount = t.messages?.length || 0;
          const prevMsgCount = prev.messages?.length || 0;
          if (tMsgCount > prevMsgCount) {
            uniqueThreadsMap.set(key, t);
          }
        }
      });

      let totalUnread = 0;
      uniqueThreadsMap.forEach(t => {
        const msgs = t.messages || [];
        const unreadMsgsInThread = msgs.filter(m => {
          if (!m) return false;
          const senderId = m.senderUid || (typeof m.sender === 'object' ? m.sender?.uid : m.sender) || m.uid || m.authorUid;
          const isFromMe = (senderId && senderId === user.uid) ||
                           (typeof m.sender === 'string' && (m.sender === user.uid || m.sender === 'me')) ||
                           (m.senderName && m.senderName === user.name);
          const isFromOther = !isFromMe;
          const isRead = Array.isArray(m.readBy) && m.readBy.includes(user.uid);
          const isDeleted = Array.isArray(m.deletedFor) && m.deletedFor.includes(user.uid);
          return isFromOther && !isRead && !isDeleted;
        }).length;

        totalUnread += unreadMsgsInThread;
      });

      setUnreadCount(totalUnread);
      setHasUnreadMessages(totalUnread > 0);
    }, (err) => {
      console.error('Unread messages listener error:', err);
    });

    return () => unsub();
  }, [user?.uid, user?.name, user?.email]);

  // Register for push notifications on native mobile when logged in
  useEffect(() => {
    if (!user?.uid || !Capacitor.isNativePlatform()) return;

    const registerPush = async () => {
      try {
        const { PushNotifications } = await import('@capacitor/push-notifications');

        let permStatus = await PushNotifications.checkPermissions();
        if (permStatus.receive === 'prompt') {
          permStatus = await PushNotifications.requestPermissions();
        }

        if (permStatus.receive === 'granted') {
          await PushNotifications.register();

          await PushNotifications.addListener('registration', async (token) => {
            if (token?.value && user?.uid) {
              const userRef = doc(db, 'users', user.uid);
              await updateDoc(userRef, { fcmToken: token.value }).catch(err => {
                console.warn('Failed to save FCM token to Firestore:', err);
              });
            }
          });

          await PushNotifications.addListener('registrationError', (err) => {
            console.error('FCM registration error:', err);
          });
        }
      } catch (err) {
        console.warn('Push registration hook error:', err);
      }
    };

    registerPush();
  }, [user?.uid]);

  const loginWithGoogle = async () => {
    if (Capacitor.isNativePlatform()) {
      const result = await FirebaseAuthentication.signInWithGoogle();
      const idToken = result.credential?.idToken || result.idToken;
      if (!idToken) {
