    if (currentlyFollowing) {
      nextFollowing = nextFollowing.filter(id => id !== tId);
      showSuccess(`Unfollowed @${tName || 'user'}`);
    } else {
      nextFollowing.push(tId);
      showSuccess(`Now following @${tName || 'user'}!`);
