                />
                {isUploadingOfficialAvatar && (
                  <div className="absolute inset-0 bg-black/60 rounded-full flex items-center justify-center">
                    <Loader2 className="w-6 h-6 text-purple-400 animate-spin" />
                  </div>
                )}
              </div>
              <input
                ref={officialFileInputRef}
                type="file"
                accept="image/*"
                className="hidden"
                onChange={handleOfficialAvatarSelect}
              />
              <Button
                variant="secondary"
                size="sm"
                className="flex items-center gap-xs text-xs font-bold border-purple-500/30 text-purple-600 dark:text-purple-300 hover:bg-purple-500/10"
                onClick={() => officialFileInputRef.current?.click()}
                disabled={isUploadingOfficialAvatar}
              >
                <Camera className="w-4 h-4 text-purple-500" /> Change Official Image
              </Button>
            </div>

            {/* Bio Edit */}
            <div>
              <label className="block text-xs font-bold text-neutral-700 dark:text-neutral-300 mb-xs uppercase tracking-wider">
                Official Account Bio
              </label>
              <textarea
                value={officialBioInput}
                onChange={(e) => setOfficialBioInput(e.target.value)}
                placeholder="Enter official account bio..."
                className="w-full p-md bg-neutral-50 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl text-sm outline-none focus:ring-2 focus:ring-purple-500 text-neutral-900 dark:text-white leading-relaxed resize-none"
                rows={4}
              />
            </div>

            {/* Modal Actions */}
            <div className="flex items-center justify-end gap-md pt-md border-t border-neutral-100 dark:border-neutral-800">
              <Button
                variant="ghost"
                onClick={() => setIsEditOfficialModalOpen(false)}
                disabled={isSavingOfficial}
              >
                Cancel
              </Button>
              <Button
                variant="primary"
                onClick={handleSaveOfficialProfile}
                disabled={isSavingOfficial || isUploadingOfficialAvatar}
                className="bg-purple-600 hover:bg-purple-700 text-white font-bold"
              >
                {isSavingOfficial ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin mr-1" /> Saving...
                  </>
                ) : (
                  'Save Changes'
                )}
              </Button>
            </div>
          </div>
        </Modal>
      )}

      {/* Instagram-style Share Modal */}
      <ShareModal
        isOpen={isProfileShareOpen}
        onClose={() => setIsProfileShareOpen(false)}
        shareUrl={window.location.href}
        title={`Profile: ${profileUser?.name || 'Cohort Student'}`}
      />
    </div>
  );
}

function SavedPosts() {
  const { showSuccess } = useNotification();
  const [savedPosts, setSavedPosts] = useState([]);

  useEffect(() => {
    const stored = localStorage.getItem('collex-saved-posts');
    if (stored) {
      setSavedPosts(JSON.parse(stored));
    }
  }, []);

  const handleUnsave = (postId, postTitle) => {
    const updated = savedPosts.filter(p => p.id !== postId);
    setSavedPosts(updated);
    localStorage.setItem('collex-saved-posts', JSON.stringify(updated));
    showSuccess(`Removed post from bookmarks.`);
  };

  return (
    <div className="section-container max-w-2xl">
      <SEO title="Saved Posts" />
      <div className="mb-3xl">
        <h1 className="text-3xl font-heading font-bold flex items-center gap-md">
          <Bookmark className="w-8 h-8 text-primary-500 fill-primary-500/10" /> Saved Posts
        </h1>
        <p className="text-neutral-600 dark:text-neutral-400 mt-xs">
          View bookmarked feeds, updates, and campus discussions you saved
        </p>
      </div>

      <AnimatePresence mode="popLayout">
        {savedPosts.length > 0 ? (
          <motion.div
            layout
            className="space-y-lg"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          >
            {savedPosts.map((post) => (
              <motion.div
                key={post.id}
                layout
                initial={{ opacity: 0, y: 15 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95 }}
                transition={{ duration: 0.25 }}
              >
                <Card className="p-lg border-neutral-100 dark:border-neutral-800">
                  {/* Header */}
                  <div className="flex items-center justify-between mb-md">
                    <div className="flex items-center gap-md">
                      <img
                        src={post.author.avatar || 'https://api.dicebear.com/7.x/avataaars/svg?seed=user'}
                        alt={post.author.name}
                        className="w-10 h-10 rounded-full object-cover"
                      />
                      <div>
                        <h4 className="font-semibold text-neutral-900 dark:text-white text-sm">
                          {post.author.name}
                        </h4>
                        <span className="text-[10px] text-neutral-400">
                          {post.author.role} • {formatRelativeTime(post.timestamp)}
                        </span>
                      </div>
                    </div>

                    <button
                      onClick={() => handleUnsave(post.id, post.content)}
                      className="p-md text-neutral-400 hover:text-danger rounded-lg hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors"
                      title="Unsave post"
                    >
                      <BookmarkMinus className="w-5 h-5" />
                    </button>
                  </div>

                  {/* Content */}
                  <p className="text-sm text-neutral-700 dark:text-neutral-300 leading-relaxed mb-lg whitespace-pre-wrap break-words">
                    {post.content}
                  </p>

                  {post.imageUrl && (
                    <div className="mb-lg rounded-2xl overflow-hidden border border-neutral-100 dark:border-neutral-800 bg-neutral-950/40 flex items-center justify-center">
                      <img
                        src={post.imageUrl}
                        alt="Post attachment"
                        className="w-full h-auto max-h-[700px] object-contain rounded-2xl"
                      />
                    </div>
                  )}

                  {/* Actions Footer */}
                  <div className="flex items-center gap-xl text-xs text-neutral-500 dark:text-neutral-400 border-t border-neutral-100 dark:border-neutral-800 pt-md">
                    <span className="flex items-center gap-md"><Heart className="w-4 h-4 text-rose-500 fill-rose-500" /> {post.likes}</span>
                    <span className="flex items-center gap-md"><MessageCircle className="w-4 h-4" /> {post.comments}</span>
                    <span className="flex items-center gap-md"><Share2 className="w-4 h-4" /> {post.shares}</span>
                  </div>
                </Card>
              </motion.div>
            ))}
          </motion.div>
        ) : (
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="text-center p-8 sm:p-10 border border-dashed border-neutral-300 dark:border-neutral-800/80 bg-white/80 dark:bg-neutral-900/80 backdrop-blur-xl max-w-md mx-auto rounded-3xl shadow-xl shadow-black/5 dark:shadow-black/30 text-neutral-900 dark:text-white"
          >
            <div className="w-16 h-16 rounded-2xl bg-neutral-100 dark:bg-neutral-800/60 border border-neutral-200 dark:border-neutral-700/60 flex items-center justify-center mx-auto mb-5 shadow-inner">
              <Bookmark className="w-8 h-8 text-neutral-400 dark:text-neutral-500 stroke-[1.8]" />
            </div>
            <h3 className="font-heading font-extrabold text-xl mb-2 text-neutral-900 dark:text-white">No Saved Posts</h3>
            <p className="text-xs sm:text-sm text-neutral-600 dark:text-neutral-400 leading-relaxed max-w-xs mx-auto font-medium">
              When you browse your campus feed on Home, click the bookmark icon to save important discussions for later reference.
            </p>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

