                      className={`absolute inset-0 rounded-full -z-10 opacity-15 dark:opacity-25 transition-all ${
                        special
                          ? 'bg-purple-500'
                          : specialConfession
                          ? 'bg-rose-500'
                          : specialFriend
                          ? 'bg-vandal-pink'
                          : specialUncut
                          ? 'bg-pink-500'
                          : 'bg-primary-500'
