const throttledHandler = (e) => {
      if (rafId) return;
      rafId = requestAnimationFrame(() => {
        const x = (e.clientX / window.innerWidth - 0.5) * 2;
        const y = (e.clientY / window.innerHeight - 0.5) * 2;
        if (Math.abs(x - lastX) > 0.01 || Math.abs(y - lastY) > 0.01) {
          lastX = x;
          lastY = y;
          setPosition({ x, y });
        }
        rafId = null;
      });
    };

