                                <div className="space-y-xs relative group min-w-0 max-w-full">
                                  {!isMe && <span className="text-[10px] font-bold text-neutral-500 ml-sm">{msg.sender?.name}{msg.sender?.role && ` · ${msg.sender?.role}`}</span>}
