const handleLikePost = async (item, isConfession) => {
    const targetColl = isConfession ? 'confessions' : 'anonymousPosts';
    const myUid = user?.uid || 'guest';
    let likedList = [...(item.likedUsers || [])];

    if (likedList.includes(myUid)) {
      likedList = likedList.filter(u => u !== myUid);
    } else {
      likedList.push(myUid);
    }

    try {
      const docRef = doc(db, targetColl, item.docId);
      if (isConfession) {
        await updateDoc(docRef, { likes: likedList.length, likedUsers: likedList });
      } else {
        await updateDoc(docRef, { likesCount: likedList.length, likedUsers: likedList });
      }
    } catch (err) {
      console.error('Error toggling like:', err);
    }
  };

const predictGenderFromName = (email) => {
  if (!email || typeof email !== 'string') return 'Neutral';

  const username = email.trim().toLowerCase().split('@')[0];
  if (!username) return 'Neutral';

  // Extract first name (split by dot, underscore, hyphen or numbers)
  const firstName = username.split(/[\._\-0-9]/)[0];
  if (!firstName || firstName.length < 2) return 'Neutral';

  const MALE_NAMES = new Set([
    'rahul', 'amit', 'abhishek', 'kushal', 'rohit', 'sachin', 'mohit', 'raj', 'deepak', 'sandeep',
    'sunil', 'anil', 'vishal', 'nikhil', 'karan', 'arjun', 'aakash', 'aditya', 'gaurav', 'manish',
    'vivek', 'harsh', 'ankit', 'ritesh', 'vikram', 'saurabh', 'pranav', 'shubham', 'rishabh', 'kartik',
    'madhav', 'varun', 'rishi', 'dev', 'raghav', 'kabir', 'yash', 'abhay', 'dhruv', 'sid',
    'siddharth', 'ayush', 'hardik', 'priyansh', 'aman', 'ritik', 'shiv', 'shivam', 'shubham', 'vijay',
    'ajay', 'sanjay', 'ram', 'shyam', 'aravind', 'anuj', 'mayank', 'prateek', 'tushar', 'gaurav',
    'rohan', 'kunal', 'pankaj', 'suresh', 'ramesh', 'dinesh', 'harish', 'mahesh', 'naresh', 'lokesh',
    'rakesh', 'vikas', 'vinay', 'ashok', 'alok', 'atul', 'arun', 'saurav', 'tarun', 'varun', 'gautam',
    'ravi', 'hari', 'shiva', 'sameer', 'aman', 'sahil', 'jatin'
  ]);

  const FEMALE_NAMES = new Set([
    'priya', 'sneha', 'neha', 'anjali', 'pooja', 'ritu', 'kavita', 'aarushi', 'shruti', 'aditi',
    'kirti', 'divya', 'pragya', 'preeti', 'swati', 'shreya', 'megha', 'tisha', 'tanvi', 'ishita',
    'ananya', 'disha', 'riya', 'rhea', 'khushi', 'muskan', 'sakshi', 'shalini', 'shivani', 'nisha',
    'jyoti', 'komal', 'pinky', 'sonal', 'payal', 'sheetal', 'kajal', 'rashmi', 'nishi', 'sonam',
    'renu', 'sapna', 'mamta', 'babita', 'gauri', 'diksha', 'rashi', 'taniya', 'anushka', 'deepika',
    'aliya', 'katrina', 'kareena', 'sushma', 'radha', 'aanchal', 'sweta', 'shweta', 'monika', 'mansi',
    'hema', 'rekha', 'jaya', 'sushmita', 'sunita', 'anita', 'geeta', 'seema', 'meena', 'asha',
    'lata', 'pallavi', 'poonam', 'prerna', 'richa', 'ridhima', 'shikha', 'tanu', 'diksha', 'alka'
  ]);

  const UNISEX_NAMES = new Set([
    'suman', 'krishna', 'kiran', 'simran', 'harpreet', 'gurpreet', 'jaspreet', 'simar', 'kripa', 'preet',
    'deep', 'sunny', 'bobby', 'ryan', 'taylor', 'alex', 'sam', 'robin'
  ]);

  // 1. Unisex overrides
  if (UNISEX_NAMES.has(firstName)) {
    return 'Neutral';
  }

  // 2. Direct Male names
  if (MALE_NAMES.has(firstName)) {
    return 'Male';
  }

  // 3. Direct Female names
  if (FEMALE_NAMES.has(firstName)) {
    return 'Female';
  }

  // 4. Suffix-based heuristics for typical Indian names
  if (firstName.endsWith('esh') || firstName.endsWith('ish') || firstName.endsWith('endra') || firstName.endsWith('jeet') || firstName.endsWith('preet') || firstName.endsWith('meet')) {
    return 'Male';
  }
  if (firstName.endsWith('ank') || firstName.endsWith('it') || firstName.endsWith('ant') || firstName.endsWith('eep') || firstName.endsWith('eet') || firstName.endsWith('ath') || firstName.endsWith('dev') || firstName.endsWith('raj')) {
    return 'Male';
  }
  if (firstName.endsWith('av') || firstName.endsWith('am') || firstName.endsWith('an') || firstName.endsWith('al') || firstName.endsWith('ar') || firstName.endsWith('ur') || firstName.endsWith('ut')) {
    return 'Male';
  }
  if (firstName.endsWith('ika') || firstName.endsWith('isha') || firstName.endsWith('anya') || firstName.endsWith('iti') || firstName.endsWith('ini') || firstName.endsWith('eta') || firstName.endsWith('iya') || firstName.endsWith('ee')) {
    return 'Female';
  }
  if (firstName.endsWith('a') || firstName.endsWith('i')) {
    return 'Female';
  }

  return 'Neutral';
};

const validateEmail = (email) => {
  const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return regex.test(email);
};

function ShareModal({ isOpen, onClose, post, shareUrl: customShareUrl, title: customTitle }) {
  const { user } = useAuth();
  const { showSuccess, showError } = useNotification();

  const [searchQuery, setSearchQuery] = useState('');
  const [recentUsers, setRecentUsers] = useState([]);
  const [loadingUsers, setLoadingUsers] = useState(false);
  const [selectedUsers, setSelectedUsers] = useState([]);
  const [isSending, setIsSending] = useState(false);
  const [sentMap, setSentMap] = useState({});
  const [copied, setCopied] = useState(false);

  const rawAuthorName = post?.author?.name || post?.authorName || '';
  const shareTitle =
    customTitle ||
    (rawAuthorName ? (rawAuthorName.toLowerCase().startsWith('post by') ? rawAuthorName : `Post by ${rawAuthorName}`) : 'Campus Post');

  const isUncut = Boolean(customShareUrl?.includes('/uncut')) || Boolean(post?.id?.includes('-')) || Boolean(post?.category);
  const shareText =
    post?.content ||
    post?.excerpt ||
    post?.text ||
    post?.caption ||
    (isUncut
      ? 'Read unfiltered real campus stories written by peers on Cohort Uncut.'
      : 'Explore student conversations, gossip, confessions and stories on Cohort.');

  const postMediaUrl =
    post?.image ||
    post?.imageUrl ||
    post?.mediaUrl ||
    post?.photo ||
    post?.media ||
    post?.coverImage ||
    post?.storyImage ||
    '';

  const rawShareUrl = customShareUrl || (post?.id ? `${window.location.origin}/post/${post.id}` : window.location.href);
  const shareUrl = rawShareUrl.includes('?') ? rawShareUrl : `${rawShareUrl}?v=1`;

  // Fetch recent chat members and campus users when modal opens
  useEffect(() => {
    if (!isOpen) {
      setSearchQuery('');
      setSelectedUsers([]);
      setSentMap({});
      setCopied(false);
      return;
    }

    const fetchContacts = async () => {
      setLoadingUsers(true);
      try {
        const usersSnap = await getDocs(collection(db, 'users'));
        const list = [];
        usersSnap.forEach((d) => {
          const uid = d.id;
          if (
            user?.uid &&
            uid !== user.uid &&
            uid !== 'cohort_official' &&
            d.data()?.username !== 'cohort'
          ) {
            const data = d.data();
            list.push({
              uid,
              name: data.name || data.username || 'Campus Student',
              username: data.username || '',
              avatar:
                data.avatar ||
                `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(uid)}`,
              college: data.college || 'KIET'
            });
          }
        });

        setRecentUsers(list);
      } catch (err) {
        console.error('Error fetching share contacts:', err);
      } finally {
        setLoadingUsers(false);
      }
    };

    fetchContacts();
  }, [isOpen, user]);

  // Filter contacts by search query
  const filteredUsers = recentUsers.filter((u) => {
    const q = searchQuery.toLowerCase().trim();
    if (!q) return true;
    return (
      u.name.toLowerCase().includes(q) ||
      u.username.toLowerCase().includes(q) ||
      u.college.toLowerCase().includes(q)
    );
  });

  // Toggle user selection
  const toggleSelectUser = (targetUser) => {
    if (sentMap[targetUser.uid]) return;
    if (selectedUsers.some((u) => u.uid === targetUser.uid)) {
      setSelectedUsers(selectedUsers.filter((u) => u.uid !== targetUser.uid));
    } else {
      setSelectedUsers([...selectedUsers, targetUser]);
    }
  };

  // Batch send direct message to all selected contacts
  const handleSendBatch = async () => {
    if (!user) {
      showError('Please sign in to send direct messages.');
      return;
    }

    if (selectedUsers.length === 0) return;

    setIsSending(true);

    const cleanStr = (val, fallback = '') => (val === undefined || val === null ? fallback : String(val));

    try {
      const myUid = cleanStr(user?.uid);
      const myName = cleanStr(user?.name || user?.displayName || user?.email?.split('@')[0], 'Me');
      const myAvatar = cleanStr(
        user?.avatar || user?.photoURL,
        `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(myUid)}`
      );

      const safeTitle = cleanStr(shareTitle, 'Campus Post');
      const safeText = cleanStr(shareText, 'Check out this post on Cohort!');
      const safeUrl = cleanStr(shareUrl, window.location.href);
      const safeMediaUrl = cleanStr(
        post?.image || post?.imageUrl || post?.mediaUrl || post?.photo || post?.media || post?.coverImage || postMediaUrl,
        ''
      );
      const lastMsgSummary = `Shared a post: ${safeText.slice(0, 35)}${safeText.length > 35 ? '...' : ''}`;
      const nowIso = new Date().toISOString();

      // Fetch existing conversations for matching
      const messagesSnap = await getDocs(collection(db, 'messages'));
      const existingDocsMap = new Map();

      messagesSnap.forEach((docSnap) => {
        const data = docSnap.data();
        const parts = Array.isArray(data.participants) ? data.participants : [];

        // Match by participants array or createdBy/recipientUid fields
        selectedUsers.forEach((tUser) => {
          const targetUid = cleanStr(tUser.uid);
          const isMatch =
            (parts.includes(myUid) && parts.includes(targetUid)) ||
            (data.createdBy === myUid && data.recipientUid === targetUid) ||
            (data.createdBy === targetUid && data.recipientUid === myUid);

          if (isMatch && !existingDocsMap.has(targetUid)) {
            existingDocsMap.set(targetUid, { id: docSnap.id, ...data });
          }
        });
      });

      const sanitizeForFirestore = (val) => {
        if (val === undefined) return null;
        if (val === null || typeof val !== 'object') return val;
        if (val instanceof Date) return val;
        if (Array.isArray(val)) return val.map(sanitizeForFirestore);
        const clean = {};
        for (const key of Object.keys(val)) {
          if (val[key] !== undefined) {
            clean[key] = sanitizeForFirestore(val[key]);
          }
        }
        return clean;
      };

      const sendPromises = selectedUsers.map(async (targetUser) => {
        const targetUid = cleanStr(targetUser.uid);
        const targetName = cleanStr(targetUser.name, 'Campus Student');
        const targetAvatar = cleanStr(
          targetUser.avatar,
          `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(targetUid)}`
        );

        const isUncut = Boolean(safeUrl.includes('/uncut') || post?.id?.includes('-') || post?.category);
        const messageObj = sanitizeForFirestore({
          id: `msg_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
          sender: myUid,
          senderUid: myUid,
          senderName: myName,
          senderAvatar: myAvatar,
          text: isUncut 
            ? `📖 Shared Uncut Story: ${safeTitle}\n"${safeText.slice(0, 120)}${safeText.length > 120 ? '...' : ''}"\n${safeUrl}`
            : `Shared post by ${safeTitle}:\n"${safeText.slice(0, 120)}${safeText.length > 120 ? '...' : ''}"\n${safeUrl}`,
          time: nowIso,
          createdAt: nowIso,
          deletedFor: [],
          isSharedPost: true,
          isUncutStory: isUncut,
          sharedPostData: {
            id: cleanStr(post?.id, ''),
            title: safeTitle,
            content: safeText,
            url: safeUrl,
            mediaUrl: safeMediaUrl
          }
        });

        const existingDoc = existingDocsMap.get(targetUid);

        if (existingDoc) {
          const chatRef = doc(db, 'messages', existingDoc.id);
          const freshSnap = await getDoc(chatRef);
          const rawData = freshSnap.exists() ? freshSnap.data() : existingDoc;

          const rawMsgs = Array.isArray(rawData.messages) ? rawData.messages : [];
          const cleanExistingMsgs = rawMsgs.map((m) => {
            const cleanM = sanitizeForFirestore(m);
            return {
              ...cleanM,
              time: m.time?.toDate ? m.time.toDate().toISOString() : (m.time ? String(m.time) : nowIso)
            };
          });

          const resetHidden = {};
          if (rawData.hiddenFor) {
            Object.keys(rawData.hiddenFor).forEach((k) => {
              resetHidden[`hiddenFor.${k}`] = false;
            });
          }

          const updatePayload = sanitizeForFirestore({
            messages: [...cleanExistingMsgs, messageObj],
            lastMessage: lastMsgSummary,
            time: new Date(),
            readBy: [myUid],
            [`participantMap.${myUid}`]: { name: myName, avatar: myAvatar },
            [`participantMap.${targetUid}`]: { name: targetName, avatar: targetAvatar },
            ...resetHidden
          });

          await updateDoc(chatRef, updatePayload);
        } else {
          const newConvData = sanitizeForFirestore({
            recipientUid: targetUid,
            recipientName: targetName,
            recipientAvatar: targetAvatar,
            participants: [myUid, targetUid],
            participantMap: {
              [myUid]: { name: myName, avatar: myAvatar },
              [targetUid]: { name: targetName, avatar: targetAvatar }
            },
            createdBy: myUid,
            createdByName: myName,
            createdByAvatar: myAvatar,
            readBy: [myUid],
            avatar: targetAvatar,
            lastMessage: lastMsgSummary,
            time: new Date(),
            messages: [messageObj]
          });
          await addDoc(collection(db, 'messages'), newConvData);
        }
      });

      await Promise.all(sendPromises);

      const newSentMap = { ...sentMap };
      selectedUsers.forEach((u) => {
        newSentMap[u.uid] = true;
      });

      setSentMap(newSentMap);
      showSuccess(
        selectedUsers.length === 1
          ? `Sent to ${selectedUsers[0].name}!`
          : `Sent to ${selectedUsers.length} contacts!`
      );
      setSelectedUsers([]);
      setTimeout(() => {
        onClose();
      }, 700);
    } catch (err) {
      console.error('Error sending batch messages:', err);
      showError('Failed to send message. Please try again.');
    } finally {
      setIsSending(false);
    }
  };

  // Copy link handler
  const handleCopyLink = () => {
    navigator.clipboard.writeText(shareUrl);
    setCopied(true);
    showSuccess('Link copied to clipboard!');
    setTimeout(() => setCopied(false), 2500);
  };

  const handleSocialShare = async (platform) => {
    const isUncutStory = shareUrl.includes('/uncut') || Boolean(post?.category) || Boolean(post?.id?.includes('-')) || shareTitle.toLowerCase().includes('uncut');
    const encodedUrl = encodeURIComponent(shareUrl);

    switch (platform) {
      case 'whatsapp': {
        let waText = '';
        if (isUncutStory) {
          const storyTitle = post?.title || shareTitle.replace(/^(Uncut Story:?|College, Love Stories and the Dilemma \| Cohort Uncut)\s*/i, '');
          const authorName = post?.authorName || post?.author?.name || 'Cohort Uncut';
          const initialLines = (post?.content || post?.excerpt || post?.text || shareText || '').slice(0, 160);

          waText = `📖 *COHORT UNCUT* | *Story*\n\n` +
                   `*"${storyTitle}"*\n` +
                   `✍️ *By ${authorName}*\n\n` +
                   `"${initialLines}${initialLines.length >= 160 ? '...' : ''}"\n\n` +
                   `👉 *Read full story on Cohort:*\n${shareUrl}`;
        } else {
          waText = `✨ *Check this out on Cohort:*\n"${shareText.slice(0, 120)}"\n\n${shareUrl}`;
        }

        window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(waText)}`, '_blank');
        break;
      }
      case 'instagram':
        navigator.clipboard.writeText(shareUrl);
        showSuccess('Link copied! Opening Instagram...');
        setTimeout(() => {
          window.open('https://www.instagram.com/direct/inbox/', '_blank');
        }, 600);
        break;
      case 'facebook':
        window.open(`https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}`, '_blank');
        break;
      case 'messenger':
        window.open(`https://www.facebook.com/dialog/send?link=${encodedUrl}&app_id=291494419107518&redirect_uri=${encodedUrl}`, '_blank');
        break;
      case 'email':
        window.open(`mailto:?subject=${encodeURIComponent(shareTitle)}&body=${encodedText}`, '_blank');
        break;
      case 'threads':
        window.open(`https://www.threads.net/intent/post?text=${encodedText}`, '_blank');
        break;
      case 'twitter':
        window.open(`https://twitter.com/intent/tweet?text=${encodedText}`, '_blank');
        break;
      default:
        handleCopyLink();
    }
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
      <div className="fixed inset-0 z-[100] bg-black/70 backdrop-blur-sm flex items-center justify-center p-4">
        {/* Backdrop click to close */}
        <div className="absolute inset-0" onClick={onClose} />

        {/* Modal Card */}
        <motion.div
          initial={{ opacity: 0, scale: 0.95, y: 15 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.95, y: 15 }}
          transition={{ duration: 0.2, ease: 'easeOut' }}
          className="relative z-10 bg-white dark:bg-zinc-900 border border-neutral-200 dark:border-zinc-800 w-full max-w-md rounded-3xl shadow-2xl overflow-hidden text-neutral-900 dark:text-neutral-100 flex flex-col max-h-[90vh]"
        >
          {/* Header */}
          <div className="relative px-5 py-4 border-b border-neutral-100 dark:border-zinc-800 flex items-center justify-center">
            <button
              onClick={onClose}
              className="absolute left-4 p-1.5 rounded-full hover:bg-neutral-100 dark:hover:bg-zinc-800 text-neutral-500 dark:text-zinc-400 hover:text-neutral-900 dark:hover:text-white transition-colors"
            >
              <X className="w-5 h-5 stroke-[2.5]" />
            </button>
            <h3 className="font-extrabold text-base tracking-tight text-neutral-900 dark:text-white">
              Share
            </h3>
          </div>

          {/* Search Bar */}
          <div className="p-4 pb-2">
            <div className="relative flex items-center bg-neutral-100 dark:bg-zinc-800/80 border border-neutral-200 dark:border-zinc-700/60 rounded-xl px-3.5 py-2.5 focus-within:border-purple-500 dark:focus-within:border-purple-400 transition-all">
              <Search className="w-4 h-4 text-neutral-400 dark:text-zinc-400 mr-2 flex-shrink-0" />
              <input
                type="text"
                placeholder="Search contacts"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full bg-transparent text-sm font-medium text-neutral-900 dark:text-white placeholder-neutral-400 dark:placeholder-zinc-500 focus:outline-none"
              />
              {searchQuery && (
                <button
                  onClick={() => setSearchQuery('')}
                  className="text-neutral-400 hover:text-neutral-600 dark:text-zinc-400 dark:hover:text-white"
                >
                  <X className="w-3.5 h-3.5" />
                </button>
