export const ThemeProvider = ({ children }) => {
  const [isDark, setIsDark] = useState(() => {
    const stored = localStorage.getItem('theme-mode');
    if (stored) return stored === 'dark';
    return true; // Dark mode is default
  });

  useEffect(() => {
    const root = document.documentElement;
    console.log('[ThemeContext] isDark changed to:', isDark, 'initial class:', root.className);
    if (isDark) {
      root.classList.add('dark');
      localStorage.setItem('theme-mode', 'dark');
    } else {
      root.classList.remove('dark');
      localStorage.setItem('theme-mode', 'light');
    }
    console.log('[ThemeContext] class after update:', root.className);
  }, [isDark]);

  const toggleTheme = () => setIsDark(!isDark);

  return (
    <ThemeContext.Provider value={{ isDark, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
};

const handleDeleteAccount = async () => {
    const confirmation = window.confirm(
      "WARNING: Are you sure you want to permanently delete your Cohort profile and account? This action is irreversible."
    );
    if (!confirmation) return;

    setIsDeleting(true);
    try {
      if (user?.uid) {
        // 1. Delete from Firestore users collection
        const userRef = doc(db, 'users', user.uid);
        await deleteDoc(userRef);
      }

      // 2. Delete from Firebase Auth
      const currentUser = auth.currentUser;
      if (currentUser) {
        await currentUser.delete();
      }

      // 3. Logout & redirect
      await logout();
      showSuccess('Your account was successfully deleted.');
      navigate('/');
    } catch (err) {
      console.error('Failed to delete account:', err);
      // Fallback: If delete requires re-login, log out anyway after deleting Firestore doc
      await logout();
      showSuccess('Your profile was removed.');
      navigate('/');
    } finally {
      setIsDeleting(false);
    }
  };

