    if (!formData.message.trim()) newErrors.message = 'Message is required';

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

const handleToggleCommentLike = async (commentId, postId, isConfession) => {
    const targetColl = isConfession ? 'confessions' : 'anonymousPosts';
    const myUid = user?.uid || 'guest';

    const commentsList = commentsMap[postId] || [];
    const targetComment = commentsList.find(c => c.id === commentId);
    if (!targetComment) return;

    let likedBy = Array.isArray(targetComment.likedBy) ? [...targetComment.likedBy] : [];
    if (likedBy.includes(myUid)) {
      likedBy = likedBy.filter(u => u !== myUid);
    } else {
      likedBy.push(myUid);
    }

    try {
      await updateDoc(doc(db, targetColl, postId, 'comments', commentId), {
        likedBy: likedBy,
        likes: likedBy.length
      });
    } catch (err) {
      console.error('Error toggling comment like:', err);
    }
  };

const handleListUserFollow = (tId, currentlyFollowing, tName) => {
    if (!currentUser || !tId) return;

    const currentFollowing = Array.isArray(currentUser.following) ? currentUser.following : [];
    let nextFollowing = [...currentFollowing];

    if (currentlyFollowing) {
      nextFollowing = nextFollowing.filter(id => id !== tId);
      showSuccess(`Unfollowed @${tName || 'user'}`);
    } else {
      nextFollowing.push(tId);
      showSuccess(`Now following @${tName || 'user'}!`);
    }

    updateUser({ following: nextFollowing });
    setDoc(doc(db, 'users', currentUser.uid), { following: nextFollowing }, { merge: true }).catch(err => console.error(err));
  };

const handleCreatePoll = async (e) => {
    if (e && e.preventDefault) e.preventDefault();
    if (!pollQuestion.trim()) {
      showSuccess('Please enter a poll question.');
      return;
    }
    const validOptions = pollOptions.filter(o => o.trim() !== '');
    if (validOptions.length < 2) { showSuccess('At least 2 options required.'); return; }

    const targetConv = conversations.find(c => c.id === selectedId || c.docId === selectedId);
    if (!targetConv) return;

    const myName = user?.name || user?.email?.split('@')[0] || 'Me';
    const pollObj = {
      question: pollQuestion.trim(),
      pollType: pollType,
      totalVotes: 0,
      options: validOptions.map((optText, i) => ({ id: `opt_${i}`, text: optText.trim(), votes: 0, votedUsers: [] }))
    };

    const newMsg = {
      sender: user?.uid || 'me',
      senderUid: user?.uid || null,
      senderName: myName,
      text: `Poll: ${pollQuestion.trim()}`,
      poll: pollObj,
      type: 'poll',
      time: new Date(),
      deletedFor: []
    };

    setIsCreatePollOpen(false);
    setPollQuestion('');
    setPollOptions(['', '']);
    setPollType('single');

    const updatedMsgs = [...(targetConv.messages || []), newMsg];
    setConversations(prev => prev.map(c => (c.id === selectedId || c.docId === selectedId) ? { ...c, messages: updatedMsgs } : c));

    const targetDocId = targetConv.docId || targetConv.id;
    if (targetDocId) {
      try {
        await updateDoc(doc(db, 'messages', targetDocId), {
          messages: updatedMsgs,
          lastMessage: `Poll: ${pollQuestion.trim()}`,
          lastTime: new Date()
        });
      } catch (err) {
        console.error(err);
      }
    }
    showSuccess('Poll published in chat!');
  };

