        },
        content: postContent.trim(),
        imageUrl: uploadedImageUrl,
        timestamp: new Date(),
        upvotes: 0,
        downvotes: 0,
        upvotedUsers: [],
        downvotedUsers: [],
        comments: 0,
        reposts: 0,
        saved: false,
        ...(hasValidPoll ? {
          poll: {
