    return await signOut(auth);
  };

const handleDirectJoin = async (community) => {
    if (!community?.id || !user?.uid) return;
    try {
      await updateDoc(doc(db, 'userCommunities', community.id), {
        members: arrayUnion(user.uid)
      });
      const updatedGroup = { roomType: 'group', ...community, members: [...(community.members || []), user.uid] };
      setSelectedRoom(updatedGroup);
      setMyCommunities(prev => [...prev.filter(c => c.id !== community.id), updatedGroup]);
      showSuccess(`Joined "${community.name}"!`);
    } catch (e) {
      console.error(e);
      showWarning('Failed to join community.');
    }
  };

const handleSocialShare = async (platform) => {
    const isUncutStory = shareUrl.includes('/uncut') || Boolean(post?.category) || Boolean(post?.id?.includes('-')) || shareTitle.toLowerCase().includes('uncut');
    const encodedUrl = encodeURIComponent(shareUrl);

    switch (platform) {
      case 'whatsapp': {
        let waText = '';
        if (isUncutStory) {
          const storyTitle = post?.title || shareTitle.replace(/^(Uncut Story:?|College, Love Stories and the Dilemma \| Cohort Uncut)\s*/i, '');
          const authorName = post?.authorName || post?.author?.name || 'Cohort Uncut';
          const initialLines = (post?.content || post?.excerpt || post?.text || shareText || '').slice(0, 160);

          waText = `📖 *COHORT UNCUT* | *Story*\n\n` +
                   `*"${storyTitle}"*\n` +
                   `✍️ *By ${authorName}*\n\n` +
                   `"${initialLines}${initialLines.length >= 160 ? '...' : ''}"\n\n` +
                   `👉 *Read full story on Cohort:*\n${shareUrl}`;
        } else {
          waText = `✨ *Check this out on Cohort:*\n"${shareText.slice(0, 120)}"\n\n${shareUrl}`;
        }

        window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(waText)}`, '_blank');
        break;
      }
      case 'instagram':
        navigator.clipboard.writeText(shareUrl);
        showSuccess('Link copied! Opening Instagram...');
        setTimeout(() => {
          window.open('https://www.instagram.com/direct/inbox/', '_blank');
        }, 600);
        break;
      case 'facebook':
        window.open(`https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}`, '_blank');
        break;
      case 'messenger':
        window.open(`https://www.facebook.com/dialog/send?link=${encodedUrl}&app_id=291494419107518&redirect_uri=${encodedUrl}`, '_blank');
        break;
      case 'email':
        window.open(`mailto:?subject=${encodeURIComponent(shareTitle)}&body=${encodedText}`, '_blank');
        break;
      case 'threads':
        window.open(`https://www.threads.net/intent/post?text=${encodedText}`, '_blank');
        break;
      case 'twitter':
        window.open(`https://twitter.com/intent/tweet?text=${encodedText}`, '_blank');
        break;
      default:
        handleCopyLink();
    }
  };

export async function uploadImageToCloudinary(file) {
  const cloudName = 'p6cec4mr';
  const apiKey = '111857136275992';
  const apiSecret = 'ebK99ZxdBtm68zHUyBMhlcefP8s';

  const timestamp = Math.round(Date.now() / 1000);

  // Sort parameters alphabetically: timestamp is the only parameter being signed here
  const signatureString = `timestamp=${timestamp}${apiSecret}`;

  // Generate SHA-1 signature
  const signature = await sha1(signatureString);

  const formData = new FormData();
  formData.append('file', file);
  formData.append('api_key', apiKey);
  formData.append('timestamp', timestamp.toString());
  formData.append('signature', signature);

  const response = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, {
    method: 'POST',
    body: formData,
  });

  if (!response.ok) {
    const errorData = await response.json();
    throw new Error(errorData.error?.message || 'Cloudinary upload failed');
  }

  const data = await response.json();
  return data.secure_url;
}

