        const qGroup = query(collection(db, 'userCommunities', comm.id, 'messages'), where('starredBy', 'array-contains', user.uid));
        const unsubGroup = onSnapshot(qGroup, (snap) => {
          const list = [];
          snap.forEach(d => {
