                            >
                              {isMuted ? (
                                <>
                                  <Bell className="w-3.5 h-3.5 text-emerald-500" /> Unmute Notifications
                                </>
                              ) : (
                                <>
                                  <BellOff className="w-3.5 h-3.5 text-neutral-500" /> Mute Notifications
                                </>
