            {newItem.imageUrl ? (
              <div className="relative h-40 rounded-xl overflow-hidden border border-neutral-200 dark:border-neutral-700 bg-neutral-900 group">
                <img
                  src={newItem.imageUrl}
                  alt="Product preview"
                  className="w-full h-full object-cover"
                />
