      {/* Interactive Post Poll */}
      {post.poll && (
        <div className="mb-xl p-4 rounded-2xl bg-neutral-50 dark:bg-neutral-900/80 border border-neutral-200/80 dark:border-neutral-800 space-y-3 shadow-xs">
