    </div>
  );
};

const handleVerifyOTP = async (e) => {
    if (e) e.preventDefault();
    setErrorMsg('');
    const targetOtp = otpInput.trim();

    if (!targetOtp || targetOtp.length !== 6) {
      setErrorMsg('Please enter the 6-digit verification code.');
      return;
    }

    setIsLoading(true);
    try {
      const otpDocRef = doc(db, 'otps', `kyc_${user.uid}`);
      const otpSnap = await getDoc(otpDocRef);

      if (!otpSnap.exists()) {
        setErrorMsg('Verification code not found. Please request a new one.');
        return;
      }

      const otpData = otpSnap.data();

      // Check if OTP matches
      if (otpData.otp !== targetOtp) {
        setErrorMsg('Invalid verification code. Please check your email and try again.');
        return;
      }

      // Check expiration (10 minutes)
      const createdAt = new Date(otpData.createdAt);
      const now = new Date();
      const diffMinutes = (now - createdAt) / 1000 / 60;
      if (diffMinutes > 10) {
        setErrorMsg('Verification code has expired. Please request a new one.');
        return;
      }

      // 3. Mark user as KYC verified in database and auth context
      const predicted = predictGenderFromName(otpData.email);
      await setKycVerified(otpData.email, predicted);

      showSuccess('Student email verified successfully!');
      setStep(3);
    } catch (err) {
      console.error(err);
      setErrorMsg('Failed to verify OTP. Please try again.');
      showError('Verification failed.');
    } finally {
      setIsLoading(false);
    }
  };

const handleSendOTP = async () => {
    const emailToUse = formData.email.trim();
    if (!emailToUse) {
      setErrors({ email: 'Email address is required' });
      return;
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(emailToUse)) {
      setErrors({ email: 'Please enter a valid email address' });
      return;
    }

    setIsLoading(true);
    try {
      // Check if email already exists in Firestore users
      const q = query(collection(db, 'users'), where('email', '==', emailToUse.toLowerCase()));
      const querySnap = await getDocs(q);
      if (!querySnap.empty) {
        setErrors({ email: 'This email is already registered. Please sign in instead.' });
        showError('This email is already registered. Please sign in instead.');
        setIsLoading(false);
        return;
      }

      const resData = await sendVerificationCode(emailToUse);
      showSuccess('Verification code sent to your email!');

      if (resData.otp) {
        console.log(`%c[OTP Code (Dev Mode)] ${resData.otp}`, 'color: #9333ea; font-size: 16px; font-weight: bold;');
        if (resData.previewUrl) {
          console.log(`[Email Preview Link] ${resData.previewUrl}`);
        }
        showSuccess(`[Dev Mode] OTP code is ${resData.otp} (Logged to console)`);
      }

      setSignupStep(2);
      setResendTimer(30);
    } catch (err) {
      console.error(err);
      setErrors({ email: err.message || 'Failed to send verification code. Please try again.' });
      showError(err.message || 'Failed to send verification code. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

