const handleTouchMove = (e) => {
    if (!isDragging || e.touches.length !== 1) return;
    const touch = e.touches[0];
    const newX = touch.clientX - dragStart.current.x;
    const newY = touch.clientY - dragStart.current.y;
    setPosition({ x: newX, y: newY });
  };

const handleMouseDown = (e) => {
    e.preventDefault();
    setIsDragging(true);
    dragStart.current = { x: e.clientX - position.x, y: e.clientY - position.y };
  };

const handleMarketplaceImageUpload = async (file) => {
    if (!file || !editingMarketplaceItem) return;
    setImageUploading(true);
    try {
      let finalUrl = '';
      try {
        finalUrl = await uploadImageToCloudinary(file);
      } catch (err) {
        finalUrl = await compressImage(file);
      }
      setEditingMarketplaceItem(prev => ({ ...prev, imageUrl: finalUrl }));
    } catch (err) {
      console.error('Failed to upload marketplace image:', err);
    } finally {
      setImageUploading(false);
    }
  };

const handleStarGroupMessage = async (msgId) => {
    if (!user?.uid) return;
    const isCollege = isCollegeRoom || selectedRoom?.roomType === 'college';
    const targetColl = isCollege ? 'community-messages' : (selectedRoom?.id ? `userCommunities/${selectedRoom.id}/messages` : null);
    if (!targetColl) return;

    const msgsList = isCollege ? messages : communityMessages;
    const msg = msgsList.find(m => m.id === msgId);
    if (!msg) return;

    const isStarred = Array.isArray(msg.starredBy) && msg.starredBy.includes(user.uid);
    const docRef = doc(db, targetColl, msgId);

    try {
      if (isStarred) {
        await updateDoc(docRef, { starredBy: arrayRemove(user.uid) });
        showSuccess('Message unstarred');
      } else {
        await updateDoc(docRef, { starredBy: arrayUnion(user.uid) });
        showSuccess('Message starred ⭐');
      }
    } catch (e) {
      console.error('Failed to star message:', e);
    }
  };

const handleContactSeller = (sellerName, itemTitle, sellerUid) => {
    setSelectedItem(null);
    if (sellerUid && user?.uid && sellerUid === user.uid) {
      navigate('/messages');
      return;
    }
    const productParam = itemTitle ? `&product=${encodeURIComponent(itemTitle)}` : '';
    if (sellerUid) {
      navigate(`/messages?recipientUid=${sellerUid}&recipientName=${encodeURIComponent(sellerName)}${productParam}`);
    } else {
      navigate(`/messages?recipientName=${encodeURIComponent(sellerName)}${productParam}`);
    }
  };

