          : new Date(data.expiresAt || (data.createdAt?.toDate ? data.createdAt.toDate().getTime() + 86400000 : now + 86400000)).getTime();

        if (expiresAtMs > now) {
          loaded.push({
            id: d.id,
            docId: d.id,
            ...data,
            expiresAtMs,
            createdAt: data.createdAt?.toDate ? data.createdAt.toDate() : new Date(data.createdAt || Date.now())
