                  <button
                    type="button"
                    disabled={resendTimer > 0 || isLoading}
                    onClick={handleResend}
                    className={`flex items-center gap-1 cursor-pointer font-bold ${
                      resendTimer > 0 
                        ? 'text-neutral-400 cursor-not-allowed' 
