function EditProfile() {
  const navigate = useNavigate();
  const { user, updateUser, logout } = useAuth();
  const { showSuccess, showError } = useNotification();

  const [isLoading, setIsLoading] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  // Image Upload States
  const [avatarFile, setAvatarFile] = useState(null);
  const [avatarPreviewUrl, setAvatarPreviewUrl] = useState(null);
  const [cropperSrc, setCropperSrc] = useState(null);
  const fileInputRef = useRef(null);

  const [formData, setFormData] = useState({
    name: user?.name || '',
    bio: user?.bio || '',
    college: user?.college || 'Delhi University',
    gender: user?.gender || 'Prefer not to say',
    year: user?.year || '1st Year',
    dob: user?.dob || '',
  });

  const handleRemovePhoto = () => {
    setAvatarFile(null);
    const defaultUrl = `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(user?.email || 'user')}`;
    setAvatarPreviewUrl(defaultUrl);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    try {
      let uploadedAvatarUrl = user?.avatar || '';

      // If a preview URL is a default Dicebear URL and avatarFile is null, it means they clicked "Remove Photo"
      if (avatarPreviewUrl && avatarPreviewUrl.startsWith('https://api.dicebear.com')) {
        uploadedAvatarUrl = avatarPreviewUrl;
      } else if (avatarFile) {
        uploadedAvatarUrl = await uploadImageToCloudinary(avatarFile);
      }

      const hasCollegeChanged = formData.college !== user?.college;
      const updatedData = {
        ...formData,
        avatar: uploadedAvatarUrl,
        ...(hasCollegeChanged ? { kycVerified: false, kycEmail: null } : {})
      };

      await updateUser(updatedData);
      showSuccess('Profile updated successfully!');
      navigate('/profile');
    } catch (err) {
      console.error(err);
      showError('Failed to update profile. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleDeleteAccount = async () => {
    const confirmation = window.confirm(
      "WARNING: Are you sure you want to permanently delete your Cohort profile and account? This action is irreversible."
    );
    if (!confirmation) return;

    setIsDeleting(true);
    try {
      if (user?.uid) {
        // 1. Delete from Firestore users collection
        const userRef = doc(db, 'users', user.uid);
        await deleteDoc(userRef);
      }

      // 2. Delete from Firebase Auth
      const currentUser = auth.currentUser;
      if (currentUser) {
        await currentUser.delete();
      }

      // 3. Logout & redirect
      await logout();
      showSuccess('Your account was successfully deleted.');
      navigate('/');
    } catch (err) {
      console.error('Failed to delete account:', err);
      // Fallback: If delete requires re-login, log out anyway after deleting Firestore doc
      await logout();
      showSuccess('Your profile was removed.');
      navigate('/');
    } finally {
      setIsDeleting(false);
    }
  };

  return (
    <div className="section-container max-w-2xl">
      <SEO title="Edit Profile" />
      <h1 className="text-3xl font-heading font-bold mb-lg">Edit Profile</h1>

      <Card className="mb-lg">
        <form onSubmit={handleSubmit} className="space-y-lg">
          {/* Profile Picture */}
          <div>
            <label className="block font-semibold mb-md text-sm text-neutral-700 dark:text-neutral-300">
              Profile Picture
            </label>
            <div className="flex items-center gap-lg">
              <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                <UserAvatar
                  src={avatarPreviewUrl || user?.avatar}
                  name={user?.name || 'User'}
                  className="w-20 h-20 rounded-full border-2 border-primary-500 object-cover shadow-sm group-hover:opacity-85 transition-opacity"
                />
                <div className="absolute inset-0 flex items-center justify-center bg-black/45 rounded-full opacity-0 group-hover:opacity-100 transition-opacity">
                  <Camera className="w-5 h-5 text-white" />
                </div>
                <input
                  type="file"
                  ref={fileInputRef}
                  onChange={(e) => {
                    const file = e.target.files[0];
                    if (file) {
                      setCropperSrc(URL.createObjectURL(file));
                    }
                  }}
                  accept="image/*"
                  className="hidden"
                />
              </div>
              <div className="flex flex-col gap-xs">
                <div className="flex gap-md">
                  <Button type="button" size="sm" variant="secondary" onClick={() => fileInputRef.current?.click()}>
                    Upload New
                  </Button>
                  <Button
                    type="button"
                    size="sm"
                    variant="ghost"
                    className="text-danger hover:bg-red-50 dark:hover:bg-red-950/20"
                    onClick={handleRemovePhoto}
                  >
                    Remove Photo
                  </Button>
                </div>
                <span className="text-[10px] text-neutral-400">JPG, PNG or SVG. Max 5MB.</span>
              </div>
            </div>
          </div>

          {/* Full Name */}
          <Input
            label="Full Name"
            value={formData.name}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            required
          />

          {/* Bio */}
          <div>
            <label className="block font-semibold mb-md text-sm text-neutral-700 dark:text-neutral-300">Bio</label>
            <textarea
              value={formData.bio}
              onChange={(e) => setFormData({ ...formData, bio: e.target.value })}
              className="input-base resize-none text-sm px-lg py-md"
              rows={3}
              placeholder="Tell us about yourself..."
            />
          </div>

          {/* College / University Selector with Toggle */}
          <CollegeSelector
            value={formData.college}
            onChange={(newCollege) => setFormData({ ...formData, college: newCollege })}
          />

          {/* Gender and Year of Study */}
          <div className="grid grid-cols-2 gap-lg">
            <div>
              <label className="block font-semibold mb-md text-sm text-neutral-700 dark:text-neutral-300">
                Gender
              </label>
              <select
                value={formData.gender}
                onChange={(e) => setFormData({ ...formData, gender: e.target.value })}
                className="input-base text-sm h-10 py-0"
              >
                <option value="Male">Male</option>
                <option value="Female">Female</option>
                <option value="Non-binary">Non-binary</option>
                <option value="Prefer not to say">Prefer not to say</option>
              </select>
            </div>

            <div>
              <label className="block font-semibold mb-md text-sm text-neutral-700 dark:text-neutral-300">
                Year of Study
              </label>
              <select
                value={formData.year}
                onChange={(e) => setFormData({ ...formData, year: e.target.value })}
                className="input-base text-sm h-10 py-0"
              >
                <option value="1st Year">1st Year</option>
                <option value="2nd Year">2nd Year</option>
                <option value="3rd Year">3rd Year</option>
                <option value="4th Year">4th Year</option>
                <option value="5th Year">5th Year</option>
                <option value="Post Graduate">Post Graduate</option>
              </select>
            </div>
          </div>

          {/* Date of Birth */}
          <div>
            <label className="block font-semibold mb-md text-sm text-neutral-700 dark:text-neutral-300">
              Date of Birth (DOB)
            </label>
            <input
              type="date"
              value={formData.dob}
              onChange={(e) => setFormData({ ...formData, dob: e.target.value })}
              className="input-base text-sm h-10"
              required
            />
          </div>

          <div className="flex gap-md pt-md border-t border-neutral-100 dark:border-neutral-800">
            <Button variant="secondary" className="flex-1" type="button" onClick={() => navigate('/profile')}>
              Cancel
            </Button>
            <Button variant="primary" type="submit" className="flex-1" disabled={isLoading}>
              {isLoading ? 'Saving Changes...' : 'Save Changes'}
            </Button>
          </div>
        </form>
      </Card>

      {/* Danger Zone */}
      <Card className="border-red-200 dark:border-red-950 bg-red-50/20 dark:bg-red-950/10">
        <div className="flex items-start gap-md">
          <AlertTriangle className="w-5 h-5 text-red-500 mt-xs flex-shrink-0" />
          <div className="space-y-md flex-1">
            <div>
              <h3 className="text-base font-bold text-red-600 dark:text-red-400">Danger Zone</h3>
              <p className="text-xs text-neutral-500 mt-xs">
                Deleting your profile will permanently remove your user credentials and profile details. All your personal discussions will be disassociated.
              </p>
            </div>
            <Button
              type="button"
              variant="secondary"
              size="sm"
              onClick={handleDeleteAccount}
              disabled={isDeleting}
              className="border-red-300 hover:border-red-400 text-red-600 hover:bg-red-50 dark:hover:bg-red-950/20"
            >
              {isDeleting ? 'Deleting Account...' : 'Delete Profile & Account'}
            </Button>
          </div>
        </div>
      </Card>
      {cropperSrc && (
        <ImageCropper
          imageSrc={cropperSrc}
          onCrop={(croppedFile) => {
            setAvatarFile(croppedFile);
            setAvatarPreviewUrl(URL.createObjectURL(croppedFile));
            setCropperSrc(null);
          }}
          onCancel={() => {
            setCropperSrc(null);
          }}
        />
      )}
    </div>
  );
}

const KycVerificationModal = () => {
  const { user, isKycModalOpen, closeKycModal, setKycVerified } = useAuth();
  const { showSuccess, showError, showWarning } = useNotification();

  const [step, setStep] = useState(1); // 1 = enter email, 2 = enter otp, 3 = success
  const [emailInput, setEmailInput] = useState('');
  const [otpInput, setOtpInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [resendTimer, setResendTimer] = useState(0);
  const [errorMsg, setErrorMsg] = useState('');

  const timerRef = useRef(null);

  // Sync timers
  useEffect(() => {
    if (resendTimer > 0) {
      timerRef.current = setTimeout(() => {
        setResendTimer(prev => prev - 1);
      }, 1000);
    }
    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [resendTimer]);

  // Clean states on modal close/open
  useEffect(() => {
    if (isKycModalOpen) {
      setStep(1);
      setEmailInput('');
      setOtpInput('');
      setErrorMsg('');
      setResendTimer(0);
    }
  }, [isKycModalOpen]);

  if (!isKycModalOpen || !user) return null;

  const currentCollege = user.college || 'KIET';

  const handleSendOTP = async (e) => {
    if (e) e.preventDefault();
    setErrorMsg('');
    const targetEmail = emailInput.trim();

    if (!targetEmail) {
      setErrorMsg('Email address is required.');
      return;
    }

    if (!isCollegeEmail(targetEmail)) {
      setErrorMsg('Please enter a valid student/college email address (e.g. ends with .edu, .ac.in, etc.).');
      return;
    }

    // Verify it matches the user's selected college
    const isMatching = verifyEmailMatchesCollege(targetEmail, currentCollege);
    if (!isMatching) {
      setErrorMsg(`This email does not seem to belong to "${currentCollege}". Please use your official email for this campus.`);
      return;
    }

    setIsLoading(true);
    try {
      const generatedOtp = Math.floor(100000 + Math.random() * 900000).toString();
      const emailKey = targetEmail.toLowerCase();

      // 1. Store verification OTP in Firestore
      await setDoc(doc(db, 'otps', `kyc_${user.uid}`), {
        otp: generatedOtp,
        email: emailKey,
        createdAt: new Date().toISOString()
      });

      // 2. Dispatch email via send-otp API
      const isMobileApp = Capacitor.isNativePlatform();
      const apiUrl = isMobileApp ? `https://www.cohortnow.online/api/send-otp` : '/api/send-otp';

      const response = await fetch(apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ email: emailKey, otp: generatedOtp }),
      });

      const resData = await response.json();

      if (!response.ok) {
        throw new Error(resData.error || 'Failed to dispatch email.');
      }

      showSuccess('Verification code sent to your student email!');

      // Developer Mode convenience
      if (resData.otp) {
        console.log(`%c[KYC OTP Code (Dev Mode)] ${resData.otp}`, 'color: #ea580c; font-size: 16px; font-weight: bold;');
        if (resData.previewUrl) {
          console.log(`[Email Preview Link] ${resData.previewUrl}`);
        }
        showSuccess(`[Dev Mode] OTP is ${resData.otp} (Logged to console)`);
      }

      setStep(2);
      setResendTimer(30);
    } catch (err) {
      console.error(err);
      setErrorMsg(err.message || 'Failed to send OTP code. Please try again.');
      showError('Failed to send OTP code. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleVerifyOTP = async (e) => {
    if (e) e.preventDefault();
    setErrorMsg('');
    const targetOtp = otpInput.trim();

    if (!targetOtp || targetOtp.length !== 6) {
      setErrorMsg('Please enter the 6-digit verification code.');
      return;
    }

    setIsLoading(true);
    try {
      const otpDocRef = doc(db, 'otps', `kyc_${user.uid}`);
      const otpSnap = await getDoc(otpDocRef);

      if (!otpSnap.exists()) {
        setErrorMsg('Verification code not found. Please request a new one.');
        return;
      }

      const otpData = otpSnap.data();

      // Check if OTP matches
      if (otpData.otp !== targetOtp) {
        setErrorMsg('Invalid verification code. Please check your email and try again.');
        return;
      }

      // Check expiration (10 minutes)
      const createdAt = new Date(otpData.createdAt);
      const now = new Date();
      const diffMinutes = (now - createdAt) / 1000 / 60;
      if (diffMinutes > 10) {
        setErrorMsg('Verification code has expired. Please request a new one.');
        return;
      }

      // 3. Mark user as KYC verified in database and auth context
      const predicted = predictGenderFromName(otpData.email);
      await setKycVerified(otpData.email, predicted);

      showSuccess('Student email verified successfully!');
      setStep(3);
    } catch (err) {
      console.error(err);
      setErrorMsg('Failed to verify OTP. Please try again.');
      showError('Verification failed.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleResend = async () => {
    if (resendTimer > 0) return;
    await handleSendOTP();
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 overflow-y-auto animate-in fade-in duration-200">
      {/* Dark blur backdrop */}
      <div 
        className="fixed inset-0 bg-black/70 backdrop-blur-md transition-opacity" 
        onClick={step === 3 ? closeKycModal : undefined} 
      />

      {/* Glassmorphic Modal Body */}
      <motion.div 
        initial={{ scale: 0.95, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        exit={{ scale: 0.95, opacity: 0 }}
        className="relative bg-white/95 dark:bg-neutral-900/95 border border-neutral-200/80 dark:border-neutral-800/90 rounded-3xl shadow-2xl max-w-md w-full p-6 sm:p-8 z-10 my-auto transform transition-all backdrop-blur-2xl overflow-hidden"
      >
        {/* Glow backgrounds */}
        <div className="absolute top-0 right-0 -mr-20 -mt-20 w-44 h-44 rounded-full bg-primary-500/10 dark:bg-primary-500/5 blur-3xl pointer-events-none" />
        <div className="absolute bottom-0 left-0 -ml-20 -mb-20 w-44 h-44 rounded-full bg-pink-500/10 dark:bg-pink-500/5 blur-3xl pointer-events-none" />

        {/* Close Button */}
        {step !== 3 && (
          <button 
            onClick={closeKycModal}
            className="absolute top-4 right-4 p-1.5 rounded-full hover:bg-neutral-100 dark:hover:bg-neutral-800 text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-200 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        )}

        <AnimatePresence mode="wait">
          {step === 1 && (
            <motion.div
              key="step-email"
              initial={{ opacity: 0, x: -10 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 10 }}
              className="space-y-5 text-left"
            >
              <div className="space-y-2">
                <div className="w-12 h-12 rounded-2xl bg-primary-500/10 dark:bg-primary-500/20 text-primary-500 flex items-center justify-center">
                  <Building2 className="w-6 h-6" />
                </div>
                <h3 className="text-xl sm:text-2xl font-heading font-extrabold text-neutral-900 dark:text-white">
                  Verify Student Identity
                </h3>
                <p className="text-xs sm:text-sm text-neutral-500 dark:text-neutral-400 leading-relaxed">
                  Join the official <strong className="text-neutral-900 dark:text-white font-bold">{currentCollege}</strong> community. Verify your student email to post on the college wall, confessions tab, and unlock matchmaking.
                </p>
              </div>

              <form onSubmit={handleSendOTP} className="space-y-4 pt-2">
                <div>
                  <label className="block text-xs font-bold text-neutral-700 dark:text-neutral-300 uppercase tracking-wider mb-2">
                    Official College Email Address
                  </label>
                  <div className="relative">
                    <input
                      type="email"
                      required
                      value={emailInput}
                      onChange={(e) => {
                        setEmailInput(e.target.value);
                        setErrorMsg('');
                      }}
                      placeholder="e.g. kushal@kiet.edu"
                      className="w-full pl-10 pr-4 py-3 text-sm rounded-2xl bg-neutral-50 dark:bg-neutral-950 border border-neutral-200 dark:border-neutral-800 focus:outline-none focus:ring-2 focus:ring-primary-500 dark:focus:ring-primary-500 text-neutral-900 dark:text-neutral-100 transition-all font-medium"
                    />
                    <Mail className="w-4.5 h-4.5 text-neutral-400 absolute left-3.5 top-1/2 -translate-y-1/2" />
                  </div>
                </div>

                {errorMsg && (
                  <div className="p-3.5 rounded-2xl bg-rose-500/5 dark:bg-rose-500/10 border border-rose-500/20 text-rose-500 text-xs font-semibold flex items-start gap-2.5 leading-relaxed">
                    <ShieldAlert className="w-4 h-4 flex-shrink-0 mt-0.5 text-rose-500" />
                    <span>{errorMsg}</span>
                  </div>
                )}

                <Button 
                  type="submit" 
                  disabled={isLoading}
                  className="w-full py-3 bg-gradient-to-r from-primary-600 to-pink-600 text-white font-bold rounded-2xl shadow-lg active:scale-95 transition-all text-sm flex items-center justify-center gap-2"
                >
                  {isLoading ? (
                    <RefreshCw className="w-4 h-4 animate-spin" />
                  ) : (
                    <>
                      <span>Send Verification Code</span>
                      <ArrowRight className="w-4 h-4" />
                    </>
                  )}
                </Button>
              </form>
            </motion.div>
          )}

          {step === 2 && (
            <motion.div
              key="step-otp"
              initial={{ opacity: 0, x: -10 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 10 }}
              className="space-y-5 text-left"
            >
              <div className="space-y-2">
                <div className="w-12 h-12 rounded-2xl bg-orange-500/10 dark:bg-orange-500/20 text-orange-500 flex items-center justify-center">
                  <KeyRound className="w-6 h-6" />
                </div>
                <h3 className="text-xl sm:text-2xl font-heading font-extrabold text-neutral-900 dark:text-white">
                  Enter Verification Code
                </h3>
                <p className="text-xs sm:text-sm text-neutral-500 dark:text-neutral-400 leading-relaxed">
                  We sent a 6-digit code to <strong className="text-neutral-900 dark:text-white font-bold">{emailInput}</strong>. Enter it below to complete your campus verification.
                </p>
              </div>

              <form onSubmit={handleVerifyOTP} className="space-y-4 pt-2">
                <div>
                  <label className="block text-xs font-bold text-neutral-700 dark:text-neutral-300 uppercase tracking-wider mb-2">
                    6-Digit Code
                  </label>
                  <input
                    type="text"
