const parseNotifTime = (data) => {
      if (data.time?.toDate) return data.time.toDate();
      if (data.time) {
        const d = new Date(data.time);
        if (!isNaN(d.getTime())) return d;
      }
      if (data.createdAt) {
        const d = new Date(data.createdAt);
        if (!isNaN(d.getTime())) return d;
      }
      return new Date();
    };

