const getSharedInterests = (answersA, answersB) => {
    const list = [];
    QUESTIONS.forEach((q) => {
      if (answersA[q.id] === answersB[q.id]) {
        list.push({
          text: q.options[answersA[q.id]],
          Icon: q.icon
        });
      }
    });
    return list;
  };

const validateEmail = (email) => {
  const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return regex.test(email);
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [hasUnreadMessages, setHasUnreadMessages] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);
  const [isKycModalOpen, setIsKycModalOpen] = useState(false);

  const openKycModal = () => setIsKycModalOpen(true);
  const closeKycModal = () => setIsKycModalOpen(false);

  const setKycVerified = async (verifiedEmail, predictedGender = 'Neutral') => {
    await updateUser({
      kycVerified: true,
      kycEmail: verifiedEmail,
      kycGender: predictedGender
    });
  };

  const ensureCohortOfficialAndAutoFollow = async (currentProfile) => {
    if (!currentProfile || !currentProfile.uid) return;

    try {
      const cohortDocRef = doc(db, 'users', 'cohort_official');
      const cohortSnap = await getDoc(cohortDocRef);

      let cohortFollowers = [];
      if (!cohortSnap.exists()) {
        const cohortOfficialData = {
          uid: 'cohort_official',
          id: 'cohort_official',
          name: 'Cohort',
          username: 'cohort',
          email: 'cohort@official.com',
          college: 'Cohort Official Platform',
          isOfficial: true,
          bio: 'The official Cohort platform account. Connecting students across campuses. Follow for official feature updates, campus drops, and 24/7 support.',
          followers: currentProfile.uid !== 'cohort_official' ? [currentProfile.uid] : [],
          following: [],
          avatar: 'https://ui-avatars.com/api/?name=Cohort&background=9333ea&color=fff&bold=true&size=128',
          joinedDate: new Date().toISOString()
        };
        await setDoc(cohortDocRef, cohortOfficialData);
        cohortFollowers = cohortOfficialData.followers;
      } else {
        const data = cohortSnap.data();
        cohortFollowers = Array.isArray(data.followers) ? data.followers : [];
        if (currentProfile.uid !== 'cohort_official' && !cohortFollowers.includes(currentProfile.uid)) {
          cohortFollowers.push(currentProfile.uid);
          await updateDoc(cohortDocRef, { followers: cohortFollowers });
        }
      }

      // Auto-follow from current user perspective
      if (currentProfile.uid !== 'cohort_official') {
        const userFollowing = Array.isArray(currentProfile.following) ? currentProfile.following : [];
        if (!userFollowing.includes('cohort_official')) {
          const nextFollowing = [...userFollowing, 'cohort_official'];
          await updateDoc(doc(db, 'users', currentProfile.uid), { following: nextFollowing });
          setUser(prev => prev ? ({ ...prev, following: nextFollowing }) : prev);
        }
      }
    } catch (err) {
      console.error('Error in ensureCohortOfficialAndAutoFollow:', err);
    }
  };

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      setIsLoading(true);
      if (firebaseUser) {
        try {
          // Get user metadata from Firestore
          const docRef = doc(db, 'users', firebaseUser.uid);
          const docSnap = await getDoc(docRef);
          if (docSnap.exists()) {
            const profileData = {
              id: firebaseUser.uid,
              uid: firebaseUser.uid,
              ...docSnap.data()
            };
            setUser(profileData);
            localStorage.setItem(`user_profile_${firebaseUser.uid}`, JSON.stringify(profileData));
            setIsAuthenticated(true);
            ensureCohortOfficialAndAutoFollow(profileData);
          } else {
            // New Google user or profile missing in Firestore
            const displayName = firebaseUser.displayName || firebaseUser.email.split('@')[0];
            const newProfile = {
              name: displayName,
              email: firebaseUser.email,
              college: 'KIET',
              avatar: firebaseUser.photoURL || `https://ui-avatars.com/api/?name=${encodeURIComponent(displayName)}&background=0ea5e9&color=fff&bold=true&size=128`,
              joinedDate: new Date().toISOString()
            };
            await setDoc(docRef, newProfile);
            const profileData = {
              id: firebaseUser.uid,
              uid: firebaseUser.uid,
              ...newProfile
            };
            setUser(profileData);
            localStorage.setItem(`user_profile_${firebaseUser.uid}`, JSON.stringify(profileData));
            setIsAuthenticated(true);
            ensureCohortOfficialAndAutoFollow(profileData);
          }
        } catch (error) {
          console.error('Failed to retrieve user profile from Firestore:', error);
          const cached = localStorage.getItem(`user_profile_${firebaseUser.uid}`);
          if (cached) {
            setUser(JSON.parse(cached));
          } else {
            const displayName = firebaseUser.displayName || firebaseUser.email.split('@')[0];
            setUser({
              id: firebaseUser.uid,
              uid: firebaseUser.uid,
              email: firebaseUser.email,
              name: displayName,
              college: 'KIET',
              avatar: firebaseUser.photoURL || `https://ui-avatars.com/api/?name=${encodeURIComponent(displayName)}&background=0ea5e9&color=fff&bold=true&size=128`
            });
          }
          setIsAuthenticated(true);
        }
      } else {
        setUser(null);
        setIsAuthenticated(false);
      }
      setIsLoading(false);
    });

    return () => unsubscribe();
  }, []);

  // Real-time Firestore Listener for Unread Direct Messages & Count
  useEffect(() => {
    if (!user?.uid) {
      setHasUnreadMessages(false);
      setUnreadCount(0);
      return;
    }

    const unsub = onSnapshot(collection(db, 'messages'), (snapshot) => {
      const threads = [];

      snapshot.forEach(d => {
        const data = d.data();
        const isParticipant = (data.participants && data.participants.includes(user.uid)) ||
                              data.recipientUid === user.uid ||
                              data.createdBy === user.uid;

        if (isParticipant && data.hiddenFor?.[user.uid] !== true) {
          threads.push({
            id: d.id,
            ...data
          });
        }
      });

      // Deduplicate conversation threads for the same user pair (matching Messages.jsx logic)
      const uniqueThreadsMap = new Map();
      threads.forEach(t => {
        const otherUid = (t.participants || []).find(p => p !== user.uid) || t.recipientUid;
        const key = otherUid || t.name || t.id;
        if (!uniqueThreadsMap.has(key)) {
          uniqueThreadsMap.set(key, t);
        } else {
          const prev = uniqueThreadsMap.get(key);
          const tMsgCount = t.messages?.length || 0;
          const prevMsgCount = prev.messages?.length || 0;
          if (tMsgCount > prevMsgCount) {
            uniqueThreadsMap.set(key, t);
          }
        }
      });

      let totalUnread = 0;
      uniqueThreadsMap.forEach(t => {
        const msgs = t.messages || [];
        const unreadMsgsInThread = msgs.filter(m => {
          if (!m) return false;
          const senderId = m.senderUid || (typeof m.sender === 'object' ? m.sender?.uid : m.sender) || m.uid || m.authorUid;
          const isFromMe = (senderId && senderId === user.uid) ||
                           (typeof m.sender === 'string' && (m.sender === user.uid || m.sender === 'me')) ||
                           (m.senderName && m.senderName === user.name);
          const isFromOther = !isFromMe;
          const isRead = Array.isArray(m.readBy) && m.readBy.includes(user.uid);
          const isDeleted = Array.isArray(m.deletedFor) && m.deletedFor.includes(user.uid);
          return isFromOther && !isRead && !isDeleted;
        }).length;

        totalUnread += unreadMsgsInThread;
      });

      setUnreadCount(totalUnread);
      setHasUnreadMessages(totalUnread > 0);
    }, (err) => {
      console.error('Unread messages listener error:', err);
    });

    return () => unsub();
  }, [user?.uid, user?.name, user?.email]);

  // Register for push notifications on native mobile when logged in
  useEffect(() => {
    if (!user?.uid || !Capacitor.isNativePlatform()) return;

    const registerPush = async () => {
      try {
        const { PushNotifications } = await import('@capacitor/push-notifications');

        let permStatus = await PushNotifications.checkPermissions();
        if (permStatus.receive === 'prompt') {
          permStatus = await PushNotifications.requestPermissions();
        }

        if (permStatus.receive === 'granted') {
          await PushNotifications.register();

          await PushNotifications.addListener('registration', async (token) => {
            if (token?.value && user?.uid) {
              const userRef = doc(db, 'users', user.uid);
              await updateDoc(userRef, { fcmToken: token.value }).catch(err => {
                console.warn('Failed to save FCM token to Firestore:', err);
              });
            }
          });

          await PushNotifications.addListener('registrationError', (err) => {
            console.error('FCM registration error:', err);
          });
        }
      } catch (err) {
        console.warn('Push registration hook error:', err);
      }
    };

    registerPush();
  }, [user?.uid]);

  const loginWithGoogle = async () => {
    if (Capacitor.isNativePlatform()) {
      const result = await FirebaseAuthentication.signInWithGoogle();
      const idToken = result.credential?.idToken || result.idToken;
      if (!idToken) {
        throw new Error('Google Sign-In failed: No ID Token received from native SDK.');
      }
      const credential = GoogleAuthProvider.credential(idToken);
      const userCredential = await signInWithCredential(auth, credential);
      return userCredential.user;
    } else {
      const provider = new GoogleAuthProvider();
      provider.setCustomParameters({ prompt: 'select_account' });
      const result = await signInWithPopup(auth, provider);
      return result.user;
    }
  };

  const login = async (emailOrUsername, password) => {
    let emailToUse = emailOrUsername.trim();
    if (!emailToUse.includes('@')) {
      const cleanUsername = emailToUse.replace(/^@/, '').toLowerCase();
      try {
        const usersRef = collection(db, 'users');
        const q1 = query(usersRef, where('username', '==', cleanUsername));
        const snap1 = await getDocs(q1);
        if (!snap1.empty && snap1.docs[0].data()?.email) {
          emailToUse = snap1.docs[0].data().email;
        } else {
          const q2 = query(usersRef, where('usernameHandle', '==', cleanUsername));
          const snap2 = await getDocs(q2);
          if (!snap2.empty && snap2.docs[0].data()?.email) {
            emailToUse = snap2.docs[0].data().email;
          } else {
            emailToUse = `${cleanUsername}@student.edu`;
          }
        }
      } catch (err) {
        console.error('Username lookup error:', err);
        emailToUse = `${cleanUsername}@student.edu`;
      }
    }
    return signInWithEmailAndPassword(auth, emailToUse, password);
  };

  const setPasswordForUser = async (newPassword) => {
    if (!auth.currentUser) {
      console.error('[setPasswordForUser] No authenticated user found.');
      throw new Error("No authenticated user");
    }

    try {
      console.log('[setPasswordForUser] Attempting to update password for:', auth.currentUser.email);
      await updatePassword(auth.currentUser, newPassword);
      console.log('[setPasswordForUser] Password updated successfully on first try.');
    } catch (error) {
      console.warn('[setPasswordForUser] Update password failed. Error code:', error.code, 'Error message:', error.message);
      if (error.code === 'auth/requires-recent-login') {
        const tempPassword = localStorage.getItem('cohort_temp_signup_password');
        console.log('[setPasswordForUser] Found tempPassword in localStorage:', !!tempPassword);
        if (tempPassword) {
          try {
            const { EmailAuthProvider, reauthenticateWithCredential } = await import('firebase/auth');
            console.log('[setPasswordForUser] Re-authenticating with temp password...');
            const credential = EmailAuthProvider.credential(auth.currentUser.email, tempPassword);
            await reauthenticateWithCredential(auth.currentUser, credential);
            console.log('[setPasswordForUser] Re-authentication successful. Retrying password update...');
            await updatePassword(auth.currentUser, newPassword);
            console.log('[setPasswordForUser] Password updated successfully after re-authentication.');
            localStorage.removeItem('cohort_temp_signup_password');
          } catch (reauthErr) {
            console.error('[setPasswordForUser] Re-authentication or retried update failed:', reauthErr);
            throw reauthErr;
          }
        } else {
          console.error('[setPasswordForUser] auth/requires-recent-login occurred but no temporary signup password was found in localStorage.');
          throw error;
        }
      } else {
        throw error;
      }
    }

    const uid = auth.currentUser.uid;
    const docRef = doc(db, 'users', uid);
    await updateDoc(docRef, { hasPassword: true });
    setUser(prev => ({ ...prev, hasPassword: true }));

    // Clean up temporary password on success
    localStorage.removeItem('cohort_temp_signup_password');
  };

  const signup = async (userData) => {
    const { email, password, name, college } = userData;
    const userCredential = await createUserWithEmailAndPassword(auth, email, password);
    const uid = userCredential.user.uid;

    const isCollege = isCollegeEmail(email);
    const isMatching = isCollege && verifyEmailMatchesCollege(email, college || 'KIET');

    const profile = {
      name: name || 'Student',
      email: email,
      college: college || 'KIET',
      avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(name || email)}`,
      joinedDate: new Date().toISOString(),
      hasPassword: true,
      kycVerified: isMatching,
      kycEmail: isMatching ? email : null,
      kycGender: isMatching ? predictGenderFromName(email) : null
    };

    // Save profile metadata inside Firestore
    await setDoc(doc(db, 'users', uid), profile);
    setUser({ id: uid, uid, ...profile });
    setIsAuthenticated(true);
    return userCredential.user;
  };

  const requestLogout = () => {
    setIsLogoutModalOpen(true);
  };

  const cancelLogout = () => {
    setIsLogoutModalOpen(false);
  };

  const confirmLogout = async () => {
    setIsLogoutModalOpen(false);
    if (user?.uid) {
      localStorage.removeItem(`user_profile_${user.uid}`);
    }
    setUser(null);
    setIsAuthenticated(false);
    setHasUnreadMessages(false);
    return await signOut(auth);
  };

  const logout = () => {
    requestLogout();
  };

  const forceLogout = async () => {
    setIsLogoutModalOpen(false);
    if (auth.currentUser?.uid) {
      localStorage.removeItem(`user_profile_${auth.currentUser.uid}`);
    }
    setUser(null);
    setIsAuthenticated(false);
    setHasUnreadMessages(false);
    return await signOut(auth);
  };

  const syncUserProfileAcrossFirestore = async (uid, newName, newAvatar, newUsername) => {
    if (!uid) return;

    try {
      const batch = writeBatch(db);
      let batchCount = 0;

      // 1. Sync Posts where user is author or has comments
      const postsRef = collection(db, 'posts');
      const postsSnap = await getDocs(postsRef);

      postsSnap.forEach((docSnap) => {
        const post = docSnap.data();
        let postUpdated = false;
        const postRef = doc(db, 'posts', docSnap.id);
        const updatePayload = {};

        // Author sync
        if (post.author?.uid === uid || post.authorUid === uid) {
          if (newName) updatePayload['author.name'] = newName;
          if (newAvatar) updatePayload['author.avatar'] = newAvatar;
          if (newUsername) updatePayload['author.username'] = newUsername;
          postUpdated = true;
        }

        // Comments array sync
        if (Array.isArray(post.comments) && post.comments.length > 0) {
          let commentsUpdated = false;
          const updatedComments = post.comments.map(c => {
            if (c.authorUid === uid || c.author?.uid === uid || c.uid === uid) {
              commentsUpdated = true;
              return {
                ...c,
                authorName: newName || c.authorName,
                authorAvatar: newAvatar || c.authorAvatar,
                author: {
                  ...(c.author || {}),
                  name: newName || c.author?.name,
                  avatar: newAvatar || c.author?.avatar
                }
              };
            }
            return c;
          });

          if (commentsUpdated) {
            updatePayload.comments = updatedComments;
            postUpdated = true;
          }
        }

        if (postUpdated) {
          batch.update(postRef, updatePayload);
          batchCount++;
        }
      });

      // 2. Sync Messages / Conversations collection
      const messagesRef = collection(db, 'messages');
      const messagesSnap = await getDocs(messagesRef);

      messagesSnap.forEach((docSnap) => {
        const chat = docSnap.data();
        const chatRef = doc(db, 'messages', docSnap.id);
        let chatUpdated = false;
        const updatePayload = {};

        // Sync participant maps
        if (Array.isArray(chat.participants) && chat.participants.includes(uid)) {
          if (chat.participantNames) {
            updatePayload[`participantNames.${uid}`] = newName;
            chatUpdated = true;
          }
          if (chat.participantAvatars) {
            updatePayload[`participantAvatars.${uid}`] = newAvatar;
            chatUpdated = true;
          }
          if (chat.lastSenderUid === uid) {
            if (newName) updatePayload.lastSenderName = newName;
            if (newAvatar) updatePayload.lastSenderAvatar = newAvatar;
            chatUpdated = true;
          }
        }

        // Sync message array inside thread
        if (Array.isArray(chat.messages) && chat.messages.length > 0) {
          let msgsUpdated = false;
          const updatedMsgs = chat.messages.map(m => {
            if (m.senderUid === uid || m.sender?.uid === uid) {
              msgsUpdated = true;
              return {
                ...m,
                senderName: newName || m.senderName,
                senderAvatar: newAvatar || m.senderAvatar,
                sender: m.sender ? {
                  ...m.sender,
                  name: newName || m.sender.name,
                  avatar: newAvatar || m.sender.avatar
                } : undefined
              };
            }
            return m;
          });

          if (msgsUpdated) {
            updatePayload.messages = updatedMsgs;
            chatUpdated = true;
          }
        }

        if (chatUpdated) {
          batch.update(chatRef, updatePayload);
          batchCount++;
        }
      });

      // 3. Sync Community Messages collection
      const commMsgsRef = collection(db, 'community-messages');
      const commMsgsSnap = await getDocs(commMsgsRef);

      commMsgsSnap.forEach((docSnap) => {
        const msg = docSnap.data();
        if (msg.senderUid === uid || msg.sender?.uid === uid) {
          const msgRef = doc(db, 'community-messages', docSnap.id);
          const msgUpdate = {};
          if (newName) {
            msgUpdate.senderName = newName;
            msgUpdate['sender.name'] = newName;
          }
          if (newAvatar) {
            msgUpdate.senderAvatar = newAvatar;
            msgUpdate['sender.avatar'] = newAvatar;
          }
          batch.update(msgRef, msgUpdate);
          batchCount++;
        }
      });

      // 4. Sync Notifications
      const notifsRef = collection(db, 'notifications');
      const notifsSnap = await getDocs(notifsRef);

      notifsSnap.forEach((docSnap) => {
        const notif = docSnap.data();
        if (notif.senderUid === uid) {
          const notifRef = doc(db, 'notifications', docSnap.id);
          const notifUpdate = {};
          if (newName) notifUpdate.senderName = newName;
          if (newAvatar) notifUpdate.senderAvatar = newAvatar;
          batch.update(notifRef, notifUpdate);
          batchCount++;
        }
      });

      if (batchCount > 0) {
        await batch.commit();
        console.log(`Synced user profile across ${batchCount} Firestore documents.`);
      }
    } catch (err) {
      console.error('Error syncing profile across Firestore:', err);
    }
  };

  const updateUser = async (updates) => {
    if (!auth.currentUser) return;
    const uid = auth.currentUser.uid;
    const docRef = doc(db, 'users', uid);
    await updateDoc(docRef, updates);

    const newName = updates.name;
    const newAvatar = updates.avatar;
    const newUsername = updates.username;

    setUser(prev => {
      const updated = { ...prev, ...updates };
      localStorage.setItem(`user_profile_${uid}`, JSON.stringify(updated));
      return updated;
    });

    if (newName || newAvatar || newUsername) {
      syncUserProfileAcrossFirestore(uid, newName, newAvatar, newUsername);
    }
  };

  const requestPasswordReset = (email) => {
    return sendPasswordResetEmail(auth, email);
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        isAuthenticated,
        isLoading,
        hasUnreadMessages,
        setHasUnreadMessages,
        unreadCount,
        setUnreadCount,
        loginWithGoogle,
        login,
        signup,
        setPasswordForUser,
        logout,
        requestLogout,
        confirmLogout,
        cancelLogout,
        forceLogout,
        updateUser,
        requestPasswordReset,
        isKycModalOpen,
        openKycModal,
        closeKycModal,
        setKycVerified
      }}
    >
      {children}

      {/* Modern Logout Confirmation Modal */}
      {isLogoutModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6 overflow-y-auto animate-in fade-in duration-200">
          {/* Dark Glass Backdrop */}
          <div
            className="fixed inset-0 bg-black/75 backdrop-blur-md transition-opacity"
            onClick={cancelLogout}
          />

          {/* Elevated Glass Card */}
          <div className="relative bg-white/95 dark:bg-neutral-900/95 border border-neutral-200/80 dark:border-neutral-800/90 rounded-3xl shadow-2xl max-w-sm w-full p-6 text-center z-10 my-auto transform transition-all scale-100 backdrop-blur-2xl">
            {/* Icon Badge */}
            <div className="w-16 h-16 rounded-full bg-rose-500/15 text-rose-500 flex items-center justify-center mx-auto mb-4 border border-rose-500/30 shadow-md">
              <LogOut className="w-8 h-8 stroke-[2.5] animate-pulse" />
            </div>

            <h3 className="text-xl font-heading font-extrabold text-neutral-900 dark:text-white tracking-tight mb-2">
              Confirm Logout
            </h3>
            <p className="text-xs sm:text-sm text-neutral-600 dark:text-neutral-400 leading-relaxed mb-6">
              Are you sure you want to log out? You will need to log back in to access your campus messages and posts.
            </p>

            {/* Action Buttons */}
            <div className="flex items-center gap-3">
              <button
                type="button"
                onClick={cancelLogout}
                className="flex-1 py-2.5 px-4 rounded-xl border border-neutral-200 dark:border-neutral-700/80 text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800 font-bold text-xs transition-all cursor-pointer"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={confirmLogout}
                className="flex-1 py-2.5 px-4 rounded-xl bg-gradient-to-r from-rose-600 to-red-600 hover:from-rose-500 hover:to-red-500 text-white font-extrabold text-xs shadow-lg shadow-rose-500/25 active:scale-95 transition-all cursor-pointer"
              >
                Yes, Logout
              </button>
            </div>
          </div>
        </div>
      )}
    </AuthContext.Provider>
  );
};

export default function MakeAFriend() {
  const { user, updateUser, openKycModal } = useAuth();
  const { showSuccess, showError } = useNotification();
  const navigate = useNavigate();

  // Step state: 'onboarding' | 'match_ready' | 'matching_animation' | 'swiping'
  const [step, setStep] = useState('onboarding');
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [answers, setAnswers] = useState({});
  const [genderConfirmation, setGenderConfirmation] = useState('Male');

  // Swipe view states
  const [genderFilter, setGenderFilter] = useState('All');
  const [profiles, setProfiles] = useState([]);
  const [currentProfileIndex, setCurrentProfileIndex] = useState(0);
  const [matchingConsoleLogs, setMatchingConsoleLogs] = useState([]);
  const [swipeDirection, setSwipeDirection] = useState(null); // 'left' | 'right' | null
  const [isMatchOverlayOpen, setIsMatchOverlayOpen] = useState(false);
  const [matchedProfile, setMatchedProfile] = useState(null);

  // New liked profiles state
  const [likedProfiles, setLikedProfiles] = useState([]);
  const [viewMode, setViewMode] = useState('swipe'); // 'swipe' | 'liked'
  const [campusFilter, setCampusFilter] = useState('On Campus'); // 'On Campus' | 'Outside Campus'

  // Initialize state based on user loaded makeAFriendProfile
  useEffect(() => {
    if (user?.makeAFriendProfile?.completed) {
      setAnswers(user.makeAFriendProfile.answers || {});
      setCampusFilter(user.makeAFriendProfile.campusFilter || 'On Campus');
      if (step === 'onboarding') {
        setStep('swiping');
      }
    } else {
      setStep('onboarding');
      if (user?.gender && user.gender !== 'Prefer not to say') {
        setGenderConfirmation(user.gender);
      }
    }
  }, [user]);

  // Load and match profiles when in swiping step
  useEffect(() => {
    if (step === 'swiping') {
      fetchAndCalculateMatches();
    }
  }, [step, genderFilter, campusFilter]);

  // Fetch liked profiles when user swiped state changes
  useEffect(() => {
    if (step === 'swiping' && user?.makeAFriendProfile?.swiped) {
      fetchLikedProfiles();
    }
  }, [step, user?.makeAFriendProfile?.swiped]);

  // Fetch liked profiles from DB
  const fetchLikedProfiles = async () => {
    try {
      const currentSwiped = user?.makeAFriendProfile?.swiped || {};
      const likedUids = Object.keys(currentSwiped).filter(uid => currentSwiped[uid] === 'right');

      if (likedUids.length === 0) {
        setLikedProfiles([]);
        return;
      }

      const usersSnap = await getDocs(collection(db, 'users'));
      const rawList = [];
      usersSnap.forEach((d) => {
        const uid = d.id;
        if (likedUids.includes(uid)) {
          const data = d.data();
          rawList.push({
            uid,
            name: data.name || 'Anonymous Student',
            avatar: data.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(uid)}`,
            email: data.email,
            updatedAt: data.updatedAt || data.joinedDate || 0
          });
        }
      });

      // Deduplicate liked profiles by normalized name or email to avoid duplicate user accounts
      const uniqueMap = new Map();
      rawList.forEach((item) => {
        const normName = item.name.toLowerCase().trim();
        const firstName = normName.split(' ')[0];
        const key = item.email ? item.email.toLowerCase() : firstName;

        if (!uniqueMap.has(key)) {
          uniqueMap.set(key, item);
        } else {
          const existing = uniqueMap.get(key);
          if (item.name.length > existing.name.length || item.updatedAt > existing.updatedAt) {
            uniqueMap.set(key, item);
          }
        }
      });

      setLikedProfiles(Array.from(uniqueMap.values()));
    } catch (err) {
      console.error('Error fetching liked profiles:', err);
    }
  };

  // Fetch users and calculate match percentage
  const fetchAndCalculateMatches = async () => {
    try {
      const usersSnap = await getDocs(collection(db, 'users'));
      const list = [];
      const currentSwiped = user?.makeAFriendProfile?.swiped || {};
      const currentAnswers = user?.makeAFriendProfile?.answers || answers;

      usersSnap.forEach((d) => {
        const data = d.data();
        const uid = d.id;

        // Skip current user, official Cohort account, already swiped profiles, and users who haven't completed the quiz
        if (
          uid === user.uid ||
          uid === 'cohort_official' ||
          (data.username || '').toLowerCase() === 'cohort' ||
          data.isOfficial === true ||
          currentSwiped[uid] ||
          !data.makeAFriendProfile?.completed
        ) {
          return;
        }

        // Resolve gender (use Firestore gender or deterministic fallback if undefined/prefer not to say)
        const resolvedGender = data.gender && data.gender !== 'Prefer not to say'
          ? data.gender
          : (uid.charCodeAt(0) % 2 === 0 ? 'Male' : 'Female');

        // Apply gender filter
        const matchesGender = () => {
          if (genderFilter === 'All') return true;
          return resolvedGender.toLowerCase() === genderFilter.toLowerCase();
        };

        if (!matchesGender()) {
          return;
        }

        // Apply campus filter
        const matchesCampus = () => {
          const myCollege = (user?.college || 'KIET').toLowerCase().trim();
          const theirCollege = (data.college || 'KIET').toLowerCase().trim();
          if (campusFilter === 'On Campus' || campusFilter === 'Same College') {
            return myCollege === theirCollege;
          } else if (campusFilter === 'Outside Campus') {
            return myCollege !== theirCollege;
          }
          return true; // 'All' or 'All Campuses'
        };

        if (!matchesCampus()) {
          return;
        }

        // Retrieve the user's completed makeAFriendProfile
        const targetProfile = data.makeAFriendProfile;
        const matchPct = calculateCompatibility(currentAnswers, targetProfile.answers, user.uid, uid, user.college, data.college);

        list.push({
          uid,
          id: uid,
          name: data.name || 'Anonymous Student',
          college: data.college || 'KIET',
          avatar: data.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(uid)}`,
          gender: resolvedGender,
          answers: targetProfile.answers,
          matchPercentage: matchPct,
          sharedInterests: getSharedInterests(currentAnswers, targetProfile.answers)
        });
      });

      // Sort by match percentage desc
      list.sort((a, b) => b.matchPercentage - a.matchPercentage);
      setProfiles(list);
      setCurrentProfileIndex(0);
    } catch (err) {
      console.error('Error fetching match profiles:', err);
      showError('Failed to fetch matched profiles.');
    }
  };

  // Compute shared interests list
  const getSharedInterests = (answersA, answersB) => {
    const list = [];
    QUESTIONS.forEach((q) => {
      if (answersA[q.id] === answersB[q.id]) {
        list.push({
          text: q.options[answersA[q.id]],
          Icon: q.icon
        });
      }
    });
    return list;
  };

  // Custom compatibility algorithm
  const calculateCompatibility = (answersA, answersB, uidA, uidB, collegeA, collegeB) => {
    let matchCount = 0;
    QUESTIONS.forEach((q) => {
      if (answersA[q.id] === answersB[q.id]) {
        matchCount++;
      }
    });

    let base = 45 + matchCount * 2.5;

    // High compatibility boost (+20%) for Same College peers
    if (collegeA && collegeB && collegeA.toLowerCase().trim() === collegeB.toLowerCase().trim()) {
      base += 20;
    }

    const combinedUid = (uidA || '') + (uidB || '');
    let hash = 0;
    for (let i = 0; i < combinedUid.length; i++) {
      hash = combinedUid.charCodeAt(i) + ((hash << 5) - hash);
    }
    const variance = (Math.abs(hash) % 30) / 10;
    const finalPct = base + variance;

    return Math.min(100, Math.round(finalPct * 10) / 10);
  };

  const handleSelectOption = (questionId, optionIndex) => {
    const nextAnswers = { ...answers, [questionId]: optionIndex };
    setAnswers(nextAnswers);

    setTimeout(() => {
      if (currentQuestionIndex < QUESTIONS.length - 1) {
        setCurrentQuestionIndex((prev) => prev + 1);
      } else {
        setStep('match_ready');
      }
    }, 250);
  };

  const handleOnboardingBack = () => {
    if (currentQuestionIndex > 0) {
      setCurrentQuestionIndex((prev) => prev - 1);
    }
  };

  const submitOnboardingAnswers = async () => {
    try {
      setViewMode('swipe');

      const friendProfile = {
        answers,
        completed: true,
        swiped: user?.makeAFriendProfile?.swiped || {},
        campusFilter
      };

      await updateUser({
        makeAFriendProfile: friendProfile,
        gender: genderConfirmation
      });

      setStep('matching_animation');
      runMatchingSequence();
    } catch (err) {
      console.error('Failed to submit onboarding answers:', err);
      showError('Something went wrong. Please try again.');
    }
  };

  const runMatchingSequence = () => {
    const logs = [
      'Launching Campus Vibe Checker...',
      'Syncing student interests & profiles...',
      'Analyzing personality maps & hobbies...',
      'Scanning campus cohorts...',
      'Calibrating vibe alignments...',
      'Vibe twins located! Loading profiles...'
    ];

    setMatchingConsoleLogs([]);
    logs.forEach((logText, idx) => {
      setTimeout(() => {
        setMatchingConsoleLogs((prev) => [...prev, logText]);
        if (idx === logs.length - 1) {
          setTimeout(() => {
            setStep('swiping');
          }, 1000);
        }
      }, (idx + 1) * 600);
    });
  };

  // Swiping functions (Fixed skipping bug)
  const handleSwipe = async (direction) => {
    if (profiles.length === 0 || currentProfileIndex >= profiles.length) return;

    const targetProfile = profiles[currentProfileIndex];
    setSwipeDirection(direction);

    // Advance card index smoothly without triggering re-fetch reset
    setTimeout(() => {
      setCurrentProfileIndex((prev) => prev + 1);
      setSwipeDirection(null);
    }, 250);

    const updatedSwipes = {
      ...(user?.makeAFriendProfile?.swiped || {}),
      [targetProfile.uid]: direction
    };

    const updatedProfile = {
      ...user.makeAFriendProfile,
      swiped: updatedSwipes
    };

    try {
      await updateUser({
        makeAFriendProfile: updatedProfile
      });
    } catch (e) {
      console.error('Error updating swipe profile:', e);
    }

    if (direction === 'right') {
      try {
        await addDoc(collection(db, 'notifications'), {
          recipientUid: targetProfile.uid,
          senderUid: user.uid,
          senderName: user.name || 'Student',
          senderAvatar: user.avatar || '',
          type: 'like',
          text: `you were right swiped by ${user.name || 'Student'}.`,
          read: false,
          time: new Date()
        });

        const targetUserSnap = await getDocs(collection(db, 'users'));
        let targetUserLikedUs = false;
        targetUserSnap.forEach((d) => {
          if (d.id === targetProfile.uid) {
            const swipedList = d.data()?.makeAFriendProfile?.swiped || {};
            if (swipedList[user.uid] === 'right') {
              targetUserLikedUs = true;
            }
          }
        });

        const isMatch = targetUserLikedUs || Math.random() < 0.25;

        if (isMatch) {
          setMatchedProfile(targetProfile);
          setIsMatchOverlayOpen(true);
        }
      } catch (e) {
        console.error('Error handling right swipe match:', e);
      }
    }
  };

  const handleResetSwipes = async () => {
    try {
      const updatedProfile = {
        ...user.makeAFriendProfile,
        swiped: {}
      };
      await updateUser({
        makeAFriendProfile: updatedProfile
      });
      showSuccess('Swipes reset! You can start matching again.');
      fetchAndCalculateMatches();
    } catch (e) {
      console.error(e);
      showError('Failed to reset swipes.');
    }
  };

  const handleRetakeQuiz = () => {
    setStep('onboarding');
    setCurrentQuestionIndex(0);
  };

  const startChat = (profile) => {
    setIsMatchOverlayOpen(false);
    navigate(`/messages?recipientUid=${profile.uid}&recipientName=${encodeURIComponent(profile.name)}`);
  };

  // Questionnaire Helper
  const currentCategory = QUESTIONS[currentQuestionIndex]?.category;
  const currentQuestion = QUESTIONS[currentQuestionIndex];
  const questionNumber = currentQuestionIndex + 1;
  const progressPercent = (questionNumber / QUESTIONS.length) * 100;
  const QuestionIcon = currentQuestion?.icon;

  return (
