              Cancel
            </Button>
            <button
              type="submit"
              onClick={handleCreatePoll}
              className="flex-1 rounded-2xl py-3 text-xs font-bold bg-white text-neutral-900 hover:bg-neutral-200 transition-all cursor-pointer shadow-md"
