const handleCancelReplyMode = () => {
    if (replyingToComment) {
      const username = replyingToComment.username;
      if (username) {
        const tagPattern = new RegExp(`^@${username}\\s*`, 'i');
        setNewComment(prev => prev.replace(tagPattern, ''));
      }
    }
    setReplyingToComment(null);
  };

const handleDeleteMsgForMe = async (msgId) => {
    if (!user?.uid || !msgId) return;
    const targetColl = isCollegeRoom ? 'community-messages' : `userCommunities/${selectedRoom.id}/messages`;
    try {
      await updateDoc(doc(db, targetColl, msgId), {
        deletedFor: arrayUnion(user.uid)
      });
      showSuccess('Message deleted for you 🗑️');
      setMsgToDeleteModal(null);
    } catch (e) { console.error(e); }
  };

const handleBulkDeleteSelected = async () => {
    if (selectedMsgIds.length === 0) return;
    const targetColl = isCollegeRoom ? 'community-messages' : `userCommunities/${selectedRoom.id}/messages`;
    try {
      for (const id of selectedMsgIds) {
        await updateDoc(doc(db, targetColl, id), { deletedFor: arrayUnion(user.uid) });
      }
      showSuccess(`${selectedMsgIds.length} messages deleted for you`);
      setSelectedMsgIds([]);
      setIsSelectMode(false);
    } catch (e) { console.error(e); }
  };

const handleTouchMove = (e) => {
    if (!isDragging || e.touches.length !== 1) return;
    const touch = e.touches[0];
    const newX = touch.clientX - dragStart.current.x;
    const newY = touch.clientY - dragStart.current.y;
    setPosition({ x: newX, y: newY });
  };

const handleClearAll = async () => {
    setList([]);
    showSuccess('All notifications cleared.');

    const batch = writeBatch(db);
    list.forEach(n => {
      if (n.docId) {
        const docRef = doc(db, 'notifications', n.docId);
        batch.delete(docRef);
      }
    });
    try {
      await batch.commit();
    } catch (e) {
      console.error('Failed to clear database logs:', e);
    }
  };

const handleSaveInlineEdit = async () => {
    if (!editPostContent.trim()) return;
    try {
      const postId = post.docId || post.id;
      await updateDoc(doc(db, 'posts', postId), { content: editPostContent.trim() });
      post.content = editPostContent.trim();
      setIsEditingPost(false);
      setShowPostMenu(false);
      showSuccess('Post updated successfully!');
    } catch (err) {
      console.error('Failed to edit post:', err);
    }
  };

const ExpandableCaption = ({ text, maxLength = 200, className = '' }) => {
  const [isExpanded, setIsExpanded] = useState(false);

  if (!text) return null;

  const lines = text.split('\n');
  const hasTooManyLines = lines.length > 4;
  const shouldTruncate = text.length > maxLength || hasTooManyLines;

  let displayText = text;
  if (!isExpanded && shouldTruncate) {
    if (hasTooManyLines && lines.length > 4) {
      displayText = lines.slice(0, 4).join('\n').trim() + '...';
    } else {
      displayText = text.slice(0, maxLength).trim() + '...';
    }
  }

  return (
    <div className={className}>
      <p className="text-neutral-800 dark:text-neutral-200 leading-relaxed whitespace-pre-wrap break-words inline">
        <FormattedText text={displayText} />
      </p>
      {shouldTruncate && (
        <button
          type="button"
          onClick={(e) => {
            e.stopPropagation();
            setIsExpanded(!isExpanded);
          }}
          className="ml-1.5 text-xs font-bold text-purple-600 hover:text-purple-700 dark:text-purple-400 dark:hover:text-purple-300 transition-colors inline-block cursor-pointer"
        >
          {isExpanded ? 'See less' : 'See more'}
        </button>
      )}
    </div>
  );
};

