      <!-- Soft magenta center backdrop backing the logo -->
      <circle cx="1024" cy="500" r="350" fill="#FF2A85" opacity="0.08" filter="url(#glow-pink)" />

      <!-- Centered Logo Icon (Exactly matching public/logo.svg contents) -->
