              >
                <div className="w-10 h-10 rounded-xl bg-amber-500/10 dark:bg-amber-500/20 text-amber-500 flex items-center justify-center flex-shrink-0 group-hover:scale-110 transition-transform">
                  <Zap className="w-5 h-5 fill-amber-500/20" />
                </div>
                <div>
                  <h4 className="font-bold text-sm text-neutral-900 dark:text-white flex items-center gap-xs">
                    Reshare Instantly
                  </h4>
                  <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-xs leading-normal">
                    Post directly to your campus feed without adding a caption.
                  </p>
                </div>
              </button>

              <button
                type="button"
                onClick={() => setReshareMode('thoughts')}
                className="w-full p-lg bg-neutral-50 dark:bg-neutral-800/80 hover:bg-neutral-100 dark:hover:bg-neutral-700/80 border border-neutral-200 dark:border-neutral-700 rounded-2xl flex items-start gap-md text-left transition-all active:scale-[0.99] group cursor-pointer"
              >
                <div className="w-10 h-10 rounded-xl bg-primary-500/10 dark:bg-primary-500/20 text-primary-500 flex items-center justify-center flex-shrink-0 group-hover:scale-110 transition-transform">
                  <PenSquare className="w-5 h-5" />
                </div>
                <div>
                  <h4 className="font-bold text-sm text-neutral-900 dark:text-white flex items-center gap-xs">
                    Reshare with Your Thoughts
                  </h4>
                  <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-xs leading-normal">
                    Add your own commentary or opinion above the original post preview.
                  </p>
                </div>
              </button>

              {isResharedByMe && (
                <button
                  type="button"
                  onClick={handleUnreshare}
                  disabled={isSubmittingReshare}
                  className="w-full p-lg bg-rose-500/5 dark:bg-rose-500/10 hover:bg-rose-500/10 dark:hover:bg-rose-500/20 border border-rose-200 dark:border-rose-900/40 rounded-2xl flex items-start gap-md text-left transition-all active:scale-[0.99] group cursor-pointer"
                >
                  <div className="w-10 h-10 rounded-xl bg-rose-500/10 dark:bg-rose-500/20 text-rose-500 flex items-center justify-center flex-shrink-0 group-hover:scale-110 transition-transform">
                    <Trash2 className="w-5 h-5" />
                  </div>
                  <div>
                    <h4 className="font-bold text-sm text-rose-600 dark:text-rose-400 flex items-center gap-xs">
                      Undo Reshare
                    </h4>
                    <p className="text-xs text-rose-500/80 dark:text-rose-400/80 mt-xs leading-normal">
                      Remove your reshare from feed and decrease reshare count.
                    </p>
                  </div>
                </button>
              )}
            </div>
          )}
        </Modal>
      )}

      {/* Instagram-style Share Modal */}
      <ShareModal
        isOpen={isShareModalOpen}
        onClose={() => setIsShareModalOpen(false)}
        post={post}
        shareUrl={`https://cohortnow.online/post/${post.id}`}
        title={`Post by ${post.author?.name || 'Cohort Student'}`}
      />

      {/* WhatsApp-Style Poll Votes Breakdown Modal */}
      <Modal isOpen={Boolean(viewVotesPoll)} onClose={() => setViewVotesPoll(null)} title="Poll Votes Breakdown" size="md">
        <div className="space-y-4 py-1">
          <div className="p-3.5 rounded-2xl bg-neutral-900 border border-neutral-800 flex items-center justify-between">
            <div className="min-w-0 pr-2">
              <span className="text-[10px] font-bold text-sky-400 uppercase tracking-wider block">Question</span>
              <h4 className="text-sm font-extrabold text-white mt-0.5 truncate">{viewVotesPoll?.question}</h4>
            </div>
            <span className="text-[10px] font-bold text-sky-300 px-2.5 py-1 rounded-full bg-sky-500/15 border border-sky-500/25 flex-shrink-0">
              {viewVotesPoll?.totalVotes || 0} Total Votes
            </span>
          </div>

          <div className="space-y-3 max-h-96 overflow-y-auto pr-1 scrollbar-thin">
            {viewVotesPoll?.options?.map((opt, idx) => {
              const voters = (Array.isArray(opt.votedUserDetails) && opt.votedUserDetails.length > 0)
                ? opt.votedUserDetails
                : ((viewVotesPoll.votedUsers || []).filter(uid => viewVotesPoll.userChoices?.[uid] === idx).length > 0
                    ? (viewVotesPoll.votedUsers || []).filter(uid => viewVotesPoll.userChoices?.[uid] === idx).map(uid => ({ uid, name: uid === user?.uid ? (user?.name || 'Student') : 'Student', avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${uid}` }))
                    : (opt.votes > 0
                        ? Array.from({ length: opt.votes }).map((_, i) => ({ uid: `v_${i}`, name: i === 0 && user?.name ? user.name : `Student ${i + 1}`, avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${(user?.email || 's') + i}` }))
                        : []));

              return (
                <div key={idx} className="p-3 rounded-2xl bg-neutral-900/90 border border-neutral-800 space-y-2">
                  <div className="flex items-center justify-between font-bold text-xs">
                    <span className="text-white font-extrabold">{opt.text}</span>
                    <span className="text-neutral-400 font-mono text-[11px]">{voters.length} {voters.length === 1 ? 'vote' : 'votes'}</span>
                  </div>

                  {voters.length > 0 ? (
                    <div className="space-y-1.5 pt-1">
                      {voters.map((voter, vIdx) => (
                        <div key={vIdx} className="flex items-center justify-between p-2 rounded-xl bg-neutral-950/70 border border-neutral-800/60 text-xs">
                          <div className="flex items-center gap-2 min-w-0">
                            <img
                              src={voter.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(voter.name || 'Student')}`}
                              alt={voter.name}
                              className="w-7 h-7 rounded-full object-cover border border-neutral-700 flex-shrink-0"
                            />
                            <span className="font-bold text-neutral-200 truncate">{voter.name || 'Student'}</span>
                          </div>
                          <CheckCircle2 className="w-4 h-4 text-emerald-400 fill-emerald-400/20 flex-shrink-0" />
                        </div>
                      ))}
                    </div>
                  ) : (
                    <p className="text-[11px] text-neutral-500 italic px-1">No votes for this option yet.</p>
                  )}
                </div>
              );
            })}
          </div>

          <div className="pt-2 border-t border-neutral-800 flex justify-end">
            <Button variant="secondary" onClick={() => setViewVotesPoll(null)} className="rounded-2xl px-5 text-xs font-semibold">
              Close
            </Button>
          </div>
        </div>
      </Modal>
    </Card>
  );
};

const UsernameModal = () => {
  const { user, updateUser, isAuthenticated, setPasswordForUser } = useAuth();
  const { showSuccess } = useNotification();

  const [usernameInput, setUsernameInput] = useState('');
  const [nameInput, setNameInput] = useState(user?.name || '');
  const [passwordInput, setPasswordInput] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [checking, setChecking] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');

  // Extended Onboarding States
  const [avatarFile, setAvatarFile] = useState(null);
  const [avatarPreviewUrl, setAvatarPreviewUrl] = useState(null);
  const [cropperSrc, setCropperSrc] = useState(null);

  const [collegeInput, setCollegeInput] = useState(user?.college || '');

  const [gender, setGender] = useState('Prefer not to say');
  const [year, setYear] = useState('1st Year');
  const [dob, setDob] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef(null);

  // Sync name input when user profile is loaded
  useEffect(() => {
    if (user) {
      setNameInput(user.name || '');
      setCollegeInput(user.college || '');
    }
  }, [user]);

  // Keep modal open if authenticated and either username or onboarding incomplete
  if (!isAuthenticated || !user || (user.username && user.onboarded)) {
    return null;
  }

  const handleCreateUsername = async (e) => {
    e.preventDefault();
    setErrorMsg('');

    const cleanName = nameInput.trim();
    if (!cleanName || cleanName.length < 2) {
      setErrorMsg('Display Name must be at least 2 characters long.');
      return;
    }

    const cleanUsername = usernameInput.trim().toLowerCase().replace(/[^a-z0-9_.]/g, '');

    if (!cleanUsername || cleanUsername.length < 3) {
      setErrorMsg('Username must be at least 3 characters long (letters, numbers, underscores).');
      return;
    }

    if (!user.hasPassword) {
      if (!passwordInput || passwordInput.length < 6) {
        setErrorMsg('Password must be at least 6 characters long.');
        return;
      }
    }

    if (!collegeInput.trim()) {
      setErrorMsg('Please select or enter your college / university name.');
      return;
    }

    if (!dob) {
      setErrorMsg('Please select your Date of Birth.');
      return;
    }

    setChecking(true);
    try {
      // Query Firestore users collection for existing username
      const q = query(collection(db, 'users'), where('username', '==', cleanUsername));
      const querySnapshot = await getDocs(q);

      let isTaken = false;
      querySnapshot.forEach((docSnap) => {
        if (docSnap.id !== user.uid) {
          isTaken = true;
        }
      });

      if (isTaken) {
        setErrorMsg(`Username "@${cleanUsername}" is already taken. Please try another.`);
        setChecking(false);
        return;
      }

      // 1. Set chosen password in Firebase Auth first if user does not have a password
      if (!user.hasPassword) {
        await setPasswordForUser(passwordInput);
      }

      // 2. Upload profile picture if selected
      let uploadedAvatarUrl = user.avatar || null;
      if (avatarFile) {
        setIsUploading(true);
        uploadedAvatarUrl = await uploadImageToCloudinary(avatarFile);
      }

      // 3. Update Firestore user document
      const userRef = doc(db, 'users', user.uid);
      const isCollege = isCollegeEmail(user.email);
      const isMatching = isCollege && verifyEmailMatchesCollege(user.email, collegeInput);

      const onboardingData = {
        name: cleanName,
        username: cleanUsername,
        avatar: uploadedAvatarUrl || avatarPreviewUrl || user.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${cleanUsername}`,
        college: collegeInput,
        gender: gender,
        year: year,
        dob: dob,
        onboarded: true,
        kycVerified: isMatching,
        kycEmail: isMatching ? user.email : null,
        kycGender: isMatching ? predictGenderFromName(user.email) : null
      };

      await updateDoc(userRef, onboardingData);
      await updateUser(onboardingData);
      showSuccess(`Welcome! Your unique username is @${cleanUsername}`);
    } catch (err) {
      console.error('Error during onboarding setup:', err);
      setErrorMsg(err.message || 'Failed to complete onboarding. Please try again.');
    } finally {
      setChecking(false);
      setIsUploading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto bg-black/70 backdrop-blur-md flex justify-center items-start sm:items-center p-md sm:p-lg py-xl">
      <div className="bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-3xl p-lg sm:p-xl max-w-md w-full shadow-2xl my-auto space-y-md sm:space-y-lg animate-in fade-in zoom-in duration-200">
        <div className="text-center space-y-sm">
          <div className="w-12 h-12 bg-primary-50 dark:bg-primary-950/50 rounded-xl flex items-center justify-center mx-auto text-primary-500 shadow-inner">
            <Sparkles className="w-6 h-6 animate-pulse" />
          </div>
          <h2 className="text-xl sm:text-2xl font-heading font-bold text-neutral-900 dark:text-white">
            Complete Your Profile Setup
          </h2>
          <p className="text-xs text-neutral-500 dark:text-neutral-400 max-w-sm mx-auto leading-relaxed">
            Welcome to Cohort! Let's set up your campus profile so classmates can connect with you directly.
          </p>
        </div>

        <form onSubmit={handleCreateUsername} className="space-y-md">
          {/* Avatar Upload */}
          <div className="flex flex-col items-center space-y-sm pb-xs">
            <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
              <img
                src={avatarPreviewUrl || user?.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(user?.email || 'user')}`}
                alt="Avatar"
                className="w-20 h-20 rounded-full border-4 border-primary-500 object-cover shadow-md group-hover:opacity-80 transition-opacity"
              />
              <div className="absolute inset-0 flex items-center justify-center bg-black/40 rounded-full opacity-0 group-hover:opacity-100 transition-opacity">
                <Camera className="w-5 h-5 text-white" />
              </div>
              <input
                type="file"
                ref={fileInputRef}
                onChange={(e) => {
                  const file = e.target.files[0];
                  if (file) {
                    setCropperSrc(URL.createObjectURL(file));
                  }
                }}
                accept="image/*"
                className="hidden"
              />
            </div>
            <div className="flex gap-sm">
              <Button type="button" size="sm" variant="secondary" onClick={() => fileInputRef.current?.click()}>
