  };

const formatShortCollegeName = (rawName) => {
  if (!rawName) return 'Campus';
  let short = String(rawName).trim();
  if (short.includes(' - ')) {
    short = short.split(' - ')[0].trim();
  }
  if (short.includes(' (')) {
    short = short.split(' (')[0].trim();
  }
  if (short.includes(',')) {
    short = short.split(',')[0].trim();
  }
  return short;
};

