export const UserAvatar = ({
  src,
  name = 'Student',
  className = 'w-8 h-8 rounded-full',
  alt
}) => {
  const [hasError, setHasError] = useState(false);

  const fallbackUrl = `https://ui-avatars.com/api/?name=${encodeURIComponent(name || 'Student')}&background=0ea5e9&color=fff&bold=true&size=128`;

  // Check if src is invalid or a broken dicebear URL
  const isValidSrc = src && typeof src === 'string' && src.trim().length > 0 && !src.includes('dicebear.com');
  const imageSrc = !hasError && isValidSrc ? src : fallbackUrl;

  return (
    <img
      src={imageSrc}
      alt={alt || name || 'User avatar'}
      className={`object-cover rounded-full flex-shrink-0 ${className}`}
      referrerPolicy="no-referrer"
      onError={(e) => {
        if (!hasError) {
          setHasError(true);
          e.currentTarget.src = fallbackUrl;
        }
      }}
    />
  );
};

const handleToggleStarMessage = async (msgToStar) => {
    if (!activeConversation || !activeConversation.docId) return;

    const currentMsgs = activeConversation.messages || [];
    const updatedMsgs = currentMsgs.map(m => {
      const isTarget = m === msgToStar ||
        (m.text === msgToStar.text && Math.abs(new Date(m.time).getTime() - new Date(msgToStar.time).getTime()) < 2000);
      if (isTarget) {
        const starList = m.starredBy || [];
        const isStarred = starList.includes(myUid);
        const newStarList = isStarred
          ? starList.filter(u => u !== myUid)
          : [...starList, myUid];
        return { ...m, starredBy: newStarList };
      }
      return m;
    });

    try {
      const docRef = doc(db, 'messages', activeConversation.docId);
      await updateDoc(docRef, { messages: updatedMsgs });
      const wasStarred = (msgToStar.starredBy || []).includes(myUid);
      showSuccess(wasStarred ? 'Message unstarred' : 'Message starred ⭐');
    } catch (err) {
      console.error('Failed to toggle star message:', err);
    }
  };

const handleAddComment = async (e) => {
    if ((e.key === 'Enter' || e.type === 'click') && newComment.trim()) {
      const postId = post.docId || post.id;
      if (!postId) return;

      const textToSend = newComment.trim();
      const targetReply = replyingToComment;
      setNewComment('');
      setReplyingToComment(null);

      const parentId = targetReply?.parentId || null;
      const tempId = `temp_${Date.now()}`;

      const newCommentObj = {
        id: tempId,
        authorUid: user?.uid || null,
        authorUsername: user?.username || null,
        author: user?.name || user?.email?.split('@')[0] || 'Student',
        avatar: user?.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(user?.email || 'user')}`,
        text: textToSend,
        parentId: parentId,
        replyToAuthorUid: targetReply?.authorUid || null,
        replyToAuthorName: targetReply?.author || null,
        likes: 0,
        likedBy: [],
        timestamp: new Date(),
        time: 'Just now'
      };

      // Optimistic UI Update
      setComments(prev => [...prev, newCommentObj]);

      // Auto-expand parent replies so newly added reply is immediately visible
      if (parentId) {
        setExpandedReplies(prev => ({ ...prev, [parentId]: true }));
      }

      const commentData = {
        authorUid: newCommentObj.authorUid,
        authorUsername: newCommentObj.authorUsername,
        author: newCommentObj.author,
        avatar: newCommentObj.avatar,
        text: textToSend,
        parentId: parentId,
        replyToAuthorUid: targetReply?.authorUid || null,
        replyToAuthorName: targetReply?.author || null,
        likes: 0,
        likedBy: [],
        timestamp: new Date()
      };

      try {
        const newCommentRef = await addDoc(collection(db, 'posts', postId, 'comments'), commentData);

        const postRef = doc(db, 'posts', postId);
        await updateDoc(postRef, {
          comments: (comments.length || 0) + 1
        });

        const postAuthorUid = post.author?.uid || post.authorUid || post.uid;

        // 1. Dispatch Comment Notification to post author (if not self)
        if (postAuthorUid && postAuthorUid !== user?.uid) {
          createNotification({
            recipientUid: postAuthorUid,
            senderUid: user?.uid,
            senderName: user?.name || 'Student',
            senderAvatar: user?.avatar,
            type: 'reply',
            text: `commented: "${textToSend.slice(0, 35)}${textToSend.length > 35 ? '...' : ''}"`,
            postId: postId,
            commentId: newCommentRef.id
          });
        }

        // 2. Dispatch Reply Notification to the specific comment author tagged/replied to
        const commentAuthorUid = targetReply?.authorUid;
        if (
          commentAuthorUid &&
          commentAuthorUid !== user?.uid &&
          commentAuthorUid !== postAuthorUid
        ) {
          createNotification({
            recipientUid: commentAuthorUid,
            senderUid: user?.uid,
            senderName: user?.name || 'Student',
            senderAvatar: user?.avatar,
            type: 'reply',
            text: `replied to your comment: "${textToSend.slice(0, 35)}${textToSend.length > 35 ? '...' : ''}"`,
            postId: postId,
            commentId: newCommentRef.id
          });
        }
      } catch (err) {
        console.error('Failed to add reply comment in Firestore:', err);
      }
    }
  };

const handleReshareWithThoughtsSubmit = async () => {
    if (!thoughtCaption.trim()) return;
    const rootOriginalPostId = post.originalPostId || post.docId || post.id;
    const origAuthor = post.originalPost?.author || post.author;
    const origContent = post.originalPost?.content || post.content;
    const origTimestamp = post.originalPost?.timestamp || post.timestamp;
    const myUid = user?.uid;

    setIsSubmittingReshare(true);
    setLocalReposts(prev => prev + 1);
    if (myUid) setLocalResharedUsers(prev => [...prev, myUid]);

    try {
      const reshareDocData = {
        isReshare: true,
        originalPostId: rootOriginalPostId,
        originalPost: {
          id: rootOriginalPostId,
          author: origAuthor,
          content: origContent,
          timestamp: origTimestamp
        },
        resharedBy: {
          uid: myUid || null,
          name: user?.name || 'Student',
          username: user?.username || null,
          avatar: user?.avatar || null
        },
        college: user?.college || 'KIET',
        author: {
          uid: myUid || null,
          name: user?.name || 'Student',
          username: user?.username || null,
          avatar: user?.avatar || null,
          role: user?.college || 'KIET',
          college: user?.college || 'KIET'
        },
        thought: thoughtCaption.trim(),
        content: thoughtCaption.trim(),
        timestamp: new Date(),
        upvotes: 0,
        downvotes: 0,
        upvotedUsers: [],
        downvotedUsers: [],
        comments: 0,
        reposts: 0,
        saved: false
      };

      await addDoc(collection(db, 'posts'), reshareDocData);

      const origPostRef = doc(db, 'posts', rootOriginalPostId);
      await updateDoc(origPostRef, {
        reposts: increment(1),
        resharedUsers: myUid ? arrayUnion(myUid) : []
      });

      if (onRepost) onRepost(rootOriginalPostId);

      const origAuthorUid = origAuthor?.uid || post.author?.uid;
      if (origAuthorUid && origAuthorUid !== myUid) {
        createNotification({
          recipientUid: origAuthorUid,
          senderUid: myUid,
          senderName: user?.name || 'Student',
          senderAvatar: user?.avatar,
          type: 'reshare',
          text: 'reshared your post with their thoughts.',
          postId: rootOriginalPostId
        });
      }

      showSuccess('Post reshared with thoughts successfully.');
      setShowReshareModal(false);
      setReshareMode(null);
      setThoughtCaption('');
    } catch (err) {
      console.error('Failed to reshare post with thoughts:', err);
      setLocalReposts(post.reposts || 0);
      setLocalResharedUsers(post.resharedUsers || []);
    } finally {
      setIsSubmittingReshare(false);
    }
  };

const processTarget = async () => {
      try {
        const messagesSnap = await getDocs(collection(db, 'messages'));
        let existingId = null;

        messagesSnap.forEach(d => {
          const data = d.data();
          const isParticipant = (data.participants && data.participants.includes(user.uid)) ||
                                data.recipientUid === user.uid ||
                                data.createdBy === user.uid;
          const isHidden = data.hiddenFor?.[user.uid] === true;

          if (isParticipant && !isHidden) {
            const matchesUid = targetRecipientUid && (data.participants?.includes(targetRecipientUid) || data.recipientUid === targetRecipientUid);
            const matchesName = targetRecipientName && (data.name?.toLowerCase() === decodeURIComponent(targetRecipientName).toLowerCase());
            if (matchesUid || matchesName) {
              existingId = d.id;
            }
          }
        });

        if (existingId) {
          setSelectedId(existingId);
          setMobileView('chat');
          if (targetProduct) {
            setMessageText(`Hi, I'm interested in your product listed on Marketplace: "${decodeURIComponent(targetProduct)}"`);
          }
        } else {
          let sellerData = null;
          if (targetRecipientUid) {
            try {
              const sDoc = await getDoc(doc(db, 'users', targetRecipientUid));
              if (sDoc.exists()) sellerData = sDoc.data();
            } catch (e) {}
          }

          const displayName = sellerData?.name || (targetRecipientName ? decodeURIComponent(targetRecipientName) : 'Seller');
          const displayAvatar = sellerData?.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(displayName)}`;

          const initialMsgText = targetProduct
            ? `Hi, I'm interested in your product listed on Marketplace: "${decodeURIComponent(targetProduct)}"`
            : '';

          const newConvData = {
            name: displayName,
            recipientUid: targetRecipientUid || null,
            recipientName: displayName,
            recipientAvatar: displayAvatar,
            participants: targetRecipientUid ? [user.uid, targetRecipientUid] : [user.uid],
            participantMap: {
              [user.uid]: { name: user.name || 'User', avatar: user.avatar || '' },
              ...(targetRecipientUid ? { [targetRecipientUid]: { name: displayName, avatar: displayAvatar } } : {})
            },
            createdBy: user.uid,
            createdByName: user.name || 'User',
            createdByAvatar: user.avatar || '',
            readBy: [user.uid],
            avatar: displayAvatar,
            lastMessage: targetProduct ? `Inquiring about ${decodeURIComponent(targetProduct)}` : 'Started a new conversation',
            time: new Date(),
            messages: []
          };

          const docRef = await addDoc(collection(db, 'messages'), newConvData);
          setSelectedId(docRef.id);
          setMobileView('chat');
          if (initialMsgText) {
            setMessageText(initialMsgText);
          }
        }
      } catch (err) {
        console.error('Error processing Marketplace recipient target:', err);
      } finally {
        navigate('/messages', { replace: true });
      }
    };

