            {msg.replyTo && <div className={`p-1 px-2 rounded-lg border text-xs mb-1 ${isMe ? 'bg-black/25 text-white border-white/90' : 'bg-primary-500/10 text-neutral-800 dark:text-neutral-100 border-primary-500'}`}><p className="font-bold">{msg.replyTo.name}</p><p className="truncate mt-xs">{msg.replyTo.text}</p></div>}
            <div className="relative inline-block max-w-full">
              <span className="text-[13.5px] leading-snug break-words font-normal">{msg.content}</span>
              <span className="inline-flex items-center gap-1 float-right mt-1 ml-2.5 text-[10px] leading-none select-none">
                <span className={isMe ? 'text-white/75' : 'text-neutral-500 dark:text-neutral-400 font-medium'}>
                  {formatTime(msg.timestamp)}
                </span>
                {isMe && (
                  <CheckCheck
                    className={`w-3.5 h-3.5 stroke-[2.8] transition-colors duration-300 ${
                      isSeen
                        ? 'text-emerald-300 dark:text-emerald-300 drop-shadow-[0_0_6px_rgba(16,185,129,0.7)]'
                        : 'text-white/50 dark:text-neutral-400'
                    }`}
                    title={isSeen ? "Seen (Green Tick)" : "Sent to group"}
                  />
                )}
              </span>
            </div>
          </div>
        {msg.reactions && msg.reactions.length > 0 && (
          <div className="flex flex-wrap gap-xs pt-xs pl-sm">
            {msg.reactions.map((react, rIdx) => (
              <button key={rIdx} onClick={() => onReact && onReact(msg.id, react.emoji)} className={`px-sm py-[2px] rounded-full text-[10px] font-bold border flex items-center gap-xs ${react.users?.includes(user?.uid || 'user') ? 'bg-primary-50 border-primary-200 text-primary-600 dark:bg-primary-950/20' : 'bg-white border-neutral-100 text-neutral-500 dark:bg-neutral-900 dark:border-neutral-800'}`}>
                <span>{react.emoji}</span><span>{react.count}</span>
              </button>
            ))}
          </div>
        )}
        {onReply && (
          <div className={`absolute top-0 opacity-0 group-hover:opacity-100 transition-opacity flex gap-xs bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-full shadow-md px-md py-[3px] z-10 ${isMe ? 'right-full mr-md' : 'left-full ml-md'}`}>
            <button onClick={() => onReply(msg)} className="text-neutral-400 hover:text-neutral-600 dark:hover:text-white p-xs" title="Reply"><Reply className="w-3.5 h-3.5" /></button>
            <button onClick={() => setShowEmoji(showEmojiFor === msg.id ? null : msg.id)} className="text-neutral-400 hover:text-neutral-600 dark:hover:text-white p-xs" title="React"><Smile className="w-3.5 h-3.5" /></button>
            {showEmojiFor === msg.id && (
              <div className="absolute bottom-full left-0 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl shadow-lg p-sm flex gap-xs z-20 mb-xs">
                {chatEmojis.map(e => <button key={e} onClick={() => onReact && onReact(msg.id, e)} className="hover:scale-125 transition-transform text-sm">{e}</button>)}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default function Signup() {
  const navigate = useNavigate();
  const location = useLocation();
  const { login, loginWithGoogle, setPasswordForUser } = useAuth();
  const { showError, showSuccess } = useNotification();

  const [isSignup, setIsSignup] = useState(location.pathname === '/signup');
  const [signupStep, setSignupStep] = useState(1); // 1 = enter email, 2 = enter otp
  const [otpInput, setOtpInput] = useState('');
  const [resendTimer, setResendTimer] = useState(0);

  useEffect(() => {
    setIsSignup(location.pathname === '/signup');
    setSignupStep(1);
    setOtpInput('');
    setErrors({});
  }, [location.pathname]);

  // Resend OTP Countdown Timer
  useEffect(() => {
    if (resendTimer > 0) {
      const interval = setInterval(() => {
        setResendTimer(prev => prev - 1);
      }, 1000);
      return () => clearInterval(interval);
    }
  }, [resendTimer]);

  const toggleAuthMode = () => {
    const nextIsSignup = !isSignup;
    setIsSignup(nextIsSignup);
    setSignupStep(1);
    setOtpInput('');
    setErrors({});
    navigate(nextIsSignup ? '/signup' : '/login');
  };

  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isGoogleLoading, setIsGoogleLoading] = useState(false);



  const [formData, setFormData] = useState({
    email: '',
    password: '',
  });
  const [errors, setErrors] = useState({});

  const handleGoogleSignIn = async () => {
    setIsGoogleLoading(true);
    try {
      await loginWithGoogle();
      showSuccess('Signed in with Google successfully!');
      navigate('/home');
    } catch (error) {
      console.error(error);
      showError(error.message || 'Google sign in failed. Please try again.');
    } finally {
      setIsGoogleLoading(false);
    }
  };

  const handleInputChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }));
    }
  };

  // Generate and send OTP helper
  const sendVerificationCode = async (targetEmail) => {
    const generatedOtp = Math.floor(100000 + Math.random() * 900000).toString();

    // Save to Firestore 'otps' collection
    const emailKey = targetEmail.trim().toLowerCase();
    await setDoc(doc(db, 'otps', emailKey), {
      otp: generatedOtp,
      createdAt: new Date().toISOString()
    });

    // Call serverless send-otp API
    const isMobileApp = Capacitor.isNativePlatform();
    const apiUrl = isMobileApp ? `https://www.cohortnow.online/api/send-otp` : '/api/send-otp';

    const response = await fetch(apiUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ email: emailKey, otp: generatedOtp }),
    });

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.error || 'Failed to send OTP code');
    }

    const resData = await response.json();
    return resData;
  };

  const handleSendOTP = async () => {
    const emailToUse = formData.email.trim();
    if (!emailToUse) {
      setErrors({ email: 'Email address is required' });
      return;
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(emailToUse)) {
      setErrors({ email: 'Please enter a valid email address' });
      return;
    }

    setIsLoading(true);
    try {
      // Check if email already exists in Firestore users
      const q = query(collection(db, 'users'), where('email', '==', emailToUse.toLowerCase()));
      const querySnap = await getDocs(q);
      if (!querySnap.empty) {
        setErrors({ email: 'This email is already registered. Please sign in instead.' });
        showError('This email is already registered. Please sign in instead.');
        setIsLoading(false);
        return;
      }

      const resData = await sendVerificationCode(emailToUse);
      showSuccess('Verification code sent to your email!');

      if (resData.otp) {
        console.log(`%c[OTP Code (Dev Mode)] ${resData.otp}`, 'color: #9333ea; font-size: 16px; font-weight: bold;');
        if (resData.previewUrl) {
          console.log(`[Email Preview Link] ${resData.previewUrl}`);
        }
        showSuccess(`[Dev Mode] OTP code is ${resData.otp} (Logged to console)`);
      }

      setSignupStep(2);
      setResendTimer(30);
    } catch (err) {
      console.error(err);
      setErrors({ email: err.message || 'Failed to send verification code. Please try again.' });
      showError(err.message || 'Failed to send verification code. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleResendOTP = async () => {
    if (resendTimer > 0) return;
    try {
      await sendVerificationCode(formData.email);
      showSuccess('Verification code resent!');
      setResendTimer(30);
    } catch (err) {
      console.error(err);
      setErrors({ otp: err.message || 'Failed to resend code.' });
      showError(err.message || 'Failed to resend code.');
    }
  };

  const handleVerifyAndSignup = async (e) => {
    e.preventDefault();
    if (!otpInput || otpInput.trim().length !== 6) {
      setErrors({ otp: 'Please enter the 6-digit verification code.' });
      showError('Please enter the 6-digit verification code.');
      return;
    }

    setIsLoading(true);
    const emailKey = formData.email.trim().toLowerCase();

    try {
      // Clear any existing stale Firebase session first to prevent requires-recent-login session conflicts
      const { signOut } = await import('firebase/auth');
      await signOut(auth).catch(() => {});

      const otpDocRef = doc(db, 'otps', emailKey);
      const otpSnap = await getDoc(otpDocRef);

      if (!otpSnap.exists()) {
        setErrors({ otp: 'Verification code not found. Please request a new one.' });
        showError('Verification code not found. Please request a new one.');
        setIsLoading(false);
        return;
      }

      const otpData = otpSnap.data();
      if (otpData.otp !== otpInput.trim()) {
        setErrors({ otp: 'Incorrect verification code. Please check and try again.' });
        showError('Incorrect verification code. Please check and try again.');
        setIsLoading(false);
        return;
      }

      const timeDiff = Date.now() - new Date(otpData.createdAt).getTime();
      if (timeDiff > 10 * 60 * 1000) { // 10 minutes expiry
        setErrors({ otp: 'Verification code expired. Please request a new one.' });
        showError('Verification code expired. Please request a new one.');
        setIsLoading(false);
        return;
      }

      // Cleanup OTP document from Firestore
      await deleteDoc(otpDocRef).catch(err => console.warn('Failed to delete verified OTP doc:', err));

      // Sign up in Firebase Authentication with temporary password
      const tempPassword = Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);
      localStorage.setItem('cohort_temp_signup_password', tempPassword);
      const userCredential = await createUserWithEmailAndPassword(auth, emailKey, tempPassword);
      const uid = userCredential.user.uid;

      // Create user document in Firestore with onboarded: false, hasPassword: false
      const profile = {
        email: emailKey,
        college: '',
        joinedDate: new Date().toISOString(),
        onboarded: false,
        hasPassword: false
      };

      await setDoc(doc(db, 'users', uid), profile);
      showSuccess('Email verified successfully! Setup your profile.');
      navigate('/home');

    } catch (err) {
      console.error('OTP Verification signup error:', err);
      setErrors({ otp: err.message || 'Signup failed. Please try again.' });
      showError(err.message || 'Signup failed. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (isSignup) {
      if (signupStep === 1) {
        await handleSendOTP();
      } else {
        await handleVerifyAndSignup(e);
      }
      return;
    }

    // Login Form Submit logic
    const newErrors = {};

    if (!formData.email.trim()) {
      newErrors.email = 'Email or Username is required';
    }

    if (!formData.password) {
      newErrors.password = 'Password is required';
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    setIsLoading(true);

    try {
      await login(formData.email.trim(), formData.password);
      showSuccess('Welcome back to Cohort!');
      navigate('/home');
    } catch (error) {
      console.error(error);
      if (error.code === 'auth/operation-not-allowed') {
        showError('Please sign in via Google below!');
      } else if (error.code === 'auth/user-not-found' || error.code === 'auth/wrong-password' || error.code === 'auth/invalid-credential') {
        showError('Invalid email/username or password. Please check your details.');
      } else {
        showError(error.message || 'Sign in failed. Please check your credentials.');
      }
    } finally {
      setIsLoading(false);
    }
  };


  return (
    <div className="relative min-h-screen w-full bg-[#08080C] text-neutral-100 flex flex-col justify-start overflow-x-hidden select-none pb-0 lg:pb-24">
      <SEO 
        title={isSignup ? "Sign Up" : "Log In"} 
        description="Connect with your university campus community on Cohort. Log in or create a new student account." 
      />

      {/* Full-Screen React Bits <Scanner /> WebGL Component Background */}
      <div className="absolute inset-0 z-0 opacity-65 pointer-events-none">
        <Scanner
          color1="#963BFF"
          color2="#FF2A85"
          color3="#00F0FF"
          speed={0.4}
          sweepSpeed={0.3}
          sweepWidth={1.4}
          sweepFalloff={5}
          scale={1.4}
          frequency={2.2}
          ripple={0.25}
          bandDensity={10}
          lineSharpness={5.0}
          glow={0.3}
          scanDirection="diagonal"
          colorSpread={0.8}
          brightness={1.1}
          contrast={1.2}
          softness={1.3}
          vignette={0.4}
          scanline={true}
          grain={true}
          grainIntensity={0.04}
          opacity={0.85}
          mouseInteraction={true}
          mouseRadius={0.6}
          mouseStrength={0.6}
        />
      </div>

      {/* Background ambient lighting */}
      <div className="absolute top-1/4 -left-32 w-[500px] h-[500px] bg-purple-600/10 rounded-full blur-[160px] pointer-events-none" />
      <div className="absolute bottom-10 right-1/3 w-[600px] h-[600px] bg-indigo-600/10 rounded-full blur-[180px] pointer-events-none" />

      {/* --- TOP NAVBAR --- */}
      <header className="relative z-30 px-6 sm:px-12 py-3 flex items-center justify-between flex-shrink-0">
        <Link
          to="/"
          className="flex items-center gap-2.5 cursor-pointer group"
          title="Return to Landing Page"
        >
          <LogoIcon className="w-8 h-8 group-hover:scale-105 transition-transform" variant="badge" glow={true} />
          <span className="font-display font-black text-xl text-white tracking-tight">
            Cohort<span className="text-pink-500">.</span>
          </span>
        </Link>
        <div className="flex items-center gap-4">
          <button
            onClick={toggleAuthMode}
