          </div>

          {/* Divider */}
          <div className="border-t border-neutral-100 dark:border-zinc-800/80 pt-3 mt-3 flex items-center justify-between flex-wrap gap-2">
            {/* Left Action Tools */}
            <div className="flex items-center gap-2 flex-wrap">

              {activeTab !== 'confessions' && (
                <>
                  <input
