const handleSendBatch = async () => {
    if (!user) {
      showError('Please sign in to send direct messages.');
      return;
    }

    if (selectedUsers.length === 0) return;

    setIsSending(true);

    const cleanStr = (val, fallback = '') => (val === undefined || val === null ? fallback : String(val));

    try {
      const myUid = cleanStr(user?.uid);
      const myName = cleanStr(user?.name || user?.displayName || user?.email?.split('@')[0], 'Me');
      const myAvatar = cleanStr(
        user?.avatar || user?.photoURL,
        `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(myUid)}`
      );

      const safeTitle = cleanStr(shareTitle, 'Campus Post');
      const safeText = cleanStr(shareText, 'Check out this post on Cohort!');
      const safeUrl = cleanStr(shareUrl, window.location.href);
      const safeMediaUrl = cleanStr(
        post?.image || post?.imageUrl || post?.mediaUrl || post?.photo || post?.media || post?.coverImage || postMediaUrl,
        ''
      );
      const lastMsgSummary = `Shared a post: ${safeText.slice(0, 35)}${safeText.length > 35 ? '...' : ''}`;
      const nowIso = new Date().toISOString();

      // Fetch existing conversations for matching
      const messagesSnap = await getDocs(collection(db, 'messages'));
      const existingDocsMap = new Map();

      messagesSnap.forEach((docSnap) => {
        const data = docSnap.data();
        const parts = Array.isArray(data.participants) ? data.participants : [];

        // Match by participants array or createdBy/recipientUid fields
        selectedUsers.forEach((tUser) => {
          const targetUid = cleanStr(tUser.uid);
          const isMatch =
            (parts.includes(myUid) && parts.includes(targetUid)) ||
            (data.createdBy === myUid && data.recipientUid === targetUid) ||
            (data.createdBy === targetUid && data.recipientUid === myUid);

          if (isMatch && !existingDocsMap.has(targetUid)) {
            existingDocsMap.set(targetUid, { id: docSnap.id, ...data });
          }
        });
      });

      const sanitizeForFirestore = (val) => {
        if (val === undefined) return null;
        if (val === null || typeof val !== 'object') return val;
        if (val instanceof Date) return val;
        if (Array.isArray(val)) return val.map(sanitizeForFirestore);
        const clean = {};
        for (const key of Object.keys(val)) {
          if (val[key] !== undefined) {
            clean[key] = sanitizeForFirestore(val[key]);
          }
        }
        return clean;
      };

      const sendPromises = selectedUsers.map(async (targetUser) => {
        const targetUid = cleanStr(targetUser.uid);
        const targetName = cleanStr(targetUser.name, 'Campus Student');
        const targetAvatar = cleanStr(
          targetUser.avatar,
          `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(targetUid)}`
        );

        const isUncut = Boolean(safeUrl.includes('/uncut') || post?.id?.includes('-') || post?.category);
        const messageObj = sanitizeForFirestore({
          id: `msg_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
          sender: myUid,
          senderUid: myUid,
          senderName: myName,
          senderAvatar: myAvatar,
          text: isUncut 
            ? `📖 Shared Uncut Story: ${safeTitle}\n"${safeText.slice(0, 120)}${safeText.length > 120 ? '...' : ''}"\n${safeUrl}`
            : `Shared post by ${safeTitle}:\n"${safeText.slice(0, 120)}${safeText.length > 120 ? '...' : ''}"\n${safeUrl}`,
          time: nowIso,
          createdAt: nowIso,
          deletedFor: [],
          isSharedPost: true,
          isUncutStory: isUncut,
          sharedPostData: {
            id: cleanStr(post?.id, ''),
            title: safeTitle,
            content: safeText,
            url: safeUrl,
            mediaUrl: safeMediaUrl
          }
        });

        const existingDoc = existingDocsMap.get(targetUid);

        if (existingDoc) {
          const chatRef = doc(db, 'messages', existingDoc.id);
          const freshSnap = await getDoc(chatRef);
          const rawData = freshSnap.exists() ? freshSnap.data() : existingDoc;

          const rawMsgs = Array.isArray(rawData.messages) ? rawData.messages : [];
          const cleanExistingMsgs = rawMsgs.map((m) => {
            const cleanM = sanitizeForFirestore(m);
            return {
              ...cleanM,
              time: m.time?.toDate ? m.time.toDate().toISOString() : (m.time ? String(m.time) : nowIso)
            };
          });

          const resetHidden = {};
          if (rawData.hiddenFor) {
            Object.keys(rawData.hiddenFor).forEach((k) => {
              resetHidden[`hiddenFor.${k}`] = false;
            });
          }

          const updatePayload = sanitizeForFirestore({
            messages: [...cleanExistingMsgs, messageObj],
            lastMessage: lastMsgSummary,
            time: new Date(),
            readBy: [myUid],
            [`participantMap.${myUid}`]: { name: myName, avatar: myAvatar },
            [`participantMap.${targetUid}`]: { name: targetName, avatar: targetAvatar },
            ...resetHidden
          });

          await updateDoc(chatRef, updatePayload);
        } else {
          const newConvData = sanitizeForFirestore({
            recipientUid: targetUid,
            recipientName: targetName,
            recipientAvatar: targetAvatar,
            participants: [myUid, targetUid],
            participantMap: {
              [myUid]: { name: myName, avatar: myAvatar },
              [targetUid]: { name: targetName, avatar: targetAvatar }
            },
            createdBy: myUid,
            createdByName: myName,
            createdByAvatar: myAvatar,
            readBy: [myUid],
            avatar: targetAvatar,
            lastMessage: lastMsgSummary,
            time: new Date(),
            messages: [messageObj]
          });
          await addDoc(collection(db, 'messages'), newConvData);
        }
      });

      await Promise.all(sendPromises);

      const newSentMap = { ...sentMap };
      selectedUsers.forEach((u) => {
        newSentMap[u.uid] = true;
      });

      setSentMap(newSentMap);
      showSuccess(
        selectedUsers.length === 1
          ? `Sent to ${selectedUsers[0].name}!`
          : `Sent to ${selectedUsers.length} contacts!`
      );
      setSelectedUsers([]);
      setTimeout(() => {
        onClose();
      }, 700);
    } catch (err) {
      console.error('Error sending batch messages:', err);
      showError('Failed to send message. Please try again.');
    } finally {
      setIsSending(false);
    }
  };

export const ImageCropper = ({ imageSrc, onCrop, onCancel }) => {
  const [zoom, setZoom] = useState(1);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [imgSize, setImgSize] = useState({ width: 0, height: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const dragStart = useRef({ x: 0, y: 0 });
  const imgRef = useRef(null);

  const handleImageLoad = (e) => {
    const { naturalWidth, naturalHeight } = e.target;
    const ratio = naturalWidth / naturalHeight;
    let width = 256;
    let height = 256;

    // Fit image to viewport so smaller dimension covers 256px
    if (ratio > 1) {
      width = 256 * ratio;
    } else {
      height = 256 / ratio;
    }
    setImgSize({ width, height });
    setPosition({ x: 0, y: 0 });
    setZoom(1);
  };

  const handleMouseDown = (e) => {
    e.preventDefault();
    setIsDragging(true);
    dragStart.current = { x: e.clientX - position.x, y: e.clientY - position.y };
  };

  const handleMouseMove = (e) => {
    if (!isDragging) return;
    const newX = e.clientX - dragStart.current.x;
    const newY = e.clientY - dragStart.current.y;
    setPosition({ x: newX, y: newY });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const handleTouchStart = (e) => {
    if (e.touches.length !== 1) return;
    setIsDragging(true);
    const touch = e.touches[0];
    dragStart.current = { x: touch.clientX - position.x, y: touch.clientY - position.y };
  };

  const handleTouchMove = (e) => {
    if (!isDragging || e.touches.length !== 1) return;
    const touch = e.touches[0];
    const newX = touch.clientX - dragStart.current.x;
    const newY = touch.clientY - dragStart.current.y;
    setPosition({ x: newX, y: newY });
  };

  const handleTouchEnd = () => {
    setIsDragging(false);
  };

  const handleCropSave = () => {
    if (!imgRef.current) return;

    const canvas = document.createElement('canvas');
    canvas.width = 256;
    canvas.height = 256;
    const ctx = canvas.getContext('2d');

    // Draw background color
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, 256, 256);

    // Apply translations and zoom from center (128, 128)
    ctx.translate(128 + position.x, 128 + position.y);
    ctx.scale(zoom, zoom);

    // Draw natural dimension centered
    const left = -imgSize.width / 2;
    const top = -imgSize.height / 2;
    ctx.drawImage(imgRef.current, left, top, imgSize.width, imgSize.height);

    canvas.toBlob((blob) => {
      if (blob) {
        const croppedFile = new File([blob], 'avatar.jpg', { type: 'image/jpeg' });
        onCrop(croppedFile);
      }
    }, 'image/jpeg', 0.9);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-md bg-black/80 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-3xl p-xl max-w-sm w-full space-y-lg shadow-2xl flex flex-col items-center animate-in zoom-in-95 duration-200">
        <div className="text-center">
          <h3 className="text-lg font-bold text-neutral-900 dark:text-white">Crop Profile Picture</h3>
          <p className="text-xs text-neutral-500 mt-xs">Drag to pan, slide to zoom. Ensure your face fits inside the circle.</p>
        </div>

        {/* Circular Viewport */}
        <div className="relative group">
          <div
            className="w-64 h-64 rounded-full border-4 border-primary-500 overflow-hidden relative cursor-move bg-neutral-950 shadow-inner select-none flex items-center justify-center"
            onMouseDown={handleMouseDown}
            onMouseMove={handleMouseMove}
            onMouseUp={handleMouseUp}
            onMouseLeave={handleMouseUp}
            onTouchStart={handleTouchStart}
            onTouchMove={handleTouchMove}
            onTouchEnd={handleTouchEnd}
          >
            <img
              ref={imgRef}
              src={imageSrc}
              onLoad={handleImageLoad}
              alt="Cropping Profile Picture"
              draggable={false}
              style={{
                width: imgSize.width,
                height: imgSize.height,
                transform: `translate(${position.x}px, ${position.y}px) scale(${zoom})`,
                transformOrigin: 'center',
                position: 'absolute',
                left: (256 - imgSize.width) / 2,
                top: (256 - imgSize.height) / 2,
                maxWidth: 'none',
              }}
            />
          </div>
          <div className="absolute bottom-2 right-2 bg-neutral-900/60 p-1.5 rounded-full text-white pointer-events-none opacity-60">
            <Move className="w-4 h-4" />
          </div>
        </div>

        {/* Zoom Slider */}
        <div className="w-full space-y-xs px-xs">
          <div className="flex items-center justify-between text-[10px] uppercase font-bold tracking-wider text-neutral-400">
            <span className="flex items-center gap-xs"><ZoomOut className="w-3.5 h-3.5" /> Out</span>
            <span className="flex items-center gap-xs">In <ZoomIn className="w-3.5 h-3.5" /></span>
          </div>
          <input
            type="range"
            min="1"
            max="3"
            step="0.01"
            value={zoom}
            onChange={(e) => setZoom(parseFloat(e.target.value))}
            className="w-full h-1.5 bg-neutral-200 dark:bg-neutral-800 rounded-lg appearance-none cursor-pointer accent-primary-500"
          />
        </div>

        {/* Action Buttons */}
        <div className="flex gap-md w-full pt-xs border-t border-neutral-100 dark:border-neutral-800">
          <Button variant="secondary" className="flex-1" type="button" onClick={onCancel}>
            Cancel
          </Button>
          <Button variant="primary" className="flex-1" type="button" onClick={handleCropSave}>
            Save Crop
          </Button>
        </div>
      </div>
    </div>
  );
};

export default function DownloadAppModal({ isOpen, onClose }) {
  const [notifyLaunch, setNotifyLaunch] = useState(true);
  const [shouldRender, setShouldRender] = useState(isOpen);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    if (isOpen) {
      setShouldRender(true);
      // Double rAF ensures standard browser paint cycle handles transitions perfectly
      const rAF = requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          setIsVisible(true);
        });
      });
      return () => cancelAnimationFrame(rAF);
    } else {
      setIsVisible(false);
      const timer = setTimeout(() => {
        setShouldRender(false);
      }, 300);
      return () => clearTimeout(timer);
    }
  }, [isOpen]);

  if (!shouldRender) return null;

  return (
    <div
      className={`fixed inset-0 z-[200] flex items-end sm:items-center justify-center transition-opacity duration-300 ease-out ${
        isVisible ? 'opacity-100' : 'opacity-0'
      }`}
    >
      {/* Background Backdrop with simple dark color on mobile, light blur on desktop */}
      <div
        className={`absolute inset-0 bg-black/75 transition-opacity duration-300 ${
          isVisible ? 'opacity-100' : 'opacity-0'
        } sm:backdrop-blur-sm`}
        onClick={onClose}
      />

