          </div>
          <div className="flex gap-md pt-md"><Button variant="secondary" className="flex-1" onClick={() => setIsShareFileOpen(false)}>Cancel</Button><Button variant="primary" type="submit" className="flex-1">Share File</Button></div>
        </form>
