  const navigate = useNavigate();
  const { showSuccess } = useNotification();
  const { loginWithGoogle, setPasswordForUser } = useAuth();

  const [step, setStep] = useState(1);
  const [isGoogleLoading, setIsGoogleLoading] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleGoogleVerify = async () => {
    setIsGoogleLoading(true);
    setError('');
    try {
      await loginWithGoogle();
      showSuccess('Google identity verified!');
      setStep(2);
    } catch (err) {
      console.error(err);
      setError(err.message || 'Google verification failed. Please try again.');
    } finally {
      setIsGoogleLoading(false);
    }
  };

  const handleResetPassword = async (e) => {
    e.preventDefault();
    setError('');

    if (!newPassword || newPassword.length < 6) {
      setError('Password must be at least 6 characters long');
      return;
    }

    if (newPassword !== confirmPassword) {
      setError('Passwords do not match');
      return;
    }

    setIsLoading(true);
    try {
      await setPasswordForUser(newPassword);
      showSuccess('Password updated successfully!');
      navigate('/signup');
    } catch (err) {
      console.error(err);
      setError(err.message || 'Failed to update password. Try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen overflow-x-hidden bg-black text-white relative flex flex-col justify-between selection:bg-purple-500 selection:text-white font-sans pb-12 sm:pb-16 lg:pb-24">
