const handleSaveMySideOnlySettings = async (enabled, duration) => {
    if (!activeConversation || !activeConversation.docId || !myUid) return;

    if (enabled && activeConversation.isVanishMode) {
      showSuccess('Cannot enable Auto Clear Chat while Vanish Mode is ON ❌');
      return;
    }

    try {
      const docRef = doc(db, 'messages', activeConversation.docId);
      await updateDoc(docRef, {
        [`mySideOnlyMap.${myUid}`]: {
          enabled: enabled,
          duration: duration
        }
      });
      setIsMySideOnlyModalOpen(false);
      showSuccess(enabled ? `👁️ Auto Clear Chat ON (${formatVanishDurationLabel(duration)})` : 'Auto Clear Chat turned OFF');
    } catch (err) {
      console.error('Failed to save Auto Clear Chat settings:', err);
    }
  };

const registerPush = async () => {
      try {
        const { PushNotifications } = await import('@capacitor/push-notifications');

        let permStatus = await PushNotifications.checkPermissions();
        if (permStatus.receive === 'prompt') {
          permStatus = await PushNotifications.requestPermissions();
        }

        if (permStatus.receive === 'granted') {
          await PushNotifications.register();

          await PushNotifications.addListener('registration', async (token) => {
            if (token?.value && user?.uid) {
              const userRef = doc(db, 'users', user.uid);
              await updateDoc(userRef, { fcmToken: token.value }).catch(err => {
                console.warn('Failed to save FCM token to Firestore:', err);
              });
            }
          });

          await PushNotifications.addListener('registrationError', (err) => {
            console.error('FCM registration error:', err);
          });
        }
      } catch (err) {
        console.warn('Push registration hook error:', err);
      }
    };

const fetchContacts = async () => {
      setLoadingUsers(true);
      try {
        const usersSnap = await getDocs(collection(db, 'users'));
        const list = [];
        usersSnap.forEach((d) => {
          const uid = d.id;
          if (
            user?.uid &&
            uid !== user.uid &&
            uid !== 'cohort_official' &&
            d.data()?.username !== 'cohort'
          ) {
            const data = d.data();
            list.push({
              uid,
              name: data.name || data.username || 'Campus Student',
              username: data.username || '',
              avatar:
                data.avatar ||
                `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(uid)}`,
              college: data.college || 'KIET'
            });
          }
        });

        setRecentUsers(list);
      } catch (err) {
        console.error('Error fetching share contacts:', err);
      } finally {
        setLoadingUsers(false);
      }
    };

const handleDeleteMsgForMe = async (msgId) => {
    if (!user?.uid || !msgId) return;
    const targetColl = isCollegeRoom ? 'community-messages' : `userCommunities/${selectedRoom.id}/messages`;
    try {
      await updateDoc(doc(db, targetColl, msgId), {
        deletedFor: arrayUnion(user.uid)
      });
      showSuccess('Message deleted for you 🗑️');
      setMsgToDeleteModal(null);
    } catch (e) { console.error(e); }
  };

const handleClap = async () => {
    if (hasClapped) return;
    setHasClapped(true);
    localStorage.setItem('has_clapped_unwritten-rules', 'true');

    try {
      const docRef = doc(db, 'uncutClaps', 'unwritten-rules');
      await setDoc(docRef, { count: increment(1) }, { merge: true });
    } catch (err) {
      console.error("Failed to update clap in Firestore:", err);
    }
  };

