                    type="password"
                    placeholder="Re-enter new password"
                    value={forgotConfirmPass}
                    onChange={(e) => setForgotConfirmPass(e.target.value)}
                    className="w-full bg-neutral-950 border border-neutral-800 rounded-2xl px-4 py-2.5 text-sm text-white placeholder-neutral-500 focus:outline-none focus:border-sky-500"
                  />
                </div>

                <div className="flex gap-2 pt-2">
                  <button
                    type="button"
                    onClick={() => setIsForgotModalOpen(false)}
                    className="flex-1 py-2.5 rounded-xl border border-neutral-800 text-xs font-bold text-neutral-400 hover:bg-neutral-800 transition-colors cursor-pointer"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    disabled={isSavingForgotPass}
                    className="flex-1 py-2.5 rounded-xl bg-gradient-to-r from-sky-500 to-blue-600 hover:from-sky-400 hover:to-blue-500 text-xs font-extrabold text-white shadow-lg shadow-sky-500/20 transition-all cursor-pointer"
                  >
                    {isSavingForgotPass ? 'Saving...' : 'Reset Password'}
                  </button>
                </div>
              </form>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

const loadInviteUsers = async () => {
    if (!user?.uid) return;
    setLoadingInviteUsers(true);
    try {
      const usersSnap = await getDocs(collection(db, 'users'));
      const loaded = [];
      usersSnap.forEach(d => {
        if (d.id !== user.uid) {
          const data = d.data();
          const isFollower = (data.followers || []).includes(user.uid);
          const isFollowing = (data.following || []).includes(user.uid);
          const alreadyMember = (selectedRoom?.members || []).includes(d.id);
          if (!alreadyMember) {
            loaded.push({ uid: d.id, ...data, isFollower, isFollowing });
          }
        }
      });
      // Sort: connections first
      loaded.sort((a, b) => {
        const aScore = (a.isFollower ? 1 : 0) + (a.isFollowing ? 1 : 0);
        const bScore = (b.isFollower ? 1 : 0) + (b.isFollowing ? 1 : 0);
        return bScore - aScore;
      });
      setInviteUsers(loaded);
    } catch (e) { console.error(e); }
    finally { setLoadingInviteUsers(false); }
  };

