export const formatShortCollegeName = (rawName) => {
  if (!rawName) return 'Campus';
  let short = String(rawName).trim();
  if (short.includes(' - ')) {
    short = short.split(' - ')[0].trim();
  }
  if (short.includes(' (')) {
    short = short.split(' (')[0].trim();
  }
  if (short.includes(',')) {
    short = short.split(',')[0].trim();
  }
  return short;
};

const handleCardImageSelect = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!file.type.startsWith('image/')) {
      showWarning('Please select an image file');
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      showWarning('Image size should be less than 5MB');
      return;
    }
    const reader = new FileReader();
    reader.onload = (event) => {
      setCardSelectedImage(event.target.result);
    };
    reader.readAsDataURL(file);
  };

