      }
      return part;
    });
  };

  const toggleReplies = (commentId) => {
    setExpandedRepliesMap(prev => ({
      ...prev,
      [commentId]: !prev[commentId]
    }));
  };

  const handleInitiateReplyToComment = (c, postId) => {
