    setReplyingToComment({
      commentId: c.id,
      authorUid: c.authorUid,
      author: name,
      parentId: c.parentId || c.id
    });
    setCommentText(`@${name} `);

    if (commentInputRef.current) {
      commentInputRef.current.focus();
    }
  };

  const handleReport = async (itemId, isConfession) => {
