                                        <AnimatePresence>
                                          {isExpanded && (
                                            <motion.div
                                              initial={{ opacity: 0, height: 0 }}
                                              animate={{ opacity: 1, height: 'auto' }}
                                              exit={{ opacity: 0, height: 0 }}
                                              className="space-y-xs border-l-2 border-zinc-800/80 ml-2 pl-2"
                                            >
