                                                      <Heart className={`w-3 h-3 ${isReplyLiked ? 'fill-rose-500 text-rose-500' : ''}`} />
                                                    </button>
                                                  </div>
                                                );
                                              })}
                                            </motion.div>
                                          )}
                                        </AnimatePresence>
                                      </div>
                                    )}
                                  </div>
                                );
