    e.preventDefault();
    if (!forgotNewPass || forgotNewPass.length < 6) {
      showError('Password must be at least 6 characters long.');
      return;
    }
    if (forgotNewPass !== forgotConfirmPass) {
      showError('Passwords do not match.');
      return;
