    try {
      await setPasswordForUser(forgotNewPass);
      showSuccess('Password reset successfully! You can now use your new password.');
      setIsForgotModalOpen(false);
      setForgotStep(1);
      setForgotNewPass('');
      setForgotConfirmPass('');
