        status: 'rejected',
        read: true
      });
      setList(prev => prev.map(n => n.id === notif.id ? { ...n, status: 'rejected', read: true } : n));
      showSuccess('Invite declined.');
    } catch (err) {
      console.error('Failed to reject invite:', err);
    }
  };

