          </p>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="max-w-2xl mx-auto space-y-6">
        {/* Toggle between Public Feed and My College Feed (Only shown on Anonymous Feed tab) */}
        {activeTab === 'feed' && (
          <FeedToggle
