                    }`}
                    title="Add Photos"
                  >
                    <ImageIcon className={`w-4 h-4 transition-transform duration-300 ${cardSelectedImage ? 'scale-110 text-sky-500' : ''}`} />
                    <span>Add Photos</span>
                    {cardSelectedImage && (
