  };

  const userCollege = user?.college || 'KIET';

  const filterAnonymousItem = (item) => {
    const postCollege = item.college || item.authorCollege || item.author?.college || item.author?.role;
    const cleanPost = postCollege ? String(postCollege).toLowerCase().trim() : '';
    const cleanUser = String(userCollege).toLowerCase().trim();
    const isSameCollege = cleanPost && (cleanPost.includes(cleanUser) || cleanUser.includes(cleanPost));
    const isMyPost = item.authorUid === user?.uid;

    const isCollegeOnlyPost = item.audience === 'college_only' || item.visibility === 'college_only';

    // 1. Public Feed: strictly show ONLY public posts (exclude college-only posts)
    if (feedType === 'public') {
      return !isCollegeOnlyPost;
    }

    // 2. My College Feed: strictly show ONLY college-only posts from user's college (or user's own college posts)
    return isCollegeOnlyPost && (isSameCollege || isMyPost);
  };

  const displayedPosts = posts.filter(filterAnonymousItem);
  const displayedConfessions = confessions.filter(filterAnonymousItem);

  return (
    <div className="section-container !py-6 !px-4 min-h-screen">
      <SEO title={activeTab === 'confessions' ? '24-Hour Confessions' : 'Anonymous Campus Feed'} />

      {/* Header */}
      <div className="flex items-center justify-between max-w-2xl mx-auto border-b border-neutral-200 dark:border-zinc-800/80 pb-lg mb-6">
        <div>
          <h1 className={`text-2xl md:text-3xl font-heading font-bold bg-clip-text text-transparent ${
            activeTab === 'confessions'
              ? 'bg-gradient-to-r from-rose-500 via-red-500 to-pink-500 dark:from-rose-400 dark:via-red-400 dark:to-pink-400 drop-shadow-[0_0_15px_rgba(244,63,94,0.3)]'
              : 'bg-gradient-to-r from-violet-600 via-purple-500 to-indigo-600 dark:from-violet-400 dark:via-purple-300 dark:to-indigo-300'
          }`}>
            {activeTab === 'confessions' ? 'Confessions' : 'Anonymous'}
          </h1>
          <p className="text-xs text-neutral-500 dark:text-zinc-400 mt-xs font-medium tracking-wide">
            {activeTab === 'confessions'
              ? 'Share your secret campus confessions. Nobody knows it’s you.'
              : 'Share freely. Nobody knows it’s you.'}
          </p>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="max-w-2xl mx-auto space-y-6">
        {/* Toggle between Public Feed and My College Feed (Only shown on Anonymous Feed tab) */}
        {activeTab === 'feed' && (
          <FeedToggle
            activeFeed={feedType}
            onChangeFeed={setFeedType}
            userCollege={userCollege}
          />
        )}

        {/* Inline Create Post Card */}
        <div className="border border-neutral-200/80 dark:border-zinc-800/80 bg-white/90 dark:bg-zinc-900/90 backdrop-blur-xl rounded-3xl p-4 sm:p-5 shadow-lg shadow-black/5 dark:shadow-black/30 transition-all">
          {activeTab === 'confessions' && !user?.kycVerified ? (
            <div className="flex flex-col items-center text-center py-4 px-2 space-y-4">
              <div className="w-12 h-12 rounded-2xl bg-amber-500/10 dark:bg-amber-500/20 text-amber-500 flex items-center justify-center border border-amber-500/20 shadow-xs">
                <ShieldAlert className="w-6 h-6 text-amber-500" />
              </div>
              <div className="space-y-1">
                <h4 className="text-sm font-extrabold text-neutral-900 dark:text-white">
                  Confessions Restricted
                </h4>
                <p className="text-xs text-neutral-500 dark:text-neutral-400 max-w-sm leading-relaxed">
                  Confessions are restricted to verified students. Verify your student email to post confessions on this campus.
                </p>
              </div>
              <button
                type="button"
                onClick={openKycModal}
                className="px-6 py-2.5 rounded-full bg-gradient-to-r from-violet-600 to-indigo-600 hover:from-violet-500 hover:to-indigo-500 text-white font-extrabold text-xs shadow-md transition-all active:scale-95 cursor-pointer uppercase tracking-wider"
              >
                Verify Student ID
              </button>
            </div>
          ) : (
            <>
              <div className="flex gap-3 sm:gap-4">
            {/* Anonymous / Confession Avatar Badge */}
            <div className={`w-11 h-11 rounded-full flex items-center justify-center flex-shrink-0 shadow-md transition-all ${
              activeTab === 'confessions'
                ? 'bg-rose-500/10 border border-rose-500/30 text-rose-400'
                : 'bg-sky-500/10 border border-sky-500/30 text-sky-400'
            }`}>
              {activeTab === 'confessions' ? (
                <Flame className="w-5 h-5 text-rose-400 fill-rose-500/20" />
              ) : (
                <EyeOff className="w-5 h-5 text-sky-400" />
              )}
            </div>

            {/* Seamless Input Textarea */}
            <div className="flex-1 min-w-0">
              <textarea
                rows={3}
                value={cardInputText}
                onChange={(e) => setCardInputText(e.target.value)}
                placeholder={
                  activeTab === 'confessions'
                    ? "Share a secret confession..."
