const login = async (emailOrUsername, password) => {
    let emailToUse = emailOrUsername.trim();
    if (!emailToUse.includes('@')) {
      const cleanUsername = emailToUse.replace(/^@/, '').toLowerCase();
      try {
        const usersRef = collection(db, 'users');
        const q1 = query(usersRef, where('username', '==', cleanUsername));
        const snap1 = await getDocs(q1);
        if (!snap1.empty && snap1.docs[0].data()?.email) {
          emailToUse = snap1.docs[0].data().email;
        } else {
          const q2 = query(usersRef, where('usernameHandle', '==', cleanUsername));
          const snap2 = await getDocs(q2);
          if (!snap2.empty && snap2.docs[0].data()?.email) {
            emailToUse = snap2.docs[0].data().email;
          } else {
            emailToUse = `${cleanUsername}@student.edu`;
          }
        }
      } catch (err) {
        console.error('Username lookup error:', err);
        emailToUse = `${cleanUsername}@student.edu`;
      }
    }
    return signInWithEmailAndPassword(auth, emailToUse, password);
  };

const handleLikePost = async (item, isConfession) => {
    const targetColl = isConfession ? 'confessions' : 'anonymousPosts';
    const myUid = user?.uid || 'guest';
    let likedList = [...(item.likedUsers || [])];

    if (likedList.includes(myUid)) {
      likedList = likedList.filter(u => u !== myUid);
    } else {
      likedList.push(myUid);
    }

    try {
      const docRef = doc(db, targetColl, item.docId);
      if (isConfession) {
        await updateDoc(docRef, { likes: likedList.length, likedUsers: likedList });
      } else {
        await updateDoc(docRef, { likesCount: likedList.length, likedUsers: likedList });
      }
    } catch (err) {
      console.error('Error toggling like:', err);
    }
  };

const renderTaggedCommentText = (text) => {
    if (!text) return '';
    const mentionRegex = /(@[a-zA-Z0-9_\s]+?)(?=\s|$|[.,!?])/g;
    const parts = text.split(mentionRegex);

    return parts.map((part, index) => {
      if (part.startsWith('@')) {
        return (
          <span key={index} className="font-bold text-violet-400 bg-violet-950/40 px-1 py-0.5 rounded">
            {part}
          </span>
        );
      }
      return part;
    });
  };

