                                           window.location.href = targetUrl;
                                         } else if (sharedId) {
                                           if (sharedId.includes('-') || sharedId.includes('/')) {
                                             window.location.href = `/uncut/${sharedId}`;
                                           } else {
                                             window.location.href = `/post/${sharedId}`;
                                           }
                                         } else {
                                           window.location.href = '/home';
                                         }
