                                            : 'text-white/50 dark:text-neutral-400'
                                        }`}
                                        title={isSeen ? "Seen (Green Tick)" : "Sent/Delivered"}
                                      />
                                    )}
                                  </span>
                                </div>

                                {/* Vanish Mode Indicators & Per-User Keep Status */}
                                {msg.isVanish && (() => {
