                  <div className="flex items-center gap-md min-w-0">
                    {selectedMedia.type === 'image' ? (
                      <img src={selectedMedia.url} alt="Preview" className="w-12 h-12 rounded-xl object-cover border shadow-sm flex-shrink-0" />
