          }

          const rawId = typeof idItem === 'object' ? (idItem.uid || idItem.id) : String(idItem);
          const matchedUser = userMap[rawId] || userMap[rawId.toLowerCase()];

          if (matchedUser) {
            results.push(matchedUser);
