const formatShortCollegeName = (rawName) => {
  if (!rawName) return 'Campus';
  let short = rawName.trim();
  if (short.includes(' - ')) {
    short = short.split(' - ')[0].trim();
  } else if (short.includes(' (')) {
    short = short.split(' (')[0].trim();
  }
  return short;
};

