              <Button variant="primary" className="flex-1" onClick={handleJoinCommunity} disabled={isJoining}>{isJoining ? 'Joining...' : 'Join Community'}</Button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="flex flex-col md:flex-row gap-0 md:gap-lg h-full min-h-0 flex-1 overflow-hidden max-w-full min-w-0">
        {/* ──────── LEFT SIDEBAR ──────── */}
        <div className={`w-full md:w-80 lg:w-96 flex-shrink-0 flex flex-col h-full overflow-hidden max-w-full min-w-0 ${selectedRoom ? 'hidden md:flex' : 'flex'}`}>
          <Card className="flex-1 flex flex-col p-0 overflow-hidden rounded-none md:rounded-xl border-none md:border max-w-full min-w-0">

        {/* Sidebar Header */}
        <div className="px-lg pt-lg pb-md flex-shrink-0">
          <div className="flex items-center justify-between mb-md">
            <div className="flex items-center gap-xs">
              <button
                onClick={() => navigate('/messages?tab=direct')}
                className="p-xs text-neutral-500 hover:text-neutral-900 dark:hover:text-white hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors cursor-pointer active:scale-95"
                title="Back to Direct Messages"
