function Messages() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const targetRecipientUid = searchParams.get('recipientUid');
  const targetRecipientName = searchParams.get('recipientName');

  const { user } = useAuth();
  const { showSuccess } = useNotification();

  const [conversations, setConversations] = useState([]);
  const [myCommunities, setMyCommunities] = useState([]);
  const [selectedId, setSelectedId] = useState(null);
  const initialTab = searchParams.get('tab') === 'community' ? 'community' : 'direct';
  const [messagesTab, setMessagesTab] = useState(initialTab); // 'direct' | 'community'
  const [search, setSearch] = useState('');
  const [messageText, setMessageText] = useState('');
  const [mobileView, setMobileView] = useState('list'); // list, chat

  // Hide mobile floating nav when inside active chat on mobile
  useEffect(() => {
    if (mobileView === 'chat') {
      document.body.classList.add('in-active-chat');
      document.documentElement.classList.add('in-active-chat');
    } else {
      document.body.classList.remove('in-active-chat');
      document.documentElement.classList.remove('in-active-chat');
    }
    return () => {
      document.body.classList.remove('in-active-chat');
      document.documentElement.classList.remove('in-active-chat');
    };
  }, [mobileView]);

  // Attachment Popover State
  const [showAttachMenuPop, setShowAttachMenuPop] = useState(false);

  // Intercept back button / history state when attachment popover is open
  useEffect(() => {
    if (showAttachMenuPop) {
      window.history.pushState({ trayOpen: true }, '');
      const handlePopState = () => {
        setShowAttachMenuPop(false);
      };
      window.addEventListener('popstate', handlePopState);
      return () => {
        window.removeEventListener('popstate', handlePopState);
      };
    }
  }, [showAttachMenuPop]);

  const [allStarredCommunityMsgs, setAllStarredCommunityMsgs] = useState([]);
  const [isCommunityStarredModalOpen, setIsCommunityStarredModalOpen] = useState(false);
  const [selectedMedia, setSelectedMedia] = useState(null);
  const [previewImageModal, setPreviewImageModal] = useState(null);
  const [msgToDeleteModal, setMsgToDeleteModal] = useState(null);
  const [revealedDeletedMsgs, setRevealedDeletedMsgs] = useState([]);
  const mediaInputRef = useRef(null);
  const docInputRef = useRef(null);
  const messageInputRef = useRef(null);

  // DM Poll Modal State
  const [isCreatePollOpen, setIsCreatePollOpen] = useState(false);
  const [pollQuestion, setPollQuestion] = useState('');
  const [pollOptions, setPollOptions] = useState(['', '']);
  const [pollType, setPollType] = useState('single');

  const handleDocumentSelect = (e) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedMedia({
        file,
        url: URL.createObjectURL(file),
        type: 'file',
        name: file.name
      });
      showSuccess(`Document attached: ${file.name}`);
    }
  };

  const handleCreatePoll = async (e) => {
    if (e && e.preventDefault) e.preventDefault();
    if (!pollQuestion.trim()) {
      showSuccess('Please enter a poll question.');
      return;
    }
    const validOptions = pollOptions.filter(o => o.trim() !== '');
    if (validOptions.length < 2) { showSuccess('At least 2 options required.'); return; }

    const targetConv = conversations.find(c => c.id === selectedId || c.docId === selectedId);
    if (!targetConv) return;

    const myName = user?.name || user?.email?.split('@')[0] || 'Me';
    const pollObj = {
      question: pollQuestion.trim(),
      pollType: pollType,
      totalVotes: 0,
      options: validOptions.map((optText, i) => ({ id: `opt_${i}`, text: optText.trim(), votes: 0, votedUsers: [] }))
    };

    const newMsg = {
      sender: user?.uid || 'me',
      senderUid: user?.uid || null,
      senderName: myName,
      text: `Poll: ${pollQuestion.trim()}`,
      poll: pollObj,
      type: 'poll',
      time: new Date(),
      deletedFor: []
    };

    setIsCreatePollOpen(false);
    setPollQuestion('');
    setPollOptions(['', '']);
    setPollType('single');

    const updatedMsgs = [...(targetConv.messages || []), newMsg];
    setConversations(prev => prev.map(c => (c.id === selectedId || c.docId === selectedId) ? { ...c, messages: updatedMsgs } : c));

    const targetDocId = targetConv.docId || targetConv.id;
    if (targetDocId) {
      try {
        await updateDoc(doc(db, 'messages', targetDocId), {
          messages: updatedMsgs,
          lastMessage: `Poll: ${pollQuestion.trim()}`,
          lastTime: new Date()
        });
      } catch (err) {
        console.error(err);
      }
    }
    showSuccess('Poll published in chat!');
  };

  const handleMessagePollVote = async (targetMsg, optIndex) => {
    if (!targetMsg || !targetMsg.poll) return;

    const targetConv = conversations.find(c => c.id === selectedId || c.docId === selectedId);
    if (!targetConv) return;

    const messages = [...(targetConv.messages || [])];
    const realMsgIndex = messages.findIndex(m =>
      m === targetMsg ||
      (m.poll && targetMsg.poll && m.poll.question === targetMsg.poll.question && (m.time === targetMsg.time || m.text === targetMsg.text))
    );

    if (realMsgIndex === -1) {
      console.warn('Could not find target message for poll vote');
      return;
    }

    const currentMsg = messages[realMsgIndex];
    const targetPoll = currentMsg.poll;
    const isMultiple = targetPoll.pollType === 'multiple';
    const myUid = user?.uid || 'guest_user';
    const myName = user?.name || user?.email?.split('@')[0] || 'Student';
    const myAvatar = user?.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(user?.email || myName)}`;
    const myUserObj = { uid: myUid, name: myName, avatar: myAvatar };

    const updatedOptions = (targetPoll.options || []).map((o, idx) => {
      const currentVotedUsers = Array.isArray(o.votedUsers) ? o.votedUsers : [];
      const currentDetails = Array.isArray(o.votedUserDetails) ? o.votedUserDetails : [];
      const hasVoted = currentVotedUsers.includes(myUid);

      if (idx === optIndex) {
        if (hasVoted) {
          const nextVoted = currentVotedUsers.filter(id => id !== myUid);
          const nextDetails = currentDetails.filter(u => u.uid !== myUid);
          return { ...o, votedUsers: nextVoted, votedUserDetails: nextDetails, votes: nextVoted.length, selected: false };
        } else {
          const nextVoted = [...currentVotedUsers, myUid];
          const nextDetails = [...currentDetails.filter(u => u.uid !== myUid), myUserObj];
          return { ...o, votedUsers: nextVoted, votedUserDetails: nextDetails, votes: nextVoted.length, selected: true };
        }
      } else if (!isMultiple) {
        const nextVoted = currentVotedUsers.filter(id => id !== myUid);
        const nextDetails = currentDetails.filter(u => u.uid !== myUid);
        return { ...o, votedUsers: nextVoted, votedUserDetails: nextDetails, votes: nextVoted.length, selected: false };
      }
      return { ...o, votedUsers: currentVotedUsers, votedUserDetails: currentDetails, votes: currentVotedUsers.length, selected: currentVotedUsers.includes(myUid) };
    });

    const newTotalVotes = updatedOptions.reduce((sum, o) => sum + (o.votedUsers?.length || 0), 0);
    const updatedPoll = { ...targetPoll, options: updatedOptions, totalVotes: newTotalVotes };
    const updatedMsg = { ...currentMsg, poll: updatedPoll };

    messages[realMsgIndex] = updatedMsg;
    setConversations(prev => prev.map(c => (c.id === selectedId || c.docId === selectedId) ? { ...c, messages: messages } : c));
    showSuccess('Vote recorded!');

    const targetDocId = targetConv.docId || targetConv.id;
    if (targetDocId) {
      try {
        await updateDoc(doc(db, 'messages', targetDocId), { messages: messages });
      } catch (err) {
        console.error('Failed to update poll vote in Firestore:', err);
      }
    }
  };


  const handleToggleRevealDeleted = (msgKey) => {
    setRevealedDeletedMsgs(prev =>
      prev.includes(msgKey) ? prev.filter(k => k !== msgKey) : [...prev, msgKey]
    );
  };

  const handleDownloadMedia = (url, filename = 'download.png') => {
    try {
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      showSuccess('Download started 📥');
    } catch (err) {
      console.error('Download error:', err);
      window.open(url, '_blank');
    }
  };

  // New Chat Modal & Context Menu States
  const [isNewChatOpen, setIsNewChatOpen] = useState(false);
  const [searchUserQuery, setSearchUserQuery] = useState('');
  const [matchingUsers, setMatchingUsers] = useState([]);
  const [searchingUsers, setSearchingUsers] = useState(false);
  const [openMenuId, setOpenMenuId] = useState(null);

  // Chat Search, Starred, Select Mode & Profile Modal States
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [chatSearchQuery, setChatSearchQuery] = useState('');
  const [isSelectMode, setIsSelectMode] = useState(false);
  const [selectedMsgKeys, setSelectedMsgKeys] = useState([]);
  const [replyToMsg, setReplyToMsg] = useState(null);
  const [isStarredModalOpen, setIsStarredModalOpen] = useState(false);
  const [isGlobalStarredModalOpen, setIsGlobalStarredModalOpen] = useState(false);
  const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
  const [recipientProfile, setRecipientProfile] = useState(null);
  const [highlightedMsgKey, setHighlightedMsgKey] = useState(null);

  // WhatsApp-style Poll Votes Breakdown Modal state
  const [viewVotesPoll, setViewVotesPoll] = useState(null);

  // Real-time Users Map for live avatar & profile sync across chats & modals
  const [usersMap, setUsersMap] = useState({});

  useEffect(() => {
    const unsub = onSnapshot(collection(db, 'users'), (snap) => {
      const map = {};
      snap.forEach(d => {
        map[d.id] = { id: d.id, uid: d.id, ...d.data() };
      });
      setUsersMap(map);
    }, (err) => console.error('Users map snapshot error:', err));
    return () => unsub();
  }, []);

  const getLiveRecipientProfile = (conv) => {
    if (!conv) return { avatar: '', name: 'Student', username: '', college: 'KIET' };

    // Always resolve the OTHER participant's UID (distinct from current user myUid)
    let otherUid = (conv.participants || []).find(p => p && p !== myUid);
    if (!otherUid) {
      if (conv.recipientUid && conv.recipientUid !== myUid) {
        otherUid = conv.recipientUid;
      } else if (conv.createdBy && conv.createdBy !== myUid) {
        otherUid = conv.createdBy;
      } else {
        const otherMsg = (conv.messages || []).find(m => (m.senderUid && m.senderUid !== myUid) || (m.sender && m.sender !== myUid && m.sender !== 'me'));
        if (otherMsg) {
          otherUid = otherMsg.senderUid || (otherMsg.sender !== 'me' ? otherMsg.sender : null);
        }
      }
    }

    const liveUser = (otherUid && usersMap[otherUid]) || null;
    const mapInfo = (otherUid && conv.participantMap?.[otherUid]) || null;

    let name = liveUser?.name || mapInfo?.name;
    if (!name) {
      if (conv.recipientUid && conv.recipientUid !== myUid && conv.recipientName) {
        name = conv.recipientName;
      } else if (conv.createdBy && conv.createdBy !== myUid && conv.createdByName) {
        name = conv.createdByName;
      } else {
        name = (conv.name && conv.name !== user?.name) ? conv.name : (conv.recipientName || 'Student');
      }
    }

    let avatar = liveUser?.avatar || mapInfo?.avatar;
    if (!avatar) {
      if (conv.recipientUid && conv.recipientUid !== myUid && conv.recipientAvatar) {
        avatar = conv.recipientAvatar;
      } else if (conv.createdBy && conv.createdBy !== myUid && conv.createdByAvatar) {
        avatar = conv.createdByAvatar;
      } else {
        avatar = (conv.avatar && conv.avatar !== user?.avatar) ? conv.avatar : `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(name)}`;
      }
    }

    return {
      avatar,
      name,
      username: liveUser?.username || mapInfo?.username || conv.username || '',
      college: liveUser?.college || mapInfo?.college || conv.college || 'Campus Peer',
      bio: liveUser?.bio || mapInfo?.bio || conv.bio || '',
      uid: otherUid || (conv.recipientUid !== myUid ? conv.recipientUid : conv.createdBy)
    };
  };

  // Optional Vanish Mode States
  const [isVanishModalOpen, setIsVanishModalOpen] = useState(false);
  const [isKeepForeverActive, setIsKeepForeverActive] = useState(false);
  const [vanishDurationInput, setVanishDurationInput] = useState(3600); // Default 1 hour (3600s)
  const [vanishKeepPermissionInput, setVanishKeepPermissionInput] = useState('always'); // 'always' | 'ask' | 'never'
  const [customVanishInput, setCustomVanishInput] = useState('');
  const [nowTick, setNowTick] = useState(Date.now());

  // My Side Only (Local Auto-Delete) States
  const [isMySideOnlyModalOpen, setIsMySideOnlyModalOpen] = useState(false);
  const [mySideOnlyDurationInput, setMySideOnlyDurationInput] = useState(300); // Default 5 minutes (300s)

  // ── Confirmation Popups
  const [confirmClearChatConv, setConfirmClearChatConv] = useState(null);
  const [confirmDeleteConv, setConfirmDeleteConv] = useState(null);

  const [loading, setLoading] = useState(true);
  const [showHeaderMenu, setShowHeaderMenu] = useState(false);

  const messagesEndRef = useRef(null);
  const myUid = user?.uid || 'guest';

  // Live ticker for second-by-second vanish countdown
  useEffect(() => {
    const timer = setInterval(() => {
      setNowTick(Date.now());
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  // Helper to format vanish duration
  const formatVanishDurationLabel = (sec) => {
    if (!sec) return '1 Hour';
    if (sec < 60) return `${sec} Sec${sec === 1 ? '' : 's'}`;
    if (sec < 3600) return `${Math.floor(sec / 60)} Min${Math.floor(sec / 60) === 1 ? '' : 's'}`;
    if (sec < 86400) return `${Math.floor(sec / 3600)} Hour${Math.floor(sec / 3600) === 1 ? '' : 's'}`;
    return `${Math.floor(sec / 86400)} Day${Math.floor(sec / 86400) === 1 ? '' : 's'}`;
  };

  // Helper to compute live remaining countdown
  const getRemainingVanishTime = (expiresAtTime) => {
    if (!expiresAtTime) return null;
    const targetMs = expiresAtTime.toDate ? expiresAtTime.toDate().getTime() : new Date(expiresAtTime).getTime();
    const diffMs = targetMs - nowTick;
    if (diffMs <= 0) return 'Expired';
    const totalSec = Math.floor(diffMs / 1000);
    if (totalSec < 60) return `${totalSec}s`;
    if (totalSec < 3600) {
      const m = Math.floor(totalSec / 60);
      const s = totalSec % 60;
      return `${m}m ${s}s`;
    }
    const h = Math.floor(totalSec / 3600);
    const m = Math.floor((totalSec % 3600) / 60);
    return `${h}h ${m}m`;
  };

  // Load matching users from Firestore when searchUserQuery or Modal opens
  useEffect(() => {
    if (!isNewChatOpen) return;

    const fetchUsers = async () => {
      setSearchingUsers(true);
      try {
        const usersSnap = await getDocs(collection(db, 'users'));
        const loaded = [];
        const cleanQuery = searchUserQuery.toLowerCase().replace('@', '').trim();

        usersSnap.forEach(d => {
          if (d.id === user?.uid) return; // Skip self

          const data = d.data();
          const nameMatch = !cleanQuery || (data.name && data.name.toLowerCase().includes(cleanQuery));
          const usernameMatch = cleanQuery && data.username && data.username.toLowerCase().includes(cleanQuery);
          const collegeMatch = cleanQuery && data.college && data.college.toLowerCase().includes(cleanQuery);

          if (nameMatch || usernameMatch || collegeMatch) {
            loaded.push({ id: d.id, uid: d.id, ...data });
          }
        });

        setMatchingUsers(loaded);
      } catch (err) {
        console.error('Failed to search users in modal:', err);
      } finally {
        setSearchingUsers(false);
      }
    };

    fetchUsers();
  }, [searchUserQuery, isNewChatOpen, user?.uid]);

  // Ref lock to prevent target recipient processing from running multiple times or looping
  const hasHandledTargetRef = useRef(false);

  // Real-time Firestore Listener for User Conversations
  useEffect(() => {
    if (!user) return;
    setLoading(true);

    const messagesCollection = collection(db, 'messages');

    const unsubscribe = onSnapshot(messagesCollection, (snapshot) => {
      const loaded = [];
      snapshot.forEach(d => {
        const data = d.data();
        const convName = (data.name || '').toLowerCase();
        const isFake = FAKE_CHAT_NAMES.some(fake => convName.includes(fake));

        if (isFake) {
          deleteDoc(doc(db, 'messages', d.id)).catch(err => console.error('Purging fake chat thread:', err));
        } else {
          const isParticipant = (data.participants && data.participants.includes(user.uid)) ||
                                data.recipientUid === user.uid ||
                                data.createdBy === user.uid;

          // Check if conversation is hidden specifically for current user
          const isHiddenForMe = data.hiddenFor?.[user.uid] === true;

          if (isParticipant && !isHiddenForMe) {
            const parsedMsgs = (data.messages || []).map(m => ({
              ...m,
              time: m.time?.toDate ? m.time.toDate() : new Date(m.time || Date.now())
            }));

            // Determine other participant's UID and details
            let otherUid = (data.participants || []).find(pUid => pUid && pUid !== user.uid);
            if (!otherUid) {
              if (data.recipientUid && data.recipientUid !== user.uid) {
                otherUid = data.recipientUid;
              } else if (data.createdBy && data.createdBy !== user.uid) {
                otherUid = data.createdBy;
              }
            }

            let displayTitle = '';
            let avatarUrl = '';

            if (otherUid && data.participantMap && data.participantMap[otherUid]) {
              displayTitle = data.participantMap[otherUid].name;
              avatarUrl = data.participantMap[otherUid].avatar;
            } else if (data.recipientUid && data.recipientUid !== user.uid) {
              displayTitle = data.recipientName || (data.name !== user.name ? data.name : '') || 'Chat';
              avatarUrl = data.recipientAvatar || data.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(displayTitle)}`;
            } else if (data.createdBy && data.createdBy !== user.uid) {
              displayTitle = data.createdByName || 'Chat';
              avatarUrl = data.createdByAvatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(displayTitle)}`;
            } else {
              const otherMsg = parsedMsgs.find(m => m.senderUid && m.senderUid !== user.uid);
              if (otherMsg && otherMsg.senderName) {
                displayTitle = otherMsg.senderName;
                avatarUrl = `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(displayTitle)}`;
              } else {
                displayTitle = (data.name && data.name !== user.name) ? data.name : (data.recipientName || 'Chat');
                avatarUrl = data.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(displayTitle)}`;
              }
            }

            loaded.push({
              id: d.id,
              docId: d.id,
              ...data,
              name: displayTitle,
              avatar: avatarUrl,
              time: data.time?.toDate ? data.time.toDate() : new Date(data.time || Date.now()),
              messages: parsedMsgs
            });
          }
        }
      });

