                          >
                            <EyeOff className="w-3 h-3 text-purple-400 flex-shrink-0" />
                            <span className="truncate">Auto Clear • {formatVanishDurationLabel(activeConversation.mySideOnlyMap?.[myUid]?.duration || 300)}</span>
                          </div>
