  // Subscribe to real-time claps from Firestore
  useEffect(() => {
    const unsub = onSnapshot(doc(db, 'uncutClaps', '3am-coffee-club'), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (typeof data.count === 'number') {
          setClaps(data.count);
        }
      }
    });
    return () => unsub();
  }, []);

