          <span className="mx-3 text-neutral-300 dark:text-neutral-700">·</span>
          <Link to="/" className="text-sm text-neutral-400 dark:text-neutral-600 hover:text-neutral-600 dark:hover:text-neutral-400 transition-colors">
            Homepage
          </Link>
        </div>
