        await deleteDoc(doc(db, 'posts', postId));
        if (deletingPost.isReshare && deletingPost.originalPostId) {
          try {
            const origPostRef = doc(db, 'posts', deletingPost.originalPostId);
            await updateDoc(origPostRef, {
              reposts: increment(-1)
            });
          } catch (e) {
