        const isAPinned = a.pinnedFor?.[user.uid] === true;
        const isBPinned = b.pinnedFor?.[user.uid] === true;
        if (isAPinned && !isBPinned) return -1;
        if (!isAPinned && isBPinned) return 1;
        return b.time - a.time;
