                    const recipientUid = activeConversation?.recipientUid || (activeConversation?.participants || []).find(p => p !== myUid);
                    const isSeen = Boolean(isMe && (
                      msg.read === true ||
                      (Array.isArray(msg.readBy) && recipientUid && msg.readBy.includes(recipientUid))
