                    const msgKey = `${msg.text}_${new Date(msg.time).getTime()}`;
                    const isMsgSelected = selectedMsgKeys.includes(msgKey);
                    const isStarred = Array.isArray(msg.starredBy) && msg.starredBy.includes(myUid);
