                                                     {voterDetails.slice(0, 3).map((voter, vIdx) => (
                                                       <img
                                                         key={vIdx}
                                                         src={voter.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${voter.name}`}
