              </a>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* ── CREATE CAMPUS POLL MODAL ── */}
      {isCreatePollOpen && (
        <Modal isOpen={isCreatePollOpen} onClose={() => setIsCreatePollOpen(false)} title="Create Campus Poll" size="md">
          <form onSubmit={handleCreatePoll} className="space-y-5 py-1">
            {/* Question Input */}
            <div>
              <label className="block text-xs font-bold text-neutral-400 uppercase tracking-wider mb-2 flex items-center justify-between">
                <span>Poll Question</span>
                <span className="text-[10px] text-neutral-500 font-normal">Required</span>
              </label>
              <input
                type="text"
                placeholder="e.g. When should we schedule the exam review?"
                value={pollQuestion}
                onChange={(e) => setPollQuestion(e.target.value)}
                className="w-full px-4 py-3 rounded-2xl bg-neutral-900 border border-neutral-800 text-sm text-neutral-100 placeholder:text-neutral-500 focus:outline-none focus:border-neutral-700 transition-all font-medium"
                required
              />
            </div>

            {/* Voting Mode Toggle (Single vs Multiple choice) */}
            <div className="space-y-2">
              <label className="block text-xs font-bold text-neutral-400 uppercase tracking-wider">
                Voting Mode
              </label>
              <div className="grid grid-cols-2 gap-2 p-1.5 bg-neutral-900/80 rounded-2xl border border-neutral-800">
                <button
                  type="button"
                  onClick={() => setPollType('single')}
                  className={`py-2.5 px-3 rounded-xl text-xs font-semibold transition-all flex items-center justify-center gap-2 cursor-pointer ${
                    pollType === 'single'
                      ? 'bg-neutral-800 text-white border border-neutral-700 shadow-sm'
                      : 'text-neutral-400 hover:text-neutral-200'
                  }`}
                >
                  <CheckCircle2 className={`w-4 h-4 ${pollType === 'single' ? 'text-white' : 'text-neutral-500'}`} />
                  <span>Single Choice</span>
                </button>
                <button
                  type="button"
                  onClick={() => setPollType('multiple')}
                  className={`py-2.5 px-3 rounded-xl text-xs font-semibold transition-all flex items-center justify-center gap-2 cursor-pointer ${
                    pollType === 'multiple'
                      ? 'bg-neutral-800 text-white border border-neutral-700 shadow-sm'
                      : 'text-neutral-400 hover:text-neutral-200'
                  }`}
                >
                  <CheckSquare className={`w-4 h-4 ${pollType === 'multiple' ? 'text-white' : 'text-neutral-500'}`} />
                  <span>Multiple Choice</span>
                </button>
              </div>
              <p className="text-[11px] text-neutral-400 font-medium px-1">
                {pollType === 'single'
                  ? 'Students can select only one answer.'
                  : 'Students can select multiple answers.'}
              </p>
            </div>

            {/* Poll Options */}
            <div>
              <div className="flex items-center justify-between mb-2">
                <label className="text-xs font-bold text-neutral-400 uppercase tracking-wider">
                  Poll Options ({pollOptions.length}/6)
                </label>
                <span className="text-[10px] text-neutral-500 font-medium">Min 2 options</span>
              </div>
              <div className="space-y-2.5">
                {pollOptions.map((opt, idx) => (
                  <div key={idx} className="flex items-center gap-2">
                    <div className="relative flex-1">
                      <input
                        type="text"
                        placeholder={`Option ${idx + 1}`}
                        value={opt}
                        onChange={(e) => {
                          const n = [...pollOptions];
                          n[idx] = e.target.value;
                          setPollOptions(n);
                        }}
                        className="w-full pl-4 pr-10 py-2.5 rounded-2xl bg-neutral-900 border border-neutral-800 text-sm text-neutral-100 placeholder:text-neutral-500 focus:outline-none focus:border-neutral-700 font-medium transition-all"
                      />
                      <span className="absolute right-3.5 top-1/2 -translate-y-1/2 text-xs font-mono font-bold text-neutral-500">
                        #{idx + 1}
                      </span>
                    </div>
                    {pollOptions.length > 2 && (
                      <button
                        type="button"
                        onClick={() => setPollOptions(pollOptions.filter((_, i) => i !== idx))}
                        className="p-2.5 rounded-2xl bg-neutral-900 border border-neutral-800 text-neutral-400 hover:text-rose-400 transition-colors cursor-pointer"
                        title="Remove option"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                ))}
              </div>

              {pollOptions.length < 6 && (
                <button
                  type="button"
                  onClick={() => setPollOptions([...pollOptions, ''])}
                  className="w-full mt-3 py-2.5 border border-dashed border-neutral-800 hover:border-neutral-700 bg-neutral-900/40 hover:bg-neutral-900 rounded-2xl text-xs font-semibold text-neutral-300 hover:text-white transition-all flex items-center justify-center gap-2 cursor-pointer"
                >
                  <Plus className="w-4 h-4" />
                  <span>Add Option</span>
                </button>
              )}
            </div>

            <div className="flex gap-3 pt-3 border-t border-neutral-800">
              <Button variant="secondary" type="button" className="flex-1 rounded-2xl py-3 text-xs font-semibold cursor-pointer border-neutral-800 text-neutral-300 hover:bg-neutral-800" onClick={() => setIsCreatePollOpen(false)}>Cancel</Button>
              <button type="submit" disabled={!pollQuestion.trim() || pollOptions.filter(o => o.trim()).length < 2} className="flex-1 rounded-2xl py-3 text-xs font-bold bg-white text-neutral-900 hover:bg-neutral-200 transition-all cursor-pointer shadow-md disabled:opacity-50">Publish Poll</button>
            </div>
          </form>
        </Modal>
      )}

      {/* WhatsApp-Style Poll Votes Breakdown Modal */}
      {Boolean(viewVotesPoll) && (
        <Modal isOpen={Boolean(viewVotesPoll)} onClose={() => setViewVotesPoll(null)} title="Poll Votes Breakdown" size="md">
          <div className="space-y-4 py-1">
            <div className="p-3.5 rounded-2xl bg-neutral-900 border border-neutral-800 flex items-center justify-between">
              <div className="min-w-0 pr-2">
                <span className="text-[10px] font-bold text-violet-400 uppercase tracking-wider block">Question</span>
                <h4 className="text-sm font-extrabold text-white mt-0.5 truncate">{viewVotesPoll?.question}</h4>
              </div>
              <span className="text-[10px] font-bold text-violet-300 px-2.5 py-1 rounded-full bg-violet-500/15 border border-violet-500/25 flex-shrink-0">
                {(viewVotesPoll?.options || []).reduce((sum, o) => {
                  const vList = Array.isArray(o.votedUserDetails) ? o.votedUserDetails : (Array.isArray(o.votedUsers) ? o.votedUsers : []);
                  return sum + (vList.length || o.votes || 0);
                }, 0)} Total Votes
              </span>
            </div>

            <div className="space-y-3 max-h-96 overflow-y-auto pr-1 scrollbar-thin">
              {viewVotesPoll?.options?.map((opt, idx) => {
                const voters = (Array.isArray(opt.votedUserDetails) && opt.votedUserDetails.length > 0)
                  ? opt.votedUserDetails
                  : (Array.isArray(opt.votedUsers) && opt.votedUsers.length > 0
                      ? opt.votedUsers.map(u => ({ uid: u, name: usersMap[u]?.name || (u === user?.uid ? user?.name : 'Student'), avatar: usersMap[u]?.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${u}` }))
                      : (opt.votes > 0
                          ? Array.from({ length: opt.votes }).map((_, i) => ({ uid: `v_${i}`, name: i === 0 && user?.name ? user.name : `Student ${i + 1}`, avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${(user?.email || 's') + i}` }))
                          : []));

                return (
                  <div key={idx} className="p-3 rounded-2xl bg-neutral-900/90 border border-neutral-800 space-y-2">
                    <div className="flex items-center justify-between font-bold text-xs">
                      <span className="text-white font-extrabold">{opt.text}</span>
                      <span className="text-neutral-400 font-mono text-[11px]">{voters.length} {voters.length === 1 ? 'vote' : 'votes'}</span>
                    </div>

                    {voters.length > 0 ? (
                      <div className="space-y-1.5 pt-1">
                        {voters.map((voter, vIdx) => (
                          <div key={vIdx} className="flex items-center justify-between p-2 rounded-xl bg-neutral-950/70 border border-neutral-800/60 text-xs">
                            <div className="flex items-center gap-2 min-w-0">
                              <img
                                src={voter.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(voter.name || 'Student')}`}
                                alt={voter.name}
                                className="w-7 h-7 rounded-full object-cover border border-neutral-700 flex-shrink-0"
                              />
                              <span className="font-bold text-neutral-200 truncate">{voter.name || 'Student'}</span>
                            </div>
                            <CheckCircle2 className="w-4 h-4 text-emerald-400 fill-emerald-400/20 flex-shrink-0" />
                          </div>
                        ))}
                      </div>
                    ) : (
                      <p className="text-[11px] text-neutral-500 italic px-1">No votes for this option yet.</p>
                    )}
                  </div>
                );
              })}
            </div>

            <div className="pt-2 border-t border-neutral-800 flex justify-end">
              <Button variant="secondary" onClick={() => setViewVotesPoll(null)} className="rounded-2xl px-5 text-xs font-semibold">
                Close
              </Button>
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
}

const handleToggle = (key) => {
    setSettings(prev => {
      const updated = { ...prev, [key]: !prev[key] };
      showSuccess('Setting preference saved');
      return updated;
    });
  };

export const PostCard = ({
  post,
  onVote,
  onRepost,
  onSave,
  isHighlighted,
  autoOpenComments = false,
  highlightedCommentId = null
}) => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { showSuccess } = useNotification();
  const [showComments, setShowComments] = useState(autoOpenComments || Boolean(highlightedCommentId));
  const [newComment, setNewComment] = useState('');
  const [comments, setComments] = useState([]);
  const [replyingToComment, setReplyingToComment] = useState(null);
  const [expandedReplies, setExpandedReplies] = useState({});
  const commentInputRef = useRef(null);

  useEffect(() => {
    if (autoOpenComments || highlightedCommentId) {
      setShowComments(true);
    }
  }, [autoOpenComments, highlightedCommentId]);

  const [showPostMenu, setShowPostMenu] = useState(false);
  const [isEditingPost, setIsEditingPost] = useState(false);
  const [editPostContent, setEditPostContent] = useState(post.content || '');
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [commentToDelete, setCommentToDelete] = useState(null);

  // LinkedIn-style Reshare State & Tracking
  const [showReshareModal, setShowReshareModal] = useState(false);
  const [reshareMode, setReshareMode] = useState(null); // null | 'thoughts'
  const [isShareModalOpen, setIsShareModalOpen] = useState(false);
  const [thoughtCaption, setThoughtCaption] = useState('');
  const [isSubmittingReshare, setIsSubmittingReshare] = useState(false);

  const [localReposts, setLocalReposts] = useState(post.reposts || 0);
  const [localResharedUsers, setLocalResharedUsers] = useState(post.resharedUsers || []);

  useEffect(() => {
    setLocalReposts(post.reposts || 0);
    setLocalResharedUsers(post.resharedUsers || []);
  }, [post.reposts, post.resharedUsers]);

  const isResharedByMe = Boolean(user?.uid && localResharedUsers.includes(user.uid));

  const isOfficialAdmin =
    (user?.username || '').toLowerCase() === 'cohort' ||
    (user?.name || '').toLowerCase() === 'cohort' ||
    user?.isOfficial === true ||
    user?.uid === 'cohort_official' ||
    user?.email === 'cohort@official.com';

  const isActualPostOwner = (post.author?.uid && post.author.uid === user?.uid) ||
                            (post.authorUid && post.authorUid === user?.uid) ||
                            (user?.name && post.author?.name === user?.name);

  const isPostOwner = isActualPostOwner || isOfficialAdmin;

  const isCohortOfficialPost =
    (post.author?.name || '').toLowerCase() === 'cohort' ||
    (post.author?.username || '').toLowerCase() === 'cohort' ||
    post.authorUid === 'cohort_official' ||
    post.author?.uid === 'cohort_official';

  // WhatsApp-style Poll Votes Breakdown Modal state
  const [viewVotesPoll, setViewVotesPoll] = useState(null);

  // Real-time resolution of post author profile from Firestore
  const [liveAuthorProfile, setLiveAuthorProfile] = useState(null);
  const targetAuthorUid = isCohortOfficialPost
    ? 'cohort_official'
    : (post.author?.uid || post.authorUid || post.uid);

  useEffect(() => {
    if (!targetAuthorUid) return;

    const unsub = onSnapshot(doc(db, 'users', targetAuthorUid), (snap) => {
      if (snap.exists()) {
        setLiveAuthorProfile(snap.data());
      }
    }, (err) => console.error('Error listening to post author profile:', err));

    return () => unsub();
  }, [targetAuthorUid]);

  const authorAvatar = isCohortOfficialPost
    ? (liveAuthorProfile?.avatar || post.author?.avatar)
    : ((isActualPostOwner && user?.avatar) || liveAuthorProfile?.avatar || post.author?.avatar);

  const authorName = isCohortOfficialPost
    ? 'Cohort'
    : ((isActualPostOwner && user?.name) || liveAuthorProfile?.name || post.author?.name || 'Student');

  // Social Proof Context State (Liked / Commented by someone you follow)
  const [socialContext, setSocialContext] = useState(null);

  useEffect(() => {
    if (!user?.uid) return;
    const myFollowing = Array.isArray(user?.following) ? user.following : [];
    if (myFollowing.length === 0) {
      setSocialContext(null);
      return;
    }

    // 1. Check if a followed user commented
    const followedComment = comments.find(c => {
      const cUid = c.authorUid || c.uid;
      const cName = c.author || c.authorName;
      const cUser = c.authorUsername;
      return (cUid && cUid !== user.uid && myFollowing.includes(cUid)) ||
             (cUser && cUser !== user.username && myFollowing.includes(cUser)) ||
             (cName && myFollowing.includes(cName));
    });

    if (followedComment) {
      setSocialContext({
        type: 'comment',
        userName: followedComment.author || 'A user you follow',
        userUid: followedComment.authorUid,
        text: 'commented on this'
      });
      return;
    }

    // 2. Check if a followed user liked/upvoted
    const upvoters = Array.isArray(post.upvotedUsers)
      ? post.upvotedUsers
      : (Array.isArray(post.likedUsers) ? post.likedUsers : []);

    const followedLikerItem = upvoters.find(item => {
      const uid = typeof item === 'string' ? item : item?.uid;
      return uid && uid !== user.uid && myFollowing.includes(uid);
    });

    if (followedLikerItem) {
      const likerUid = typeof followedLikerItem === 'string' ? followedLikerItem : followedLikerItem?.uid;
      getDoc(doc(db, 'users', likerUid)).then(snap => {
        if (snap.exists()) {
          const lData = snap.data();
          setSocialContext({
            type: 'like',
            userName: lData.name || lData.username || 'A user you follow',
            userUid: likerUid,
            text: 'liked this'
          });
        } else {
          setSocialContext({
            type: 'like',
            userName: 'A user you follow',
            userUid: likerUid,
            text: 'liked this'
          });
        }
      }).catch(() => {
        setSocialContext({
          type: 'like',
          userName: 'A user you follow',
          userUid: likerUid,
          text: 'liked this'
        });
      });
      return;
    }

    setSocialContext(null);
  }, [comments, post.upvotedUsers, post.likedUsers, user?.following, user?.uid, user?.username]);

  const handleSaveInlineEdit = async () => {
    if (!editPostContent.trim()) return;
    try {
      const postId = post.docId || post.id;
      await updateDoc(doc(db, 'posts', postId), { content: editPostContent.trim() });
      post.content = editPostContent.trim();
      setIsEditingPost(false);
      setShowPostMenu(false);
      showSuccess('Post updated successfully!');
    } catch (err) {
      console.error('Failed to edit post:', err);
    }
  };

  const confirmDeletePostDoc = async () => {
    try {
      const postId = post.docId || post.id;
      await deleteDoc(doc(db, 'posts', postId));

      // If deleting a reshare, decrement original post's reshare counter
      if (post.isReshare && post.originalPostId) {
        try {
          const origPostRef = doc(db, 'posts', post.originalPostId);
          await updateDoc(origPostRef, {
            reposts: increment(-1),
            resharedUsers: user?.uid ? arrayRemove(user.uid) : []
          });
        } catch (e) {
          console.error('Failed to decrement original post repost count:', e);
        }
      }

      setShowDeleteModal(false);
      setShowPostMenu(false);
      showSuccess('Post deleted permanently.');
    } catch (err) {
      console.error('Failed to delete post:', err);
    }
  };

  const handleUnreshare = async () => {
    const rootOriginalPostId = post.originalPostId || post.docId || post.id;
    const myUid = user?.uid;
    if (!myUid || !rootOriginalPostId) return;

    setIsSubmittingReshare(true);
    setLocalReposts(prev => Math.max(0, prev - 1));
    setLocalResharedUsers(prev => prev.filter(u => u !== myUid));

    try {
      // 1. Decrement repost count and remove UID from original post
      const origPostRef = doc(db, 'posts', rootOriginalPostId);
      await updateDoc(origPostRef, {
        reposts: increment(-1),
        resharedUsers: arrayRemove(myUid)
      });

      // 2. Query and delete the reshare document created by this user for rootOriginalPostId
      const q = query(
        collection(db, 'posts'),
        where('isReshare', '==', true),
        where('originalPostId', '==', rootOriginalPostId),
        where('resharedBy.uid', '==', myUid)
      );
      const snapshot = await getDocs(q);
      snapshot.forEach(async (docSnap) => {
        await deleteDoc(doc(db, 'posts', docSnap.id));
      });

      showSuccess('Reshare removed.');
      setShowReshareModal(false);
    } catch (err) {
      console.error('Failed to unreshare post:', err);
      setLocalReposts(post.reposts || 0);
      setLocalResharedUsers(post.resharedUsers || []);
    } finally {
      setIsSubmittingReshare(false);
    }
  };

  const handleReshareInstant = async () => {
    const rootOriginalPostId = post.originalPostId || post.docId || post.id;
    const origAuthor = post.originalPost?.author || post.author;
    const origContent = post.originalPost?.content || post.content;
    const origTimestamp = post.originalPost?.timestamp || post.timestamp;
    const myUid = user?.uid;

    setIsSubmittingReshare(true);
    setLocalReposts(prev => prev + 1);
    if (myUid) setLocalResharedUsers(prev => [...prev, myUid]);

    try {
      const reshareDocData = {
        isReshare: true,
        originalPostId: rootOriginalPostId,
        originalPost: {
          id: rootOriginalPostId,
          author: origAuthor,
          content: origContent,
          timestamp: origTimestamp
        },
        resharedBy: {
          uid: myUid || null,
          name: user?.name || 'Student',
          username: user?.username || null,
          avatar: user?.avatar || null
        },
        college: user?.college || 'KIET',
        author: {
          uid: myUid || null,
          name: user?.name || 'Student',
          username: user?.username || null,
          avatar: user?.avatar || null,
          role: user?.college || 'KIET',
          college: user?.college || 'KIET'
        },
        thought: '',
        content: '',
        timestamp: new Date(),
        upvotes: 0,
        downvotes: 0,
        upvotedUsers: [],
        downvotedUsers: [],
        comments: 0,
        reposts: 0,
        saved: false
      };

      await addDoc(collection(db, 'posts'), reshareDocData);

      // Increment reshare count and add user UID to root original post
      const origPostRef = doc(db, 'posts', rootOriginalPostId);
      await updateDoc(origPostRef, {
        reposts: increment(1),
        resharedUsers: myUid ? arrayUnion(myUid) : []
      });

      if (onRepost) onRepost(rootOriginalPostId);

      const origAuthorUid = origAuthor?.uid || post.author?.uid;
      if (origAuthorUid && origAuthorUid !== myUid) {
        createNotification({
          recipientUid: origAuthorUid,
          senderUid: myUid,
          senderName: user?.name || 'Student',
          senderAvatar: user?.avatar,
          type: 'reshare',
          text: 'reshared your post.',
          postId: rootOriginalPostId
        });
      }

      showSuccess('Post reshared successfully.');
      setShowReshareModal(false);
      setReshareMode(null);
    } catch (err) {
      console.error('Failed to reshare post:', err);
      setLocalReposts(post.reposts || 0);
      setLocalResharedUsers(post.resharedUsers || []);
    } finally {
      setIsSubmittingReshare(false);
    }
  };

  const handleReshareWithThoughtsSubmit = async () => {
    if (!thoughtCaption.trim()) return;
    const rootOriginalPostId = post.originalPostId || post.docId || post.id;
    const origAuthor = post.originalPost?.author || post.author;
    const origContent = post.originalPost?.content || post.content;
    const origTimestamp = post.originalPost?.timestamp || post.timestamp;
    const myUid = user?.uid;

    setIsSubmittingReshare(true);
    setLocalReposts(prev => prev + 1);
    if (myUid) setLocalResharedUsers(prev => [...prev, myUid]);

    try {
      const reshareDocData = {
        isReshare: true,
        originalPostId: rootOriginalPostId,
        originalPost: {
          id: rootOriginalPostId,
          author: origAuthor,
          content: origContent,
          timestamp: origTimestamp
        },
        resharedBy: {
          uid: myUid || null,
          name: user?.name || 'Student',
          username: user?.username || null,
          avatar: user?.avatar || null
        },
        college: user?.college || 'KIET',
        author: {
          uid: myUid || null,
          name: user?.name || 'Student',
          username: user?.username || null,
          avatar: user?.avatar || null,
          role: user?.college || 'KIET',
          college: user?.college || 'KIET'
        },
        thought: thoughtCaption.trim(),
        content: thoughtCaption.trim(),
        timestamp: new Date(),
        upvotes: 0,
        downvotes: 0,
        upvotedUsers: [],
        downvotedUsers: [],
        comments: 0,
        reposts: 0,
        saved: false
      };

      await addDoc(collection(db, 'posts'), reshareDocData);

      const origPostRef = doc(db, 'posts', rootOriginalPostId);
      await updateDoc(origPostRef, {
        reposts: increment(1),
        resharedUsers: myUid ? arrayUnion(myUid) : []
      });

      if (onRepost) onRepost(rootOriginalPostId);

      const origAuthorUid = origAuthor?.uid || post.author?.uid;
      if (origAuthorUid && origAuthorUid !== myUid) {
        createNotification({
          recipientUid: origAuthorUid,
          senderUid: myUid,
          senderName: user?.name || 'Student',
          senderAvatar: user?.avatar,
          type: 'reshare',
          text: 'reshared your post with their thoughts.',
          postId: rootOriginalPostId
        });
      }

      showSuccess('Post reshared with thoughts successfully.');
      setShowReshareModal(false);
      setReshareMode(null);
      setThoughtCaption('');
    } catch (err) {
      console.error('Failed to reshare post with thoughts:', err);
      setLocalReposts(post.reposts || 0);
      setLocalResharedUsers(post.resharedUsers || []);
    } finally {
      setIsSubmittingReshare(false);
    }
  };

  const confirmDeleteCommentDoc = async () => {
    if (!commentToDelete) return;
    const commentId = commentToDelete.id || commentToDelete;
    try {
      const postId = post.docId || post.id;
      await deleteDoc(doc(db, 'posts', postId, 'comments', commentId));

      const postRef = doc(db, 'posts', postId);
      await updateDoc(postRef, {
        comments: Math.max(0, (comments.length || 1) - 1)
      });

      setComments(prev => prev.filter(c => c.id !== commentId && c.parentId !== commentId));
      setCommentToDelete(null);
      showSuccess('Comment deleted successfully.');
    } catch (err) {
      console.error('Failed to delete comment:', err);
    }
  };

  // Subscribe to real-time comments subcollection for this post in Firestore
  useEffect(() => {
    if (!post?.docId && !post?.id) return;
    const postId = post.docId || post.id;
    const commentsRef = collection(db, 'posts', postId, 'comments');
    const q = query(commentsRef, orderBy('timestamp', 'asc'));

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const loaded = [];
      snapshot.forEach((d) => {
        const data = d.data();
        loaded.push({
          id: d.id,
          ...data,
          time: data.timestamp?.toDate ? formatRelativeTime(data.timestamp.toDate()) : 'Just now'
        });
      });
      setComments(loaded);
    }, (err) => {
      console.error('Error fetching comments from Firestore:', err);
    });

    return () => unsubscribe();
  }, [post?.id, post?.docId]);

  // Auto-scroll and highlight target comment when navigated from notification
  useEffect(() => {
    if (highlightedCommentId && comments.length > 0) {
      setShowComments(true);
      const targetComment = comments.find(c => c.id === highlightedCommentId);
      if (targetComment && targetComment.parentId) {
        // Expand the parent comment's replies accordion if nested
        setExpandedReplies(prev => ({ ...prev, [targetComment.parentId]: true }));
      }
      const scrollTimer = setTimeout(() => {
        const commentEl = document.getElementById(`comment-${highlightedCommentId}`);
        if (commentEl) {
          commentEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 300);
      return () => clearTimeout(scrollTimer);
    }
  }, [highlightedCommentId, comments]);

  const toggleReplies = (parentCommentId) => {
    setExpandedReplies(prev => ({
      ...prev,
      [parentCommentId]: !prev[parentCommentId]
    }));
  };

  const handleOpenAuthorProfile = (authorUid, authorName) => {
    if (authorUid) {
      navigate(`/profile?uid=${authorUid}`);
    } else if (authorName) {
      navigate(`/profile?name=${encodeURIComponent(authorName)}`);
    } else {
      navigate(`/profile`);
    }
  };

  const handleInitiateReplyToComment = (targetComment) => {
    const parentId = targetComment.parentId || targetComment.id;
    const usernameHandle = targetComment.authorUsername || targetComment.author?.replace(/\s+/g, '');

    setReplyingToComment({
      parentId: parentId,
      commentId: targetComment.id,
      authorUid: targetComment.authorUid,
      author: targetComment.author,
      username: usernameHandle
    });

    const tag = `@${usernameHandle} `;
    let updatedText = newComment;
    if (!newComment.includes(tag.trim())) {
      const cleanedText = newComment.replace(/^@\S+\s*/, '');
      updatedText = `${tag}${cleanedText}`;
      setNewComment(updatedText);
    }

    setTimeout(() => {
      if (commentInputRef.current) {
        const el = commentInputRef.current;
        el.focus();
        const len = updatedText.length;
        el.setSelectionRange(len, len);
      }
    }, 50);
  };

  const handleCancelReplyMode = () => {
    if (replyingToComment) {
      const username = replyingToComment.username;
      if (username) {
        const tagPattern = new RegExp(`^@${username}\\s*`, 'i');
        setNewComment(prev => prev.replace(tagPattern, ''));
      }
    }
    setReplyingToComment(null);
  };

  const handleToggleCommentLike = async (commentId) => {
    const targetComment = comments.find(c => c.id === commentId);
    if (!targetComment || !user?.uid) return;

    const currentLikedBy = targetComment.likedBy || [];
    const isAlreadyLiked = currentLikedBy.includes(user.uid);
    const updatedLikedBy = isAlreadyLiked
      ? currentLikedBy.filter(uid => uid !== user.uid)
      : [...currentLikedBy, user.uid];

    const updatedLikesCount = updatedLikedBy.length;

    // Optimistic UI update
    setComments(prev => prev.map(c => {
      if (c.id === commentId) {
        return {
          ...c,
          likedBy: updatedLikedBy,
          likes: updatedLikesCount
        };
      }
      return c;
    }));

    try {
      const postId = post.docId || post.id;
      const commentRef = doc(db, 'posts', postId, 'comments', commentId);
      await updateDoc(commentRef, {
        likedBy: updatedLikedBy,
        likes: updatedLikesCount
      });

      if (!isAlreadyLiked && targetComment.authorUid && targetComment.authorUid !== user.uid) {
        createNotification({
          recipientUid: targetComment.authorUid,
          senderUid: user.uid,
          senderName: user.name || 'Student',
          senderAvatar: user.avatar,
          type: 'like',
          text: `liked your comment: "${targetComment.text?.slice(0, 30)}..."`,
          postId: postId,
          commentId: commentId
        });
      }
    } catch (err) {
      console.error('Failed to update comment like:', err);
    }
  };

  const renderTaggedCommentText = (text) => {
    if (!text) return '';
    const tokens = text.split(/(\s+)/);
    return tokens.map((token, i) => {
      if (token.startsWith('@') && token.length > 1) {
        const cleanName = token.replace(/^@|\W+$/g, '');
        return (
          <span
            key={i}
            onClick={(e) => {
              e.stopPropagation();
              if (cleanName) navigate(`/profile?name=${encodeURIComponent(cleanName)}`);
            }}
            className="text-primary-500 font-bold hover:underline cursor-pointer mr-1 inline-block"
          >
            {token}
          </span>
        );
      }
      return token;
    });
  };

  const handleAddComment = async (e) => {
    if ((e.key === 'Enter' || e.type === 'click') && newComment.trim()) {
      const postId = post.docId || post.id;
      if (!postId) return;

      const textToSend = newComment.trim();
      const targetReply = replyingToComment;
      setNewComment('');
      setReplyingToComment(null);

      const parentId = targetReply?.parentId || null;
      const tempId = `temp_${Date.now()}`;

      const newCommentObj = {
        id: tempId,
        authorUid: user?.uid || null,
        authorUsername: user?.username || null,
        author: user?.name || user?.email?.split('@')[0] || 'Student',
        avatar: user?.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(user?.email || 'user')}`,
        text: textToSend,
        parentId: parentId,
        replyToAuthorUid: targetReply?.authorUid || null,
        replyToAuthorName: targetReply?.author || null,
        likes: 0,
        likedBy: [],
        timestamp: new Date(),
        time: 'Just now'
      };

      // Optimistic UI Update
      setComments(prev => [...prev, newCommentObj]);

      // Auto-expand parent replies so newly added reply is immediately visible
      if (parentId) {
        setExpandedReplies(prev => ({ ...prev, [parentId]: true }));
      }

      const commentData = {
        authorUid: newCommentObj.authorUid,
        authorUsername: newCommentObj.authorUsername,
        author: newCommentObj.author,
        avatar: newCommentObj.avatar,
        text: textToSend,
        parentId: parentId,
        replyToAuthorUid: targetReply?.authorUid || null,
        replyToAuthorName: targetReply?.author || null,
        likes: 0,
        likedBy: [],
        timestamp: new Date()
      };

      try {
        const newCommentRef = await addDoc(collection(db, 'posts', postId, 'comments'), commentData);

        const postRef = doc(db, 'posts', postId);
        await updateDoc(postRef, {
          comments: (comments.length || 0) + 1
        });

        const postAuthorUid = post.author?.uid || post.authorUid || post.uid;

        // 1. Dispatch Comment Notification to post author (if not self)
        if (postAuthorUid && postAuthorUid !== user?.uid) {
          createNotification({
            recipientUid: postAuthorUid,
            senderUid: user?.uid,
            senderName: user?.name || 'Student',
            senderAvatar: user?.avatar,
            type: 'reply',
            text: `commented: "${textToSend.slice(0, 35)}${textToSend.length > 35 ? '...' : ''}"`,
            postId: postId,
            commentId: newCommentRef.id
          });
        }

        // 2. Dispatch Reply Notification to the specific comment author tagged/replied to
        const commentAuthorUid = targetReply?.authorUid;
        if (
          commentAuthorUid &&
          commentAuthorUid !== user?.uid &&
          commentAuthorUid !== postAuthorUid
        ) {
          createNotification({
            recipientUid: commentAuthorUid,
            senderUid: user?.uid,
            senderName: user?.name || 'Student',
            senderAvatar: user?.avatar,
            type: 'reply',
            text: `replied to your comment: "${textToSend.slice(0, 35)}${textToSend.length > 35 ? '...' : ''}"`,
            postId: postId,
            commentId: newCommentRef.id
          });
        }
      } catch (err) {
        console.error('Failed to add reply comment in Firestore:', err);
      }
    }
  };

  const myUid = user?.uid || 'guest';
  const userVote = Array.isArray(post.upvotedUsers) && post.upvotedUsers.includes(myUid)
    ? 'up'
    : Array.isArray(post.downvotedUsers) && post.downvotedUsers.includes(myUid)
    ? 'down'
    : null;

  const upvotesCount = Array.isArray(post.upvotedUsers)
    ? post.upvotedUsers.length
    : (typeof post.upvotes === 'number' ? post.upvotes : 0);

  const downvotesCount = Array.isArray(post.downvotedUsers)
    ? post.downvotedUsers.length
    : (typeof post.downvotes === 'number' ? post.downvotes : 0);

  const topLevelComments = comments.filter(c => !c.parentId);



  return (
    <Card
      id={`post-${post.id || post.docId}`}
      className={`mb-lg transition-all duration-500 ease-out ${
        isHighlighted
          ? 'ring-2 ring-purple-500/60 dark:ring-purple-400/60 border-purple-500/80 shadow-md shadow-purple-500/20 rounded-2xl'
          : isCohortOfficialPost
          ? "border-purple-500/50 dark:border-purple-500/60 shadow-[0_0_15px_rgba(168,85,247,0.15)] bg-white dark:bg-neutral-900"
          : "border-neutral-100 dark:border-neutral-800 shadow-sm"
      }`}
    >
      {/* Social Context Banner (Liked / Commented by someone you follow) */}
      {socialContext && (
        <div className="flex items-center gap-2 text-xs font-semibold text-neutral-500 dark:text-neutral-400 mb-3 pb-2.5 border-b border-neutral-100 dark:border-neutral-800/80">
