              className="text-neutral-800 dark:text-neutral-200 font-extrabold hover:underline cursor-pointer"
            >
              {socialContext.userName}
            </strong>{' '}
            {socialContext.text}
          </span>
        </div>
      )}

      {/* Header */}
      <div className="flex items-start justify-between mb-lg">
        <div
          onClick={() => handleOpenAuthorProfile(post.author?.uid, post.author?.name)}
          className="flex items-center gap-md cursor-pointer group"
        >
          <UserAvatar
            src={authorAvatar}
