  };

const validateForm = () => {
    const newErrors = {};
    if (!formData.name.trim()) newErrors.name = 'Name is required';
    if (!formData.email) newErrors.email = 'Email is required';
    else if (!validateEmail(formData.email)) newErrors.email = 'Invalid email address';
    if (!formData.subject.trim()) newErrors.subject = 'Subject is required';
    if (!formData.message.trim()) newErrors.message = 'Message is required';

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

const handleSendOTP = async () => {
    const emailToUse = formData.email.trim();
    if (!emailToUse) {
      setErrors({ email: 'Email address is required' });
      return;
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(emailToUse)) {
      setErrors({ email: 'Please enter a valid email address' });
      return;
    }

    setIsLoading(true);
    try {
      // Check if email already exists in Firestore users
      const q = query(collection(db, 'users'), where('email', '==', emailToUse.toLowerCase()));
      const querySnap = await getDocs(q);
      if (!querySnap.empty) {
        setErrors({ email: 'This email is already registered. Please sign in instead.' });
        showError('This email is already registered. Please sign in instead.');
        setIsLoading(false);
        return;
      }

      const resData = await sendVerificationCode(emailToUse);
      showSuccess('Verification code sent to your email!');

      if (resData.otp) {
        console.log(`%c[OTP Code (Dev Mode)] ${resData.otp}`, 'color: #9333ea; font-size: 16px; font-weight: bold;');
        if (resData.previewUrl) {
          console.log(`[Email Preview Link] ${resData.previewUrl}`);
        }
        showSuccess(`[Dev Mode] OTP code is ${resData.otp} (Logged to console)`);
      }

      setSignupStep(2);
      setResendTimer(30);
    } catch (err) {
      console.error(err);
      setErrors({ email: err.message || 'Failed to send verification code. Please try again.' });
      showError(err.message || 'Failed to send verification code. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

const confirmDeleteCommentDoc = async () => {
    if (!commentToDelete) return;
    const commentId = commentToDelete.id || commentToDelete;
    try {
      const postId = post.docId || post.id;
      await deleteDoc(doc(db, 'posts', postId, 'comments', commentId));

      const postRef = doc(db, 'posts', postId);
      await updateDoc(postRef, {
        comments: Math.max(0, (comments.length || 1) - 1)
      });

      setComments(prev => prev.filter(c => c.id !== commentId && c.parentId !== commentId));
      setCommentToDelete(null);
      showSuccess('Comment deleted successfully.');
    } catch (err) {
      console.error('Failed to delete comment:', err);
    }
  };

const handleSelectUser = (suggestedUser) => {
    if (mentionStartIndex === -1 || !textareaRef.current) return;

    const usernameTag = `@${suggestedUser.username || suggestedUser.name.toLowerCase().replace(/\s+/g, '')} `;
    const textBeforeMention = value.slice(0, mentionStartIndex);
    const cursorPos = textareaRef.current.selectionStart;
    const textAfterMention = value.slice(cursorPos);

    const newText = textBeforeMention + usernameTag + textAfterMention;

    // Trigger synthetic onChange event
    const event = {
      target: { value: newText }
    };
    onChange(event);

    setShowSuggestions(false);
    setMentionQuery(null);

    // Set cursor position after the inserted @username tag
    setTimeout(() => {
      if (textareaRef.current) {
        textareaRef.current.focus();
        const nextPos = textBeforeMention.length + usernameTag.length;
        textareaRef.current.setSelectionRange(nextPos, nextPos);
      }
    }, 50);
  };

function EditProfile() {
  const navigate = useNavigate();
  const { user, updateUser, logout } = useAuth();
  const { showSuccess, showError } = useNotification();

  const [isLoading, setIsLoading] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  // Image Upload States
  const [avatarFile, setAvatarFile] = useState(null);
  const [avatarPreviewUrl, setAvatarPreviewUrl] = useState(null);
  const [cropperSrc, setCropperSrc] = useState(null);
  const fileInputRef = useRef(null);

  const [formData, setFormData] = useState({
    name: user?.name || '',
    bio: user?.bio || '',
    college: user?.college || 'Delhi University',
    gender: user?.gender || 'Prefer not to say',
    year: user?.year || '1st Year',
    dob: user?.dob || '',
  });

  const handleRemovePhoto = () => {
    setAvatarFile(null);
    const defaultUrl = `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(user?.email || 'user')}`;
    setAvatarPreviewUrl(defaultUrl);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    try {
      let uploadedAvatarUrl = user?.avatar || '';

      // If a preview URL is a default Dicebear URL and avatarFile is null, it means they clicked "Remove Photo"
      if (avatarPreviewUrl && avatarPreviewUrl.startsWith('https://api.dicebear.com')) {
        uploadedAvatarUrl = avatarPreviewUrl;
      } else if (avatarFile) {
        uploadedAvatarUrl = await uploadImageToCloudinary(avatarFile);
      }

      const hasCollegeChanged = formData.college !== user?.college;
      const updatedData = {
        ...formData,
        avatar: uploadedAvatarUrl,
        ...(hasCollegeChanged ? { kycVerified: false, kycEmail: null } : {})
      };

      await updateUser(updatedData);
      showSuccess('Profile updated successfully!');
      navigate('/profile');
    } catch (err) {
      console.error(err);
      showError('Failed to update profile. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleDeleteAccount = async () => {
    const confirmation = window.confirm(
      "WARNING: Are you sure you want to permanently delete your Cohort profile and account? This action is irreversible."
    );
    if (!confirmation) return;

    setIsDeleting(true);
    try {
      if (user?.uid) {
        // 1. Delete from Firestore users collection
        const userRef = doc(db, 'users', user.uid);
        await deleteDoc(userRef);
      }

      // 2. Delete from Firebase Auth
      const currentUser = auth.currentUser;
      if (currentUser) {
        await currentUser.delete();
      }

      // 3. Logout & redirect
      await logout();
      showSuccess('Your account was successfully deleted.');
      navigate('/');
    } catch (err) {
      console.error('Failed to delete account:', err);
      // Fallback: If delete requires re-login, log out anyway after deleting Firestore doc
      await logout();
      showSuccess('Your profile was removed.');
      navigate('/');
    } finally {
      setIsDeleting(false);
    }
  };

  return (
    <div className="section-container max-w-2xl">
      <SEO title="Edit Profile" />
      <h1 className="text-3xl font-heading font-bold mb-lg">Edit Profile</h1>

      <Card className="mb-lg">
        <form onSubmit={handleSubmit} className="space-y-lg">
          {/* Profile Picture */}
