        timestamp: new Date(),
        upvotes: 0,
        downvotes: 0,
        upvotedUsers: [],
        downvotedUsers: [],
        comments: 0,
        reposts: 0,
        saved: false,
        ...(hasValidPoll ? {
          poll: {
            question: pollQuestion.trim(),
            options: validPollOptions.map(t => ({ text: t.trim(), votes: 0 })),
            totalVotes: 0,
            votedUsers: [],
