                className="input-base text-sm resize-none"
              />
              {errors.desc && <p className="text-xs text-danger mt-xs">{errors.desc}</p>}
            </div>

            <div className="flex gap-md pt-md border-t border-neutral-100 dark:border-neutral-800">
              <Button variant="secondary" className="flex-1" onClick={() => setEditingItem(null)}>
                Cancel
              </Button>
              <button
                type="submit"
                disabled={imageUploading}
                className="flex-1 py-2.5 rounded-xl bg-gradient-to-r from-sky-500 to-blue-600 hover:from-sky-400 hover:to-blue-500 text-white font-extrabold text-sm shadow-[0_0_15px_rgba(14,165,233,0.3)] active:scale-95 transition-all cursor-pointer border border-sky-400/30 disabled:opacity-50"
              >
                Save Changes
              </button>
            </div>
          </form>
        </Modal>
      )}

      {/* Delete Item Confirmation Modal */}
      {deletingItem && (
        <Modal
          isOpen={Boolean(deletingItem)}
          onClose={() => setDeletingItem(null)}
          title="Delete Marketplace Listing"
          size="sm"
        >
          <div className="text-center py-sm space-y-md">
            <div className="w-14 h-14 rounded-full bg-rose-500/10 text-rose-500 flex items-center justify-center mx-auto shadow-inner">
              <AlertCircle className="w-8 h-8" />
            </div>
            <div>
              <h4 className="text-lg font-bold text-neutral-900 dark:text-white">Delete "{deletingItem.name}"?</h4>
              <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-xs leading-relaxed">
                This listing will be permanently removed from the Campus Marketplace. This action cannot be undone.
              </p>
            </div>
            <div className="flex items-center justify-center gap-md pt-sm">
              <Button variant="secondary" size="sm" onClick={() => setDeletingItem(null)} className="w-full">
                Cancel
              </Button>
              <button
                type="button"
                onClick={confirmDeleteItem}
                className="w-full py-2 px-md bg-gradient-to-r from-rose-500 to-red-600 hover:from-rose-600 hover:to-red-700 text-white font-bold text-xs rounded-xl shadow-lg shadow-rose-500/25 active:scale-95 transition-all cursor-pointer"
              >
                Yes, Delete
              </button>
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
}

const handleSaveGroupSettings = async () => {
    if (!selectedRoom?.id || !editGroupName.trim()) return;
    try {
      const updatePayload = {
        name: editGroupName.trim(),
        description: editGroupDesc.trim(),
        visibility: editGroupVisibility,
        type: editGroupVisibility,
        audience: editGroupAudience,
        joinControl: editGroupJoinControl,
        avatar: editGroupAvatar.trim() || null,
        adminPermissions: editAdminPermissions
      };
      await updateDoc(doc(db, 'userCommunities', selectedRoom.id), updatePayload);
      setSelectedRoom(prev => ({ ...prev, ...updatePayload }));
      setMyCommunities(prev => prev.map(c => c.id === selectedRoom.id ? { ...c, ...updatePayload } : c));
      showSuccess('Community settings updated!'); setManageTab('members');
    } catch (e) { console.error(e); }
  };

const handleCreateCommunity = async (e) => {
    e.preventDefault();
    if (!newGroupName.trim()) return;
    setIsCreatingGroup(true);
    try {
      const groupData = {
        name: newGroupName.trim(),
        description: newGroupDesc.trim(),
        visibility: newGroupVisibility,
        type: newGroupVisibility,
        audience: newGroupAudience,
        college: user?.college || collegeName,
        joinControl: newGroupJoinControl,
        avatar: newGroupAvatar.trim() || null,
        creatorUid: user.uid,
        admins: [user.uid],
        members: [user.uid],
        joinRequests: [],
        adminPermissions: {
          canEditInfo: true,
          canInviteMembers: true,
          canRemoveMembers: true,
          canPromoteAdmins: false,
          canDeleteMessages: true
        },
        createdAt: new Date(),
        lastActivity: new Date()
      };
      const docRef = await addDoc(collection(db, 'userCommunities'), groupData);
      const newGroup = { roomType: 'group', id: docRef.id, ...groupData };
      setSelectedRoom(newGroup);
      setShowCreateModal(false);
      setNewGroupName(''); setNewGroupDesc(''); setNewGroupType('public'); setNewGroupAvatar('');
      setNewGroupVisibility('public'); setNewGroupAudience('everyone'); setNewGroupJoinControl('direct');
      showSuccess(`"${groupData.name}" created!`);
    } catch (e) { console.error(e); showWarning('Failed to create.'); }
    finally { setIsCreatingGroup(false); }
  };

function CarouselCard() {
  const wrapRef = useRef(null);
  const [cardWidth, setCardWidth] = useState(400);

  useEffect(() => {
    if (!wrapRef.current) return;
    const ro = new ResizeObserver(([entry]) => {
      setCardWidth(entry.contentRect.width);
    });
    ro.observe(wrapRef.current);
    return () => ro.disconnect();
  }, []);

  return (
    <div ref={wrapRef} id="feature-carousel-section" style={{ width: '100%', height: '100%', minHeight: 420 }}>
      <Carousel
        autoplay={true}
        autoplayDelay={3000}
        pauseOnHover={true}
        loop={true}
        round={false}
        baseWidth={cardWidth}
      />
    </div>
  );
}

