    setSelectedMedia(null);

    const updatedMsgs = [...(targetConv.messages || []), newMsg];
    const sentText = messageText.trim() || (sentMedia?.type === 'video' ? '🎬 Sent a video' : '🖼️ Sent a photo');
    setMessageText('');

