      try {
        const usersRef = collection(db, 'users');
        const q1 = query(usersRef, where('username', '==', cleanUsername));
        const snap1 = await getDocs(q1);
        if (!snap1.empty && snap1.docs[0].data()?.email) {
          emailToUse = snap1.docs[0].data().email;
