            emailToUse = snap2.docs[0].data().email;
          } else {
            emailToUse = `${cleanUsername}@student.edu`;
          }
        }
      } catch (err) {
        console.error('Username lookup error:', err);
        emailToUse = `${cleanUsername}@student.edu`;
      }
    }
    return signInWithEmailAndPassword(auth, emailToUse, password);
