          const expiresAtDate = new Date(seenAtDate.getTime() + durationSec * 1000);
          const scopeUser = msg.vanishScopeUser || activeConversation.vanishScopeUser || msg.senderUid;

          return {
            ...msg,
            seenBy: [...(msg.seenBy || []), user.uid],
