                        variant="danger"
                        disabled={selectedMsgKeys.length === 0}
                        onClick={handleBulkDeleteSelected}
                        className="flex items-center gap-xs"
                      >
                        <Trash2 className="w-4 h-4" /> Delete
                      </Button>
                    </div>
                  </div>
