                    {activeConversation.isVanishMode && <Flame className="w-3 h-3 text-amber-500 fill-amber-500" />}
                  </div>
                </button>
              </div>
            </div>

            {/* Action Button */}
            <div className="pt-sm border-t border-neutral-100 dark:border-neutral-800/80">
              <button
                type="button"
