const runMatchingSequence = () => {
    const logs = [
      'Launching Campus Vibe Checker...',
      'Syncing student interests & profiles...',
      'Analyzing personality maps & hobbies...',
      'Scanning campus cohorts...',
      'Calibrating vibe alignments...',
      'Vibe twins located! Loading profiles...'
    ];

    setMatchingConsoleLogs([]);
    logs.forEach((logText, idx) => {
      setTimeout(() => {
        setMatchingConsoleLogs((prev) => [...prev, logText]);
        if (idx === logs.length - 1) {
          setTimeout(() => {
            setStep('swiping');
          }, 1000);
        }
      }, (idx + 1) * 600);
    });
  };

const handleSwipe = async (direction) => {
    if (profiles.length === 0 || currentProfileIndex >= profiles.length) return;

    const targetProfile = profiles[currentProfileIndex];
    setSwipeDirection(direction);

    // Advance card index smoothly without triggering re-fetch reset
    setTimeout(() => {
      setCurrentProfileIndex((prev) => prev + 1);
      setSwipeDirection(null);
    }, 250);

    const updatedSwipes = {
      ...(user?.makeAFriendProfile?.swiped || {}),
      [targetProfile.uid]: direction
    };

    const updatedProfile = {
      ...user.makeAFriendProfile,
      swiped: updatedSwipes
    };

    try {
      await updateUser({
        makeAFriendProfile: updatedProfile
      });
    } catch (e) {
      console.error('Error updating swipe profile:', e);
    }

    if (direction === 'right') {
      try {
        await addDoc(collection(db, 'notifications'), {
          recipientUid: targetProfile.uid,
          senderUid: user.uid,
          senderName: user.name || 'Student',
          senderAvatar: user.avatar || '',
          type: 'like',
          text: `you were right swiped by ${user.name || 'Student'}.`,
          read: false,
          time: new Date()
        });

        const targetUserSnap = await getDocs(collection(db, 'users'));
        let targetUserLikedUs = false;
        targetUserSnap.forEach((d) => {
          if (d.id === targetProfile.uid) {
            const swipedList = d.data()?.makeAFriendProfile?.swiped || {};
            if (swipedList[user.uid] === 'right') {
              targetUserLikedUs = true;
            }
          }
        });

        const isMatch = targetUserLikedUs || Math.random() < 0.25;

        if (isMatch) {
          setMatchedProfile(targetProfile);
          setIsMatchOverlayOpen(true);
        }
      } catch (e) {
        console.error('Error handling right swipe match:', e);
      }
    }
  };

const handleReshareInstant = async () => {
    const rootOriginalPostId = post.originalPostId || post.docId || post.id;
    const origAuthor = post.originalPost?.author || post.author;
    const origContent = post.originalPost?.content || post.content;
    const origTimestamp = post.originalPost?.timestamp || post.timestamp;
    const myUid = user?.uid;

    setIsSubmittingReshare(true);
    setLocalReposts(prev => prev + 1);
    if (myUid) setLocalResharedUsers(prev => [...prev, myUid]);

    try {
      const reshareDocData = {
        isReshare: true,
        originalPostId: rootOriginalPostId,
        originalPost: {
          id: rootOriginalPostId,
          author: origAuthor,
          content: origContent,
          timestamp: origTimestamp
        },
        resharedBy: {
          uid: myUid || null,
          name: user?.name || 'Student',
          username: user?.username || null,
          avatar: user?.avatar || null
        },
        college: user?.college || 'KIET',
        author: {
          uid: myUid || null,
          name: user?.name || 'Student',
          username: user?.username || null,
          avatar: user?.avatar || null,
          role: user?.college || 'KIET',
          college: user?.college || 'KIET'
        },
        thought: '',
        content: '',
        timestamp: new Date(),
        upvotes: 0,
        downvotes: 0,
        upvotedUsers: [],
        downvotedUsers: [],
        comments: 0,
        reposts: 0,
        saved: false
      };

      await addDoc(collection(db, 'posts'), reshareDocData);

      // Increment reshare count and add user UID to root original post
      const origPostRef = doc(db, 'posts', rootOriginalPostId);
      await updateDoc(origPostRef, {
        reposts: increment(1),
        resharedUsers: myUid ? arrayUnion(myUid) : []
      });

      if (onRepost) onRepost(rootOriginalPostId);

      const origAuthorUid = origAuthor?.uid || post.author?.uid;
      if (origAuthorUid && origAuthorUid !== myUid) {
        createNotification({
          recipientUid: origAuthorUid,
          senderUid: myUid,
          senderName: user?.name || 'Student',
          senderAvatar: user?.avatar,
          type: 'reshare',
          text: 'reshared your post.',
          postId: rootOriginalPostId
        });
      }

      showSuccess('Post reshared successfully.');
      setShowReshareModal(false);
      setReshareMode(null);
    } catch (err) {
      console.error('Failed to reshare post:', err);
      setLocalReposts(post.reposts || 0);
      setLocalResharedUsers(post.resharedUsers || []);
    } finally {
      setIsSubmittingReshare(false);
    }
  };

