const handleRejectRequest = async (requestObj) => {
    if (!selectedRoom?.id || !requestObj?.uid) return;
    try {
      await updateDoc(doc(db, 'userCommunities', selectedRoom.id), {
        joinRequests: arrayRemove(requestObj)
      });
      setSelectedRoom(prev => ({
        ...prev,
        joinRequests: (prev.joinRequests || []).filter(r => (typeof r === 'string' ? r !== requestObj.uid : r.uid !== requestObj.uid))
      }));
      showSuccess('Join request rejected.');
    } catch (e) {
      console.error(e);
    }
  };

const fetchUsers = async () => {
      setSearchingUsers(true);
      try {
        const usersSnap = await getDocs(collection(db, 'users'));
        const loaded = [];
        const cleanQuery = searchUserQuery.toLowerCase().replace('@', '').trim();

        usersSnap.forEach(d => {
          if (d.id === user?.uid) return; // Skip self

          const data = d.data();
          const nameMatch = !cleanQuery || (data.name && data.name.toLowerCase().includes(cleanQuery));
          const usernameMatch = cleanQuery && data.username && data.username.toLowerCase().includes(cleanQuery);
          const collegeMatch = cleanQuery && data.college && data.college.toLowerCase().includes(cleanQuery);

          if (nameMatch || usernameMatch || collegeMatch) {
            loaded.push({ id: d.id, uid: d.id, ...data });
          }
        });

        setMatchingUsers(loaded);
      } catch (err) {
        console.error('Failed to search users in modal:', err);
      } finally {
        setSearchingUsers(false);
      }
    };

const handleOfficialAvatarSelect = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      setIsUploadingOfficialAvatar(true);
      const preview = URL.createObjectURL(file);
      setOfficialAvatarPreview(preview);

      const compressed = await compressImage(file);
      const uploadedUrl = await uploadImageToCloudinary(compressed);

      if (uploadedUrl) {
        setOfficialAvatarUrl(uploadedUrl);
        setOfficialAvatarPreview(uploadedUrl);
      } else {
        const reader = new FileReader();
        reader.onloadend = () => {
          setOfficialAvatarUrl(reader.result);
          setOfficialAvatarPreview(reader.result);
        };
        reader.readAsDataURL(compressed);
      }
    } catch (err) {
      console.error('Failed to process avatar:', err);
      showError('Failed to upload image. Please try again.');
    } finally {
      setIsUploadingOfficialAvatar(false);
    }
  };

