const handleSaveEditItem = async (e) => {
    e.preventDefault();
    if (!editingItem || !validateForm(editingItem)) return;

    try {
      await updateDoc(doc(db, 'marketplace', editingItem.id), {
        name: editingItem.name.trim(),
        price: Number(editingItem.price),
        category: editingItem.category,
        condition: editingItem.condition,
        age: editingItem.age.trim(),
        desc: editingItem.desc.trim(),
        imageUrl: editingItem.imageUrl || '',
        updatedAt: new Date().toISOString()
      });

      showSuccess(`Updated listing for "${editingItem.name}"!`);
      setEditingItem(null);
      setErrors({});
    } catch (err) {
      console.error('Failed to update listing:', err);
    }
  };

const handleContactSeller = (sellerName, itemTitle, sellerUid) => {
    setSelectedItem(null);
    if (sellerUid && user?.uid && sellerUid === user.uid) {
      navigate('/messages');
      return;
    }
    const productParam = itemTitle ? `&product=${encodeURIComponent(itemTitle)}` : '';
    if (sellerUid) {
      navigate(`/messages?recipientUid=${sellerUid}&recipientName=${encodeURIComponent(sellerName)}${productParam}`);
    } else {
      navigate(`/messages?recipientName=${encodeURIComponent(sellerName)}${productParam}`);
    }
  };

const handleTouchEnd = () => {
    setIsDragging(false);
  };

const handleInitiateReplyToComment = (targetComment) => {
    const parentId = targetComment.parentId || targetComment.id;
    const usernameHandle = targetComment.authorUsername || targetComment.author?.replace(/\s+/g, '');

    setReplyingToComment({
      parentId: parentId,
      commentId: targetComment.id,
      authorUid: targetComment.authorUid,
      author: targetComment.author,
      username: usernameHandle
    });

    const tag = `@${usernameHandle} `;
    let updatedText = newComment;
    if (!newComment.includes(tag.trim())) {
      const cleanedText = newComment.replace(/^@\S+\s*/, '');
      updatedText = `${tag}${cleanedText}`;
      setNewComment(updatedText);
    }

    setTimeout(() => {
      if (commentInputRef.current) {
        const el = commentInputRef.current;
        el.focus();
        const len = updatedText.length;
        el.setSelectionRange(len, len);
      }
    }, 50);
  };

const handleCreateSubmit = async (e) => {
    e.preventDefault();
    if (!inputText.trim() && !modalSelectedImage) return;

    setIsSubmitting(true);
    const randomIndex = Math.floor(Math.random() * ANONYMOUS_NAMES.length);
    const chosenName = ANONYMOUS_NAMES[randomIndex];

    try {
      const autoAudience = (feedType === 'college' || feedType === 'my_college') ? 'college_only' : 'public';

      if (postType === 'confession' || activeTab === 'confessions') {
        const now = new Date();
        const expiresAt = new Date(now.getTime() + 24 * 60 * 60 * 1000);

        await addDoc(collection(db, 'confessions'), {
          authorUid: user?.uid || 'anonymous_guest',
          college: user?.college || 'KIET',
          gender: (user?.kycGender && user.kycGender !== 'Neutral') ? user.kycGender : (user?.gender || 'Prefer not to say'),
          text: inputText.trim(),
          imageUrl: null,
          audience: autoAudience,
          visibility: autoAudience,
          createdAt: now,
          expiresAt: expiresAt,
          likes: 0,
          likedUsers: [],
          comments: 0,
          reports: false
        });
        showSuccess('24-Hour Confession published!');
      } else {
        await addDoc(collection(db, 'anonymousPosts'), {
          authorUid: user?.uid || 'anonymous_guest',
          college: user?.college || 'KIET',
          gender: (user?.kycGender && user.kycGender !== 'Neutral') ? user.kycGender : (user?.gender || 'Prefer not to say'),
          anonymousName: chosenName,
          text: inputText.trim(),
          imageUrl: modalSelectedImage || null,
          audience: autoAudience,
          visibility: autoAudience,
          likesCount: 0,
          likedUsers: [],
          commentsCount: 0,
          reported: false,
          createdAt: new Date()
        });
        showSuccess('Anonymous post published!');
      }

      setInputText('');
      setModalSelectedImage(null);
