const confirmDeleteItem = async () => {
    if (!deletingItem) return;
    try {
      await deleteDoc(doc(db, 'marketplace', deletingItem.id));
      showSuccess(`Deleted listing for "${deletingItem.name}"`);
      setDeletingItem(null);
      if (selectedItem?.id === deletingItem.id) {
        setSelectedItem(null);
      }
    } catch (err) {
      console.error('Failed to delete listing:', err);
    }
  };

const validateForm = (itemState) => {
    const newErrors = {};
    if (!itemState.name.trim()) newErrors.name = 'Item name is required';
    if (!itemState.price || isNaN(itemState.price) || Number(itemState.price) <= 0) {
      newErrors.price = 'Please enter a valid positive price';
    }
    if (!itemState.age.trim()) newErrors.age = 'Age is required';
    if (!itemState.desc.trim()) newErrors.desc = 'Description is required';

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

const handleAcceptRequest = async (requestObj) => {
    if (!selectedRoom?.id || !requestObj?.uid) return;
    try {
      await updateDoc(doc(db, 'userCommunities', selectedRoom.id), {
        members: arrayUnion(requestObj.uid),
        joinRequests: arrayRemove(requestObj)
      });
      setSelectedRoom(prev => ({
        ...prev,
        members: [...(prev.members || []), requestObj.uid],
        joinRequests: (prev.joinRequests || []).filter(r => (typeof r === 'string' ? r !== requestObj.uid : r.uid !== requestObj.uid))
      }));
      showSuccess(`Accepted request! Member added.`);
    } catch (e) {
      console.error(e);
      showWarning('Failed to accept request.');
    }
  };

