      if (!isKept) {
        const myExpire = msg.mySideOnlyExpiresAt?.[myUid];
        if (myExpire) {
          const expMs = myExpire.toDate ? myExpire.toDate().getTime() : new Date(myExpire).getTime();
          if (nowTick >= expMs) return false;
        }
      }
    }

