                        className="p-xs text-neutral-500 hover:text-neutral-900 dark:hover:text-white rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors cursor-pointer"
                        title="Close Chat"
                      >
                        <ChevronLeft className="w-6 h-6" />
