                  {showAttachMenuPop && (
                    <div className="absolute bottom-full mb-2 left-0 z-50 w-56 bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-2xl shadow-2xl p-2 text-xs font-semibold space-y-1">
                      <button
                        type="button"
                        onClick={() => { mediaInputRef.current?.click(); setShowAttachMenuPop(false); }}
                        className="w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-neutral-700 dark:text-neutral-200 hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors cursor-pointer"
                      >
                        <Image className="w-4 h-4 text-sky-500" />
                        <span>Photos / Gallery</span>
                      </button>
                      <button
                        type="button"
                        onClick={() => { setIsCreatePollOpen(true); setShowAttachMenuPop(false); }}
                        className="w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-neutral-700 dark:text-neutral-200 hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors cursor-pointer"
                      >
                        <BarChart2 className="w-4 h-4 text-purple-500" />
                        <span>Create Campus Poll</span>
                      </button>
                      <button
                        type="button"
                        onClick={() => { docInputRef.current?.click(); setShowAttachMenuPop(false); }}
                        className="w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-neutral-700 dark:text-neutral-200 hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors cursor-pointer"
                      >
                        <FileText className="w-4 h-4 text-amber-500" />
                        <span>Attach File / Doc</span>
                      </button>
                    </div>
                  )}
                </div>

                {activeConversation.isVanishMode && (
                  <button
                    type="button"
                    onClick={() => setIsKeepForeverActive(!isKeepForeverActive)}
                    className={`p-2 sm:px-md sm:py-xs rounded-full border text-xs font-semibold flex items-center gap-xs transition-all flex-shrink-0 ${
                      isKeepForeverActive
                        ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/40 shadow-sm ring-1 ring-emerald-500/30'
                        : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-400 border-neutral-200 dark:border-neutral-700 hover:text-neutral-900 dark:hover:text-white'
                    }`}
                    title="Toggle Keep Forever for this message"
                  >
                    <InfinityIcon className="w-4 h-4" />
                    <span className="hidden xs:inline text-[11px] font-bold">Keep</span>
                  </button>
                )}

                {/* Input Container */}
                <div className="flex-1 flex items-center bg-neutral-100 dark:bg-neutral-800/90 border border-neutral-200 dark:border-neutral-700/80 rounded-full px-4 py-1.5">
                  <input
                    ref={messageInputRef}
                    type="text"
                    placeholder={`Message ${activeConversation.name}...`}
                    value={messageText}
                    onChange={(e) => setMessageText(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleSendMessage(e)}
                    className="w-full bg-transparent border-0 py-1 text-sm text-neutral-900 dark:text-white placeholder:text-neutral-400 focus:outline-none"
                  />
                </div>

                <button
                  type="submit"
                  onMouseDown={(e) => e.preventDefault()}
                  onTouchStart={(e) => e.preventDefault()}
