                                <>
                                  <ShieldCheck className="w-3.5 h-3.5 text-emerald-500" /> Unblock User
                                </>
                              ) : (
                                <>
                                  <Ban className="w-3.5 h-3.5 text-amber-600" /> Block User
                                </>
