                    type="button"
                    onClick={() => setReplyToMsg(null)}
                    className="p-xs hover:bg-neutral-200 dark:hover:bg-neutral-700 rounded-full text-neutral-400 hover:text-neutral-700 dark:hover:text-white transition-colors ml-md"
