const getLiveRecipientProfile = (conv) => {
    if (!conv) return { avatar: '', name: 'Student', username: '', college: 'KIET' };

    // Always resolve the OTHER participant's UID (distinct from current user myUid)
    let otherUid = (conv.participants || []).find(p => p && p !== myUid);
    if (!otherUid) {
      if (conv.recipientUid && conv.recipientUid !== myUid) {
        otherUid = conv.recipientUid;
      } else if (conv.createdBy && conv.createdBy !== myUid) {
        otherUid = conv.createdBy;
      } else {
        const otherMsg = (conv.messages || []).find(m => (m.senderUid && m.senderUid !== myUid) || (m.sender && m.sender !== myUid && m.sender !== 'me'));
        if (otherMsg) {
          otherUid = otherMsg.senderUid || (otherMsg.sender !== 'me' ? otherMsg.sender : null);
        }
      }
    }

    const liveUser = (otherUid && usersMap[otherUid]) || null;
    const mapInfo = (otherUid && conv.participantMap?.[otherUid]) || null;

    let name = liveUser?.name || mapInfo?.name;
    if (!name) {
      if (conv.recipientUid && conv.recipientUid !== myUid && conv.recipientName) {
        name = conv.recipientName;
      } else if (conv.createdBy && conv.createdBy !== myUid && conv.createdByName) {
        name = conv.createdByName;
      } else {
        name = (conv.name && conv.name !== user?.name) ? conv.name : (conv.recipientName || 'Student');
      }
    }

    let avatar = liveUser?.avatar || mapInfo?.avatar;
    if (!avatar) {
      if (conv.recipientUid && conv.recipientUid !== myUid && conv.recipientAvatar) {
        avatar = conv.recipientAvatar;
      } else if (conv.createdBy && conv.createdBy !== myUid && conv.createdByAvatar) {
        avatar = conv.createdByAvatar;
      } else {
        avatar = (conv.avatar && conv.avatar !== user?.avatar) ? conv.avatar : `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(name)}`;
      }
    }

    return {
      avatar,
      name,
      username: liveUser?.username || mapInfo?.username || conv.username || '',
      college: liveUser?.college || mapInfo?.college || conv.college || 'Campus Peer',
      bio: liveUser?.bio || mapInfo?.bio || conv.bio || '',
      uid: otherUid || (conv.recipientUid !== myUid ? conv.recipientUid : conv.createdBy)
    };
  };

const Topography = ({
  lowColor = '#5227FF',
  midColor = '#FF9FFC',
  highColor = '#FFFFFF',
  speed = 0.35,
  morphAmount = 3.0,
  morphSpeed = 0.05,
  bands = 2.0,
  thickness = 0.01,
  scale = 1.0,
  pixelSize = 1.0,
  glow = 0.5,
  colorMode = 'elevation',
  contrast = 3.0,
  brightness = 1.0,
  fillBands = false,
  opacity = 1.0,
  grain = true,
  grainIntensity = 0.05,
  mouseInteraction = true,
  mouseRadius = 0.3,
  mouseStrength = 0.4,
  className = ''
}) => {
  const containerRef = useRef(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const renderer = new Renderer({
      webgl: 2,
      alpha: true,
      premultipliedAlpha: true,
      antialias: false,
      dpr: Math.min(window.devicePixelRatio || 1, 2)
    });

    const gl = renderer.gl;
    gl.clearColor(0, 0, 0, 0);
    const canvas = gl.canvas;
    canvas.style.width = '100%';
    canvas.style.height = '100%';
    canvas.style.display = 'block';
    container.appendChild(canvas);

    const geometry = new Triangle(gl);
    const program = new Program(gl, {
      vertex,
      fragment,
      uniforms: {
        iTime: { value: 0 },
        iResolution: { value: new Float32Array([1, 1]) },
        uSpeed: { value: 0.35 },
        uMorphAmount: { value: 3.0 },
        uMorphSpeed: { value: 0.05 },
        uBands: { value: 2.0 },
        uThickness: { value: 0.01 },
        uScale: { value: 1.0 },
        uPixelSize: { value: 1.0 },
        uGlow: { value: 0.5 },
        uColorMode: { value: 0.0 },
        uContrast: { value: 3.0 },
        uBrightness: { value: 1.0 },
        uFillBands: { value: 0.0 },
        uOpacity: { value: 1.0 },
        uGrain: { value: 1.0 },
        uGrainIntensity: { value: 0.05 },
        uLow: { value: new Float32Array([1, 1, 1]) },
        uMid: { value: new Float32Array([1, 1, 1]) },
        uHigh: { value: new Float32Array([1, 1, 1]) },
        uMouse: { value: new Float32Array([0.5, 0.5]) },
        uMouseEnabled: { value: 1.0 },
        uMouseRadius: { value: 0.3 },
        uMouseStrength: { value: 0.4 },
        uMouseActive: { value: 0.0 },
        uCtrlA: { value: new Float32Array([0, 0, 0, 0]) },
        uCtrlB: { value: new Float32Array([0, 0, 0, 0]) },
        uCtrlC: { value: new Float32Array([0, 0, 0, 0]) },
        uCtrlD: { value: new Float32Array([0, 0, 0, 0]) }
      }
    });

    const mesh = new Mesh(gl, { geometry, program });
    ctxMap.set(container, { renderer, program, mesh });

    const setSize = () => {
      const rect = container.getBoundingClientRect();
      const w = Math.max(1, Math.floor(rect.width));
      const h = Math.max(1, Math.floor(rect.height));
      renderer.setSize(w, h);
      const res = program.uniforms.iResolution.value;
      res[0] = gl.drawingBufferWidth;
      res[1] = gl.drawingBufferHeight;
      renderer.render({ scene: mesh });
    };

    const ro = new ResizeObserver(setSize);
    ro.observe(container);
    setSize();

    const currentMouse = [0.5, 0.5];
    const targetMouse = [0.5, 0.5];
    let mouseActive = 0;
    let mouseActiveTarget = 0;

    const onMouseMove = e => {
      const rect = canvas.getBoundingClientRect();
      targetMouse[0] = (e.clientX - rect.left) / rect.width;
      targetMouse[1] = 1.0 - (e.clientY - rect.top) / rect.height;
      mouseActiveTarget = 1;
    };
    const onMouseLeave = () => {
      mouseActiveTarget = 0;
    };
    canvas.addEventListener('mousemove', onMouseMove);
    canvas.addEventListener('mouseleave', onMouseLeave);

    const ctrlArrays = [
      program.uniforms.uCtrlA.value,
      program.uniforms.uCtrlB.value,
      program.uniforms.uCtrlC.value,
      program.uniforms.uCtrlD.value
    ];

    let raf = 0;
    let isVisible = true;
    let isPageVisible = !document.hidden;
    const t0 = performance.now();

    const loop = t => {
      const time = (t - t0) * 0.001;
      const u = program.uniforms;
      u.iTime.value = time;

      const ma = u.uMorphAmount.value;
      const sp = u.uSpeed.value;
      const msp = u.uMorphSpeed.value;
      for (let g = 0; g < 4; g++) {
        const arr = ctrlArrays[g];
        const idx = CTRL_INDICES[g];
        for (let j = 0; j < 4; j++) {
          const i = idx[j];
          arr[j] = ma * Math.sin(time * sp * Math.sin(i * msp) + i);
        }
      }

      currentMouse[0] += 0.05 * (targetMouse[0] - currentMouse[0]);
      currentMouse[1] += 0.05 * (targetMouse[1] - currentMouse[1]);
      u.uMouse.value[0] = currentMouse[0];
      u.uMouse.value[1] = currentMouse[1];

      mouseActive += 0.05 * (mouseActiveTarget - mouseActive);
      u.uMouseActive.value = mouseActive;

      renderer.render({ scene: mesh });
      raf = requestAnimationFrame(loop);
    };

    const tryStart = () => {
      if (isVisible && isPageVisible && raf === 0) raf = requestAnimationFrame(loop);
    };
    const tryStop = () => {
      if (raf !== 0) {
        cancelAnimationFrame(raf);
        raf = 0;
      }
    };

    const io = new IntersectionObserver(
      ([entry]) => {
        isVisible = entry.isIntersecting;
        isVisible ? tryStart() : tryStop();
      },
      { threshold: 0 }
    );
    io.observe(container);

    const onVisibility = () => {
      isPageVisible = !document.hidden;
      isPageVisible ? tryStart() : tryStop();
    };
    document.addEventListener('visibilitychange', onVisibility);

    tryStart();

    return () => {
      tryStop();
      ro.disconnect();
      io.disconnect();
      document.removeEventListener('visibilitychange', onVisibility);
      canvas.removeEventListener('mousemove', onMouseMove);
      canvas.removeEventListener('mouseleave', onMouseLeave);
      ctxMap.delete(container);
      try {
        container.removeChild(canvas);
      } catch {}
      gl.getExtension('WEBGL_lose_context')?.loseContext();
    };
  }, []);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    const ctx = ctxMap.get(container);
    if (!ctx) return;
    const { program } = ctx;
    const u = program.uniforms;

    u.uSpeed.value = speed;
    u.uMorphAmount.value = morphAmount;
    u.uMorphSpeed.value = morphSpeed;
    u.uBands.value = bands;
    u.uThickness.value = thickness;
    u.uScale.value = scale;
    u.uPixelSize.value = pixelSize;
    u.uGlow.value = glow;
    u.uColorMode.value = colorModeToFloat(colorMode);
    u.uContrast.value = contrast;
    u.uBrightness.value = brightness;
    u.uFillBands.value = fillBands ? 1.0 : 0.0;
    u.uOpacity.value = opacity;
    u.uGrain.value = grain ? 1.0 : 0.0;
    u.uGrainIntensity.value = grainIntensity;
    u.uLow.value = new Float32Array(hexToRgb(lowColor));
    u.uMid.value = new Float32Array(hexToRgb(midColor));
    u.uHigh.value = new Float32Array(hexToRgb(highColor));
    u.uMouseEnabled.value = mouseInteraction ? 1.0 : 0.0;
    u.uMouseRadius.value = mouseRadius;
    u.uMouseStrength.value = mouseStrength;
  }, [
    lowColor,
    midColor,
    highColor,
    speed,
    morphAmount,
    morphSpeed,
    bands,
    thickness,
    scale,
    pixelSize,
    glow,
    colorMode,
    contrast,
    brightness,
    fillBands,
    opacity,
    grain,
    grainIntensity,
    mouseInteraction,
    mouseRadius,
    mouseStrength
  ]);

  return <div ref={containerRef} className={`topography-container ${className}`.trim()} />;
};

const handleReshareWithThoughtsSubmit = async () => {
    if (!thoughtCaption.trim()) return;
    const rootOriginalPostId = post.originalPostId || post.docId || post.id;
    const origAuthor = post.originalPost?.author || post.author;
    const origContent = post.originalPost?.content || post.content;
    const origTimestamp = post.originalPost?.timestamp || post.timestamp;
    const myUid = user?.uid;

    setIsSubmittingReshare(true);
    setLocalReposts(prev => prev + 1);
    if (myUid) setLocalResharedUsers(prev => [...prev, myUid]);

    try {
      const reshareDocData = {
        isReshare: true,
        originalPostId: rootOriginalPostId,
        originalPost: {
          id: rootOriginalPostId,
          author: origAuthor,
          content: origContent,
          timestamp: origTimestamp
        },
        resharedBy: {
          uid: myUid || null,
          name: user?.name || 'Student',
          username: user?.username || null,
          avatar: user?.avatar || null
        },
        college: user?.college || 'KIET',
        author: {
          uid: myUid || null,
          name: user?.name || 'Student',
          username: user?.username || null,
          avatar: user?.avatar || null,
          role: user?.college || 'KIET',
          college: user?.college || 'KIET'
        },
        thought: thoughtCaption.trim(),
        content: thoughtCaption.trim(),
        timestamp: new Date(),
        upvotes: 0,
        downvotes: 0,
        upvotedUsers: [],
        downvotedUsers: [],
        comments: 0,
        reposts: 0,
        saved: false
      };

      await addDoc(collection(db, 'posts'), reshareDocData);

      const origPostRef = doc(db, 'posts', rootOriginalPostId);
      await updateDoc(origPostRef, {
        reposts: increment(1),
        resharedUsers: myUid ? arrayUnion(myUid) : []
      });

      if (onRepost) onRepost(rootOriginalPostId);

      const origAuthorUid = origAuthor?.uid || post.author?.uid;
      if (origAuthorUid && origAuthorUid !== myUid) {
        createNotification({
          recipientUid: origAuthorUid,
          senderUid: myUid,
          senderName: user?.name || 'Student',
          senderAvatar: user?.avatar,
          type: 'reshare',
          text: 'reshared your post with their thoughts.',
          postId: rootOriginalPostId
        });
      }

      showSuccess('Post reshared with thoughts successfully.');
      setShowReshareModal(false);
      setReshareMode(null);
      setThoughtCaption('');
    } catch (err) {
      console.error('Failed to reshare post with thoughts:', err);
      setLocalReposts(post.reposts || 0);
      setLocalResharedUsers(post.resharedUsers || []);
    } finally {
      setIsSubmittingReshare(false);
    }
  };

