        avatar = (conv.avatar && conv.avatar !== user?.avatar) ? conv.avatar : `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(name)}`;
      }
    }

    return {
      avatar,
      name,
      username: liveUser?.username || mapInfo?.username || conv.username || '',
      college: liveUser?.college || mapInfo?.college || conv.college || 'Campus Peer',
      bio: liveUser?.bio || mapInfo?.bio || conv.bio || '',
      uid: otherUid || (conv.recipientUid !== myUid ? conv.recipientUid : conv.createdBy)
    };
  };

const isCollegeEmail = (email) => {
  if (!email || typeof email !== 'string') return false;
  const domain = email.trim().toLowerCase().split('@')[1];
  if (!domain) return false;

  // Suffix checks:
  // - .edu (e.g. stanford.edu)
  // - .edu.xx (e.g. college.edu.in, college.edu.co)
  // - .ac.xx (e.g. iitd.ac.in, cam.ac.uk)
  // - .res.in (some research institutes in India)
  const academicRegex = /(\.edu|\.edu\.[a-z]{2}|\.ac\.[a-z]{2}|\.res\.in)$/i;

  // Custom popular exceptions that are academic but might not use the standard suffixes
  const customAcademicDomains = [
    'christuniversity.in',
    'srmist.edu.in',
    'mahe.edu',
    'manipal.edu',
    'symbiosis.ac.in'
  ];

  return academicRegex.test(domain) || customAcademicDomains.includes(domain);
};

const hasTokenMatch = (strA, strB) => {
            const tokensA = getTokens(strA);
            const tokensB = getTokens(strB);
            return tokensA.some(t => tokensB.includes(t));
          };

