  // Handle claps
  const handleClap = async (id, e) => {
    e.stopPropagation();

    // Prevent excessive clapping or track locally
    const currentClaps = clappedArticles[id] || 0;
    if (currentClaps >= 10) return; // Cap at 10 claps per session

    setClappedArticles(prev => ({
