const handleCreatePoll = async (e) => {
    if (e && e.preventDefault) e.preventDefault();
    if (!pollQuestion.trim()) {
      showSuccess('Please enter a poll question.');
      return;
    }
    const validOptions = pollOptions.filter(o => o.trim() !== '');
    if (validOptions.length < 2) { showSuccess('At least 2 options required.'); return; }

    const targetConv = conversations.find(c => c.id === selectedId || c.docId === selectedId);
    if (!targetConv) return;

    const myName = user?.name || user?.email?.split('@')[0] || 'Me';
    const pollObj = {
      question: pollQuestion.trim(),
      pollType: pollType,
      totalVotes: 0,
      options: validOptions.map((optText, i) => ({ id: `opt_${i}`, text: optText.trim(), votes: 0, votedUsers: [] }))
    };

    const newMsg = {
      sender: user?.uid || 'me',
      senderUid: user?.uid || null,
      senderName: myName,
      text: `Poll: ${pollQuestion.trim()}`,
      poll: pollObj,
      type: 'poll',
      time: new Date(),
      deletedFor: []
    };

    setIsCreatePollOpen(false);
    setPollQuestion('');
    setPollOptions(['', '']);
    setPollType('single');

    const updatedMsgs = [...(targetConv.messages || []), newMsg];
    setConversations(prev => prev.map(c => (c.id === selectedId || c.docId === selectedId) ? { ...c, messages: updatedMsgs } : c));

    const targetDocId = targetConv.docId || targetConv.id;
    if (targetDocId) {
      try {
        await updateDoc(doc(db, 'messages', targetDocId), {
          messages: updatedMsgs,
          lastMessage: `Poll: ${pollQuestion.trim()}`,
          lastTime: new Date()
        });
      } catch (err) {
        console.error(err);
      }
    }
    showSuccess('Poll published in chat!');
  };

const handleTogglePollVote = (index) => {
    setPollVotes(prev => {
      return prev.map((opt, i) => {
        if (i === index) {
          const isRemoving = selectedPollIndex === index;
          return { ...opt, count: isRemoving ? Math.max(0, opt.count - 1) : opt.count + 1 };
        } else if (selectedPollIndex === i) {
          return { ...opt, count: Math.max(0, opt.count - 1) };
        }
        return opt;
      });
    });

    setSelectedPollIndex(prev => (prev === index ? null : index));
  };

const resize = () => {
      // Fractional size + explicit center keep the SDF pinned to the exact
      // CSS border, instead of drifting up to a pixel from offsetWidth rounding.
      const rect = btn.getBoundingClientRect();
      const w = rect.width;
      const h = rect.height;
      sizeRef.w = w;
      sizeRef.h = h;
      renderer.setSize(w + PAD * 2, h + PAD * 2);
      program.uniforms.uCenter.value = [(PAD + w / 2) * dpr, (PAD + h / 2) * dpr];
      program.uniforms.uHalfSize.value = [(w / 2) * dpr, (h / 2) * dpr];
    };

export const formatRelativeTime = (date) => {
  const now = new Date();
  const diff = now - new Date(date);
  const seconds = Math.floor(diff / 1000);
  const minutes = Math.floor(seconds / 60);
  const hours = Math.floor(minutes / 60);
  const days = Math.floor(hours / 24);

  if (seconds < 60) return 'just now';
  if (minutes < 60) return `${minutes}m ago`;
  if (hours < 24) return `${hours}h ago`;
  if (days < 7) return `${days}d ago`;

  return formatDate(date);
};

