const handleRejectRequest = async (requestObj) => {
    if (!selectedRoom?.id || !requestObj?.uid) return;
    try {
      await updateDoc(doc(db, 'userCommunities', selectedRoom.id), {
        joinRequests: arrayRemove(requestObj)
      });
      setSelectedRoom(prev => ({
        ...prev,
        joinRequests: (prev.joinRequests || []).filter(r => (typeof r === 'string' ? r !== requestObj.uid : r.uid !== requestObj.uid))
      }));
      showSuccess('Join request rejected.');
    } catch (e) {
      console.error(e);
    }
  };

const getInitials = (str) => {
    const fillerWords = ['of', 'and', 'the', 'for', 'in', 'at', 'on', 'a', 'an', 'to', 'group', 'institutions'];
    return str
      .replace(/[^a-zA-Z\s]/g, '') // remove punctuation
      .split(/\s+/)
      .map(word => word.trim().toLowerCase())
      .filter(word => word.length > 0 && !fillerWords.includes(word))
      .map(word => word[0])
      .join('')
      .toLowerCase();
  };

const handleBulkStarSelected = async () => {
    if (!activeConversation || !activeConversation.docId || selectedMsgKeys.length === 0) return;

    const currentMsgs = activeConversation.messages || [];
    const updatedMsgs = currentMsgs.map(m => {
      const msgKey = `${m.text}_${new Date(m.time).getTime()}`;
      if (selectedMsgKeys.includes(msgKey)) {
        const starList = m.starredBy || [];
        if (!starList.includes(myUid)) {
          return { ...m, starredBy: [...starList, myUid] };
        }
      }
      return m;
    });

    try {
      const docRef = doc(db, 'messages', activeConversation.docId);
      await updateDoc(docRef, { messages: updatedMsgs });
      showSuccess(`${selectedMsgKeys.length} messages starred ⭐`);
      setSelectedMsgKeys([]);
      setIsSelectMode(false);
    } catch (err) {
      console.error('Failed to bulk star messages:', err);
    }
  };

const handleBulkDeleteSelected = async () => {
