const handleRepost = async (postId) => {
    const targetPost = posts.find(p => p.id === postId);
    if (!targetPost || !targetPost.docId) return;

    const newRepostsCount = (targetPost.reposts || 0) + 1;
    showSuccess('Reposted to your feed!');

    try {
      const docRef = doc(db, 'posts', targetPost.docId);
      await updateDoc(docRef, {
        reposts: newRepostsCount
      });
    } catch (error) {
      console.error('Failed to update reposts in Firestore:', error);
    }
  };

const runMatchingSequence = () => {
    const logs = [
      'Launching Campus Vibe Checker...',
      'Syncing student interests & profiles...',
      'Analyzing personality maps & hobbies...',
      'Scanning campus cohorts...',
      'Calibrating vibe alignments...',
      'Vibe twins located! Loading profiles...'
    ];

    setMatchingConsoleLogs([]);
    logs.forEach((logText, idx) => {
      setTimeout(() => {
        setMatchingConsoleLogs((prev) => [...prev, logText]);
        if (idx === logs.length - 1) {
          setTimeout(() => {
            setStep('swiping');
          }, 1000);
        }
      }, (idx + 1) * 600);
    });
  };

