      const universityName = universityNameRaw.replace(cleanIdRegex, '').trim();

      const state = item.state || '';
      const district = item.district || '';

      if (
        collegeName.toLowerCase().includes(cleanQuery) ||
        universityName.toLowerCase().includes(cleanQuery) ||
        state.toLowerCase().includes(cleanQuery) ||
        district.toLowerCase().includes(cleanQuery)
      ) {
        results.push({
          name: collegeName,
          university: universityName,
          state,
          district,
          location: district ? `${district}, ${state}` : state
        });

        if (results.length >= 50) {
          break;
        }
      }
    }

    res.setHeader('Content-Type', 'application/json');
    res.setHeader('Cache-Control', 's-maxage=86400, stale-while-revalidate=3600');
    return res.status(200).json(results);
  } catch (error) {
    console.error('Search colleges error:', error);
    return res.status(500).json({ error: 'Internal Server Error' });
  }
}

const handleMediaSelect = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const isVideo = file.type.startsWith('video/');
    const isImage = file.type.startsWith('image/');

    if (!isImage && !isVideo) {
      showError('Please select a photo or video file ❌');
      return;
    }

    if (file.size > 50 * 1024 * 1024) {
      showError('Media file size must be less than 50MB ⚠️');
      return;
    }

    const reader = new FileReader();
    reader.onload = (event) => {
      setSelectedMedia({
        file,
        url: event.target.result,
        type: isVideo ? 'video' : 'image',
        name: file.name
      });
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };

const handleDocumentSelect = (e) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedMedia({
        file,
        url: URL.createObjectURL(file),
        type: 'file',
        name: file.name
      });
      showSuccess(`Document attached: ${file.name}`);
    }
  };

