        </Modal>
      )}

      {/* Modal to Edit Cohort Official Account */}
      {isEditOfficialModalOpen && isOfficialLoggedIn && (
        <Modal
          isOpen={isEditOfficialModalOpen}
          onClose={() => setIsEditOfficialModalOpen(false)}
