          expiresAt: expiresAt,
          likes: 0,
          likedUsers: [],
          comments: 0,
          reports: false
        });
        showSuccess('24-Hour Confession published!');
      } else {
        await addDoc(collection(db, 'anonymousPosts'), {
          authorUid: user?.uid || 'anonymous_guest',
