async function handler(req, res) {
  try {
    const { q } = req.query || {};
    if (!q) {
      res.setHeader('Content-Type', 'application/json');
      return res.status(200).json(POPULAR_COLLEGES);
    }

    const cleanQuery = q.trim().toLowerCase();
    if (cleanQuery.length < 2) {
      res.setHeader('Content-Type', 'application/json');
      return res.status(200).json(POPULAR_COLLEGES);
    }

    const results = [];
    const cleanIdRegex = /\s*\(Id:\s*[^)]+\)/gi;

    for (let i = 0; i < colleges.length; i++) {
      const item = colleges[i];
      const collegeNameRaw = item.college || '';
      const universityNameRaw = item.university || '';

      const collegeName = collegeNameRaw.replace(cleanIdRegex, '').trim();
      const universityName = universityNameRaw.replace(cleanIdRegex, '').trim();

      const state = item.state || '';
      const district = item.district || '';

      if (
        collegeName.toLowerCase().includes(cleanQuery) ||
        universityName.toLowerCase().includes(cleanQuery) ||
        state.toLowerCase().includes(cleanQuery) ||
        district.toLowerCase().includes(cleanQuery)
      ) {
        results.push({
          name: collegeName,
          university: universityName,
          state,
          district,
          location: district ? `${district}, ${state}` : state
        });

        if (results.length >= 50) {
          break;
        }
      }
    }

    res.setHeader('Content-Type', 'application/json');
    res.setHeader('Cache-Control', 's-maxage=86400, stale-while-revalidate=3600');
    return res.status(200).json(results);
  } catch (error) {
    console.error('Search colleges error:', error);
    return res.status(500).json({ error: 'Internal Server Error' });
  }
}

const handleDeleteMessageForEveryone = async (msgToDelete) => {
    if (!activeConversation || !activeConversation.docId || !msgToDelete) return;

    const currentMsgs = activeConversation.messages || [];
    const updatedMsgs = currentMsgs.map(m => {
      const isTarget = m === msgToDelete ||
                       (m.text === msgToDelete.text && Math.abs(new Date(m.time).getTime() - new Date(msgToDelete.time).getTime()) < 2000);
      if (isTarget) {
        const origText = (m.text && m.text !== 'This message was deleted by sender')
          ? m.text
          : (m.originalText || m.mediaName || 'Attachment');
        return {
          ...m,
          isDeletedForEveryone: true,
          originalText: origText,
          text: 'This message was deleted by sender',
          mediaUrl: null,
          mediaType: null
        };
      }
      return m;
    });

    try {
      const docRef = doc(db, 'messages', activeConversation.docId);
      await updateDoc(docRef, { messages: updatedMsgs });
      showSuccess('Message deleted for everyone 🗑️');
      setMsgToDeleteModal(null);
    } catch (err) {
      console.error('Failed to delete message for everyone:', err);
    }
  };

