                onClick={() => handleJumpToStarredMessage(sMsg)}
                className="p-md rounded-2xl bg-neutral-50 dark:bg-neutral-900 border border-neutral-200/80 dark:border-neutral-800 hover:border-amber-500/50 hover:bg-amber-500/5 transition-all cursor-pointer space-y-xs group"
              >
                <div className="flex items-center justify-between gap-md">
                  <div className="flex items-center gap-xs min-w-0">
                    <span className="px-2 py-0.5 rounded-md bg-sky-500/10 text-sky-600 dark:text-sky-400 font-bold text-[10px] truncate">
                      {sMsg.roomName}
                    </span>
                    <span className="text-xs font-bold text-neutral-900 dark:text-white truncate">
                      {sMsg.sender?.name || 'User'}
                    </span>
                  </div>
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      handleStarGroupMessage(sMsg.id);
                    }}
                    className="text-xs text-amber-500 hover:text-amber-600 font-semibold flex items-center gap-xs p-xs rounded hover:bg-amber-500/10 transition-colors flex-shrink-0"
                    title="Unstar message"
                  >
                    <Star className="w-3.5 h-3.5 fill-amber-400" />
                  </button>
                </div>
                <p className="text-xs text-neutral-700 dark:text-neutral-300 leading-relaxed whitespace-pre-wrap line-clamp-3">
                  {sMsg.content}
                </p>
                <div className="flex items-center justify-between text-[10px] text-neutral-400 pt-xs">
                  <span className="text-amber-500 group-hover:underline font-semibold flex items-center gap-xs">
                    Tap to open in chat →
                  </span>
                  <span>{formatTime(sMsg.timestamp)}</span>
                </div>
              </div>
            ))
          )}
        </div>
      </Modal>

      {/* ── CONFIRM DELETE INDIVIDUAL MESSAGE MODAL ── */}
      <Modal
        isOpen={!!msgToDeleteModal}
        onClose={() => setMsgToDeleteModal(null)}
        title="Delete Message?"
        size="sm"
      >
        <div className="space-y-lg">
          <div className="flex items-start gap-md p-md bg-neutral-50 dark:bg-neutral-800/60 rounded-2xl border border-neutral-200/80 dark:border-neutral-700/80">
            <div className="p-sm bg-rose-500/10 text-rose-500 rounded-xl flex-shrink-0">
              <Trash2 className="w-5 h-5" />
            </div>
            <div className="min-w-0 flex-1">
              <p className="font-bold text-sm text-neutral-900 dark:text-white mb-xs">
                {msgToDeleteModal?.canEveryone ? 'Message Deletion Options' : 'Delete from your view'}
              </p>
              <p className="text-xs text-neutral-500 dark:text-neutral-400 line-clamp-2 italic bg-white dark:bg-neutral-900 p-xs px-sm rounded-lg border border-neutral-200/60 dark:border-neutral-800">
                "{msgToDeleteModal?.msg?.content || msgToDeleteModal?.msg?.text || msgToDeleteModal?.msg?.fileName || 'Message attachment'}"
              </p>
            </div>
          </div>

          {msgToDeleteModal?.canEveryone ? (
            <div className="space-y-sm">
              <p className="text-xs text-neutral-600 dark:text-neutral-300 font-medium">
                Choose how you would like to delete this message:
              </p>

              <button
                type="button"
                onClick={() => handleDeleteMsgForEveryone(msgToDeleteModal.msg?.id)}
                className="w-full py-md px-lg bg-rose-600 hover:bg-rose-700 active:scale-95 text-white font-bold text-xs rounded-xl shadow-md transition-all flex items-center justify-center gap-xs cursor-pointer"
              >
                <Trash2 className="w-4 h-4" />
                <span>Delete for Everyone (Both Sides)</span>
              </button>

              <button
                type="button"
                onClick={() => handleDeleteMsgForMe(msgToDeleteModal.msg?.id)}
                className="w-full py-md px-lg bg-neutral-100 dark:bg-neutral-800 hover:bg-neutral-200 dark:hover:bg-neutral-700 active:scale-95 text-neutral-900 dark:text-white font-bold text-xs rounded-xl transition-all flex items-center justify-center gap-xs cursor-pointer border border-neutral-200 dark:border-neutral-700"
              >
                <User className="w-4 h-4 text-primary-500" />
                <span>Delete for Me Only</span>
              </button>

              <button
                type="button"
                onClick={() => setMsgToDeleteModal(null)}
                className="w-full py-xs text-xs font-semibold text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-200 transition-colors text-center"
              >
                Cancel
              </button>
            </div>
          ) : (
            <div className="space-y-sm">
              <p className="text-xs text-neutral-600 dark:text-neutral-300 font-medium">
                This message will be removed only from your view.
              </p>

              <div className="flex gap-md pt-xs">
                <Button
                  variant="secondary"
                  className="flex-1"
                  onClick={() => setMsgToDeleteModal(null)}
                >
                  Cancel
                </Button>

                <button
                  type="button"
                  onClick={() => handleDeleteMsgForMe(msgToDeleteModal.msg?.id)}
                  className="flex-1 py-md px-lg bg-rose-600 hover:bg-rose-700 active:scale-95 text-white font-bold text-xs rounded-xl shadow-md transition-all flex items-center justify-center gap-xs cursor-pointer"
                >
                  <Trash2 className="w-4 h-4" />
                  <span>Delete for Me</span>
                </button>
              </div>
            </div>
          )}
        </div>
      </Modal>
    </div>
  );
}

const handleImageUpload = async (file, setTargetState) => {
    if (!file) return;
    setImageUploading(true);
    try {
      let finalUrl = '';
      try {
        finalUrl = await uploadImageToCloudinary(file);
      } catch (err) {
        console.warn('Cloudinary upload failed, using compressed base64 image:', err);
        finalUrl = await compressImage(file);
      }
      setTargetState(prev => ({ ...prev, imageUrl: finalUrl }));
    } catch (err) {
      console.error('Failed to process image:', err);
    } finally {
      setImageUploading(false);
    }
  };

const updateMetaTag = (attribute, value, content) => {
      let element = document.querySelector(`meta[${attribute}="${value}"]`);
      if (!element) {
        element = document.createElement('meta');
        element.setAttribute(attribute, value);
        document.head.appendChild(element);
      }
      element.setAttribute('content', content);
    };

const handleDeleteConversation = async (targetConv = activeConversation, e = null, forceConfirmed = false) => {
    if (e) e.stopPropagation();
    const convToDelete = targetConv || activeConversation;
    const targetDocId = convToDelete?.docId || convToDelete?.id;
    if (!convToDelete || !targetDocId) return;
    setOpenMenuId(null);
    setShowHeaderMenu(false);

    if (!forceConfirmed) {
      setConfirmDeleteConv(convToDelete);
      return;
    }

    const currentUid = user?.uid;

    // Optimistically update UI state immediately
    setConversations(prev => prev.filter(c => c.id !== convToDelete.id && c.docId !== targetDocId));
    if (selectedId === convToDelete.id || selectedId === targetDocId) {
      setSelectedId(null);
      setMobileView('list');
    }
    setConfirmDeleteConv(null);

    try {
      const docRef = doc(db, 'messages', targetDocId);
      const realMsgs = convToDelete.messages || [];
      const hasRealUserMsgs = realMsgs.some(m => !m.isDeletedForEveryone);

      if (!hasRealUserMsgs) {
        await deleteDoc(docRef).catch(() => {});
      } else {
        await updateDoc(docRef, {
          [`hiddenFor.${currentUid}`]: true,
          [`clearedFor.${currentUid}`]: new Date()
        }).catch(() => {});
      }

      showSuccess('Conversation deleted');
    } catch (err) {
      console.error('Failed to delete conversation:', err);
      showSuccess('Conversation deleted');
    }
  };

const handleToggleBlock = async (targetConv, e) => {
    if (e) e.stopPropagation();
    if (!targetConv || !targetConv.docId) return;
    setOpenMenuId(null);
    const currentlyBlocked = targetConv.blockedBy?.[myUid] === true;
    try {
      const docRef = doc(db, 'messages', targetConv.docId);
      await updateDoc(docRef, {
        [`blockedBy.${myUid}`]: !currentlyBlocked
      });
      showSuccess(currentlyBlocked ? 'User unblocked' : 'User blocked');
    } catch (err) {
      console.error('Failed to toggle block:', err);
    }
  };

export default function Profile() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const targetUid = searchParams.get('uid');
  const targetName = searchParams.get('name');

  const { user: currentUser, updateUser, openKycModal } = useAuth();
  const { showSuccess } = useNotification();

  const [profileUser, setProfileUser] = useState(null);
  const [userPosts, setUserPosts] = useState([]);
  const [userAnonPosts, setUserAnonPosts] = useState([]);
  const [userMarketplaceItems, setUserMarketplaceItems] = useState([]);
  const [postsTab, setPostsTab] = useState('feed'); // 'feed' | 'anonymous' | 'marketplace'
  const [totalLikes, setTotalLikes] = useState(0);
  const [loading, setLoading] = useState(true);

  // Edit / Delete Marketplace Item State
  const [editingMarketplaceItem, setEditingMarketplaceItem] = useState(null);
  const [deletingMarketplaceItem, setDeletingMarketplaceItem] = useState(null);
  const [imageUploading, setImageUploading] = useState(false);
  const editMarketplaceFileInputRef = useRef(null);


  // Followers / Following Modal State
  const [connectionsModalOpen, setConnectionsModalOpen] = useState(false);
  const [activeTab, setActiveTab] = useState('followers');
  const [connectionsSearch, setConnectionsSearch] = useState('');
  const [connectionsList, setConnectionsList] = useState([]);
  const [loadingConnections, setLoadingConnections] = useState(false);

  // Edit / Delete Post State
  const [editingPost, setEditingPost] = useState(null);
  const [editedContent, setEditedContent] = useState('');
  const [isSubmittingEdit, setIsSubmittingEdit] = useState(false);

  // Likes & Comments Modals State
  const [selectedPostForLikes, setSelectedPostForLikes] = useState(null);
  const [likedUsersList, setLikedUsersList] = useState([]);
  const [loadingLikedUsers, setLoadingLikedUsers] = useState(false);

  // Official Cohort Account Edit State
  const [isEditOfficialModalOpen, setIsEditOfficialModalOpen] = useState(false);
  const [officialBioInput, setOfficialBioInput] = useState('');
  const [officialAvatarUrl, setOfficialAvatarUrl] = useState('');
  const [officialAvatarPreview, setOfficialAvatarPreview] = useState('');
  const [isUploadingOfficialAvatar, setIsUploadingOfficialAvatar] = useState(false);
  const [isSavingOfficial, setIsSavingOfficial] = useState(false);
  const officialFileInputRef = useRef(null);


  const [selectedPostForComments, setSelectedPostForComments] = useState(null);
  const [commentsList, setCommentsList] = useState([]);
  const [loadingComments, setLoadingComments] = useState(false);
  const [newCommentText, setNewCommentText] = useState('');
  const [submittingComment, setSubmittingComment] = useState(false);
  const [replyingToComment, setReplyingToComment] = useState(null);
  const commentInputRef = useRef(null);

  const parseCommentDate = (rawDate) => {
    if (!rawDate) return 'Recently';
    if (typeof rawDate === 'string') {
      const p = new Date(rawDate);
      if (!isNaN(p.getTime())) return formatRelativeTime(p);
      return rawDate;
    }
    if (typeof rawDate === 'number') return formatRelativeTime(new Date(rawDate));
    if (rawDate?.toDate && typeof rawDate.toDate === 'function') return formatRelativeTime(rawDate.toDate());
    if (rawDate?.seconds) return formatRelativeTime(new Date(rawDate.seconds * 1000));
    return 'Recently';
  };

  const handleOpenLikesModal = async (post) => {
    setSelectedPostForLikes(post);
    setLoadingLikedUsers(true);
    try {
      const likedUids = post.likedUsers || post.upvotedUsers || post.likedBy || (Array.isArray(post.likes) ? post.likes : []);
      if (!likedUids || likedUids.length === 0) {
        setLikedUsersList([]);
        setLoadingLikedUsers(false);
        return;
      }

      const userDocs = await Promise.all(
        likedUids.map(uid => getDoc(doc(db, 'users', uid)).catch(() => null))
      );

      const list = [];
      userDocs.forEach((d, idx) => {
        const uid = likedUids[idx];
        if (d && d.exists()) {
          const data = d.data();
          list.push({
            uid,
            name: data.name || 'Student',
            avatar: data.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(uid)}`,
            college: data.college || 'Campus Member'
          });
        } else {
          list.push({
            uid,
            name: 'Student',
            avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(uid)}`,
            college: 'Campus Member'
          });
        }
      });
      setLikedUsersList(list);
    } catch (err) {
      console.error('Failed to fetch liked users:', err);
    } finally {
      setLoadingLikedUsers(false);
    }
  };

  const handleOpenCommentsModal = (post) => {
    setSelectedPostForComments(post);
    setReplyingToComment(null);
  };

  const handleReplyToComment = (c) => {
    setReplyingToComment(c);
    const mention = (c.authorUsername || c.authorName || 'user').replace(/\s+/g, '');
    setNewCommentText(`@${mention} `);
    if (commentInputRef.current) {
      commentInputRef.current.focus();
    }
  };

  useEffect(() => {
    if (!selectedPostForComments) {
      setCommentsList([]);
      setReplyingToComment(null);
      return;
    }

    setLoadingComments(true);
    const collName = selectedPostForComments.collectionName ||
      (selectedPostForComments.isConfession ? 'confessions' : (selectedPostForComments.isAnonymous ? 'anonymousPosts' : 'posts'));

    const q = collection(db, collName, selectedPostForComments.id, 'comments');

    const unsub = onSnapshot(q, (snap) => {
      const loaded = [];
      snap.forEach(d => {
        const data = d.data();
        const rawDate = data.createdAt || data.timestamp;
        loaded.push({
          id: d.id,
          ...data,
          authorName: data.authorName || data.author || data.authorUsername || 'Student',
          authorAvatar: data.authorAvatar || data.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(data.authorUid || d.id)}`,
          displayDateText: parseCommentDate(rawDate)
        });
      });
      setCommentsList(loaded);
      setLoadingComments(false);
    }, (err) => {
      console.error('Error fetching comments:', err);
      setLoadingComments(false);
    });

    return () => unsub();
  }, [selectedPostForComments]);

  const handleAddComment = async (e) => {
    if (e) e.preventDefault();
    if (!newCommentText.trim() || !selectedPostForComments || !currentUser) return;

    setSubmittingComment(true);
    const collName = selectedPostForComments.collectionName ||
      (selectedPostForComments.isConfession ? 'confessions' : (selectedPostForComments.isAnonymous ? 'anonymousPosts' : 'posts'));

    try {
      const now = new Date();
      const commentData = {
        text: newCommentText.trim(),
        authorUid: currentUser.uid,
        authorName: currentUser.name || 'Student',
        author: currentUser.name || 'Student',
        authorAvatar: currentUser.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(currentUser.uid)}`,
        avatar: currentUser.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(currentUser.uid)}`,
        createdAt: now,
        timestamp: now,
        parentId: replyingToComment ? replyingToComment.id : null,
        replyToAuthorUid: replyingToComment ? (replyingToComment.authorUid || null) : null,
        replyToAuthorName: replyingToComment ? (replyingToComment.authorName || replyingToComment.author || null) : null,
        likes: 0,
        likedBy: []
      };

      await addDoc(collection(db, collName, selectedPostForComments.id, 'comments'), commentData);

      const postRef = doc(db, collName, selectedPostForComments.id);
      await updateDoc(postRef, {
        commentsCount: increment(1),
        comments: increment(1)
      }).catch(() => {});

      const updateList = (list) => list.map(p => p.id === selectedPostForComments.id ? { ...p, commentsCount: (p.commentsCount || 0) + 1 } : p);
      setUserPosts(prev => updateList(prev));
      setUserAnonPosts(prev => updateList(prev));

      setNewCommentText('');
      setReplyingToComment(null);
      showSuccess('Comment posted!');
    } catch (err) {
      console.error('Failed to add comment:', err);
    } finally {
      setSubmittingComment(false);
    }
  };

  const handleOpenEditModal = (post) => {
    setEditingPost(post);
    setEditedContent(post.content || post.text || '');
  };

  const handleSavePostEdit = async () => {
    if (!editingPost || !editedContent.trim()) return;
    setIsSubmittingEdit(true);
    try {
      if (editingPost.isAnonymous) {
        const targetColl = editingPost.isConfession ? 'confessions' : 'anonymousPosts';
        await updateDoc(doc(db, targetColl, editingPost.id), {
          text: editedContent.trim()
        });
        setUserAnonPosts(prev => prev.map(p => p.id === editingPost.id ? { ...p, text: editedContent.trim() } : p));
      } else {
        const postRef = doc(db, 'posts', editingPost.id);
        await updateDoc(postRef, {
          content: editedContent.trim(),
          updatedAt: new Date()
        });
        setUserPosts(prev => prev.map(p => p.id === editingPost.id ? { ...p, content: editedContent.trim() } : p));
      }

      showSuccess('Post updated successfully!');
      setEditingPost(null);
    } catch (err) {
      console.error('Failed to update post:', err);
    } finally {
      setIsSubmittingEdit(false);
    }
  };

  const [deletingPost, setDeletingPost] = useState(null);

  const confirmDeleteProfilePost = async () => {
    if (!deletingPost) return;
    try {
      const postId = typeof deletingPost === 'string' ? deletingPost : deletingPost.id;
      if (deletingPost.isAnonymous) {
        const targetColl = deletingPost.isConfession ? 'confessions' : 'anonymousPosts';
        await deleteDoc(doc(db, targetColl, postId));
        setUserAnonPosts(prev => prev.filter(p => p.id !== postId));
      } else {
        await deleteDoc(doc(db, 'posts', postId));
        if (deletingPost.isReshare && deletingPost.originalPostId) {
          try {
            const origPostRef = doc(db, 'posts', deletingPost.originalPostId);
            await updateDoc(origPostRef, {
              reposts: increment(-1)
            });
          } catch (e) {
            console.error('Failed to decrement original post repost count:', e);
          }
        }
        setUserPosts(prev => prev.filter(p => p.id !== postId));
      }

      showSuccess('Post deleted successfully!');
      setDeletingPost(null);
    } catch (err) {
      console.error('Failed to delete post:', err);
    }
  };

  // Marketplace Edit / Delete Handlers in Profile
  const handleMarketplaceImageUpload = async (file) => {
    if (!file || !editingMarketplaceItem) return;
    setImageUploading(true);
    try {
      let finalUrl = '';
      try {
        finalUrl = await uploadImageToCloudinary(file);
      } catch (err) {
        finalUrl = await compressImage(file);
      }
      setEditingMarketplaceItem(prev => ({ ...prev, imageUrl: finalUrl }));
    } catch (err) {
      console.error('Failed to upload marketplace image:', err);
    } finally {
      setImageUploading(false);
    }
  };

  const handleSaveMarketplaceEdit = async (e) => {
    e.preventDefault();
    if (!editingMarketplaceItem || !editingMarketplaceItem.name?.trim() || !editingMarketplaceItem.price) return;
    try {
      const updatedFields = {
        name: editingMarketplaceItem.name.trim(),
        price: Number(editingMarketplaceItem.price),
        category: editingMarketplaceItem.category,
        condition: editingMarketplaceItem.condition,
        age: editingMarketplaceItem.age.trim(),
        desc: editingMarketplaceItem.desc.trim(),
        imageUrl: editingMarketplaceItem.imageUrl || '',
        updatedAt: new Date().toISOString()
      };
      await updateDoc(doc(db, 'marketplace', editingMarketplaceItem.id), updatedFields);
      setUserMarketplaceItems(prev => prev.map(item => item.id === editingMarketplaceItem.id ? { ...item, ...updatedFields } : item));
      showSuccess(`Updated listing for "${editingMarketplaceItem.name}"!`);
      setEditingMarketplaceItem(null);
    } catch (err) {
      console.error('Failed to update marketplace listing:', err);
    }
  };

  const confirmDeleteMarketplaceItem = async () => {
    if (!deletingMarketplaceItem) return;
    try {
      await deleteDoc(doc(db, 'marketplace', deletingMarketplaceItem.id));
      setUserMarketplaceItems(prev => prev.filter(item => item.id !== deletingMarketplaceItem.id));
      showSuccess(`Deleted listing for "${deletingMarketplaceItem.name}"!`);
      setDeletingMarketplaceItem(null);
    } catch (err) {
      console.error('Failed to delete marketplace listing:', err);
    }
  };

  // Check if viewing own profile or another student
  const hasTarget = Boolean(targetUid || targetName);
  const isOfficialLoggedIn =
    (currentUser?.username || '').toLowerCase() === 'cohort' ||
    (currentUser?.name || '').toLowerCase() === 'cohort' ||
    currentUser?.isOfficial === true ||
    currentUser?.uid === 'cohort_official';

  const isOwnProfile = !hasTarget ||
    (targetUid && (targetUid === currentUser?.uid || (isOfficialLoggedIn && targetUid === 'cohort_official'))) ||
    (targetName && targetName.toLowerCase() === currentUser?.name?.toLowerCase());

  // Load Profile data directly from Firestore
  useEffect(() => {
    const loadProfile = async () => {
      if (!profileUser) {
        setLoading(true);
      }
      try {
        let activeProfile = null;

        // First: check if the target UID itself points to a cohort-named account
        let targetData = null;
        if (targetUid && targetUid !== 'cohort_official') {
          const preCheck = await getDoc(doc(db, 'users', targetUid));
          if (preCheck.exists()) {
            targetData = preCheck.data();
          }
        }

        const isCohortTarget =
          targetUid === 'cohort_official' ||
          (targetName || '').toLowerCase() === 'cohort' ||
          (isOwnProfile && isOfficialLoggedIn) ||
          (targetData?.username || '').toLowerCase() === 'cohort' ||
          (targetData?.name || '').toLowerCase() === 'cohort' ||
          targetData?.isOfficial === true;

        if (isCohortTarget) {
          const cohortDocRef = doc(db, 'users', 'cohort_official');
          const cohortSnap = await getDoc(cohortDocRef);
          if (cohortSnap.exists()) {
            activeProfile = { uid: 'cohort_official', id: 'cohort_official', ...cohortSnap.data() };
          } else {
            activeProfile = {
              uid: 'cohort_official',
              id: 'cohort_official',
              name: 'Cohort',
              username: 'cohort',
              email: 'cohort@official.com',
              college: 'Cohort Official Platform',
              isOfficial: true,
              bio: 'The official Cohort platform account. Connecting students across campuses. Follow for official feature updates, campus drops, and 24/7 support.',
              followers: [],
              following: [],
              avatar: 'https://ui-avatars.com/api/?name=Cohort&background=9333ea&color=fff&bold=true&size=128',
              joinedDate: new Date().toISOString()
            };
          }
        } else if (isOwnProfile) {
          activeProfile = currentUser;
        } else {
            if (targetUid) {
              // Fetch target user by UID
              const docRef = doc(db, 'users', targetUid);
              const docSnap = await getDoc(docRef);
              if (docSnap.exists()) {
                activeProfile = { uid: targetUid, id: targetUid, ...docSnap.data() };
              }
            }

            if (!activeProfile && targetName) {
              // Fetch target user by Name
              const q = query(collection(db, 'users'), where('name', '==', targetName));
              const querySnapshot = await getDocs(q);
              querySnapshot.forEach(d => {
                activeProfile = { uid: d.id, id: d.id, ...d.data() };
              });
            }

            if (!activeProfile && (targetUid || targetName)) {
              // Create fallback profile so actions like follow/message work seamlessly
              const fallbackId = targetUid || `user_${Date.now()}`;
              const fallbackName = targetName || 'Kushal';
              activeProfile = {
                uid: fallbackId,
                id: fallbackId,
                name: fallbackName,
                username: fallbackName.toLowerCase().replace(/\s+/g, ''),
                college: 'KIET',
                followers: [],
                following: [],
                joinedDate: new Date().toISOString()
              };
            }
          }

        setProfileUser(activeProfile);

        const activeUid = activeProfile?.uid || activeProfile?.id || targetUid || currentUser?.uid;
        if (activeUid && activeUid !== 'cohort_official') {
          onSnapshot(doc(db, 'users', activeUid), (snap) => {
            if (snap.exists()) {
              setProfileUser(prev => ({ ...prev, ...snap.data() }));
            }
          });
        }

        if (activeProfile) {
          const currentUid = activeProfile.uid || activeProfile.id || targetUid || currentUser?.uid;
          const currentName = activeProfile.name || targetName || currentUser?.name;
          const currentUsername = activeProfile.username || currentUser?.username || (targetUsername ? targetUsername.replace('@', '') : null);
          const currentEmail = activeProfile.email || currentUser?.email;

          const cleanStr = (s) => (s || '').toString().toLowerCase().replace(/[^a-z0-9]/g, '');

          const getTokens = (str) => (str || '').toLowerCase().replace(/[^a-z0-9]/g, ' ').split(/\s+/).filter(t => t.length >= 3);
          const hasTokenMatch = (strA, strB) => {
            const tokensA = getTokens(strA);
            const tokensB = getTokens(strB);
            return tokensA.some(t => tokensB.includes(t));
          };

          const currentNameClean = cleanStr(currentName || currentUser?.name);
          const currentUsernameClean = cleanStr(currentUsername || currentUser?.username);
          const currentEmailClean = cleanStr(currentEmail || currentUser?.email);

          // 1. Real-time listener for Feed Posts authored by this user
          onSnapshot(collection(db, 'posts'), (querySnapshot) => {
            const loaded = [];
            querySnapshot.forEach((docSnap) => {
              const data = docSnap.data();

              const postAuthorUid = data.author?.uid || data.authorUid || data.uid || data.userUid || data.resharedBy?.uid;
              const authorNameStr = typeof data.author === 'string' ? data.author : (data.author?.name || data.authorName || data.resharedBy?.name || '');
              const authorUsernameStr = data.author?.username || data.authorUsername || data.resharedBy?.username || '';
              const authorEmailStr = data.author?.email || data.authorEmail || '';

              const postAuthorNameClean = cleanStr(authorNameStr);
              const postAuthorUsernameClean = cleanStr(authorUsernameStr);
              const postAuthorEmailClean = cleanStr(authorEmailStr);

              const isMatch =
                (currentUid && postAuthorUid === currentUid) ||
                (currentUser?.uid && postAuthorUid === currentUser.uid) ||
                (currentNameClean && (postAuthorNameClean === currentNameClean || postAuthorUsernameClean === currentNameClean)) ||
                (currentUsernameClean && (postAuthorNameClean === currentUsernameClean || postAuthorUsernameClean === currentUsernameClean)) ||
                (currentEmailClean && postAuthorEmailClean && postAuthorEmailClean === currentEmailClean) ||
                hasTokenMatch(authorNameStr, currentName) ||
                hasTokenMatch(authorNameStr, currentUsername) ||
                hasTokenMatch(authorUsernameStr, currentName) ||
                hasTokenMatch(authorUsernameStr, currentUsername) ||
                (isOwnProfile && (
                  hasTokenMatch(authorNameStr, currentUser?.name) ||
                  hasTokenMatch(authorNameStr, currentUser?.username) ||
                  hasTokenMatch(authorUsernameStr, currentUser?.name) ||
                  hasTokenMatch(authorUsernameStr, currentUser?.username)
                ));

              if (isMatch) {
                const likedUsers = data.likedUsers || data.upvotedUsers || data.likedBy || (Array.isArray(data.likes) ? data.likes : []);
                const likesCount = (typeof data.likes === 'number' && data.likes > 0)
                  ? data.likes
                  : (typeof data.upvotes === 'number' && data.upvotes > 0
                    ? data.upvotes
                    : (data.likesCount || likedUsers.length));
                let commentsCount = (typeof data.comments === 'number' && data.comments > 0)
                  ? data.comments
                  : (data.commentsCount || (Array.isArray(data.comments) ? data.comments.length : 0));

                loaded.push({
                  id: docSnap.id,
                  docId: docSnap.id,
                  collectionName: 'posts',
                  ...data,
                  likedUsers,
                  likesCount,
                  commentsCount,
                  timestamp: data.timestamp?.toDate ? data.timestamp.toDate() : new Date(data.timestamp || Date.now())
                });
              }
            });

            loaded.sort((a, b) => (b.timestamp?.getTime ? b.timestamp.getTime() : 0) - (a.timestamp?.getTime ? a.timestamp.getTime() : 0));
            setUserPosts(loaded);
            const likesSum = loaded.reduce((acc, curr) => acc + (curr.likesCount || 0), 0);
            setTotalLikes(likesSum);
          });

          // 2. Real-time listener for Anonymous Posts & Confessions authored by this user
          let rawAnonPosts = [];
          let rawConfessions = [];
          const updateAnonState = () => {
            const combined = [...rawAnonPosts, ...rawConfessions];
            combined.sort((a, b) => (b.createdAt?.getTime ? b.createdAt.getTime() : 0) - (a.createdAt?.getTime ? a.createdAt.getTime() : 0));
            setUserAnonPosts(combined);
          };

          onSnapshot(collection(db, 'anonymousPosts'), (snap) => {
            const loaded = [];
            snap.forEach((d) => {
              const data = d.data();
              const postAuthorUid = data.authorUid || data.uid || data.userUid || data.author?.uid;
              const postAuthorNameClean = cleanStr(data.anonymousName || data.authorName || data.author?.name);

              const isMatch =
                (currentUid && postAuthorUid === currentUid) ||
                (currentUser?.uid && postAuthorUid === currentUser.uid) ||
                (currentNameClean && postAuthorNameClean === currentNameClean) ||
                (currentUsernameClean && postAuthorNameClean === currentUsernameClean) ||
                hasTokenMatch(data.anonymousName, currentName) ||
                hasTokenMatch(data.anonymousName, currentUsername);

              if (isMatch) {
                const likedUsers = data.likedUsers || data.upvotedUsers || data.likedBy || (Array.isArray(data.likes) ? data.likes : []);
                const likesCount = (typeof data.likes === 'number' && data.likes > 0)
                  ? data.likes
                  : (typeof data.upvotes === 'number' && data.upvotes > 0
                    ? data.upvotes
                    : (data.likesCount || likedUsers.length));
                let commentsCount = (typeof data.comments === 'number' && data.comments > 0)
                  ? data.comments
                  : (data.commentsCount || (Array.isArray(data.comments) ? data.comments.length : 0));

                loaded.push({
                  id: d.id,
                  docId: d.id,
                  collectionName: 'anonymousPosts',
                  isAnonymous: true,
                  isConfession: false,
                  ...data,
                  likedUsers,
                  likesCount,
                  commentsCount,
                  createdAt: data.createdAt?.toDate ? data.createdAt.toDate() : new Date(data.createdAt || Date.now())
                });
              }
            });
            rawAnonPosts = loaded;
            updateAnonState();
          });

          onSnapshot(collection(db, 'confessions'), (snap) => {
            const loaded = [];
            snap.forEach((d) => {
              const data = d.data();
              const postAuthorUid = data.authorUid || data.uid || data.userUid || data.author?.uid;
              const postAuthorNameClean = cleanStr(data.anonymousName || data.authorName || data.author?.name);

              const isMatch =
                (currentUid && postAuthorUid === currentUid) ||
                (currentUser?.uid && postAuthorUid === currentUser.uid) ||
                (currentNameClean && postAuthorNameClean === currentNameClean) ||
                (currentUsernameClean && postAuthorNameClean === currentUsernameClean) ||
                hasTokenMatch(data.anonymousName, currentName) ||
                hasTokenMatch(data.anonymousName, currentUsername);

              if (isMatch) {
                const likedUsers = data.likedUsers || data.upvotedUsers || data.likedBy || (Array.isArray(data.likes) ? data.likes : []);
                const likesCount = (typeof data.likes === 'number' && data.likes > 0)
                  ? data.likes
                  : (typeof data.upvotes === 'number' && data.upvotes > 0
                    ? data.upvotes
                    : (data.likesCount || likedUsers.length));
                let commentsCount = (typeof data.comments === 'number' && data.comments > 0)
                  ? data.comments
                  : (data.commentsCount || (Array.isArray(data.comments) ? data.comments.length : 0));

                loaded.push({
                  id: d.id,
                  docId: d.id,
                  collectionName: 'confessions',
                  isAnonymous: true,
                  isConfession: true,
                  ...data,
                  likedUsers,
                  likesCount,
                  commentsCount,
