                  { label: '10 Min', sec: 600 },
                  { label: '30 Min', sec: 1800 },
                  { label: '1 Hour', sec: 3600 },
                  { label: '6 Hours', sec: 21600 },
                  { label: '12 Hours', sec: 43200 },
                  { label: '24 Hours', sec: 86400 },
                  { label: '3 Days', sec: 259200 },
                  { label: '7 Days', sec: 604800 },
