                <Star className="w-3.5 h-3.5 fill-amber-400" />
                <span>Starred</span>
                <span className="px-1.5 py-[1px] text-[10px] bg-amber-500/20 rounded-full font-bold">
                  {allStarredCommunityMsgs.length}
                </span>
