                      );
                    })}
              </div>

              {/* Chat Input Bar */}
              <div className="flex-shrink-0 z-30 bg-white dark:bg-neutral-900 border-t border-neutral-100 dark:border-neutral-800 p-2 sm:p-3 shadow-lg w-full max-w-full min-w-0 overflow-hidden">
