                    </div>
                  </div>
                )}
                {attachedGroupFile && (
                  <div className="bg-primary-50 dark:bg-primary-950/20 border border-primary-200 dark:border-primary-800 rounded-lg p-sm flex justify-between items-center text-xs mb-xs">
