                  onClick={() => { showSuccess('Post reported to campus moderators.'); setShowPostMenu(false); }}
                  className="w-full px-md py-2 text-left hover:bg-neutral-100 dark:hover:bg-neutral-700 text-neutral-500 font-medium"
                >
                  Report Post
                </button>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Reshared By Header Strip */}
      {post.isReshare && (
        <div className="flex items-center gap-2 text-xs font-semibold text-neutral-500 dark:text-neutral-400 mb-sm pb-xs border-b border-neutral-100 dark:border-neutral-800">
          <Repeat className="w-3.5 h-3.5 text-primary-500" />
          <span>
            Reshared by{' '}
            <strong
              onClick={() => handleOpenAuthorProfile(post.resharedBy?.uid || post.author?.uid, post.resharedBy?.name || post.author?.name)}
              className="text-neutral-800 dark:text-neutral-200 font-bold hover:underline cursor-pointer"
            >
              {post.resharedBy?.name || post.author?.name || 'Student'}
            </strong>
          </span>
          <span>•</span>
          <span className="text-[11px] text-neutral-400">{formatRelativeTime(post.timestamp)}</span>
        </div>
      )}

      {/* Content / Thoughts */}
      {isEditingPost ? (
        <div className="mb-xl space-y-sm">
          <MentionTextArea
            value={editPostContent}
            onChange={(e) => setEditPostContent(e.target.value)}
            className="w-full p-md bg-neutral-50 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl text-sm outline-none focus:ring-2 focus:ring-primary-500 text-neutral-900 dark:text-white leading-relaxed resize-none"
            rows={3}
            placeholder="Edit your post content (type @ to tag a peer)..."
          />
          <div className="flex items-center justify-end gap-md">
            <button
              type="button"
              onClick={() => setIsEditingPost(false)}
              className="px-md py-xs text-xs font-semibold text-neutral-500 hover:text-neutral-700 dark:hover:text-white"
            >
              Cancel
            </button>
            <button
              type="button"
              onClick={handleSaveInlineEdit}
              className="px-md py-xs text-xs font-bold bg-primary-500 text-white rounded-lg hover:bg-primary-600 transition-colors"
            >
              Save Changes
            </button>
          </div>
        </div>
      ) : (
        <>
          {post.thought && (
            <p className="text-neutral-800 dark:text-neutral-200 mb-md leading-relaxed text-base font-normal">
              {post.thought}
            </p>
          )}

          {post.isReshare ? (
            /* Embedded Original Post Card */
            <div
              onClick={() => {
                const rootId = post.originalPostId || post.id;
                navigate(`/home#post-${rootId}`);
              }}
              className="border border-neutral-200 dark:border-neutral-700/80 rounded-2xl p-md sm:p-lg bg-neutral-50/60 dark:bg-neutral-800/40 hover:border-primary-500/40 transition-all cursor-pointer space-y-sm mb-lg shadow-2xs group/embedded"
            >
              <div className="flex items-center gap-md">
                <img
                  src={post.originalPost?.author?.avatar || post.author?.avatar || 'https://api.dicebear.com/7.x/avataaars/svg?seed=user'}
                  alt={post.originalPost?.author?.name || post.author?.name || 'Student'}
                  className="w-9 h-9 rounded-full object-cover border border-neutral-200 dark:border-neutral-700"
                />
                <div>
                  <h4 className="font-bold text-xs text-neutral-900 dark:text-white group-hover/embedded:text-primary-500 transition-colors">
                    {post.originalPost?.author?.name || post.author?.name || 'Student'}
                  </h4>
                  <p className="text-[10px] text-neutral-500 dark:text-neutral-400">
                    {post.originalPost?.author?.role || post.originalPost?.author?.college || 'KIET'} • {formatRelativeTime(post.originalPost?.timestamp || post.timestamp)}
                  </p>
                </div>
              </div>
              <ExpandableCaption
                text={post.originalPost?.content || post.content}
                className="pt-xs text-sm"
              />
            </div>
          ) : (
            <ExpandableCaption
              text={post.content}
              className="mb-xl text-base"
            />
          )}
        </>
      )}

      {post.imageUrl && (
        <div className="mb-xl rounded-2xl overflow-hidden border border-neutral-100 dark:border-neutral-800/80 bg-neutral-950/20 dark:bg-neutral-950/60 flex items-center justify-center">
          <img
            src={post.imageUrl}
            alt="Post attachment"
            className="w-full h-auto max-h-[700px] object-contain rounded-2xl transition-transform duration-300 hover:scale-[1.005]"
          />
        </div>
      )}

      {/* Interactive Post Poll */}
      {post.poll && (
        <div className="mb-xl p-4 rounded-2xl bg-neutral-50 dark:bg-neutral-900/80 border border-neutral-200/80 dark:border-neutral-800 space-y-3 shadow-xs">
          <h4 className="font-bold text-sm text-neutral-900 dark:text-neutral-100 flex items-center gap-2">
            <BarChart2 className="w-4 h-4 text-purple-500 flex-shrink-0" />
            <span>{post.poll.question}</span>
          </h4>
          <div className="space-y-2">
            {post.poll.options?.map((opt, idx) => {
              const total = post.poll.totalVotes || 0;
              const votes = opt.votes || 0;
              const pct = total > 0 ? Math.round((votes / total) * 100) : 0;
              const hasVoted = post.poll.votedUsers?.includes(user?.uid);
              const isMyChoice = post.poll.userChoices?.[user?.uid] === idx;
              const voterDetails = opt.votedUserDetails || (post.poll.votedUsers || []).map(uid => ({
                uid,
                name: (uid === user?.uid ? user?.name : 'Student'),
                avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${uid}`
              }));

              return (
                <button
                  key={idx}
                  type="button"
                  onClick={async () => {
                    if (!user?.uid || !post.docId) return;
                    const votedUsers = post.poll.votedUsers || [];
                    if (votedUsers.includes(user.uid)) return;

                    const myUserObj = {
                      uid: user.uid,
                      name: user.name || user.email?.split('@')[0] || 'Student',
                      avatar: user.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(user.email || 'user')}`
                    };

                    const updatedOptions = post.poll.options.map((o, i) => {
                      if (i === idx) {
                        const currentDetails = Array.isArray(o.votedUserDetails) ? o.votedUserDetails : [];
                        return {
                          ...o,
                          votes: (o.votes || 0) + 1,
                          votedUserDetails: [...currentDetails, myUserObj]
                        };
                      }
                      return o;
                    });

                    const updatedPoll = {
                      ...post.poll,
                      totalVotes: (post.poll.totalVotes || 0) + 1,
                      options: updatedOptions,
                      votedUsers: [...votedUsers, user.uid],
                      userChoices: { ...(post.poll.userChoices || {}), [user.uid]: idx }
                    };

                    try {
                      await updateDoc(doc(db, 'posts', post.docId), { poll: updatedPoll });
                      showSuccess('Vote recorded!');
                    } catch (e) {
                      console.error('Error voting on poll:', e);
                    }
                  }}
                  className={`w-full relative overflow-hidden rounded-xl p-3 text-left border transition-all cursor-pointer ${
                    isMyChoice
                      ? 'border-purple-500 bg-purple-500/10 text-purple-600 dark:text-purple-300 font-bold'
                      : 'border-neutral-200 dark:border-neutral-800 bg-white dark:bg-neutral-950 text-neutral-800 dark:text-neutral-200 hover:border-purple-500/40 font-medium'
                  }`}
                >
                  {hasVoted && (
                    <div
                      className="absolute inset-y-0 left-0 bg-purple-500/20 dark:bg-purple-500/30 transition-all duration-500"
                      style={{ width: `${pct}%` }}
                    />
                  )}
                  <div className="relative z-10 flex items-center justify-between text-xs sm:text-sm">
                    <span className="truncate pr-2">{opt.text}</span>
                    <div className="flex items-center gap-2 flex-shrink-0">
                      {voterDetails.length > 0 && (
                        <div className="flex items-center -space-x-1.5 overflow-hidden">
                          {voterDetails.slice(0, 3).map((voter, vIdx) => (
                            <img
                              key={vIdx}
                              src={voter.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${voter.name}`}
                              alt={voter.name}
                              title={voter.name}
                              className="w-4 h-4 rounded-full ring-1 ring-neutral-800 object-cover"
                            />
                          ))}
                        </div>
                      )}
                      {hasVoted && (
                        <span className="font-mono font-bold text-xs">
                          {pct}% ({votes})
                        </span>
                      )}
                    </div>
                  </div>
                </button>
              );
            })}
          </div>
          <div className="text-[11px] font-medium text-neutral-400 dark:text-neutral-500 flex items-center justify-between pt-1 border-t border-neutral-100 dark:border-neutral-800/80">
            <span>{post.poll.totalVotes || 0} votes</span>
            <div className="flex items-center gap-3">
              {post.poll.votedUsers?.includes(user?.uid) && (
                <span className="text-purple-500 dark:text-purple-400 font-semibold">✓ Voted</span>
              )}
              <button
                type="button"
                onClick={(e) => { e.stopPropagation(); setViewVotesPoll(post.poll); }}
                className="flex items-center gap-1 text-sky-400 font-bold hover:underline cursor-pointer"
              >
                <Users className="w-3.5 h-3.5" />
                <span>View Votes</span>
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Attached File/Document */}
      {post.attachedFile && (
        <div className="mb-xl p-3.5 rounded-2xl bg-neutral-50 dark:bg-neutral-900/90 border border-neutral-200/80 dark:border-neutral-800 flex items-center justify-between">
          <div className="flex items-center gap-3 min-w-0">
            <div className="w-10 h-10 rounded-xl bg-purple-500/10 text-purple-500 border border-purple-500/20 flex items-center justify-center flex-shrink-0">
              <FileText className="w-5 h-5" />
            </div>
            <div className="min-w-0">
              <p className="text-xs sm:text-sm font-bold text-neutral-900 dark:text-neutral-100 truncate">
                {post.attachedFile.name}
              </p>
              <p className="text-[11px] text-neutral-400 font-medium">
                {post.attachedFile.size || 'Attached document'}
              </p>
            </div>
          </div>
        </div>
      )}

      {/* Modern Pill Action Bar */}
      <div className="flex items-center gap-sm flex-wrap pt-xs">
        {/* Upvote / Downvote Pill showing separate Like & Dislike counts */}
        <div className="flex items-center rounded-full bg-neutral-100 dark:bg-neutral-800/90 border border-neutral-200/60 dark:border-neutral-700/60 p-1 text-xs font-bold shadow-xs">
          {/* Like / Upvote Button */}
          <button
            type="button"
            onClick={() => {
              onVote(post.id, 'up');
              const postAuthorUid = post.author?.uid || post.authorUid || post.uid;
              if (postAuthorUid && postAuthorUid !== user?.uid && userVote !== 'up') {
                createNotification({
                  recipientUid: postAuthorUid,
                  senderUid: user?.uid,
                  senderName: user?.name || 'Student',
                  senderAvatar: user?.avatar,
                  type: 'like',
                  text: 'liked your post.',
                  postId: post.docId || post.id
                });
              }
            }}
            className={`flex items-center gap-1.5 px-3 py-1 rounded-full transition-all cursor-pointer ${
              userVote === 'up'
                ? 'bg-orange-500 text-white font-extrabold shadow-sm'
                : 'text-neutral-700 dark:text-neutral-300 hover:bg-neutral-200/70 dark:hover:bg-neutral-700/70 hover:text-orange-500'
            }`}
            title="Like / Upvote"
          >
            <ArrowUp className={`w-4 h-4 ${userVote === 'up' ? 'stroke-[2.5]' : ''}`} />
            <span>{upvotesCount}</span>
          </button>

          {/* Vertical Divider */}
          <div className="w-px h-3.5 bg-neutral-300 dark:bg-neutral-700 mx-1" />

          {/* Dislike / Downvote Button */}
          <button
            type="button"
            onClick={() => onVote(post.id, 'down')}
            className={`flex items-center gap-1.5 px-3 py-1 rounded-full transition-all cursor-pointer ${
              userVote === 'down'
                ? 'bg-rose-500 text-white font-extrabold shadow-sm'
                : 'text-neutral-700 dark:text-neutral-300 hover:bg-neutral-200/70 dark:hover:bg-neutral-700/70 hover:text-rose-500'
            }`}
            title="Dislike / Downvote"
          >
            <ArrowDown className={`w-4 h-4 ${userVote === 'down' ? 'stroke-[2.5]' : ''}`} />
            <span>{downvotesCount}</span>
          </button>
        </div>

        {/* Reply Pill */}
        <button
          onClick={() => setShowComments(!showComments)}
          className={`flex items-center gap-xs px-lg py-sm rounded-full text-xs font-semibold border transition-all ${
            showComments
              ? 'bg-primary-500 text-white border-primary-600'
