function SEO({ title, description, image, type = 'website', noindex = false }) {
  const location = useLocation();

  // Enforce cohortnow.online as the preferred canonical domain
  const canonicalUrl = `https://www.cohortnow.online${location.pathname}`;

  useEffect(() => {
    // Helper utility to safely manage meta elements
    const updateMetaTag = (attribute, value, content) => {
      let element = document.querySelector(`meta[${attribute}="${value}"]`);
      if (!element) {
        element = document.createElement('meta');
        element.setAttribute(attribute, value);
        document.head.appendChild(element);
      }
      element.setAttribute('content', content);
    };

    // Helper utility to safely manage link elements
    const updateLinkTag = (rel, href) => {
      let element = document.querySelector(`link[rel="${rel}"]`);
      if (!element) {
        element = document.createElement('link');
        element.setAttribute('rel', rel);
        document.head.appendChild(element);
      }
      element.setAttribute('href', href);
    };

    // 1. Update document title (only when provided or on homepage)
    if (title || location.pathname === '/') {
      const defaultTitle = 'Cohort - Your Campus Social Media';
      const formattedTitle = title ? `${title} | Cohort` : defaultTitle;
      const finalTitle = location.pathname === '/' ? defaultTitle : formattedTitle;
      document.title = finalTitle;

      updateMetaTag('property', 'og:title', finalTitle);
      updateMetaTag('name', 'twitter:title', finalTitle);
    }

    // 2. Robots Indexing (Noindex private routes to protect sensitive student dashboard spaces)
    if (noindex) {
      updateMetaTag('name', 'robots', 'noindex, nofollow');
    } else {
      updateMetaTag('name', 'robots', 'index, follow');
    }

    // 3. Update description (only when provided or on homepage)
    if (description || location.pathname === '/') {
      const defaultDesc = 'Cohort is the social media for campus. A student community platform connecting college students with their campus communities, events, confessions, gossip, making friends, anonymous talks, and unfiltered takes.';
      const finalDesc = description || defaultDesc;
      updateMetaTag('name', 'description', finalDesc);
      updateMetaTag('property', 'og:description', finalDesc);
      updateMetaTag('name', 'twitter:description', finalDesc);
    }

    // 4. Update Canonical Link
    updateLinkTag('canonical', canonicalUrl);

    // 5. Open Graph Meta Tags
    updateMetaTag('property', 'og:url', canonicalUrl);
    updateMetaTag('property', 'og:type', type);
    updateMetaTag('property', 'og:site_name', 'Cohort');

    const defaultImage = 'https://cohortnow.online/og-image.png';
    const finalImage = image || defaultImage;
    updateMetaTag('property', 'og:image', finalImage);

    // 6. Twitter Card Meta Tags
    updateMetaTag('name', 'twitter:card', 'summary_large_image');
    updateMetaTag('name', 'twitter:image', finalImage);

  }, [title, description, image, type, noindex, location.pathname, canonicalUrl]);

  return null;
}

const useNotification = () => {
  const context = useContext(NotificationContext);
  if (!context) throw new Error('useNotification must be used within NotificationProvider');
  return context;
};

function Notifications() {
  const { showSuccess } = useNotification();
  const { user } = useAuth();
  const navigate = useNavigate();
  const [list, setList] = useState([]);
  const [filter, setFilter] = useState('All');
  const [loading, setLoading] = useState(true);

  // Real-time Firestore Listener for User Notifications
  useEffect(() => {
    if (!user?.uid) {
      setLoading(false);
      return;
    }

    const parseNotifTime = (data) => {
      if (data.time?.toDate) return data.time.toDate();
      if (data.time) {
        const d = new Date(data.time);
        if (!isNaN(d.getTime())) return d;
      }
      if (data.createdAt) {
        const d = new Date(data.createdAt);
        if (!isNaN(d.getTime())) return d;
      }
      return new Date();
    };

    setLoading(true);
    const unsub = onSnapshot(collection(db, 'notifications'), (snapshot) => {
      const loaded = [];
      const unreadDocsToMark = [];

      snapshot.forEach(d => {
        const data = d.data();
        const isForMe = !data.recipientUid || data.recipientUid === user.uid || data.recipientUid === 'all';
        if (isForMe) {
          const notifTime = parseNotifTime(data);
          loaded.push({
            id: d.id,
            docId: d.id,
            ...data,
            time: notifTime
          });
          if (!data.read) {
            unreadDocsToMark.push(d.id);
          }
        }
      });

      loaded.sort((a, b) => b.time - a.time);
      setList(loaded);
      setLoading(false);

      // Automatically mark unread notifications as read upon opening the Notifications page
      if (unreadDocsToMark.length > 0) {
        const batch = writeBatch(db);
        unreadDocsToMark.forEach(docId => {
          batch.update(doc(db, 'notifications', docId), { read: true });
        });
        batch.commit().catch(e => console.error('Failed auto-marking notifications as read:', e));
      }
    }, (err) => {
      console.error('Error listening to notifications:', err);
      setLoading(false);
    });

    return () => unsub();
  }, [user?.uid]);

  const handleMarkAsRead = async (id) => {
    setList(prev => prev.map(notif => {
      if (notif.id === id) return { ...notif, read: true };
      return notif;
    }));

    const target = list.find(n => n.id === id);
    if (target && target.docId) {
      try {
        const docRef = doc(db, 'notifications', target.docId);
        await updateDoc(docRef, { read: true });
      } catch (e) {
        console.error('Failed to update read status:', e);
      }
    }
  };

  const handleNotificationClick = (notif) => {
    handleMarkAsRead(notif.id);

    // 1. Post or Comment related notifications
    if (notif.postId) {
      const isCommentNotif =
        notif.type === 'reply' ||
        Boolean(notif.commentId) ||
        (notif.text && (notif.text.toLowerCase().includes('comment') || notif.text.toLowerCase().includes('replied')));

      if (isCommentNotif) {
        navigate(`/home?post=${notif.postId}&openComments=true${notif.commentId ? `&comment=${notif.commentId}` : ''}`);
      } else {
        navigate(`/home?post=${notif.postId}`);
      }
      return;
    }

    // 2. Make-a-friend swipes
    if (notif.text && notif.text.toLowerCase().includes('swiped')) {
      navigate('/make-friend');
      return;
    }

    // 3. Community invitations
    if (notif.type === 'community_invite' || notif.communityId) {
      navigate('/community');
      return;
    }

    // 4. Follow alerts
    if (notif.type === 'follow' && notif.senderUid) {
      navigate(`/profile?uid=${notif.senderUid}`);
      return;
    }

    // 5. Custom link if specified
    if (notif.link) {
      navigate(notif.link);
      return;
    }

    // 6. User profile fallback
    if (notif.senderUid) {
      navigate(`/profile?uid=${notif.senderUid}`);
      return;
    }

    // 7. Fallback to main home feed
    navigate('/home');
  };

  const handleMarkAllRead = async () => {
    setList(prev => prev.map(notif => ({ ...notif, read: true })));
    showSuccess('All notifications marked as read.');

    const batch = writeBatch(db);
    list.forEach(n => {
      if (n.docId && !n.read) {
        const docRef = doc(db, 'notifications', n.docId);
        batch.update(docRef, { read: true });
      }
    });
    try {
      await batch.commit();
    } catch (e) {
      console.error('Failed to update all statuses in Firestore:', e);
    }
  };

  const handleDelete = async (e, id) => {
    e.stopPropagation();
    setList(prev => prev.filter(notif => notif.id !== id));
    showSuccess('Notification deleted.');

    const target = list.find(n => n.id === id);
