      const timer = setTimeout(() => {
        setHighlightedPostId(null);
      }, 3000);

      const scrollTimer = setTimeout(() => {
        const el = document.getElementById(`post-${targetPostId}`);
        if (el) {
          el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 200);

      return () => {
        clearTimeout(timer);
        clearTimeout(scrollTimer);
      };
    }
  }, [targetPostId, posts]);

  // Image & Attachment Upload States
  const [imageFile, setImageFile] = useState(null);
  const [imagePreviewUrl, setImagePreviewUrl] = useState(null);
  const [isUploading, setIsUploading] = useState(false);
  const imageInputRef = useRef(null);
  const cameraInputRef = useRef(null);
  const documentInputRef = useRef(null);

  // Document Attachment State
  const [documentFile, setDocumentFile] = useState(null);

  // Poll Creation State
  const [showPollCreator, setShowPollCreator] = useState(false);
  const [pollQuestion, setPollQuestion] = useState('');
  const [pollOptions, setPollOptions] = useState(['', '']);


  // Pinned Daily Poll State
  const [selectedHomePollIndex, setSelectedHomePollIndex] = useState(() => {
    try {
      const saved = localStorage.getItem('cohort_home_poll_selected');
      return saved !== null ? Number(saved) : null;
    } catch (e) {
      return null;
    }
  });

  const [homePollVotes, setHomePollVotes] = useState(() => {
    try {
      const saved = localStorage.getItem('cohort_home_poll_votes');
      return saved ? JSON.parse(saved) : [
        { label: 'Only if there is free double shot espresso', count: 84 },
        { label: 'Yes, sleep is for the weak', count: 36 },
        { label: 'I study CS. The sun is a myth.', count: 80 }
      ];
    } catch (e) {
      return [
        { label: 'Only if there is free double shot espresso', count: 84 },
        { label: 'Yes, sleep is for the weak', count: 36 },
        { label: 'I study CS. The sun is a myth.', count: 80 }
      ];
    }
  });

  const handleToggleHomePollVote = (index) => {
    setHomePollVotes(prev => {
      const updated = prev.map((opt, i) => {
        if (i === index) {
          const isRemoving = selectedHomePollIndex === index;
          return { ...opt, count: isRemoving ? Math.max(0, opt.count - 1) : opt.count + 1 };
        } else if (selectedHomePollIndex === i) {
          return { ...opt, count: Math.max(0, opt.count - 1) };
        }
        return opt;
      });
      try {
        localStorage.setItem('cohort_home_poll_votes', JSON.stringify(updated));
      } catch (e) {}
      return updated;
    });

    setSelectedHomePollIndex(prev => {
      const next = (prev === index ? null : index);
      try {
        if (next !== null) {
          localStorage.setItem('cohort_home_poll_selected', String(next));
        } else {
          localStorage.removeItem('cohort_home_poll_selected');
        }
      } catch (e) {}
      return next;
    });
  };

  const totalHomePollVotes = homePollVotes.reduce((acc, curr) => acc + curr.count, 0);

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setImageFile(file);
      setImagePreviewUrl(URL.createObjectURL(file));
    }
  };

  const handleRemoveImage = () => {
    setImageFile(null);
    if (imagePreviewUrl) {
      URL.revokeObjectURL(imagePreviewUrl);
      setImagePreviewUrl(null);
    }
    if (imageInputRef.current) {
      imageInputRef.current.value = '';
    }
  };

  // Subscribe to real-time posts from Firestore on mount
  useEffect(() => {
    setLoading(true);
    const q = query(collection(db, 'posts'), orderBy('timestamp', 'desc'));

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const loaded = [];
      snapshot.forEach((docSnap) => {
        const data = docSnap.data();
        const authorName = (data.author?.name || '').toLowerCase();
        const isFake = FAKE_NAMES.some(fake => authorName.includes(fake));

        if (isFake) {
          deleteDoc(doc(db, 'posts', docSnap.id)).catch(err => console.error('Purging fake post:', err));
        } else {
          loaded.push({
            id: docSnap.id,
            docId: docSnap.id,
            ...data,
            timestamp: data.timestamp?.toDate ? data.timestamp.toDate() : new Date(data.timestamp || Date.now())
          });
        }
      });

      setPosts(loaded);
      setLoading(false);
    }, (err) => {
      console.error('Real-time posts error:', err);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const handleDocumentChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setDocumentFile(file);
      showSuccess(`Attached document: ${file.name}`);
    }
  };

  const handleCreatePost = async () => {
    if (!postContent.trim() && !imageFile && !documentFile && (!pollQuestion.trim() || pollOptions.filter(o => o.trim()).length < 2)) return;

    setIsUploading(true);
    let uploadedImageUrl = null;

    try {
      if (imageFile) {
        uploadedImageUrl = await uploadImageToCloudinary(imageFile);
      }

      const validPollOptions = pollOptions.filter(o => o.trim() !== '');
      const hasValidPoll = pollQuestion.trim() !== '' && validPollOptions.length >= 2;

      const autoAudience = (feedType === 'college' || feedType === 'my_college') ? 'college_only' : 'public';

      const postData = {
        authorUid: user?.uid || null,
        college: user?.college || 'KIET',
        audience: autoAudience,
        visibility: autoAudience,
        author: {
          uid: user?.uid || null,
          username: user?.username || null,
          name: user?.name || 'Student',
          avatar: user?.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(user?.email || 'user')}`,
          role: user?.college || 'KIET',
          college: user?.college || 'KIET',
          email: user?.email || null,
        },
        content: postContent.trim(),
        imageUrl: uploadedImageUrl,
        timestamp: new Date(),
        upvotes: 0,
        downvotes: 0,
        upvotedUsers: [],
        downvotedUsers: [],
        comments: 0,
        reposts: 0,
        saved: false,
        ...(hasValidPoll ? {
          poll: {
            question: pollQuestion.trim(),
            options: validPollOptions.map(t => ({ text: t.trim(), votes: 0 })),
            totalVotes: 0,
            votedUsers: [],
            userChoices: {}
          }
        } : {}),
        ...(documentFile ? {
          attachedFile: {
            name: documentFile.name,
            size: `${(documentFile.size / 1024).toFixed(1)} KB`
          }
        } : {})
      };

      await addDoc(collection(db, 'posts'), postData);
      setPostContent('');
      handleRemoveImage();
      setDocumentFile(null);
      setShowPollCreator(false);
      setPollQuestion('');
      setPollOptions(['', '']);
      showSuccess('Post created successfully!');
    } catch (error) {
      console.error('Failed to create post in Firestore:', error);
      showError('Failed to upload attachment or create post. Please try again.');
    } finally {
      setIsUploading(false);
    }
  };


  const handleVote = async (postId, direction) => {
    const targetPost = posts.find(p => p.id === postId);
    if (!targetPost || !targetPost.docId) return;

    const myUid = user?.uid || 'guest';
    let upvoted = [...(targetPost.upvotedUsers || [])];
    let downvoted = [...(targetPost.downvotedUsers || [])];

    if (direction === 'up') {
      if (upvoted.includes(myUid)) {
        // Toggle off upvote
        upvoted = upvoted.filter(u => u !== myUid);
      } else {
        upvoted.push(myUid);
        downvoted = downvoted.filter(u => u !== myUid);
      }
    } else if (direction === 'down') {
      if (downvoted.includes(myUid)) {
        // Toggle off downvote
        downvoted = downvoted.filter(u => u !== myUid);
      } else {
        downvoted.push(myUid);
        upvoted = upvoted.filter(u => u !== myUid);
      }
    }

    const newUpvotesCount = upvoted.length;
    const newDownvotesCount = downvoted.length;

    // 1. Optimistic local state update (0ms UI latency)
    setPosts(prevPosts =>
      prevPosts.map(p =>
        p.id === postId
          ? {
              ...p,
              upvotes: newUpvotesCount,
              downvotes: newDownvotesCount,
              upvotedUsers: upvoted,
              downvotedUsers: downvoted
            }
          : p
      )
    );

    // 2. Firestore async persistence
    try {
      const docRef = doc(db, 'posts', targetPost.docId);
      await updateDoc(docRef, {
        upvotes: newUpvotesCount,
        downvotes: newDownvotesCount,
        upvotedUsers: upvoted,
        downvotedUsers: downvoted
      });
    } catch (error) {
      console.error('Failed to update votes in Firestore:', error);
    }
  };

  const handleRepost = async (postId) => {
    const targetPost = posts.find(p => p.id === postId);
    if (!targetPost || !targetPost.docId) return;

    const newRepostsCount = (targetPost.reposts || 0) + 1;
    showSuccess('Reposted to your feed!');

    try {
      const docRef = doc(db, 'posts', targetPost.docId);
      await updateDoc(docRef, {
        reposts: newRepostsCount
      });
    } catch (error) {
      console.error('Failed to update reposts in Firestore:', error);
    }
  };

  const handleSave = (postId) => {
    let nextSavedStatus = false;
    const updated = posts.map(post => {
      if (post.id === postId) {
        nextSavedStatus = !post.saved;
        return { ...post, saved: nextSavedStatus };
      }
      return post;
    });

    setPosts(updated);

    // Sync saved posts list in localStorage
    const savedItems = updated.filter(p => p.saved);
    localStorage.setItem('collex-saved-posts', JSON.stringify(savedItems));

    showSuccess(nextSavedStatus ? 'Post saved to bookmarks!' : 'Post removed from bookmarks!');
  };

  const userCollege = user?.college || 'KIET';
  const displayedPosts = posts.filter(post => {
    const isTarget = (post.id === targetPostId || post.docId === targetPostId);
    if (isTarget) return true;

    const postCollege = post.college || post.author?.college || post.author?.role;
    const cleanPost = postCollege ? String(postCollege).toLowerCase().trim() : '';
    const cleanUser = String(userCollege).toLowerCase().trim();
    const isSameCollege = cleanPost && (cleanPost.includes(cleanUser) || cleanUser.includes(cleanPost));
    const isMyPost = (post.authorUid || post.author?.uid) === user?.uid;

    const isCollegeOnlyPost = post.audience === 'college_only' || post.visibility === 'college_only';

    // 1. Public Feed: strictly show ONLY public posts (exclude college-only posts)
    if (feedType === 'public') {
      return !isCollegeOnlyPost;
    }

    // 2. My College Feed: strictly show ONLY college-only posts from user's college (or user's own college posts)
    return isCollegeOnlyPost && (isSameCollege || isMyPost);
  });

  return (
    <div className="section-container !py-6 !px-4 xl:!px-6">
      <SEO title="Campus Feed" />
      {/* Desktop: 2-column layout (feed + right panel) | Mobile: single column */}
      <div className="flex gap-6 items-start w-full max-w-[1100px] ml-auto mr-2 xl:mr-4">
        {/* Main Feed Column */}
        <div className="flex-1 min-w-0 max-w-2xl">
          {/* Feed Switcher (Public vs My College) */}
          <FeedToggle
            activeFeed={feedType}
            onChangeFeed={setFeedType}
            userCollege={userCollege}
          />

          {/* Create Post */}
          <div className="mb-lg p-4 sm:p-5 rounded-3xl bg-white/90 dark:bg-neutral-900/90 backdrop-blur-xl border border-neutral-200/80 dark:border-neutral-800/80 shadow-lg shadow-black/5 dark:shadow-black/30 transition-all">
            {feedType === 'college' && !user?.kycVerified ? (
              <div className="flex flex-col items-center text-center py-4 px-2 space-y-4">
                <div className="w-12 h-12 rounded-2xl bg-amber-500/10 dark:bg-amber-500/20 text-amber-500 flex items-center justify-center border border-amber-500/20 shadow-xs">
                  <ShieldAlert className="w-6 h-6 text-amber-500" />
                </div>
                <div className="space-y-1">
                  <h4 className="text-sm font-extrabold text-neutral-900 dark:text-white">
                    College Wall Restricted
                  </h4>
                  <p className="text-xs text-neutral-500 dark:text-neutral-400 max-w-sm leading-relaxed">
                    Only verified students of <strong className="text-neutral-900 dark:text-white font-bold">{userCollege}</strong> can post here. Verify your student email to join the conversation.
                  </p>
                </div>
                <button
                  type="button"
                  onClick={openKycModal}
                  className="px-6 py-2.5 rounded-full bg-gradient-to-r from-violet-600 to-indigo-600 hover:from-violet-500 hover:to-indigo-500 text-white font-extrabold text-xs shadow-md transition-all active:scale-95 cursor-pointer uppercase tracking-wider"
                >
                  Verify Student ID
                </button>
              </div>
            ) : (
              <>
                <div className="flex gap-3 sm:gap-4">
              <UserAvatar
                src={user?.avatar}
                name={user?.name || 'User'}
                className="w-10 h-10 sm:w-11 sm:h-11 rounded-full object-cover shadow-sm ring-2 ring-neutral-200/50 dark:ring-neutral-700/50 flex-shrink-0"
              />
              <div className="flex-1 min-w-0">
                <MentionTextArea
                  value={postContent}
                  onChange={(e) => setPostContent(e.target.value)}
                  placeholder="What's happening in your campus? Type #hashtag or @mention..."
                  className="w-full bg-transparent text-sm sm:text-base text-neutral-900 dark:text-neutral-100 placeholder:text-neutral-400 dark:placeholder:text-neutral-500 resize-none outline-none border-none focus:ring-0 leading-relaxed p-1"
                  rows={3}
                />
                {imagePreviewUrl && (
                  <div className="relative mt-3 rounded-2xl overflow-hidden border border-neutral-200 dark:border-neutral-700 max-h-60 shadow-md group">
                    <img src={imagePreviewUrl} alt="Preview" className="object-contain max-h-60 w-full" />
                    <button
                      type="button"
                      onClick={handleRemoveImage}
                      className="absolute top-2.5 right-2.5 bg-black/75 hover:bg-rose-600 text-white rounded-full p-1.5 transition-all shadow-lg backdrop-blur-xs cursor-pointer"
                      title="Remove image"
                    >
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                )}

                {/* Document Preview */}
                {documentFile && (
                  <div className="relative mt-3 p-3 rounded-2xl bg-neutral-100/90 dark:bg-neutral-800/90 border border-neutral-200 dark:border-neutral-700 flex items-center justify-between text-xs font-semibold">
                    <div className="flex items-center gap-2 truncate pr-2">
                      <FileText className="w-4.5 h-4.5 text-purple-500 flex-shrink-0" />
                      <span className="truncate text-neutral-800 dark:text-neutral-200">{documentFile.name}</span>
                    </div>
                    <button
                      type="button"
                      onClick={() => setDocumentFile(null)}
                      className="p-1 text-neutral-400 hover:text-rose-500 cursor-pointer"
                    >
                      <X className="w-3.5 h-3.5" />
                    </button>
                  </div>
                )}

                {/* Inline Campus Poll Creator */}
                {showPollCreator && (
                  <div className="mt-3 p-3.5 rounded-2xl bg-purple-500/5 dark:bg-neutral-800/80 border border-purple-500/20 dark:border-neutral-700 space-y-2.5 text-left">
                    <div className="flex items-center justify-between">
                      <span className="text-xs font-bold text-purple-600 dark:text-purple-400 flex items-center gap-1.5">
                        <BarChart2 className="w-3.5 h-3.5" /> Create Campus Poll
                      </span>
                      <button
                        type="button"
                        onClick={() => { setShowPollCreator(false); setPollQuestion(''); setPollOptions(['', '']); }}
                        className="text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-200 p-1 cursor-pointer"
                      >
                        <X className="w-3.5 h-3.5" />
                      </button>
                    </div>
                    <input
                      type="text"
                      value={pollQuestion}
                      onChange={(e) => setPollQuestion(e.target.value)}
                      placeholder="Ask your campus a question..."
                      className="w-full px-3 py-2 text-xs rounded-xl bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 text-neutral-900 dark:text-neutral-100 placeholder:text-neutral-400 focus:outline-none focus:border-purple-500 font-medium"
                    />
                    <div className="space-y-1.5">
                      {pollOptions.map((opt, idx) => (
                        <div key={idx} className="flex items-center gap-1.5">
                          <input
                            type="text"
                            value={opt}
                            onChange={(e) => {
                              const next = [...pollOptions];
                              next[idx] = e.target.value;
                              setPollOptions(next);
                            }}
                            placeholder={`Option ${idx + 1}`}
                            className="flex-1 px-3 py-1.5 text-xs rounded-xl bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 text-neutral-900 dark:text-neutral-100 placeholder:text-neutral-400 focus:outline-none focus:border-purple-500 font-medium"
                          />
                          {pollOptions.length > 2 && (
                            <button
                              type="button"
                              onClick={() => setPollOptions(pollOptions.filter((_, i) => i !== idx))}
                              className="p-1 text-neutral-400 hover:text-rose-500 cursor-pointer"
                            >
                              <X className="w-3.5 h-3.5" />
                            </button>
                          )}
                        </div>
                      ))}
                    </div>
                    {pollOptions.length < 4 && (
                      <button
                        type="button"
                        onClick={() => setPollOptions([...pollOptions, ''])}
                        className="text-[11px] font-bold text-purple-600 dark:text-purple-400 hover:underline flex items-center gap-1 cursor-pointer"
                      >
                        + Add Option
                      </button>
                    )}
                  </div>
                )}
              </div>
            </div>

            <div className="flex items-center justify-between pt-3 mt-3 border-t border-neutral-100 dark:border-neutral-800/80 flex-wrap gap-2">
              <div className="flex items-center gap-1.5 flex-wrap">
                {/* Minimal Icon Feed Audience Toggle */}
                <button
                  type="button"
                  onClick={() => setFeedType(feedType === 'college' || feedType === 'my_college' ? 'public' : 'college')}
                  className={`p-2 rounded-full border transition-all cursor-pointer flex items-center justify-center shadow-xs hover:scale-105 active:scale-95 ${
                    feedType === 'college' || feedType === 'my_college'
                      ? 'bg-purple-500/10 text-purple-500 border-purple-500/30 hover:bg-purple-500/20'
                      : 'bg-sky-500/10 text-sky-500 border-sky-500/30 hover:bg-sky-500/20'
                  }`}
                  title={
                    feedType === 'college' || feedType === 'my_college'
                      ? `Posting to ${userCollege} Only (Click to switch to Public Feed)`
                      : 'Posting to Public Feed (Click to switch to My College)'
                  }
                >
                  {feedType === 'college' || feedType === 'my_college' ? (
                    <GraduationCap className="w-4 h-4 text-purple-500" />
                  ) : (
                    <Globe className="w-4 h-4 text-sky-500" />
                  )}
                </button>

                {/* 1. Gallery Photo Input */}
                <input
                  type="file"
                  ref={imageInputRef}
                  onChange={handleImageChange}
                  accept="image/*"
                  className="hidden"
                />
                <button
                  type="button"
                  onClick={() => imageInputRef.current?.click()}
                  className={`px-3 py-1.5 rounded-full transition-all duration-300 cursor-pointer flex items-center gap-1.5 text-xs font-semibold ${
                    imageFile
                      ? 'bg-sky-500/15 text-sky-500 dark:text-sky-400 border border-sky-500/30'
                      : 'bg-neutral-100 dark:bg-neutral-800/80 text-neutral-600 dark:text-neutral-300 hover:bg-sky-500/10 hover:text-sky-500 dark:hover:text-sky-400 border border-transparent'
                  }`}
                  title="Gallery Photos"
                >
                  <Image className="w-3.5 h-3.5" />
                  <span>Photos</span>
                </button>

                {/* 3. Poll Share Creator */}
                <button
                  type="button"
                  onClick={() => setShowPollCreator(!showPollCreator)}
                  className={`px-3 py-1.5 rounded-full transition-all duration-300 cursor-pointer flex items-center gap-1.5 text-xs font-semibold ${
                    showPollCreator
                      ? 'bg-purple-500/15 text-purple-600 dark:text-purple-400 border border-purple-500/30'
                      : 'bg-neutral-100 dark:bg-neutral-800/80 text-neutral-600 dark:text-neutral-300 hover:bg-purple-500/10 hover:text-purple-500 dark:hover:text-purple-400 border border-transparent'
                  }`}
                  title="Share Poll"
                >
                  <BarChart2 className="w-3.5 h-3.5" />
                  <span>Poll</span>
                </button>
              </div>

              <button
                type="button"
                onClick={handleCreatePost}
                disabled={(!postContent.trim() && !imageFile && !documentFile && (!pollQuestion.trim() || pollOptions.filter(o => o.trim()).length < 2)) || isUploading}
                className="px-6 py-2 rounded-full bg-gradient-to-r from-sky-500 via-blue-600 to-indigo-600 hover:from-sky-400 hover:to-indigo-500 active:scale-95 text-white font-bold text-sm shadow-md shadow-sky-500/25 hover:shadow-sky-500/40 disabled:opacity-40 disabled:scale-100 disabled:shadow-none transition-all cursor-pointer flex items-center gap-1.5 ml-auto"
              >
                <span>{isUploading ? 'Posting...' : 'Post'}</span>
              </button>
            </div>
            </>
            )}
          </div>


          {/* Feed */}
          {loading ? (
            <div className="space-y-md">
              <div className="h-32 skeleton rounded-xl" />
              <div className="h-32 skeleton rounded-xl" />
            </div>
          ) : displayedPosts.length > 0 ? (
            <div>
              {displayedPosts.map(post => {
                const isTarget = targetPostId === post.id || targetPostId === post.docId;
                return (
                  <PostCard
                    key={post.id}
                    post={post}
                    onVote={handleVote}
                    onRepost={handleRepost}
                    onSave={handleSave}
                    isHighlighted={highlightedPostId === post.id || highlightedPostId === post.docId}
                    autoOpenComments={isTarget && autoOpenComments}
                    highlightedCommentId={isTarget ? targetCommentId : null}
                  />
                );
              })}
            </div>
          ) : (
            <Card className="text-center py-5xl">
              <AlertCircle className="w-12 h-12 text-neutral-300 dark:text-neutral-700 mx-auto mb-lg" />
              <h3 className="font-bold text-lg mb-xs">
                {feedType === 'college' ? `No posts from ${userCollege} yet` : 'No posts yet'}
              </h3>
              <p className="text-sm text-neutral-500 dark:text-neutral-400">
                {feedType === 'college'
                  ? `Be the first student from ${userCollege} to share something with your campus!`
                  : 'Be the first one to share something with your campus community!'}
              </p>
            </Card>
          )}
        </div>

        {/* Desktop Right Panel — hidden on mobile/tablet */}
        <HomeRightPanel />
      </div>
    </div>
  );
}

export const PostCard = ({
  post,
  onVote,
  onRepost,
  onSave,
  isHighlighted,
  autoOpenComments = false,
  highlightedCommentId = null
}) => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { showSuccess } = useNotification();
  const [showComments, setShowComments] = useState(autoOpenComments || Boolean(highlightedCommentId));
  const [newComment, setNewComment] = useState('');
  const [comments, setComments] = useState([]);
  const [replyingToComment, setReplyingToComment] = useState(null);
  const [expandedReplies, setExpandedReplies] = useState({});
  const commentInputRef = useRef(null);

  useEffect(() => {
    if (autoOpenComments || highlightedCommentId) {
      setShowComments(true);
    }
  }, [autoOpenComments, highlightedCommentId]);

  const [showPostMenu, setShowPostMenu] = useState(false);
  const [isEditingPost, setIsEditingPost] = useState(false);
  const [editPostContent, setEditPostContent] = useState(post.content || '');
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [commentToDelete, setCommentToDelete] = useState(null);

  // LinkedIn-style Reshare State & Tracking
  const [showReshareModal, setShowReshareModal] = useState(false);
  const [reshareMode, setReshareMode] = useState(null); // null | 'thoughts'
  const [isShareModalOpen, setIsShareModalOpen] = useState(false);
  const [thoughtCaption, setThoughtCaption] = useState('');
  const [isSubmittingReshare, setIsSubmittingReshare] = useState(false);

  const [localReposts, setLocalReposts] = useState(post.reposts || 0);
  const [localResharedUsers, setLocalResharedUsers] = useState(post.resharedUsers || []);

  useEffect(() => {
    setLocalReposts(post.reposts || 0);
    setLocalResharedUsers(post.resharedUsers || []);
  }, [post.reposts, post.resharedUsers]);

  const isResharedByMe = Boolean(user?.uid && localResharedUsers.includes(user.uid));

  const isOfficialAdmin =
    (user?.username || '').toLowerCase() === 'cohort' ||
    (user?.name || '').toLowerCase() === 'cohort' ||
    user?.isOfficial === true ||
    user?.uid === 'cohort_official' ||
    user?.email === 'cohort@official.com';

  const isActualPostOwner = (post.author?.uid && post.author.uid === user?.uid) ||
                            (post.authorUid && post.authorUid === user?.uid) ||
                            (user?.name && post.author?.name === user?.name);

  const isPostOwner = isActualPostOwner || isOfficialAdmin;

  const isCohortOfficialPost =
    (post.author?.name || '').toLowerCase() === 'cohort' ||
    (post.author?.username || '').toLowerCase() === 'cohort' ||
    post.authorUid === 'cohort_official' ||
    post.author?.uid === 'cohort_official';

  // WhatsApp-style Poll Votes Breakdown Modal state
  const [viewVotesPoll, setViewVotesPoll] = useState(null);

  // Real-time resolution of post author profile from Firestore
  const [liveAuthorProfile, setLiveAuthorProfile] = useState(null);
  const targetAuthorUid = isCohortOfficialPost
    ? 'cohort_official'
    : (post.author?.uid || post.authorUid || post.uid);

  useEffect(() => {
    if (!targetAuthorUid) return;

    const unsub = onSnapshot(doc(db, 'users', targetAuthorUid), (snap) => {
      if (snap.exists()) {
        setLiveAuthorProfile(snap.data());
      }
    }, (err) => console.error('Error listening to post author profile:', err));

    return () => unsub();
  }, [targetAuthorUid]);

  const authorAvatar = isCohortOfficialPost
    ? (liveAuthorProfile?.avatar || post.author?.avatar)
    : ((isActualPostOwner && user?.avatar) || liveAuthorProfile?.avatar || post.author?.avatar);

  const authorName = isCohortOfficialPost
    ? 'Cohort'
    : ((isActualPostOwner && user?.name) || liveAuthorProfile?.name || post.author?.name || 'Student');

  // Social Proof Context State (Liked / Commented by someone you follow)
  const [socialContext, setSocialContext] = useState(null);

  useEffect(() => {
    if (!user?.uid) return;
    const myFollowing = Array.isArray(user?.following) ? user.following : [];
    if (myFollowing.length === 0) {
      setSocialContext(null);
      return;
    }

    // 1. Check if a followed user commented
    const followedComment = comments.find(c => {
      const cUid = c.authorUid || c.uid;
      const cName = c.author || c.authorName;
      const cUser = c.authorUsername;
      return (cUid && cUid !== user.uid && myFollowing.includes(cUid)) ||
             (cUser && cUser !== user.username && myFollowing.includes(cUser)) ||
             (cName && myFollowing.includes(cName));
    });

    if (followedComment) {
      setSocialContext({
        type: 'comment',
        userName: followedComment.author || 'A user you follow',
        userUid: followedComment.authorUid,
        text: 'commented on this'
      });
      return;
    }

    // 2. Check if a followed user liked/upvoted
    const upvoters = Array.isArray(post.upvotedUsers)
      ? post.upvotedUsers
      : (Array.isArray(post.likedUsers) ? post.likedUsers : []);

    const followedLikerItem = upvoters.find(item => {
      const uid = typeof item === 'string' ? item : item?.uid;
      return uid && uid !== user.uid && myFollowing.includes(uid);
    });

    if (followedLikerItem) {
      const likerUid = typeof followedLikerItem === 'string' ? followedLikerItem : followedLikerItem?.uid;
      getDoc(doc(db, 'users', likerUid)).then(snap => {
        if (snap.exists()) {
          const lData = snap.data();
          setSocialContext({
            type: 'like',
            userName: lData.name || lData.username || 'A user you follow',
            userUid: likerUid,
            text: 'liked this'
          });
        } else {
          setSocialContext({
            type: 'like',
            userName: 'A user you follow',
            userUid: likerUid,
            text: 'liked this'
          });
        }
      }).catch(() => {
        setSocialContext({
          type: 'like',
          userName: 'A user you follow',
          userUid: likerUid,
          text: 'liked this'
        });
      });
      return;
    }

    setSocialContext(null);
  }, [comments, post.upvotedUsers, post.likedUsers, user?.following, user?.uid, user?.username]);

  const handleSaveInlineEdit = async () => {
    if (!editPostContent.trim()) return;
    try {
      const postId = post.docId || post.id;
      await updateDoc(doc(db, 'posts', postId), { content: editPostContent.trim() });
      post.content = editPostContent.trim();
      setIsEditingPost(false);
      setShowPostMenu(false);
      showSuccess('Post updated successfully!');
    } catch (err) {
      console.error('Failed to edit post:', err);
    }
  };

  const confirmDeletePostDoc = async () => {
    try {
      const postId = post.docId || post.id;
      await deleteDoc(doc(db, 'posts', postId));

      // If deleting a reshare, decrement original post's reshare counter
      if (post.isReshare && post.originalPostId) {
        try {
          const origPostRef = doc(db, 'posts', post.originalPostId);
          await updateDoc(origPostRef, {
            reposts: increment(-1),
            resharedUsers: user?.uid ? arrayRemove(user.uid) : []
          });
        } catch (e) {
          console.error('Failed to decrement original post repost count:', e);
        }
      }

      setShowDeleteModal(false);
      setShowPostMenu(false);
      showSuccess('Post deleted permanently.');
    } catch (err) {
      console.error('Failed to delete post:', err);
    }
  };

  const handleUnreshare = async () => {
    const rootOriginalPostId = post.originalPostId || post.docId || post.id;
    const myUid = user?.uid;
    if (!myUid || !rootOriginalPostId) return;

    setIsSubmittingReshare(true);
    setLocalReposts(prev => Math.max(0, prev - 1));
    setLocalResharedUsers(prev => prev.filter(u => u !== myUid));

    try {
      // 1. Decrement repost count and remove UID from original post
      const origPostRef = doc(db, 'posts', rootOriginalPostId);
      await updateDoc(origPostRef, {
        reposts: increment(-1),
        resharedUsers: arrayRemove(myUid)
      });

      // 2. Query and delete the reshare document created by this user for rootOriginalPostId
      const q = query(
        collection(db, 'posts'),
        where('isReshare', '==', true),
        where('originalPostId', '==', rootOriginalPostId),
        where('resharedBy.uid', '==', myUid)
      );
      const snapshot = await getDocs(q);
      snapshot.forEach(async (docSnap) => {
        await deleteDoc(doc(db, 'posts', docSnap.id));
      });

      showSuccess('Reshare removed.');
      setShowReshareModal(false);
    } catch (err) {
      console.error('Failed to unreshare post:', err);
      setLocalReposts(post.reposts || 0);
      setLocalResharedUsers(post.resharedUsers || []);
    } finally {
      setIsSubmittingReshare(false);
    }
  };

  const handleReshareInstant = async () => {
    const rootOriginalPostId = post.originalPostId || post.docId || post.id;
    const origAuthor = post.originalPost?.author || post.author;
    const origContent = post.originalPost?.content || post.content;
    const origTimestamp = post.originalPost?.timestamp || post.timestamp;
    const myUid = user?.uid;

    setIsSubmittingReshare(true);
    setLocalReposts(prev => prev + 1);
    if (myUid) setLocalResharedUsers(prev => [...prev, myUid]);

    try {
      const reshareDocData = {
        isReshare: true,
        originalPostId: rootOriginalPostId,
        originalPost: {
          id: rootOriginalPostId,
          author: origAuthor,
          content: origContent,
          timestamp: origTimestamp
        },
        resharedBy: {
          uid: myUid || null,
          name: user?.name || 'Student',
          username: user?.username || null,
          avatar: user?.avatar || null
        },
        college: user?.college || 'KIET',
        author: {
          uid: myUid || null,
          name: user?.name || 'Student',
          username: user?.username || null,
          avatar: user?.avatar || null,
          role: user?.college || 'KIET',
          college: user?.college || 'KIET'
        },
        thought: '',
        content: '',
        timestamp: new Date(),
        upvotes: 0,
        downvotes: 0,
        upvotedUsers: [],
        downvotedUsers: [],
        comments: 0,
        reposts: 0,
        saved: false
      };

      await addDoc(collection(db, 'posts'), reshareDocData);

      // Increment reshare count and add user UID to root original post
      const origPostRef = doc(db, 'posts', rootOriginalPostId);
      await updateDoc(origPostRef, {
        reposts: increment(1),
        resharedUsers: myUid ? arrayUnion(myUid) : []
      });

      if (onRepost) onRepost(rootOriginalPostId);

      const origAuthorUid = origAuthor?.uid || post.author?.uid;
      if (origAuthorUid && origAuthorUid !== myUid) {
        createNotification({
          recipientUid: origAuthorUid,
          senderUid: myUid,
          senderName: user?.name || 'Student',
          senderAvatar: user?.avatar,
          type: 'reshare',
          text: 'reshared your post.',
          postId: rootOriginalPostId
        });
      }

      showSuccess('Post reshared successfully.');
      setShowReshareModal(false);
      setReshareMode(null);
    } catch (err) {
      console.error('Failed to reshare post:', err);
      setLocalReposts(post.reposts || 0);
      setLocalResharedUsers(post.resharedUsers || []);
    } finally {
      setIsSubmittingReshare(false);
    }
  };

  const handleReshareWithThoughtsSubmit = async () => {
    if (!thoughtCaption.trim()) return;
    const rootOriginalPostId = post.originalPostId || post.docId || post.id;
    const origAuthor = post.originalPost?.author || post.author;
    const origContent = post.originalPost?.content || post.content;
    const origTimestamp = post.originalPost?.timestamp || post.timestamp;
    const myUid = user?.uid;

    setIsSubmittingReshare(true);
    setLocalReposts(prev => prev + 1);
    if (myUid) setLocalResharedUsers(prev => [...prev, myUid]);

    try {
      const reshareDocData = {
        isReshare: true,
        originalPostId: rootOriginalPostId,
        originalPost: {
          id: rootOriginalPostId,
          author: origAuthor,
          content: origContent,
          timestamp: origTimestamp
        },
