                    className="w-full flex items-center gap-3 p-3 text-rose-500 hover:bg-rose-500/10 rounded-2xl text-left font-medium text-sm transition-all cursor-pointer mt-1"
                  >
                    <LogOut className="w-5 h-5 text-rose-500" />
                    <span>Logout</span>
                  </button>
