                    <div className="flex items-center gap-md min-w-0">
                      <img
                        src={u.avatar}
                        alt={u.name}
                        className="w-10 h-10 rounded-full object-cover flex-shrink-0 bg-neutral-800 border border-neutral-700"
                      />
                      <div className="min-w-0">
                        <h4 className="font-bold text-xs text-neutral-900 dark:text-white truncate">
                          {u.name}
                        </h4>
                        <p className="text-[10px] text-neutral-500 truncate">
                          {u.college}
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-xs">
                      <Heart className="w-4 h-4 text-rose-500 fill-rose-500 flex-shrink-0" />
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="text-center py-xl">
                <Heart className="w-10 h-10 text-neutral-300 dark:text-neutral-700 mx-auto mb-xs" />
                <p className="text-xs font-bold text-neutral-600 dark:text-neutral-400">No likes yet</p>
                <p className="text-[10px] text-neutral-400 mt-1">Be the first to like this post!</p>
              </div>
            )}
          </div>
        </Modal>
      )}

      {/* ── COMMENTS & DISCUSSION MODAL ── */}
      {selectedPostForComments && (
        <Modal
          isOpen={Boolean(selectedPostForComments)}
          onClose={() => { setSelectedPostForComments(null); setCommentsList([]); setNewCommentText(''); }}
          title="Comments & Discussion"
          size="md"
        >
          <div className="space-y-lg flex flex-col max-h-[75vh]">
            {/* Post Summary Header */}
            <div className="p-md rounded-xl bg-neutral-50 dark:bg-neutral-800/60 border border-neutral-200/60 dark:border-neutral-700/60 space-y-xs flex-shrink-0">
              <p className="text-xs font-semibold text-neutral-900 dark:text-white leading-relaxed line-clamp-3">
                {selectedPostForComments.thought || selectedPostForComments.content || selectedPostForComments.text || 'Post details'}
              </p>
              <div className="flex items-center justify-between text-[10px] text-neutral-400 font-mono pt-xs">
                <span>{formatRelativeTime(selectedPostForComments.timestamp || selectedPostForComments.createdAt)}</span>
                <span className="text-primary-500 font-bold">{commentsList.length} comments</span>
              </div>
            </div>

            {/* Comments List */}
            <div className="flex-1 overflow-y-auto space-y-md pr-xs scrollbar-thin min-h-[150px] max-h-[300px]">
              {loadingComments ? (
                <div className="py-xl text-center space-y-xs">
                  <Loader2 className="w-6 h-6 animate-spin text-primary-500 mx-auto" />
                  <p className="text-xs text-neutral-400">Loading comments...</p>
                </div>
              ) : commentsList.length > 0 ? (
                commentsList.map((c) => (
                  <div key={c.id} className="p-md rounded-xl bg-neutral-100/70 dark:bg-neutral-800/50 border border-neutral-200/40 dark:border-neutral-700/40 space-y-xs">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-sm">
                        <UserAvatar
                          src={c.authorAvatar}
                          name={c.authorName || 'Student'}
                          className="w-6 h-6 rounded-full object-cover border border-neutral-700"
                        />
                        <span className="font-bold text-xs text-neutral-900 dark:text-white">
                          {c.authorName || 'Student'}
                        </span>
                      </div>

                      <div className="flex items-center gap-xs">
                        <span className="text-[10px] text-neutral-400 font-mono">
                          {c.displayDateText || 'Recently'}
                        </span>
                        <button
                          type="button"
                          onClick={() => handleReplyToComment(c)}
                          className="flex items-center gap-1 text-[10px] font-bold text-primary-500 hover:text-primary-400 px-2 py-0.5 rounded-md hover:bg-primary-500/10 transition-colors cursor-pointer ml-xs"
                        >
                          <MessageSquare className="w-3 h-3" />
                          <span>Reply</span>
                        </button>
                      </div>
                    </div>
                    <p className="text-xs text-neutral-700 dark:text-neutral-300 leading-relaxed pl-8">
                      {c.text}
                    </p>
                  </div>
                ))
              ) : (
                <div className="text-center py-xl">
                  <MessageSquare className="w-8 h-8 text-neutral-300 dark:text-neutral-700 mx-auto mb-xs" />
                  <p className="text-xs text-neutral-400 font-medium">No comments on this post yet.</p>
                  <p className="text-[10px] text-neutral-500 mt-0.5">Start the conversation below!</p>
                </div>
              )}
            </div>

            {/* Replying Banner */}
            {replyingToComment && (
              <div className="flex items-center justify-between px-md py-xs bg-primary-500/10 border border-primary-500/30 rounded-xl text-xs text-primary-400 font-semibold flex-shrink-0">
                <span>Replying to <strong className="text-white">@{replyingToComment.authorName}</strong></span>
                <button
                  type="button"
                  onClick={() => {
                    setReplyingToComment(null);
                    setNewCommentText('');
                  }}
                  className="text-neutral-400 hover:text-white p-0.5 cursor-pointer"
                >
                  <X className="w-3.5 h-3.5" />
                </button>
              </div>
            )}

            {/* Comment Form */}
            <form onSubmit={handleAddComment} className="flex gap-sm items-center pt-md border-t border-neutral-100 dark:border-neutral-800 flex-shrink-0">
              <input
                ref={commentInputRef}
                type="text"
                placeholder={replyingToComment ? `Replying to @${replyingToComment.authorName}...` : "Write a comment..."}
                value={newCommentText}
                onChange={(e) => setNewCommentText(e.target.value)}
                className="flex-1 px-md py-xs bg-neutral-100 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl text-xs outline-none text-neutral-900 dark:text-white placeholder-neutral-400 focus:ring-1 focus:ring-primary-500"
              />
              <Button
                type="submit"
                size="sm"
                variant="primary"
                disabled={!newCommentText.trim() || submittingComment}
                className="flex items-center gap-xs text-xs"
              >
                {submittingComment ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Send className="w-3.5 h-3.5" />}
                <span>Post</span>
              </Button>
            </form>
          </div>
        </Modal>
      )}

      {/* Modal to Edit Cohort Official Account */}
      {isEditOfficialModalOpen && isOfficialLoggedIn && (
        <Modal
          isOpen={isEditOfficialModalOpen}
          onClose={() => setIsEditOfficialModalOpen(false)}
          title="Edit Official Cohort Profile"
        >
          <div className="space-y-lg">
            {/* Avatar Edit */}
            <div className="flex flex-col items-center gap-sm">
              <div className="relative">
                <UserAvatar
                  src={officialAvatarPreview || 'https://ui-avatars.com/api/?name=Cohort&background=9333ea&color=fff&bold=true&size=128'}
                  name="Cohort"
                  className="w-24 h-24 rounded-full border-4 border-purple-500/40 object-cover shadow-xl"
                />
                {isUploadingOfficialAvatar && (
                  <div className="absolute inset-0 bg-black/60 rounded-full flex items-center justify-center">
                    <Loader2 className="w-6 h-6 text-purple-400 animate-spin" />
                  </div>
                )}
              </div>
              <input
                ref={officialFileInputRef}
                type="file"
                accept="image/*"
                className="hidden"
                onChange={handleOfficialAvatarSelect}
              />
              <Button
                variant="secondary"
                size="sm"
                className="flex items-center gap-xs text-xs font-bold border-purple-500/30 text-purple-600 dark:text-purple-300 hover:bg-purple-500/10"
                onClick={() => officialFileInputRef.current?.click()}
                disabled={isUploadingOfficialAvatar}
              >
                <Camera className="w-4 h-4 text-purple-500" /> Change Official Image
              </Button>
            </div>

            {/* Bio Edit */}
            <div>
              <label className="block text-xs font-bold text-neutral-700 dark:text-neutral-300 mb-xs uppercase tracking-wider">
                Official Account Bio
              </label>
              <textarea
                value={officialBioInput}
                onChange={(e) => setOfficialBioInput(e.target.value)}
                placeholder="Enter official account bio..."
                className="w-full p-md bg-neutral-50 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl text-sm outline-none focus:ring-2 focus:ring-purple-500 text-neutral-900 dark:text-white leading-relaxed resize-none"
                rows={4}
              />
            </div>

            {/* Modal Actions */}
            <div className="flex items-center justify-end gap-md pt-md border-t border-neutral-100 dark:border-neutral-800">
              <Button
                variant="ghost"
                onClick={() => setIsEditOfficialModalOpen(false)}
                disabled={isSavingOfficial}
              >
                Cancel
              </Button>
              <Button
                variant="primary"
                onClick={handleSaveOfficialProfile}
                disabled={isSavingOfficial || isUploadingOfficialAvatar}
                className="bg-purple-600 hover:bg-purple-700 text-white font-bold"
              >
                {isSavingOfficial ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin mr-1" /> Saving...
                  </>
                ) : (
                  'Save Changes'
                )}
              </Button>
            </div>
          </div>
        </Modal>
      )}

      {/* Instagram-style Share Modal */}
      <ShareModal
        isOpen={isProfileShareOpen}
        onClose={() => setIsProfileShareOpen(false)}
        shareUrl={window.location.href}
        title={`Profile: ${profileUser?.name || 'Cohort Student'}`}
      />
    </div>
  );
}

const handleSendMessage = () => {
    if (!profileUser) return;
    navigate(`/messages?recipientUid=${profileUser.uid}&recipientName=${encodeURIComponent(profileUser.name)}`);
  };

const fetchAndCalculateMatches = async () => {
    try {
      const usersSnap = await getDocs(collection(db, 'users'));
      const list = [];
      const currentSwiped = user?.makeAFriendProfile?.swiped || {};
      const currentAnswers = user?.makeAFriendProfile?.answers || answers;

      usersSnap.forEach((d) => {
        const data = d.data();
        const uid = d.id;

        // Skip current user, official Cohort account, already swiped profiles, and users who haven't completed the quiz
        if (
          uid === user.uid ||
          uid === 'cohort_official' ||
          (data.username || '').toLowerCase() === 'cohort' ||
          data.isOfficial === true ||
          currentSwiped[uid] ||
          !data.makeAFriendProfile?.completed
        ) {
          return;
        }

        // Resolve gender (use Firestore gender or deterministic fallback if undefined/prefer not to say)
        const resolvedGender = data.gender && data.gender !== 'Prefer not to say'
          ? data.gender
          : (uid.charCodeAt(0) % 2 === 0 ? 'Male' : 'Female');

        // Apply gender filter
        const matchesGender = () => {
          if (genderFilter === 'All') return true;
          return resolvedGender.toLowerCase() === genderFilter.toLowerCase();
        };

        if (!matchesGender()) {
          return;
        }

        // Apply campus filter
        const matchesCampus = () => {
          const myCollege = (user?.college || 'KIET').toLowerCase().trim();
          const theirCollege = (data.college || 'KIET').toLowerCase().trim();
          if (campusFilter === 'On Campus' || campusFilter === 'Same College') {
            return myCollege === theirCollege;
          } else if (campusFilter === 'Outside Campus') {
            return myCollege !== theirCollege;
          }
          return true; // 'All' or 'All Campuses'
        };

        if (!matchesCampus()) {
          return;
        }

        // Retrieve the user's completed makeAFriendProfile
        const targetProfile = data.makeAFriendProfile;
        const matchPct = calculateCompatibility(currentAnswers, targetProfile.answers, user.uid, uid, user.college, data.college);

        list.push({
          uid,
          id: uid,
          name: data.name || 'Anonymous Student',
          college: data.college || 'KIET',
          avatar: data.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(uid)}`,
          gender: resolvedGender,
          answers: targetProfile.answers,
          matchPercentage: matchPct,
          sharedInterests: getSharedInterests(currentAnswers, targetProfile.answers)
        });
      });

      // Sort by match percentage desc
      list.sort((a, b) => b.matchPercentage - a.matchPercentage);
      setProfiles(list);
      setCurrentProfileIndex(0);
    } catch (err) {
      console.error('Error fetching match profiles:', err);
      showError('Failed to fetch matched profiles.');
    }
  };

const handleSubmit = async (e) => {
    e.preventDefault();

    if (isSignup) {
      if (signupStep === 1) {
        await handleSendOTP();
      } else {
        await handleVerifyAndSignup(e);
      }
      return;
    }

    // Login Form Submit logic
    const newErrors = {};

    if (!formData.email.trim()) {
      newErrors.email = 'Email or Username is required';
    }

    if (!formData.password) {
      newErrors.password = 'Password is required';
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    setIsLoading(true);

    try {
      await login(formData.email.trim(), formData.password);
      showSuccess('Welcome back to Cohort!');
      navigate('/home');
    } catch (error) {
      console.error(error);
      if (error.code === 'auth/operation-not-allowed') {
        showError('Please sign in via Google below!');
      } else if (error.code === 'auth/user-not-found' || error.code === 'auth/wrong-password' || error.code === 'auth/invalid-credential') {
        showError('Invalid email/username or password. Please check your details.');
      } else {
        showError(error.message || 'Sign in failed. Please check your credentials.');
      }
    } finally {
      setIsLoading(false);
    }
  };

export default function ShareModal({ isOpen, onClose, post, shareUrl: customShareUrl, title: customTitle }) {
  const { user } = useAuth();
  const { showSuccess, showError } = useNotification();

  const [searchQuery, setSearchQuery] = useState('');
  const [recentUsers, setRecentUsers] = useState([]);
  const [loadingUsers, setLoadingUsers] = useState(false);
  const [selectedUsers, setSelectedUsers] = useState([]);
  const [isSending, setIsSending] = useState(false);
  const [sentMap, setSentMap] = useState({});
  const [copied, setCopied] = useState(false);

  const rawAuthorName = post?.author?.name || post?.authorName || '';
  const shareTitle =
    customTitle ||
    (rawAuthorName ? (rawAuthorName.toLowerCase().startsWith('post by') ? rawAuthorName : `Post by ${rawAuthorName}`) : 'Campus Post');

  const isUncut = Boolean(customShareUrl?.includes('/uncut')) || Boolean(post?.id?.includes('-')) || Boolean(post?.category);
  const shareText =
    post?.content ||
    post?.excerpt ||
    post?.text ||
    post?.caption ||
    (isUncut
      ? 'Read unfiltered real campus stories written by peers on Cohort Uncut.'
      : 'Explore student conversations, gossip, confessions and stories on Cohort.');

  const postMediaUrl =
    post?.image ||
    post?.imageUrl ||
    post?.mediaUrl ||
    post?.photo ||
    post?.media ||
    post?.coverImage ||
    post?.storyImage ||
    '';

  const rawShareUrl = customShareUrl || (post?.id ? `${window.location.origin}/post/${post.id}` : window.location.href);
  const shareUrl = rawShareUrl.includes('?') ? rawShareUrl : `${rawShareUrl}?v=1`;

  // Fetch recent chat members and campus users when modal opens
  useEffect(() => {
    if (!isOpen) {
      setSearchQuery('');
      setSelectedUsers([]);
      setSentMap({});
      setCopied(false);
      return;
    }

    const fetchContacts = async () => {
      setLoadingUsers(true);
      try {
        const usersSnap = await getDocs(collection(db, 'users'));
        const list = [];
        usersSnap.forEach((d) => {
          const uid = d.id;
          if (
            user?.uid &&
            uid !== user.uid &&
            uid !== 'cohort_official' &&
            d.data()?.username !== 'cohort'
          ) {
            const data = d.data();
            list.push({
              uid,
              name: data.name || data.username || 'Campus Student',
              username: data.username || '',
              avatar:
                data.avatar ||
                `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(uid)}`,
              college: data.college || 'KIET'
            });
          }
        });

        setRecentUsers(list);
      } catch (err) {
        console.error('Error fetching share contacts:', err);
      } finally {
        setLoadingUsers(false);
      }
    };

    fetchContacts();
  }, [isOpen, user]);

  // Filter contacts by search query
  const filteredUsers = recentUsers.filter((u) => {
    const q = searchQuery.toLowerCase().trim();
    if (!q) return true;
    return (
      u.name.toLowerCase().includes(q) ||
      u.username.toLowerCase().includes(q) ||
      u.college.toLowerCase().includes(q)
    );
  });

  // Toggle user selection
  const toggleSelectUser = (targetUser) => {
    if (sentMap[targetUser.uid]) return;
    if (selectedUsers.some((u) => u.uid === targetUser.uid)) {
      setSelectedUsers(selectedUsers.filter((u) => u.uid !== targetUser.uid));
    } else {
      setSelectedUsers([...selectedUsers, targetUser]);
    }
  };

  // Batch send direct message to all selected contacts
  const handleSendBatch = async () => {
    if (!user) {
      showError('Please sign in to send direct messages.');
      return;
    }

    if (selectedUsers.length === 0) return;

    setIsSending(true);

    const cleanStr = (val, fallback = '') => (val === undefined || val === null ? fallback : String(val));

    try {
      const myUid = cleanStr(user?.uid);
      const myName = cleanStr(user?.name || user?.displayName || user?.email?.split('@')[0], 'Me');
      const myAvatar = cleanStr(
        user?.avatar || user?.photoURL,
        `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(myUid)}`
      );

      const safeTitle = cleanStr(shareTitle, 'Campus Post');
      const safeText = cleanStr(shareText, 'Check out this post on Cohort!');
      const safeUrl = cleanStr(shareUrl, window.location.href);
      const safeMediaUrl = cleanStr(
        post?.image || post?.imageUrl || post?.mediaUrl || post?.photo || post?.media || post?.coverImage || postMediaUrl,
        ''
      );
      const lastMsgSummary = `Shared a post: ${safeText.slice(0, 35)}${safeText.length > 35 ? '...' : ''}`;
      const nowIso = new Date().toISOString();

      // Fetch existing conversations for matching
      const messagesSnap = await getDocs(collection(db, 'messages'));
      const existingDocsMap = new Map();

      messagesSnap.forEach((docSnap) => {
        const data = docSnap.data();
        const parts = Array.isArray(data.participants) ? data.participants : [];

        // Match by participants array or createdBy/recipientUid fields
        selectedUsers.forEach((tUser) => {
          const targetUid = cleanStr(tUser.uid);
          const isMatch =
            (parts.includes(myUid) && parts.includes(targetUid)) ||
            (data.createdBy === myUid && data.recipientUid === targetUid) ||
            (data.createdBy === targetUid && data.recipientUid === myUid);

          if (isMatch && !existingDocsMap.has(targetUid)) {
            existingDocsMap.set(targetUid, { id: docSnap.id, ...data });
          }
        });
      });

      const sanitizeForFirestore = (val) => {
        if (val === undefined) return null;
        if (val === null || typeof val !== 'object') return val;
        if (val instanceof Date) return val;
        if (Array.isArray(val)) return val.map(sanitizeForFirestore);
        const clean = {};
        for (const key of Object.keys(val)) {
          if (val[key] !== undefined) {
            clean[key] = sanitizeForFirestore(val[key]);
          }
        }
        return clean;
      };

      const sendPromises = selectedUsers.map(async (targetUser) => {
        const targetUid = cleanStr(targetUser.uid);
        const targetName = cleanStr(targetUser.name, 'Campus Student');
        const targetAvatar = cleanStr(
          targetUser.avatar,
          `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(targetUid)}`
        );

        const isUncut = Boolean(safeUrl.includes('/uncut') || post?.id?.includes('-') || post?.category);
        const messageObj = sanitizeForFirestore({
          id: `msg_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
          sender: myUid,
          senderUid: myUid,
          senderName: myName,
          senderAvatar: myAvatar,
          text: isUncut 
            ? `📖 Shared Uncut Story: ${safeTitle}\n"${safeText.slice(0, 120)}${safeText.length > 120 ? '...' : ''}"\n${safeUrl}`
            : `Shared post by ${safeTitle}:\n"${safeText.slice(0, 120)}${safeText.length > 120 ? '...' : ''}"\n${safeUrl}`,
          time: nowIso,
          createdAt: nowIso,
          deletedFor: [],
          isSharedPost: true,
          isUncutStory: isUncut,
          sharedPostData: {
            id: cleanStr(post?.id, ''),
            title: safeTitle,
            content: safeText,
            url: safeUrl,
            mediaUrl: safeMediaUrl
          }
        });

        const existingDoc = existingDocsMap.get(targetUid);

        if (existingDoc) {
          const chatRef = doc(db, 'messages', existingDoc.id);
          const freshSnap = await getDoc(chatRef);
          const rawData = freshSnap.exists() ? freshSnap.data() : existingDoc;

          const rawMsgs = Array.isArray(rawData.messages) ? rawData.messages : [];
          const cleanExistingMsgs = rawMsgs.map((m) => {
            const cleanM = sanitizeForFirestore(m);
            return {
              ...cleanM,
              time: m.time?.toDate ? m.time.toDate().toISOString() : (m.time ? String(m.time) : nowIso)
            };
          });

          const resetHidden = {};
          if (rawData.hiddenFor) {
            Object.keys(rawData.hiddenFor).forEach((k) => {
              resetHidden[`hiddenFor.${k}`] = false;
            });
          }

          const updatePayload = sanitizeForFirestore({
            messages: [...cleanExistingMsgs, messageObj],
            lastMessage: lastMsgSummary,
            time: new Date(),
            readBy: [myUid],
            [`participantMap.${myUid}`]: { name: myName, avatar: myAvatar },
            [`participantMap.${targetUid}`]: { name: targetName, avatar: targetAvatar },
            ...resetHidden
          });

          await updateDoc(chatRef, updatePayload);
        } else {
          const newConvData = sanitizeForFirestore({
            recipientUid: targetUid,
            recipientName: targetName,
            recipientAvatar: targetAvatar,
            participants: [myUid, targetUid],
            participantMap: {
              [myUid]: { name: myName, avatar: myAvatar },
              [targetUid]: { name: targetName, avatar: targetAvatar }
            },
            createdBy: myUid,
            createdByName: myName,
            createdByAvatar: myAvatar,
            readBy: [myUid],
            avatar: targetAvatar,
            lastMessage: lastMsgSummary,
            time: new Date(),
            messages: [messageObj]
          });
          await addDoc(collection(db, 'messages'), newConvData);
        }
      });

      await Promise.all(sendPromises);

      const newSentMap = { ...sentMap };
      selectedUsers.forEach((u) => {
        newSentMap[u.uid] = true;
      });

      setSentMap(newSentMap);
      showSuccess(
        selectedUsers.length === 1
          ? `Sent to ${selectedUsers[0].name}!`
          : `Sent to ${selectedUsers.length} contacts!`
      );
      setSelectedUsers([]);
      setTimeout(() => {
        onClose();
      }, 700);
    } catch (err) {
      console.error('Error sending batch messages:', err);
      showError('Failed to send message. Please try again.');
    } finally {
      setIsSending(false);
    }
  };

  // Copy link handler
  const handleCopyLink = () => {
    navigator.clipboard.writeText(shareUrl);
    setCopied(true);
    showSuccess('Link copied to clipboard!');
    setTimeout(() => setCopied(false), 2500);
  };

  const handleSocialShare = async (platform) => {
    const isUncutStory = shareUrl.includes('/uncut') || Boolean(post?.category) || Boolean(post?.id?.includes('-')) || shareTitle.toLowerCase().includes('uncut');
    const encodedUrl = encodeURIComponent(shareUrl);

    switch (platform) {
      case 'whatsapp': {
        let waText = '';
        if (isUncutStory) {
          const storyTitle = post?.title || shareTitle.replace(/^(Uncut Story:?|College, Love Stories and the Dilemma \| Cohort Uncut)\s*/i, '');
          const authorName = post?.authorName || post?.author?.name || 'Cohort Uncut';
          const initialLines = (post?.content || post?.excerpt || post?.text || shareText || '').slice(0, 160);

          waText = `📖 *COHORT UNCUT* | *Story*\n\n` +
                   `*"${storyTitle}"*\n` +
                   `✍️ *By ${authorName}*\n\n` +
                   `"${initialLines}${initialLines.length >= 160 ? '...' : ''}"\n\n` +
                   `👉 *Read full story on Cohort:*\n${shareUrl}`;
        } else {
          waText = `✨ *Check this out on Cohort:*\n"${shareText.slice(0, 120)}"\n\n${shareUrl}`;
        }

        window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(waText)}`, '_blank');
        break;
      }
      case 'instagram':
        navigator.clipboard.writeText(shareUrl);
        showSuccess('Link copied! Opening Instagram...');
        setTimeout(() => {
          window.open('https://www.instagram.com/direct/inbox/', '_blank');
        }, 600);
        break;
      case 'facebook':
        window.open(`https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}`, '_blank');
        break;
      case 'messenger':
        window.open(`https://www.facebook.com/dialog/send?link=${encodedUrl}&app_id=291494419107518&redirect_uri=${encodedUrl}`, '_blank');
        break;
      case 'email':
        window.open(`mailto:?subject=${encodeURIComponent(shareTitle)}&body=${encodedText}`, '_blank');
        break;
      case 'threads':
        window.open(`https://www.threads.net/intent/post?text=${encodedText}`, '_blank');
        break;
      case 'twitter':
        window.open(`https://twitter.com/intent/tweet?text=${encodedText}`, '_blank');
        break;
      default:
        handleCopyLink();
    }
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
