                    >
                      {parseBold(item)}
                    </span>
                  ))}
                </div>
              );
            }
          }

          return (
            <p key={lineIdx} className="text-sm text-neutral-700 dark:text-neutral-300 leading-relaxed font-medium">
              {parseBold(trimmed)}
            </p>
          );
        })}
