const loadProfile = async () => {
      if (!profileUser) {
        setLoading(true);
      }
      try {
        let activeProfile = null;

        // First: check if the target UID itself points to a cohort-named account
        let targetData = null;
        if (targetUid && targetUid !== 'cohort_official') {
          const preCheck = await getDoc(doc(db, 'users', targetUid));
          if (preCheck.exists()) {
            targetData = preCheck.data();
          }
        }

        const isCohortTarget =
          targetUid === 'cohort_official' ||
          (targetName || '').toLowerCase() === 'cohort' ||
          (isOwnProfile && isOfficialLoggedIn) ||
          (targetData?.username || '').toLowerCase() === 'cohort' ||
          (targetData?.name || '').toLowerCase() === 'cohort' ||
          targetData?.isOfficial === true;

        if (isCohortTarget) {
          const cohortDocRef = doc(db, 'users', 'cohort_official');
          const cohortSnap = await getDoc(cohortDocRef);
          if (cohortSnap.exists()) {
            activeProfile = { uid: 'cohort_official', id: 'cohort_official', ...cohortSnap.data() };
          } else {
            activeProfile = {
              uid: 'cohort_official',
              id: 'cohort_official',
              name: 'Cohort',
              username: 'cohort',
              email: 'cohort@official.com',
              college: 'Cohort Official Platform',
              isOfficial: true,
              bio: 'The official Cohort platform account. Connecting students across campuses. Follow for official feature updates, campus drops, and 24/7 support.',
              followers: [],
              following: [],
              avatar: 'https://ui-avatars.com/api/?name=Cohort&background=9333ea&color=fff&bold=true&size=128',
              joinedDate: new Date().toISOString()
            };
          }
        } else if (isOwnProfile) {
          activeProfile = currentUser;
        } else {
            if (targetUid) {
              // Fetch target user by UID
              const docRef = doc(db, 'users', targetUid);
              const docSnap = await getDoc(docRef);
              if (docSnap.exists()) {
                activeProfile = { uid: targetUid, id: targetUid, ...docSnap.data() };
              }
            }

            if (!activeProfile && targetName) {
              // Fetch target user by Name
              const q = query(collection(db, 'users'), where('name', '==', targetName));
              const querySnapshot = await getDocs(q);
              querySnapshot.forEach(d => {
                activeProfile = { uid: d.id, id: d.id, ...d.data() };
              });
            }

            if (!activeProfile && (targetUid || targetName)) {
              // Create fallback profile so actions like follow/message work seamlessly
              const fallbackId = targetUid || `user_${Date.now()}`;
              const fallbackName = targetName || 'Kushal';
              activeProfile = {
                uid: fallbackId,
                id: fallbackId,
                name: fallbackName,
                username: fallbackName.toLowerCase().replace(/\s+/g, ''),
                college: 'KIET',
                followers: [],
                following: [],
                joinedDate: new Date().toISOString()
              };
            }
          }

        setProfileUser(activeProfile);

        const activeUid = activeProfile?.uid || activeProfile?.id || targetUid || currentUser?.uid;
        if (activeUid && activeUid !== 'cohort_official') {
          onSnapshot(doc(db, 'users', activeUid), (snap) => {
            if (snap.exists()) {
              setProfileUser(prev => ({ ...prev, ...snap.data() }));
            }
          });
        }

        if (activeProfile) {
          const currentUid = activeProfile.uid || activeProfile.id || targetUid || currentUser?.uid;
          const currentName = activeProfile.name || targetName || currentUser?.name;
          const currentUsername = activeProfile.username || currentUser?.username || (targetUsername ? targetUsername.replace('@', '') : null);
          const currentEmail = activeProfile.email || currentUser?.email;

          const cleanStr = (s) => (s || '').toString().toLowerCase().replace(/[^a-z0-9]/g, '');

          const getTokens = (str) => (str || '').toLowerCase().replace(/[^a-z0-9]/g, ' ').split(/\s+/).filter(t => t.length >= 3);
          const hasTokenMatch = (strA, strB) => {
            const tokensA = getTokens(strA);
            const tokensB = getTokens(strB);
            return tokensA.some(t => tokensB.includes(t));
          };

          const currentNameClean = cleanStr(currentName || currentUser?.name);
          const currentUsernameClean = cleanStr(currentUsername || currentUser?.username);
          const currentEmailClean = cleanStr(currentEmail || currentUser?.email);

          // 1. Real-time listener for Feed Posts authored by this user
          onSnapshot(collection(db, 'posts'), (querySnapshot) => {
            const loaded = [];
            querySnapshot.forEach((docSnap) => {
              const data = docSnap.data();

              const postAuthorUid = data.author?.uid || data.authorUid || data.uid || data.userUid || data.resharedBy?.uid;
              const authorNameStr = typeof data.author === 'string' ? data.author : (data.author?.name || data.authorName || data.resharedBy?.name || '');
              const authorUsernameStr = data.author?.username || data.authorUsername || data.resharedBy?.username || '';
              const authorEmailStr = data.author?.email || data.authorEmail || '';

              const postAuthorNameClean = cleanStr(authorNameStr);
              const postAuthorUsernameClean = cleanStr(authorUsernameStr);
              const postAuthorEmailClean = cleanStr(authorEmailStr);

              const isMatch =
                (currentUid && postAuthorUid === currentUid) ||
                (currentUser?.uid && postAuthorUid === currentUser.uid) ||
                (currentNameClean && (postAuthorNameClean === currentNameClean || postAuthorUsernameClean === currentNameClean)) ||
                (currentUsernameClean && (postAuthorNameClean === currentUsernameClean || postAuthorUsernameClean === currentUsernameClean)) ||
                (currentEmailClean && postAuthorEmailClean && postAuthorEmailClean === currentEmailClean) ||
                hasTokenMatch(authorNameStr, currentName) ||
                hasTokenMatch(authorNameStr, currentUsername) ||
                hasTokenMatch(authorUsernameStr, currentName) ||
                hasTokenMatch(authorUsernameStr, currentUsername) ||
                (isOwnProfile && (
                  hasTokenMatch(authorNameStr, currentUser?.name) ||
                  hasTokenMatch(authorNameStr, currentUser?.username) ||
                  hasTokenMatch(authorUsernameStr, currentUser?.name) ||
                  hasTokenMatch(authorUsernameStr, currentUser?.username)
                ));

              if (isMatch) {
                const likedUsers = data.likedUsers || data.upvotedUsers || data.likedBy || (Array.isArray(data.likes) ? data.likes : []);
                const likesCount = (typeof data.likes === 'number' && data.likes > 0)
                  ? data.likes
                  : (typeof data.upvotes === 'number' && data.upvotes > 0
                    ? data.upvotes
                    : (data.likesCount || likedUsers.length));
                let commentsCount = (typeof data.comments === 'number' && data.comments > 0)
                  ? data.comments
                  : (data.commentsCount || (Array.isArray(data.comments) ? data.comments.length : 0));

                loaded.push({
                  id: docSnap.id,
                  docId: docSnap.id,
                  collectionName: 'posts',
                  ...data,
                  likedUsers,
                  likesCount,
                  commentsCount,
                  timestamp: data.timestamp?.toDate ? data.timestamp.toDate() : new Date(data.timestamp || Date.now())
                });
              }
            });

            loaded.sort((a, b) => (b.timestamp?.getTime ? b.timestamp.getTime() : 0) - (a.timestamp?.getTime ? a.timestamp.getTime() : 0));
            setUserPosts(loaded);
            const likesSum = loaded.reduce((acc, curr) => acc + (curr.likesCount || 0), 0);
            setTotalLikes(likesSum);
          });

          // 2. Real-time listener for Anonymous Posts & Confessions authored by this user
          let rawAnonPosts = [];
          let rawConfessions = [];
          const updateAnonState = () => {
            const combined = [...rawAnonPosts, ...rawConfessions];
            combined.sort((a, b) => (b.createdAt?.getTime ? b.createdAt.getTime() : 0) - (a.createdAt?.getTime ? a.createdAt.getTime() : 0));
            setUserAnonPosts(combined);
          };

          onSnapshot(collection(db, 'anonymousPosts'), (snap) => {
            const loaded = [];
            snap.forEach((d) => {
              const data = d.data();
              const postAuthorUid = data.authorUid || data.uid || data.userUid || data.author?.uid;
              const postAuthorNameClean = cleanStr(data.anonymousName || data.authorName || data.author?.name);

              const isMatch =
                (currentUid && postAuthorUid === currentUid) ||
                (currentUser?.uid && postAuthorUid === currentUser.uid) ||
                (currentNameClean && postAuthorNameClean === currentNameClean) ||
                (currentUsernameClean && postAuthorNameClean === currentUsernameClean) ||
                hasTokenMatch(data.anonymousName, currentName) ||
                hasTokenMatch(data.anonymousName, currentUsername);

              if (isMatch) {
                const likedUsers = data.likedUsers || data.upvotedUsers || data.likedBy || (Array.isArray(data.likes) ? data.likes : []);
                const likesCount = (typeof data.likes === 'number' && data.likes > 0)
                  ? data.likes
                  : (typeof data.upvotes === 'number' && data.upvotes > 0
                    ? data.upvotes
                    : (data.likesCount || likedUsers.length));
                let commentsCount = (typeof data.comments === 'number' && data.comments > 0)
                  ? data.comments
                  : (data.commentsCount || (Array.isArray(data.comments) ? data.comments.length : 0));

                loaded.push({
                  id: d.id,
                  docId: d.id,
                  collectionName: 'anonymousPosts',
                  isAnonymous: true,
                  isConfession: false,
                  ...data,
                  likedUsers,
                  likesCount,
                  commentsCount,
                  createdAt: data.createdAt?.toDate ? data.createdAt.toDate() : new Date(data.createdAt || Date.now())
                });
              }
            });
            rawAnonPosts = loaded;
            updateAnonState();
          });

          onSnapshot(collection(db, 'confessions'), (snap) => {
            const loaded = [];
            snap.forEach((d) => {
              const data = d.data();
              const postAuthorUid = data.authorUid || data.uid || data.userUid || data.author?.uid;
              const postAuthorNameClean = cleanStr(data.anonymousName || data.authorName || data.author?.name);

              const isMatch =
                (currentUid && postAuthorUid === currentUid) ||
                (currentUser?.uid && postAuthorUid === currentUser.uid) ||
                (currentNameClean && postAuthorNameClean === currentNameClean) ||
                (currentUsernameClean && postAuthorNameClean === currentUsernameClean) ||
                hasTokenMatch(data.anonymousName, currentName) ||
                hasTokenMatch(data.anonymousName, currentUsername);

              if (isMatch) {
                const likedUsers = data.likedUsers || data.upvotedUsers || data.likedBy || (Array.isArray(data.likes) ? data.likes : []);
                const likesCount = (typeof data.likes === 'number' && data.likes > 0)
                  ? data.likes
                  : (typeof data.upvotes === 'number' && data.upvotes > 0
                    ? data.upvotes
                    : (data.likesCount || likedUsers.length));
                let commentsCount = (typeof data.comments === 'number' && data.comments > 0)
                  ? data.comments
                  : (data.commentsCount || (Array.isArray(data.comments) ? data.comments.length : 0));

                loaded.push({
                  id: d.id,
                  docId: d.id,
                  collectionName: 'confessions',
                  isAnonymous: true,
                  isConfession: true,
                  ...data,
                  likedUsers,
                  likesCount,
                  commentsCount,
                  createdAt: data.createdAt?.toDate ? data.createdAt.toDate() : new Date(data.createdAt || Date.now())
                });
              }
            });
            rawConfessions = loaded;
            updateAnonState();
          });

          // 3. Real-time listener for Marketplace Items authored by this user
          onSnapshot(collection(db, 'marketplace'), (snap) => {
            const loaded = [];
            snap.forEach((d) => {
              const data = d.data();
              const sellerUid = data.sellerUid || data.authorUid || data.uid;
              const sellerNameStr = data.seller || data.authorName || data.author?.name || '';
              const sellerNameClean = cleanStr(sellerNameStr);

              const isMatch =
                (currentUid && sellerUid === currentUid) ||
                (currentUser?.uid && sellerUid === currentUser.uid) ||
                (currentNameClean && sellerNameClean === currentNameClean) ||
                (currentUsernameClean && sellerNameClean === currentUsernameClean) ||
                hasTokenMatch(sellerNameStr, currentName) ||
                hasTokenMatch(sellerNameStr, currentUsername);

              if (isMatch) {
                loaded.push({
                  id: d.id,
                  docId: d.id,
                  ...data
                });
              }
            });
            setUserMarketplaceItems(loaded);
          });
        }
      } catch (e) {
        console.error('Failed to load profile:', e);
      } finally {
        setLoading(false);
      }
    };

const renderFormattedBio = (text) => {
    if (!text) return null;

    const lines = text.split('\n');

    return (
      <div className="space-y-1.5 mt-sm max-w-xl">
        {lines.map((line, lineIdx) => {
          const trimmed = line.trim();
          if (!trimmed) return <div key={lineIdx} className="h-1" />;

          const parseBold = (content) => {
            const parts = content.split(/(\*\*.*?\*\*)/g);
            return parts.map((part, i) => {
              if (part.startsWith('**') && part.endsWith('**')) {
                return (
                  <strong key={i} className="font-extrabold text-neutral-900 dark:text-white bg-gradient-to-r from-purple-400 via-pink-400 to-sky-400 bg-clip-text text-transparent">
                    {part.slice(2, -2)}
                  </strong>
                );
              }
              return part;
            });
          };

          if (trimmed.includes('•') || trimmed.startsWith('- ') || trimmed.startsWith('* ')) {
            const items = trimmed
              .split('•')
              .flatMap(item => item.split(/[-*]\s+/))
              .map(i => i.trim())
              .filter(Boolean);

            if (items.length > 1) {
              return (
                <div key={lineIdx} className="flex flex-wrap gap-2 my-1.5">
                  {items.map((item, itemIdx) => (
                    <span
                      key={itemIdx}
                      className="inline-flex items-center text-xs font-bold px-3 py-1 rounded-full bg-gradient-to-r from-purple-500/15 via-pink-500/15 to-indigo-500/15 text-purple-700 dark:text-purple-300 border border-purple-500/30 shadow-xs backdrop-blur-xs"
                    >
                      {parseBold(item)}
                    </span>
                  ))}
                </div>
              );
            }
          }

          return (
            <p key={lineIdx} className="text-sm text-neutral-700 dark:text-neutral-300 leading-relaxed font-medium">
              {parseBold(trimmed)}
            </p>
          );
        })}
      </div>
    );
  };

const useNotification = () => {
  const context = useContext(NotificationContext);
  if (!context) throw new Error('useNotification must be used within NotificationProvider');
  return context;
};

const handleChangePasswordSubmit = async (e) => {
    e.preventDefault();

    if (!oldPassword) {
      showError('Please enter your current (old) password.');
      return;
    }

    if (!newPassword || newPassword.length < 6) {
      showError('New password must be at least 6 characters long.');
      return;
    }

    if (newPassword !== confirmPassword) {
      showError('New password and confirm password do not match.');
      return;
    }

    setIsChangingPass(true);
    try {
      if (user?.email) {
        try {
          await login(user.email, oldPassword);
        } catch (authErr) {
          showError('Incorrect old password. If you forgot your password, click "Forgot old password?"');
          setIsChangingPass(false);
          return;
        }
      }

      await setPasswordForUser(newPassword);
      showSuccess('Password updated successfully! You can now log in using your new password.');
      setOldPassword('');
      setNewPassword('');
      setConfirmPassword('');
      setIsPasswordFormOpen(false);
    } catch (err) {
      console.error(err);
      showError(err.message || 'Failed to update password. Please try again.');
    } finally {
      setIsChangingPass(false);
    }
  };

const handleDeleteMsgForMe = async (msgId) => {
    if (!user?.uid || !msgId) return;
    const targetColl = isCollegeRoom ? 'community-messages' : `userCommunities/${selectedRoom.id}/messages`;
    try {
      await updateDoc(doc(db, targetColl, msgId), {
        deletedFor: arrayUnion(user.uid)
      });
      showSuccess('Message deleted for you 🗑️');
      setMsgToDeleteModal(null);
    } catch (e) { console.error(e); }
  };

export default function ShareModal({ isOpen, onClose, post, shareUrl: customShareUrl, title: customTitle }) {
  const { user } = useAuth();
  const { showSuccess, showError } = useNotification();

  const [searchQuery, setSearchQuery] = useState('');
  const [recentUsers, setRecentUsers] = useState([]);
  const [loadingUsers, setLoadingUsers] = useState(false);
  const [selectedUsers, setSelectedUsers] = useState([]);
  const [isSending, setIsSending] = useState(false);
  const [sentMap, setSentMap] = useState({});
  const [copied, setCopied] = useState(false);

  const rawAuthorName = post?.author?.name || post?.authorName || '';
  const shareTitle =
    customTitle ||
    (rawAuthorName ? (rawAuthorName.toLowerCase().startsWith('post by') ? rawAuthorName : `Post by ${rawAuthorName}`) : 'Campus Post');

  const isUncut = Boolean(customShareUrl?.includes('/uncut')) || Boolean(post?.id?.includes('-')) || Boolean(post?.category);
  const shareText =
    post?.content ||
    post?.excerpt ||
    post?.text ||
    post?.caption ||
    (isUncut
      ? 'Read unfiltered real campus stories written by peers on Cohort Uncut.'
      : 'Explore student conversations, gossip, confessions and stories on Cohort.');

  const postMediaUrl =
    post?.image ||
    post?.imageUrl ||
    post?.mediaUrl ||
    post?.photo ||
    post?.media ||
    post?.coverImage ||
    post?.storyImage ||
    '';

  const rawShareUrl = customShareUrl || (post?.id ? `${window.location.origin}/post/${post.id}` : window.location.href);
  const shareUrl = rawShareUrl.includes('?') ? rawShareUrl : `${rawShareUrl}?v=1`;

  // Fetch recent chat members and campus users when modal opens
  useEffect(() => {
    if (!isOpen) {
      setSearchQuery('');
      setSelectedUsers([]);
      setSentMap({});
      setCopied(false);
      return;
    }

    const fetchContacts = async () => {
      setLoadingUsers(true);
      try {
        const usersSnap = await getDocs(collection(db, 'users'));
        const list = [];
        usersSnap.forEach((d) => {
          const uid = d.id;
          if (
            user?.uid &&
            uid !== user.uid &&
            uid !== 'cohort_official' &&
            d.data()?.username !== 'cohort'
          ) {
            const data = d.data();
            list.push({
              uid,
              name: data.name || data.username || 'Campus Student',
              username: data.username || '',
              avatar:
                data.avatar ||
                `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(uid)}`,
              college: data.college || 'KIET'
            });
          }
        });

        setRecentUsers(list);
      } catch (err) {
        console.error('Error fetching share contacts:', err);
      } finally {
        setLoadingUsers(false);
      }
    };

    fetchContacts();
  }, [isOpen, user]);

  // Filter contacts by search query
  const filteredUsers = recentUsers.filter((u) => {
    const q = searchQuery.toLowerCase().trim();
    if (!q) return true;
    return (
      u.name.toLowerCase().includes(q) ||
      u.username.toLowerCase().includes(q) ||
      u.college.toLowerCase().includes(q)
    );
  });

  // Toggle user selection
  const toggleSelectUser = (targetUser) => {
    if (sentMap[targetUser.uid]) return;
    if (selectedUsers.some((u) => u.uid === targetUser.uid)) {
      setSelectedUsers(selectedUsers.filter((u) => u.uid !== targetUser.uid));
    } else {
      setSelectedUsers([...selectedUsers, targetUser]);
    }
  };

  // Batch send direct message to all selected contacts
  const handleSendBatch = async () => {
    if (!user) {
      showError('Please sign in to send direct messages.');
      return;
    }

    if (selectedUsers.length === 0) return;

    setIsSending(true);

    const cleanStr = (val, fallback = '') => (val === undefined || val === null ? fallback : String(val));

    try {
      const myUid = cleanStr(user?.uid);
      const myName = cleanStr(user?.name || user?.displayName || user?.email?.split('@')[0], 'Me');
      const myAvatar = cleanStr(
        user?.avatar || user?.photoURL,
        `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(myUid)}`
      );

      const safeTitle = cleanStr(shareTitle, 'Campus Post');
      const safeText = cleanStr(shareText, 'Check out this post on Cohort!');
      const safeUrl = cleanStr(shareUrl, window.location.href);
      const safeMediaUrl = cleanStr(
        post?.image || post?.imageUrl || post?.mediaUrl || post?.photo || post?.media || post?.coverImage || postMediaUrl,
        ''
      );
      const lastMsgSummary = `Shared a post: ${safeText.slice(0, 35)}${safeText.length > 35 ? '...' : ''}`;
      const nowIso = new Date().toISOString();

      // Fetch existing conversations for matching
      const messagesSnap = await getDocs(collection(db, 'messages'));
      const existingDocsMap = new Map();

      messagesSnap.forEach((docSnap) => {
        const data = docSnap.data();
        const parts = Array.isArray(data.participants) ? data.participants : [];

        // Match by participants array or createdBy/recipientUid fields
        selectedUsers.forEach((tUser) => {
          const targetUid = cleanStr(tUser.uid);
          const isMatch =
            (parts.includes(myUid) && parts.includes(targetUid)) ||
            (data.createdBy === myUid && data.recipientUid === targetUid) ||
            (data.createdBy === targetUid && data.recipientUid === myUid);

          if (isMatch && !existingDocsMap.has(targetUid)) {
            existingDocsMap.set(targetUid, { id: docSnap.id, ...data });
          }
        });
      });

      const sanitizeForFirestore = (val) => {
        if (val === undefined) return null;
        if (val === null || typeof val !== 'object') return val;
        if (val instanceof Date) return val;
        if (Array.isArray(val)) return val.map(sanitizeForFirestore);
        const clean = {};
        for (const key of Object.keys(val)) {
          if (val[key] !== undefined) {
            clean[key] = sanitizeForFirestore(val[key]);
          }
        }
        return clean;
      };

      const sendPromises = selectedUsers.map(async (targetUser) => {
        const targetUid = cleanStr(targetUser.uid);
        const targetName = cleanStr(targetUser.name, 'Campus Student');
        const targetAvatar = cleanStr(
          targetUser.avatar,
          `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(targetUid)}`
        );

        const isUncut = Boolean(safeUrl.includes('/uncut') || post?.id?.includes('-') || post?.category);
        const messageObj = sanitizeForFirestore({
          id: `msg_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
          sender: myUid,
          senderUid: myUid,
          senderName: myName,
          senderAvatar: myAvatar,
          text: isUncut 
            ? `📖 Shared Uncut Story: ${safeTitle}\n"${safeText.slice(0, 120)}${safeText.length > 120 ? '...' : ''}"\n${safeUrl}`
            : `Shared post by ${safeTitle}:\n"${safeText.slice(0, 120)}${safeText.length > 120 ? '...' : ''}"\n${safeUrl}`,
          time: nowIso,
          createdAt: nowIso,
          deletedFor: [],
          isSharedPost: true,
          isUncutStory: isUncut,
          sharedPostData: {
            id: cleanStr(post?.id, ''),
            title: safeTitle,
            content: safeText,
            url: safeUrl,
            mediaUrl: safeMediaUrl
          }
        });

        const existingDoc = existingDocsMap.get(targetUid);

        if (existingDoc) {
          const chatRef = doc(db, 'messages', existingDoc.id);
          const freshSnap = await getDoc(chatRef);
          const rawData = freshSnap.exists() ? freshSnap.data() : existingDoc;

          const rawMsgs = Array.isArray(rawData.messages) ? rawData.messages : [];
          const cleanExistingMsgs = rawMsgs.map((m) => {
            const cleanM = sanitizeForFirestore(m);
            return {
              ...cleanM,
              time: m.time?.toDate ? m.time.toDate().toISOString() : (m.time ? String(m.time) : nowIso)
            };
          });

          const resetHidden = {};
          if (rawData.hiddenFor) {
            Object.keys(rawData.hiddenFor).forEach((k) => {
              resetHidden[`hiddenFor.${k}`] = false;
            });
          }

          const updatePayload = sanitizeForFirestore({
            messages: [...cleanExistingMsgs, messageObj],
            lastMessage: lastMsgSummary,
            time: new Date(),
            readBy: [myUid],
            [`participantMap.${myUid}`]: { name: myName, avatar: myAvatar },
            [`participantMap.${targetUid}`]: { name: targetName, avatar: targetAvatar },
            ...resetHidden
          });

          await updateDoc(chatRef, updatePayload);
        } else {
          const newConvData = sanitizeForFirestore({
            recipientUid: targetUid,
            recipientName: targetName,
            recipientAvatar: targetAvatar,
            participants: [myUid, targetUid],
            participantMap: {
              [myUid]: { name: myName, avatar: myAvatar },
              [targetUid]: { name: targetName, avatar: targetAvatar }
            },
            createdBy: myUid,
            createdByName: myName,
            createdByAvatar: myAvatar,
            readBy: [myUid],
            avatar: targetAvatar,
            lastMessage: lastMsgSummary,
            time: new Date(),
            messages: [messageObj]
          });
          await addDoc(collection(db, 'messages'), newConvData);
        }
      });

      await Promise.all(sendPromises);

      const newSentMap = { ...sentMap };
      selectedUsers.forEach((u) => {
        newSentMap[u.uid] = true;
      });

      setSentMap(newSentMap);
      showSuccess(
        selectedUsers.length === 1
          ? `Sent to ${selectedUsers[0].name}!`
          : `Sent to ${selectedUsers.length} contacts!`
      );
      setSelectedUsers([]);
      setTimeout(() => {
        onClose();
      }, 700);
    } catch (err) {
      console.error('Error sending batch messages:', err);
      showError('Failed to send message. Please try again.');
    } finally {
      setIsSending(false);
    }
  };

  // Copy link handler
  const handleCopyLink = () => {
    navigator.clipboard.writeText(shareUrl);
    setCopied(true);
    showSuccess('Link copied to clipboard!');
    setTimeout(() => setCopied(false), 2500);
  };

  const handleSocialShare = async (platform) => {
    const isUncutStory = shareUrl.includes('/uncut') || Boolean(post?.category) || Boolean(post?.id?.includes('-')) || shareTitle.toLowerCase().includes('uncut');
    const encodedUrl = encodeURIComponent(shareUrl);

    switch (platform) {
      case 'whatsapp': {
        let waText = '';
        if (isUncutStory) {
          const storyTitle = post?.title || shareTitle.replace(/^(Uncut Story:?|College, Love Stories and the Dilemma \| Cohort Uncut)\s*/i, '');
          const authorName = post?.authorName || post?.author?.name || 'Cohort Uncut';
          const initialLines = (post?.content || post?.excerpt || post?.text || shareText || '').slice(0, 160);

          waText = `📖 *COHORT UNCUT* | *Story*\n\n` +
                   `*"${storyTitle}"*\n` +
                   `✍️ *By ${authorName}*\n\n` +
                   `"${initialLines}${initialLines.length >= 160 ? '...' : ''}"\n\n` +
                   `👉 *Read full story on Cohort:*\n${shareUrl}`;
        } else {
          waText = `✨ *Check this out on Cohort:*\n"${shareText.slice(0, 120)}"\n\n${shareUrl}`;
        }

        window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(waText)}`, '_blank');
        break;
      }
      case 'instagram':
        navigator.clipboard.writeText(shareUrl);
        showSuccess('Link copied! Opening Instagram...');
        setTimeout(() => {
          window.open('https://www.instagram.com/direct/inbox/', '_blank');
        }, 600);
        break;
      case 'facebook':
        window.open(`https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}`, '_blank');
        break;
      case 'messenger':
        window.open(`https://www.facebook.com/dialog/send?link=${encodedUrl}&app_id=291494419107518&redirect_uri=${encodedUrl}`, '_blank');
        break;
      case 'email':
        window.open(`mailto:?subject=${encodeURIComponent(shareTitle)}&body=${encodedText}`, '_blank');
        break;
      case 'threads':
        window.open(`https://www.threads.net/intent/post?text=${encodedText}`, '_blank');
        break;
      case 'twitter':
        window.open(`https://twitter.com/intent/tweet?text=${encodedText}`, '_blank');
        break;
      default:
        handleCopyLink();
    }
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
      <div className="fixed inset-0 z-[100] bg-black/70 backdrop-blur-sm flex items-center justify-center p-4">
        {/* Backdrop click to close */}
        <div className="absolute inset-0" onClick={onClose} />

        {/* Modal Card */}
        <motion.div
          initial={{ opacity: 0, scale: 0.95, y: 15 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.95, y: 15 }}
          transition={{ duration: 0.2, ease: 'easeOut' }}
          className="relative z-10 bg-white dark:bg-zinc-900 border border-neutral-200 dark:border-zinc-800 w-full max-w-md rounded-3xl shadow-2xl overflow-hidden text-neutral-900 dark:text-neutral-100 flex flex-col max-h-[90vh]"
        >
          {/* Header */}
          <div className="relative px-5 py-4 border-b border-neutral-100 dark:border-zinc-800 flex items-center justify-center">
            <button
              onClick={onClose}
              className="absolute left-4 p-1.5 rounded-full hover:bg-neutral-100 dark:hover:bg-zinc-800 text-neutral-500 dark:text-zinc-400 hover:text-neutral-900 dark:hover:text-white transition-colors"
            >
              <X className="w-5 h-5 stroke-[2.5]" />
            </button>
            <h3 className="font-extrabold text-base tracking-tight text-neutral-900 dark:text-white">
              Share
            </h3>
          </div>

          {/* Search Bar */}
          <div className="p-4 pb-2">
            <div className="relative flex items-center bg-neutral-100 dark:bg-zinc-800/80 border border-neutral-200 dark:border-zinc-700/60 rounded-xl px-3.5 py-2.5 focus-within:border-purple-500 dark:focus-within:border-purple-400 transition-all">
              <Search className="w-4 h-4 text-neutral-400 dark:text-zinc-400 mr-2 flex-shrink-0" />
              <input
                type="text"
                placeholder="Search contacts"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full bg-transparent text-sm font-medium text-neutral-900 dark:text-white placeholder-neutral-400 dark:placeholder-zinc-500 focus:outline-none"
              />
              {searchQuery && (
                <button
                  onClick={() => setSearchQuery('')}
                  className="text-neutral-400 hover:text-neutral-600 dark:text-zinc-400 dark:hover:text-white"
                >
                  <X className="w-3.5 h-3.5" />
                </button>
              )}
            </div>
          </div>

          {/* Contact Members Grid */}
          <div className="px-4 py-2 flex-1 overflow-y-auto max-h-[300px] scrollbar-thin">
            {loadingUsers ? (
              <div className="flex items-center justify-center py-10 text-neutral-400 text-xs font-semibold">
                Loading contacts...
              </div>
            ) : filteredUsers.length > 0 ? (
              <div className="grid grid-cols-4 gap-y-5 gap-x-3 py-2">
                {filteredUsers.map((u) => {
                  const isSent = sentMap[u.uid];
                  const isSelected = selectedUsers.some((sel) => sel.uid === u.uid);

                  return (
                    <div
                      key={u.uid}
                      onClick={() => toggleSelectUser(u)}
                      className="flex flex-col items-center cursor-pointer group text-center"
                    >
                      {/* Avatar Wrapper with Selection Badge */}
                      <div className="relative mb-1.5 flex-shrink-0">
                        <div
                          className={`w-16 h-16 rounded-full p-0.5 transition-all duration-200 group-hover:scale-105 ${
                            isSent
                              ? 'bg-emerald-500'
                              : isSelected
                              ? 'bg-purple-600 ring-2 ring-purple-500/80 scale-105'
                              : 'bg-neutral-200 dark:bg-zinc-700/60 group-hover:bg-neutral-400 dark:group-hover:bg-zinc-500'
                          }`}
                        >
                          <img
                            src={u.avatar}
                            alt={u.name}
                            className="w-full h-full rounded-full object-cover bg-neutral-200 dark:bg-zinc-800 border-2 border-white dark:border-zinc-900"
                          />
                        </div>

                        {/* Badge overlay */}
                        {isSent ? (
                          <div className="absolute -bottom-1 -right-1 bg-emerald-500 text-white p-1 rounded-full shadow-md border border-white dark:border-zinc-900">
                            <Check className="w-3 h-3 stroke-[3]" />
                          </div>
                        ) : isSelected ? (
                          <div className="absolute -bottom-1 -right-1 bg-purple-600 text-white p-1 rounded-full shadow-md border border-white dark:border-zinc-900">
                            <Check className="w-3 h-3 stroke-[3]" />
                          </div>
                        ) : (
                          <div className="absolute -bottom-1 -right-1 bg-neutral-800 dark:bg-zinc-700 text-white p-1 rounded-full shadow-md border border-white dark:border-zinc-900 opacity-0 group-hover:opacity-100 transition-opacity">
                            <Send className="w-2.5 h-2.5 fill-current" />
                          </div>
                        )}
                      </div>

                      {/* Name */}
                      <span className={`text-[11px] font-bold leading-tight line-clamp-2 w-full px-0.5 transition-colors ${
                        isSelected ? 'text-purple-600 dark:text-purple-400' : 'text-neutral-800 dark:text-neutral-200 group-hover:text-neutral-900 dark:group-hover:text-white'
                      }`}>
                        {u.name}
                      </span>
                    </div>
                  );
                })}
              </div>
            ) : (
              <div className="flex flex-col items-center justify-center py-10 text-neutral-400 text-xs">
                No users found
              </div>
            )}
          </div>

