                      return (
                        <div key={msg.id || msg.docId || `gmsg-${idx}`} id={`msg-${msg.id || idx}`} className={`transition-all duration-300 ${highlightedMsgId === msg.id ? 'ring-4 ring-amber-400 rounded-2xl p-1 bg-amber-500/20 shadow-2xl animate-pulse z-20' : ''}`}>
