function createIco(images) {
  const header = Buffer.alloc(6);
  header.writeUInt16LE(0, 0); // Reserved
  header.writeUInt16LE(1, 2); // Image type (1 = ICO)
  header.writeUInt16LE(images.length, 4); // Number of images

  const entries = [];
  let offset = 6 + 16 * images.length;

  for (const img of images) {
    const entry = Buffer.alloc(16);
    entry.writeUInt8(img.width >= 256 ? 0 : img.width, 0); // Width
    entry.writeUInt8(img.height >= 256 ? 0 : img.height, 1); // Height
    entry.writeUInt8(0, 2); // Color palette
    entry.writeUInt8(0, 3); // Reserved
    entry.writeUInt16LE(1, 4); // Color planes
    entry.writeUInt16LE(32, 6); // Bits per pixel
    entry.writeUInt32LE(img.buffer.length, 8); // Size of image data
    entry.writeUInt32LE(offset, 12); // Offset of image data

    entries.push(entry);
    offset += img.buffer.length;
  }

  const buffers = [header, ...entries, ...images.map(img => img.buffer)];
  return Buffer.concat(buffers);
}

function CollegeSelector({ value, onChange, className = '' }) {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const containerRef = useRef(null);

  // Close dropdown on outside click
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (containerRef.current && !containerRef.current.contains(e.target)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Sync search input display with selected value when dropdown is closed
  useEffect(() => {
    if (!isOpen) {
      setSearchTerm(value || '');
    }
  }, [isOpen, value]);

  // Filter colleges based on user search term
  const filteredColleges = useMemo(() => {
    if (!searchTerm.trim()) return INDIAN_COLLEGES;
    const term = searchTerm.toLowerCase().trim();
    return INDIAN_COLLEGES.filter(c => c.toLowerCase().includes(term));
  }, [searchTerm]);

  const handleSelect = (collegeName) => {
    onChange(collegeName);
    setSearchTerm(collegeName);
    setIsOpen(false);
  };

  const handleInputChange = (e) => {
    const val = e.target.value;
    setSearchTerm(val);
    onChange(val);
    if (!isOpen) setIsOpen(true);
  };

  return (
    <div className={`space-y-1.5 relative ${className}`} ref={containerRef}>
      <label className="block font-semibold text-sm text-neutral-700 dark:text-neutral-300">
        College / University
      </label>

      {/* Clean Input Field */}
      <div className="relative">
        <GraduationCap className="w-4 h-4 text-neutral-400 dark:text-neutral-500 absolute left-3.5 top-1/2 -translate-y-1/2" />

        <input
          type="text"
          value={searchTerm}
          onFocus={() => setIsOpen(true)}
          onChange={handleInputChange}
          placeholder="Select or search college..."
          className="w-full pl-10 pr-9 py-2.5 rounded-xl bg-neutral-50 dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 text-sm text-neutral-900 dark:text-neutral-100 placeholder:text-neutral-400 focus:outline-none focus:border-purple-500 focus:ring-1 focus:ring-purple-500 transition-all font-medium"
        />

        {searchTerm ? (
          <button
            type="button"
            onClick={() => {
              setSearchTerm('');
              onChange('');
              setIsOpen(true);
            }}
            className="absolute right-3 top-1/2 -translate-y-1/2 text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-200 p-0.5"
          >
            <X className="w-3.5 h-3.5" />
          </button>
        ) : (
          <ChevronDown
            className={`w-4 h-4 text-neutral-400 dark:text-neutral-500 absolute right-3 top-1/2 -translate-y-1/2 transition-transform duration-200 pointer-events-none ${
              isOpen ? 'rotate-180 text-purple-500' : ''
            }`}
          />
        )}
      </div>

      {/* Floating Dropdown List */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: -4, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -4, scale: 0.98 }}
            transition={{ duration: 0.15 }}
            className="absolute left-0 right-0 top-full mt-1 z-50 max-h-60 overflow-y-auto rounded-xl bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 shadow-xl shadow-black/10 dark:shadow-black/40 divide-y divide-neutral-100 dark:divide-neutral-800/60"
          >
            {filteredColleges.length > 0 ? (
              filteredColleges.map((college, idx) => {
                const isSelected = value?.toLowerCase().trim() === college.toLowerCase().trim();
                return (
                  <button
                    key={idx}
                    type="button"
                    onClick={() => handleSelect(college)}
                    className={`w-full flex items-center justify-between px-3.5 py-2.5 text-left text-xs sm:text-sm transition-colors cursor-pointer ${
                      isSelected
                        ? 'bg-purple-500/10 text-purple-600 dark:text-purple-400 font-bold'
                        : 'text-neutral-700 dark:text-neutral-300 hover:bg-neutral-50 dark:hover:bg-neutral-800/60 font-medium'
                    }`}
                  >
                    <span className="truncate pr-2">{college}</span>
                    {isSelected && (
                      <Check className="w-4 h-4 text-purple-600 dark:text-purple-400 flex-shrink-0" />
                    )}
                  </button>
                );
              })
            ) : (
              <div className="px-3.5 py-3 text-xs text-neutral-400 dark:text-neutral-500 text-center">
                Press enter to use "{searchTerm}"
              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

const handleSendOTP = async (e) => {
    if (e) e.preventDefault();
    setErrorMsg('');
    const targetEmail = emailInput.trim();

    if (!targetEmail) {
      setErrorMsg('Email address is required.');
      return;
    }

    if (!isCollegeEmail(targetEmail)) {
      setErrorMsg('Please enter a valid student/college email address (e.g. ends with .edu, .ac.in, etc.).');
      return;
    }

    // Verify it matches the user's selected college
    const isMatching = verifyEmailMatchesCollege(targetEmail, currentCollege);
    if (!isMatching) {
      setErrorMsg(`This email does not seem to belong to "${currentCollege}". Please use your official email for this campus.`);
      return;
    }

    setIsLoading(true);
    try {
      const generatedOtp = Math.floor(100000 + Math.random() * 900000).toString();
      const emailKey = targetEmail.toLowerCase();

      // 1. Store verification OTP in Firestore
      await setDoc(doc(db, 'otps', `kyc_${user.uid}`), {
        otp: generatedOtp,
        email: emailKey,
        createdAt: new Date().toISOString()
      });

      // 2. Dispatch email via send-otp API
      const isMobileApp = Capacitor.isNativePlatform();
      const apiUrl = isMobileApp ? `https://www.cohortnow.online/api/send-otp` : '/api/send-otp';

      const response = await fetch(apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ email: emailKey, otp: generatedOtp }),
      });

      const resData = await response.json();

      if (!response.ok) {
        throw new Error(resData.error || 'Failed to dispatch email.');
      }

      showSuccess('Verification code sent to your student email!');

      // Developer Mode convenience
      if (resData.otp) {
        console.log(`%c[KYC OTP Code (Dev Mode)] ${resData.otp}`, 'color: #ea580c; font-size: 16px; font-weight: bold;');
        if (resData.previewUrl) {
          console.log(`[Email Preview Link] ${resData.previewUrl}`);
        }
        showSuccess(`[Dev Mode] OTP is ${resData.otp} (Logged to console)`);
      }

      setStep(2);
      setResendTimer(30);
    } catch (err) {
      console.error(err);
      setErrorMsg(err.message || 'Failed to send OTP code. Please try again.');
      showError('Failed to send OTP code. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

const handleOfficialAvatarSelect = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      setIsUploadingOfficialAvatar(true);
      const preview = URL.createObjectURL(file);
      setOfficialAvatarPreview(preview);

      const compressed = await compressImage(file);
      const uploadedUrl = await uploadImageToCloudinary(compressed);

      if (uploadedUrl) {
        setOfficialAvatarUrl(uploadedUrl);
        setOfficialAvatarPreview(uploadedUrl);
      } else {
        const reader = new FileReader();
        reader.onloadend = () => {
          setOfficialAvatarUrl(reader.result);
