                          src={userItem.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(userItem.name || 'user')}`}
                          alt={userItem.name}
                          className="w-10 h-10 rounded-full object-cover border border-neutral-700 group-hover:scale-105 transition-transform"
                        />
                        <div className="min-w-0 flex-1">
                          <div className="flex items-center gap-2">
                            <p className="font-bold text-sm text-white group-hover:text-primary-400 transition-colors truncate">
                              {userItem.name}
                            </p>
                            {isMutualPeer && (
                              <span className="px-2 py-0.5 rounded-full text-[9px] font-extrabold bg-sky-500/10 text-sky-400 border border-sky-500/20">
                                Mutual
                              </span>
                            )}
                          </div>
                          <p className="text-xs text-neutral-400 font-mono truncate">
                            @{userItem.username || (userItem.name || 'user').toLowerCase().replace(/\s+/g, '')}
                          </p>
                          {isMutualPeer && (
                            <p className="text-[10px] text-neutral-500 font-medium">
                              Followed by you
                            </p>
                          )}
                        </div>
                      </div>

                      {/* Action Buttons */}
                      <div className="flex items-center gap-2">
                        {!isSelf && (
                          <button
                            onClick={() => handleListUserFollow(userItem.uid, isFollowingUser, userItem.name)}
                            className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all flex items-center gap-1 ${
                              isFollowingUser
                                ? 'bg-neutral-800 text-neutral-300 hover:bg-neutral-700'
                                : 'bg-primary-500 hover:bg-primary-600 text-white shadow-md shadow-primary-500/20'
                            }`}
                          >
                            {isFollowingUser ? (
                              <>
                                <UserCheck className="w-3.5 h-3.5 text-success" />
                                <span>Following</span>
                              </>
                            ) : (
                              <>
                                <UserPlus className="w-3.5 h-3.5" />
                                <span>Follow</span>
                              </>
                            )}
                          </button>
                        )}

                        <button
                          onClick={() => {
                            setConnectionsModalOpen(false);
                            navigate(`/messages?recipientUid=${userItem.uid}&recipientName=${encodeURIComponent(userItem.name)}`);
                          }}
                          className="p-2 bg-neutral-800 hover:bg-neutral-700 text-white rounded-xl transition-colors"
                          title="Message"
                        >
                          <MessageCircleCode className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  );
                })
              )}
            </div>
          </div>
        </div>
      )}

      {/* ── LIKES LIST MODAL ── */}
      {selectedPostForLikes && (
        <Modal
          isOpen={Boolean(selectedPostForLikes)}
          onClose={() => { setSelectedPostForLikes(null); setLikedUsersList([]); }}
          title="Liked By"
          size="sm"
        >
          <div className="space-y-md">
            {loadingLikedUsers ? (
              <div className="space-y-sm py-xl text-center">
                <Loader2 className="w-6 h-6 animate-spin text-primary-500 mx-auto" />
                <p className="text-xs text-neutral-400">Loading likes list...</p>
              </div>
            ) : likedUsersList.length > 0 ? (
              <div className="space-y-xs max-h-80 overflow-y-auto pr-xs scrollbar-thin">
                {likedUsersList.map((u) => (
                  <div
                    key={u.uid}
                    onClick={() => {
                      setSelectedPostForLikes(null);
                      navigate(`/profile?uid=${u.uid}`);
                    }}
                    className="flex items-center justify-between p-sm rounded-xl hover:bg-neutral-100 dark:hover:bg-neutral-800/80 cursor-pointer transition-colors"
                  >
                    <div className="flex items-center gap-md min-w-0">
                      <img
                        src={u.avatar}
                        alt={u.name}
                        className="w-10 h-10 rounded-full object-cover flex-shrink-0 bg-neutral-800 border border-neutral-700"
                      />
                      <div className="min-w-0">
                        <h4 className="font-bold text-xs text-neutral-900 dark:text-white truncate">
                          {u.name}
                        </h4>
                        <p className="text-[10px] text-neutral-500 truncate">
                          {u.college}
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-xs">
                      <Heart className="w-4 h-4 text-rose-500 fill-rose-500 flex-shrink-0" />
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="text-center py-xl">
                <Heart className="w-10 h-10 text-neutral-300 dark:text-neutral-700 mx-auto mb-xs" />
                <p className="text-xs font-bold text-neutral-600 dark:text-neutral-400">No likes yet</p>
                <p className="text-[10px] text-neutral-400 mt-1">Be the first to like this post!</p>
              </div>
            )}
          </div>
        </Modal>
      )}

      {/* ── COMMENTS & DISCUSSION MODAL ── */}
      {selectedPostForComments && (
        <Modal
          isOpen={Boolean(selectedPostForComments)}
          onClose={() => { setSelectedPostForComments(null); setCommentsList([]); setNewCommentText(''); }}
          title="Comments & Discussion"
          size="md"
        >
          <div className="space-y-lg flex flex-col max-h-[75vh]">
            {/* Post Summary Header */}
            <div className="p-md rounded-xl bg-neutral-50 dark:bg-neutral-800/60 border border-neutral-200/60 dark:border-neutral-700/60 space-y-xs flex-shrink-0">
              <p className="text-xs font-semibold text-neutral-900 dark:text-white leading-relaxed line-clamp-3">
                {selectedPostForComments.thought || selectedPostForComments.content || selectedPostForComments.text || 'Post details'}
              </p>
              <div className="flex items-center justify-between text-[10px] text-neutral-400 font-mono pt-xs">
                <span>{formatRelativeTime(selectedPostForComments.timestamp || selectedPostForComments.createdAt)}</span>
                <span className="text-primary-500 font-bold">{commentsList.length} comments</span>
              </div>
            </div>

            {/* Comments List */}
            <div className="flex-1 overflow-y-auto space-y-md pr-xs scrollbar-thin min-h-[150px] max-h-[300px]">
              {loadingComments ? (
                <div className="py-xl text-center space-y-xs">
                  <Loader2 className="w-6 h-6 animate-spin text-primary-500 mx-auto" />
                  <p className="text-xs text-neutral-400">Loading comments...</p>
                </div>
              ) : commentsList.length > 0 ? (
                commentsList.map((c) => (
                  <div key={c.id} className="p-md rounded-xl bg-neutral-100/70 dark:bg-neutral-800/50 border border-neutral-200/40 dark:border-neutral-700/40 space-y-xs">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-sm">
                        <UserAvatar
                          src={c.authorAvatar}
                          name={c.authorName || 'Student'}
                          className="w-6 h-6 rounded-full object-cover border border-neutral-700"
                        />
                        <span className="font-bold text-xs text-neutral-900 dark:text-white">
                          {c.authorName || 'Student'}
                        </span>
                      </div>

                      <div className="flex items-center gap-xs">
                        <span className="text-[10px] text-neutral-400 font-mono">
                          {c.displayDateText || 'Recently'}
                        </span>
                        <button
                          type="button"
                          onClick={() => handleReplyToComment(c)}
                          className="flex items-center gap-1 text-[10px] font-bold text-primary-500 hover:text-primary-400 px-2 py-0.5 rounded-md hover:bg-primary-500/10 transition-colors cursor-pointer ml-xs"
                        >
                          <MessageSquare className="w-3 h-3" />
                          <span>Reply</span>
                        </button>
                      </div>
                    </div>
                    <p className="text-xs text-neutral-700 dark:text-neutral-300 leading-relaxed pl-8">
                      {c.text}
                    </p>
                  </div>
                ))
              ) : (
                <div className="text-center py-xl">
                  <MessageSquare className="w-8 h-8 text-neutral-300 dark:text-neutral-700 mx-auto mb-xs" />
                  <p className="text-xs text-neutral-400 font-medium">No comments on this post yet.</p>
                  <p className="text-[10px] text-neutral-500 mt-0.5">Start the conversation below!</p>
                </div>
              )}
            </div>

            {/* Replying Banner */}
            {replyingToComment && (
              <div className="flex items-center justify-between px-md py-xs bg-primary-500/10 border border-primary-500/30 rounded-xl text-xs text-primary-400 font-semibold flex-shrink-0">
                <span>Replying to <strong className="text-white">@{replyingToComment.authorName}</strong></span>
                <button
                  type="button"
                  onClick={() => {
                    setReplyingToComment(null);
                    setNewCommentText('');
                  }}
                  className="text-neutral-400 hover:text-white p-0.5 cursor-pointer"
                >
                  <X className="w-3.5 h-3.5" />
                </button>
              </div>
            )}

            {/* Comment Form */}
            <form onSubmit={handleAddComment} className="flex gap-sm items-center pt-md border-t border-neutral-100 dark:border-neutral-800 flex-shrink-0">
              <input
                ref={commentInputRef}
                type="text"
                placeholder={replyingToComment ? `Replying to @${replyingToComment.authorName}...` : "Write a comment..."}
                value={newCommentText}
                onChange={(e) => setNewCommentText(e.target.value)}
                className="flex-1 px-md py-xs bg-neutral-100 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl text-xs outline-none text-neutral-900 dark:text-white placeholder-neutral-400 focus:ring-1 focus:ring-primary-500"
              />
              <Button
                type="submit"
                size="sm"
                variant="primary"
                disabled={!newCommentText.trim() || submittingComment}
                className="flex items-center gap-xs text-xs"
              >
                {submittingComment ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Send className="w-3.5 h-3.5" />}
                <span>Post</span>
              </Button>
            </form>
          </div>
        </Modal>
      )}

      {/* Modal to Edit Cohort Official Account */}
      {isEditOfficialModalOpen && isOfficialLoggedIn && (
        <Modal
          isOpen={isEditOfficialModalOpen}
          onClose={() => setIsEditOfficialModalOpen(false)}
          title="Edit Official Cohort Profile"
        >
          <div className="space-y-lg">
            {/* Avatar Edit */}
            <div className="flex flex-col items-center gap-sm">
              <div className="relative">
                <UserAvatar
                  src={officialAvatarPreview || 'https://ui-avatars.com/api/?name=Cohort&background=9333ea&color=fff&bold=true&size=128'}
                  name="Cohort"
                  className="w-24 h-24 rounded-full border-4 border-purple-500/40 object-cover shadow-xl"
                />
                {isUploadingOfficialAvatar && (
                  <div className="absolute inset-0 bg-black/60 rounded-full flex items-center justify-center">
                    <Loader2 className="w-6 h-6 text-purple-400 animate-spin" />
                  </div>
                )}
              </div>
              <input
                ref={officialFileInputRef}
                type="file"
                accept="image/*"
                className="hidden"
                onChange={handleOfficialAvatarSelect}
              />
              <Button
                variant="secondary"
                size="sm"
                className="flex items-center gap-xs text-xs font-bold border-purple-500/30 text-purple-600 dark:text-purple-300 hover:bg-purple-500/10"
                onClick={() => officialFileInputRef.current?.click()}
                disabled={isUploadingOfficialAvatar}
              >
                <Camera className="w-4 h-4 text-purple-500" /> Change Official Image
              </Button>
            </div>

            {/* Bio Edit */}
            <div>
              <label className="block text-xs font-bold text-neutral-700 dark:text-neutral-300 mb-xs uppercase tracking-wider">
                Official Account Bio
              </label>
              <textarea
                value={officialBioInput}
                onChange={(e) => setOfficialBioInput(e.target.value)}
                placeholder="Enter official account bio..."
                className="w-full p-md bg-neutral-50 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl text-sm outline-none focus:ring-2 focus:ring-purple-500 text-neutral-900 dark:text-white leading-relaxed resize-none"
                rows={4}
              />
            </div>

            {/* Modal Actions */}
            <div className="flex items-center justify-end gap-md pt-md border-t border-neutral-100 dark:border-neutral-800">
              <Button
                variant="ghost"
                onClick={() => setIsEditOfficialModalOpen(false)}
                disabled={isSavingOfficial}
              >
                Cancel
              </Button>
              <Button
                variant="primary"
                onClick={handleSaveOfficialProfile}
                disabled={isSavingOfficial || isUploadingOfficialAvatar}
                className="bg-purple-600 hover:bg-purple-700 text-white font-bold"
              >
                {isSavingOfficial ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin mr-1" /> Saving...
                  </>
                ) : (
                  'Save Changes'
                )}
              </Button>
            </div>
          </div>
        </Modal>
      )}

      {/* Instagram-style Share Modal */}
      <ShareModal
        isOpen={isProfileShareOpen}
        onClose={() => setIsProfileShareOpen(false)}
        shareUrl={window.location.href}
        title={`Profile: ${profileUser?.name || 'Cohort Student'}`}
      />
    </div>
  );
}

const formatTime = (date) => {
    if (!date) return '';
    const d = date instanceof Date ? date : new Date(date);
    return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

export const UsernameModal = () => {
  const { user, updateUser, isAuthenticated, setPasswordForUser } = useAuth();
  const { showSuccess } = useNotification();

  const [usernameInput, setUsernameInput] = useState('');
  const [nameInput, setNameInput] = useState(user?.name || '');
  const [passwordInput, setPasswordInput] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [checking, setChecking] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');

  // Extended Onboarding States
  const [avatarFile, setAvatarFile] = useState(null);
  const [avatarPreviewUrl, setAvatarPreviewUrl] = useState(null);
  const [cropperSrc, setCropperSrc] = useState(null);

  const [collegeInput, setCollegeInput] = useState(user?.college || '');

  const [gender, setGender] = useState('Prefer not to say');
  const [year, setYear] = useState('1st Year');
  const [dob, setDob] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef(null);

  // Sync name input when user profile is loaded
  useEffect(() => {
    if (user) {
      setNameInput(user.name || '');
      setCollegeInput(user.college || '');
    }
  }, [user]);

  // Keep modal open if authenticated and either username or onboarding incomplete
  if (!isAuthenticated || !user || (user.username && user.onboarded)) {
    return null;
  }

  const handleCreateUsername = async (e) => {
    e.preventDefault();
    setErrorMsg('');

    const cleanName = nameInput.trim();
    if (!cleanName || cleanName.length < 2) {
      setErrorMsg('Display Name must be at least 2 characters long.');
      return;
    }

    const cleanUsername = usernameInput.trim().toLowerCase().replace(/[^a-z0-9_.]/g, '');

    if (!cleanUsername || cleanUsername.length < 3) {
      setErrorMsg('Username must be at least 3 characters long (letters, numbers, underscores).');
      return;
    }

    if (!user.hasPassword) {
      if (!passwordInput || passwordInput.length < 6) {
        setErrorMsg('Password must be at least 6 characters long.');
        return;
      }
    }

    if (!collegeInput.trim()) {
      setErrorMsg('Please select or enter your college / university name.');
      return;
    }

    if (!dob) {
      setErrorMsg('Please select your Date of Birth.');
      return;
    }

    setChecking(true);
    try {
      // Query Firestore users collection for existing username
      const q = query(collection(db, 'users'), where('username', '==', cleanUsername));
      const querySnapshot = await getDocs(q);

      let isTaken = false;
      querySnapshot.forEach((docSnap) => {
        if (docSnap.id !== user.uid) {
          isTaken = true;
        }
      });

      if (isTaken) {
        setErrorMsg(`Username "@${cleanUsername}" is already taken. Please try another.`);
        setChecking(false);
        return;
      }

      // 1. Set chosen password in Firebase Auth first if user does not have a password
      if (!user.hasPassword) {
        await setPasswordForUser(passwordInput);
      }

      // 2. Upload profile picture if selected
      let uploadedAvatarUrl = user.avatar || null;
      if (avatarFile) {
        setIsUploading(true);
        uploadedAvatarUrl = await uploadImageToCloudinary(avatarFile);
      }

      // 3. Update Firestore user document
      const userRef = doc(db, 'users', user.uid);
      const isCollege = isCollegeEmail(user.email);
      const isMatching = isCollege && verifyEmailMatchesCollege(user.email, collegeInput);

      const onboardingData = {
        name: cleanName,
        username: cleanUsername,
        avatar: uploadedAvatarUrl || avatarPreviewUrl || user.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${cleanUsername}`,
        college: collegeInput,
        gender: gender,
        year: year,
        dob: dob,
        onboarded: true,
        kycVerified: isMatching,
        kycEmail: isMatching ? user.email : null,
        kycGender: isMatching ? predictGenderFromName(user.email) : null
      };

      await updateDoc(userRef, onboardingData);
      await updateUser(onboardingData);
      showSuccess(`Welcome! Your unique username is @${cleanUsername}`);
    } catch (err) {
      console.error('Error during onboarding setup:', err);
      setErrorMsg(err.message || 'Failed to complete onboarding. Please try again.');
    } finally {
      setChecking(false);
      setIsUploading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto bg-black/70 backdrop-blur-md flex justify-center items-start sm:items-center p-md sm:p-lg py-xl">
      <div className="bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-3xl p-lg sm:p-xl max-w-md w-full shadow-2xl my-auto space-y-md sm:space-y-lg animate-in fade-in zoom-in duration-200">
        <div className="text-center space-y-sm">
          <div className="w-12 h-12 bg-primary-50 dark:bg-primary-950/50 rounded-xl flex items-center justify-center mx-auto text-primary-500 shadow-inner">
            <Sparkles className="w-6 h-6 animate-pulse" />
          </div>
          <h2 className="text-xl sm:text-2xl font-heading font-bold text-neutral-900 dark:text-white">
            Complete Your Profile Setup
          </h2>
          <p className="text-xs text-neutral-500 dark:text-neutral-400 max-w-sm mx-auto leading-relaxed">
            Welcome to Cohort! Let's set up your campus profile so classmates can connect with you directly.
          </p>
        </div>

        <form onSubmit={handleCreateUsername} className="space-y-md">
          {/* Avatar Upload */}
          <div className="flex flex-col items-center space-y-sm pb-xs">
            <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
              <img
                src={avatarPreviewUrl || user?.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(user?.email || 'user')}`}
                alt="Avatar"
                className="w-20 h-20 rounded-full border-4 border-primary-500 object-cover shadow-md group-hover:opacity-80 transition-opacity"
              />
              <div className="absolute inset-0 flex items-center justify-center bg-black/40 rounded-full opacity-0 group-hover:opacity-100 transition-opacity">
                <Camera className="w-5 h-5 text-white" />
              </div>
              <input
                type="file"
                ref={fileInputRef}
                onChange={(e) => {
                  const file = e.target.files[0];
                  if (file) {
                    setCropperSrc(URL.createObjectURL(file));
                  }
                }}
                accept="image/*"
                className="hidden"
              />
            </div>
            <div className="flex gap-sm">
              <Button type="button" size="sm" variant="secondary" onClick={() => fileInputRef.current?.click()}>
                Upload Photo
              </Button>
              {(avatarPreviewUrl || user?.avatar) && (
                <Button
                  type="button"
                  size="sm"
                  variant="ghost"
                  className="text-danger hover:bg-red-50 dark:hover:bg-red-950/20"
                  onClick={() => {
                    setAvatarFile(null);
                    setAvatarPreviewUrl(`https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(user?.email || 'user')}`);
                  }}
                >
                  Remove
                </Button>
              )}
            </div>
          </div>

          {/* Display Name */}
          <div>
            <label className="block text-xs font-bold uppercase tracking-wider text-neutral-500 mb-xs">
              Display Name
            </label>
            <div className="relative">
              <input
                type="text"
                placeholder="e.g. Vansh"
                value={nameInput}
                onChange={(e) => {
                  setNameInput(e.target.value);
                  setErrorMsg('');
                }}
                className="input-base text-sm"
                required
              />
            </div>
          </div>

          {/* Username */}
          <div>
            <label className="block text-xs font-bold uppercase tracking-wider text-neutral-500 mb-xs">
              Username Handle
            </label>
            <div className="relative">
              <span className="absolute left-md top-1/2 -translate-y-1/2 text-neutral-400 font-bold text-sm">@</span>
              <input
                type="text"
                placeholder="e.g. alex_student"
                value={usernameInput}
                onChange={(e) => {
                  setUsernameInput(e.target.value);
                  setErrorMsg('');
                }}
                className="input-base pl-2xl font-mono text-sm"
                required
              />
            </div>
            {errorMsg ? (
              <p className="text-xs text-danger mt-xs">{errorMsg}</p>
            ) : (
              <p className="text-[10px] text-neutral-400 mt-xs">
                Letters, numbers, and underscores allowed. Must be unique.
              </p>
            )}
          </div>

          {/* Choose Password (only shown if not set) */}
          {!user.hasPassword && (
            <div>
              <label className="block text-xs font-bold uppercase tracking-wider text-neutral-500 mb-xs">
                Choose Password
              </label>
              <div className="relative">
                <input
                  type={showPassword ? 'text' : 'password'}
                  placeholder="Choose password (min 6 chars)"
                  value={passwordInput}
                  onChange={(e) => {
                    setPasswordInput(e.target.value);
                    setErrorMsg('');
                  }}
                  className="input-base pr-2xl text-sm"
                  required
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute inset-y-0 right-0 pr-md flex items-center text-neutral-400 hover:text-neutral-200 transition-colors"
                >
                  {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                </button>
              </div>
            </div>
          )}

          {/* University/College */}
          <CollegeSelector
            value={collegeInput}
            onChange={(newCollege) => setCollegeInput(newCollege)}
          />

          {/* Gender and Year */}
          <div className="grid grid-cols-2 gap-md">
            <div>
              <label className="block text-xs font-bold uppercase tracking-wider text-neutral-500 mb-xs">
                Gender
              </label>
              <select
                value={gender}
                onChange={(e) => setGender(e.target.value)}
                className="input-base text-sm h-10 py-0"
              >
                <option value="Male">Male</option>
                <option value="Female">Female</option>
                <option value="Non-binary">Non-binary</option>
                <option value="Prefer not to say">Prefer not to say</option>
              </select>
            </div>

            <div>
              <label className="block text-xs font-bold uppercase tracking-wider text-neutral-500 mb-xs">
                Year of Study
              </label>
              <select
                value={year}
                onChange={(e) => setYear(e.target.value)}
                className="input-base text-sm h-10 py-0"
              >
                <option value="1st Year">1st Year</option>
                <option value="2nd Year">2nd Year</option>
                <option value="3rd Year">3rd Year</option>
                <option value="4th Year">4th Year</option>
                <option value="5th Year">5th Year</option>
                <option value="Post Graduate">Post Graduate</option>
              </select>
            </div>
          </div>

          {/* DOB */}
          <div>
            <label className="block text-xs font-bold uppercase tracking-wider text-neutral-500 mb-xs">
              Date of Birth (DOB)
            </label>
            <input
              type="date"
              value={dob}
              onChange={(e) => setDob(e.target.value)}
              className="input-base text-sm h-10"
              required
            />
          </div>

          <Button
            type="submit"
            variant="primary"
            size="lg"
