const isCollegeEmail = (email) => {
  if (!email || typeof email !== 'string') return false;
  const domain = email.trim().toLowerCase().split('@')[1];
  if (!domain) return false;

  // Suffix checks:
  // - .edu (e.g. stanford.edu)
  // - .edu.xx (e.g. college.edu.in, college.edu.co)
  // - .ac.xx (e.g. iitd.ac.in, cam.ac.uk)
  // - .res.in (some research institutes in India)
  const academicRegex = /(\.edu|\.edu\.[a-z]{2}|\.ac\.[a-z]{2}|\.res\.in)$/i;

  // Custom popular exceptions that are academic but might not use the standard suffixes
  const customAcademicDomains = [
    'christuniversity.in',
    'srmist.edu.in',
    'mahe.edu',
    'manipal.edu',
    'symbiosis.ac.in'
  ];

  return academicRegex.test(domain) || customAcademicDomains.includes(domain);
};

const handleCollegePollVote = async (msgId, optIndex) => {
    const targetMsg = messages.find(m => m.id === msgId);
    if (!targetMsg || !targetMsg.poll) return;

    const targetPoll = targetMsg.poll;
    const isMultiple = targetPoll.pollType === 'multiple';
    const myUid = user?.uid || 'guest_user';

    const updatedOptions = (targetPoll.options || []).map((o, idx) => {
      const currentVotedUsers = Array.isArray(o.votedUsers)
        ? o.votedUsers
        : (o.selected ? [myUid] : []);
      const hasVoted = currentVotedUsers.includes(myUid);

      if (idx === optIndex) {
        if (hasVoted) {
          const nextVoted = currentVotedUsers.filter(id => id !== myUid);
          return { ...o, votedUsers: nextVoted, votes: nextVoted.length, selected: false };
        } else {
          const nextVoted = [...currentVotedUsers, myUid];
          return { ...o, votedUsers: nextVoted, votes: nextVoted.length, selected: true };
        }
      } else if (!isMultiple) {
        const nextVoted = currentVotedUsers.filter(id => id !== myUid);
        return { ...o, votedUsers: nextVoted, votes: nextVoted.length, selected: false };
      }
      return { ...o, votedUsers: currentVotedUsers, votes: currentVotedUsers.length, selected: currentVotedUsers.includes(myUid) };
    });

    const newTotalVotes = updatedOptions.reduce((sum, o) => sum + (o.votedUsers?.length || 0), 0);
    const updatedPoll = { ...targetPoll, options: updatedOptions, totalVotes: newTotalVotes };
    const updatedMsg = { ...targetMsg, poll: updatedPoll };

    setMessages(prev => prev.map(m => m.id === msgId ? updatedMsg : m));
    showSuccess('Vote recorded!');

    const targetDocId = targetMsg.docId || targetMsg.id;
    if (targetDocId) {
      try {
        await updateDoc(doc(db, 'community-messages', targetDocId), {
          poll: updatedPoll
        });
      } catch (e) {
        console.error('Failed to update college poll vote:', e);
      }
    }
  };

const handleToggleFollow = () => {
    if (!currentUser || !targetId || isOwnProfile) return;

    const currentFollowing = Array.isArray(currentUser.following) ? currentUser.following : [];
    const targetFollowers = Array.isArray(profileUser?.followers) ? profileUser.followers : [];

    const currentlyFollowing = currentFollowing.includes(targetId);
    let nextFollowing = [...currentFollowing];
    let nextFollowers = [...targetFollowers];

    if (currentlyFollowing) {
      nextFollowing = nextFollowing.filter(id => id !== targetId);
      nextFollowers = nextFollowers.filter(id => id !== currentUser.uid);
      showSuccess(`Unfollowed @${profileUser?.username || profileUser?.name || 'user'}`);
    } else {
      nextFollowing.push(targetId);
      if (currentUser.uid && !nextFollowers.includes(currentUser.uid)) {
        nextFollowers.push(currentUser.uid);
      }
      showSuccess(`Now following @${profileUser?.username || profileUser?.name || 'user'}!`);
    }

    // 1. INSTANT 0ms OPTIMISTIC UI UPDATE
    setProfileUser(prev => prev ? ({ ...prev, followers: nextFollowers }) : { uid: targetId, followers: nextFollowers });
    updateUser({ following: nextFollowing });

    // 2. BACKGROUND FIRESTORE SYNC (non-blocking)
    const tasks = [
      setDoc(doc(db, 'users', currentUser.uid), { following: nextFollowing }, { merge: true }),
      setDoc(doc(db, 'users', targetId), { followers: nextFollowers }, { merge: true })
    ];

    if (!currentlyFollowing) {
      tasks.push(
        addDoc(collection(db, 'notifications'), {
          recipientUid: targetId,
          senderUid: currentUser.uid,
          senderName: currentUser.name || 'Student',
          senderAvatar: currentUser.avatar || '',
          type: 'follow',
          text: 'started following you.',
          read: false,
          time: new Date(),
          createdAt: new Date().toISOString()
        })
      );
    }

    Promise.all(tasks).catch(err => console.error('Error syncing follow state:', err));
  };

const isMutual = (uId) => {
    const myFollowing = currentUser?.following || [];
