  };

  const handleInitiateReplyToComment = (c, postId) => {
    const name = c.anonymousName || 'Anonymous';
    setReplyingToComment({
      commentId: c.id,
      authorUid: c.authorUid,
      author: name,
      parentId: c.parentId || c.id
