                              >
                                <Trash2 className="w-3.5 h-3.5" /> Delete Post
                              </button>
                            </div>
                          )}
                        </div>
                      )}
                    </div>

                    {/* Post Content / Thoughts & Embedded Preview */}
                    {post.thought && (
                      <p className="text-neutral-900 dark:text-zinc-100 text-sm font-semibold leading-relaxed">
                        <FormattedText text={post.thought} />
