const performSearch = async () => {
      if (!debouncedQuery.trim()) {
        setPeopleResults([]);
        setPostsResults([]);
        return;
      }

      setLoading(true);
      const rawTerm = debouncedQuery.trim().toLowerCase();
      const cleanTerm = rawTerm.replace(/^[@#]/, '').trim();
      const isHashtagSearch = rawTerm.startsWith('#');

      try {
        // Search Students / Users (skip if purely searching a hashtag)
        if (!isHashtagSearch) {
          const usersSnap = await getDocs(collection(db, 'users'));
          const foundPeople = [];
          let addedCohort = false;

          usersSnap.forEach(d => {
            const data = d.data();
            const nameMatch = data.name && data.name.toLowerCase().includes(cleanTerm);
            const usernameMatch = data.username && data.username.toLowerCase().includes(cleanTerm);
            const collegeMatch = data.college && data.college.toLowerCase().includes(cleanTerm);

            if (nameMatch || usernameMatch || collegeMatch) {
              const isCohortAccount =
                d.id === 'cohort_official' ||
                (data.username || '').toLowerCase() === 'cohort' ||
                (data.name || '').toLowerCase() === 'cohort' ||
                data.isOfficial === true;

              if (isCohortAccount) {
                if (!addedCohort) {
                  addedCohort = true;
                  foundPeople.push({
                    id: 'cohort_official',
                    uid: 'cohort_official',
                    name: 'Cohort',
                    username: 'cohort',
                    college: 'Cohort Official Platform',
                    isOfficial: true,
                    bio: data.bio || 'The official Cohort platform account. Connecting students across campuses.',
                    avatar: data.avatar || 'https://ui-avatars.com/api/?name=Cohort&background=9333ea&color=fff&bold=true&size=128'
                  });
                }
              } else {
                foundPeople.push({ id: d.id, uid: d.id, ...data });
              }
            }
          });
          setPeopleResults(foundPeople);
        } else {
          setPeopleResults([]);
        }

        // Search Feed Posts for matching content or hashtag
        const postsSnap = await getDocs(collection(db, 'posts'));
        const foundPosts = [];
        postsSnap.forEach(d => {
          const data = d.data();
          const content = (data.content || '').toLowerCase();
          const authorName = (data.author?.name || '').toLowerCase();

          const contentMatch = content.includes(rawTerm) || content.includes(cleanTerm);
          const authorMatch = authorName.includes(cleanTerm);

          if (contentMatch || authorMatch) {
            foundPosts.push({ id: d.id, docId: d.id, ...data });
          }
        });
        setPostsResults(foundPosts);
      } catch (err) {
        console.error('Search error:', err);
      } finally {
        setLoading(false);
      }
    };

const verifyEmailMatchesCollege = (email, collegeName, universityName = '') => {
  if (!email || !collegeName) return false;
  const domain = email.trim().toLowerCase().split('@')[1];
  if (!domain) return false;

  // Custom dictionary matching substring of college name to allowed domain bases / full domains
  const COLLEGE_DOMAIN_OVERRIDES = {
    'kiet': ['kiet.edu', 'kiet.ac.in'],
    'abes': ['abes.ac.in'],
    'ims': ['imsec.ac.in', 'ims.ac.in'],
    'bits pilani': ['bits-pilani.ac.in', 'bits-goa.ac.in', 'bits-hyderabad.ac.in'],
    'iit bombay': ['iitb.ac.in'],
    'iit delhi': ['iitd.ac.in'],
    'delhi university': ['du.ac.in', 'dse.du.ac.in'],
    'delhi school of economics': ['dse.du.ac.in', 'du.ac.in'],
    'christ university': ['christuniversity.in', 'christuniversity.edu.in'],
    'vit vellore': ['vit.ac.in', 'vitstudent.ac.in', 'vit.edu'],
    'manipal': ['manipal.edu', 'mahe.edu'],
    'ashoka university': ['ashoka.edu.in'],
    'srm': ['srmist.edu.in', 'srmuniv.ac.in'],
    'galgotias': ['galgotiasuniversity.edu.in', 'galgotiascolleges.edu', 'galgotias.edu.in'],
    'maseno': ['maseno.ac.ke'],
  };

  const collegeLower = collegeName.toLowerCase();
  const universityLower = universityName ? universityName.toLowerCase() : '';

  // Check explicit overrides dictionary
  for (const [key, domains] of Object.entries(COLLEGE_DOMAIN_OVERRIDES)) {
    if (collegeLower.includes(key) || universityLower.includes(key)) {
      if (domains.includes(domain) || domains.some(d => domain.endsWith(d))) {
        return true;
      }
    }
  }

  // Fallback Heuristics:
  // Extract base domain name: e.g. "kiet.edu" -> "kiet", "bits-pilani.ac.in" -> "bits-pilani"
  // Remove extensions (.edu, .ac.in, .edu.in, .edu.co, .ac.uk, .com, .org, etc.)
  const baseDomain = domain.replace(/(\.edu|\.ac|\.res|\.org|\.com|\.co)?(\.[a-z]{2,3})*$/g, '');
  if (!baseDomain) return false;

  // 1. Check if base domain is a direct substring of the college or university name
  // E.g., "kiet" in "KIET Group of Institutions"
  if (collegeLower.includes(baseDomain) || universityLower.includes(baseDomain)) {
    return true;
  }

  // 2. Check if the college or university name contains the base domain as an acronym / initials
  // E.g. "iitd" for "Indian Institute of Technology Delhi"
  const getInitials = (str) => {
    const fillerWords = ['of', 'and', 'the', 'for', 'in', 'at', 'on', 'a', 'an', 'to', 'group', 'institutions'];
    return str
      .replace(/[^a-zA-Z\s]/g, '') // remove punctuation
      .split(/\s+/)
      .map(word => word.trim().toLowerCase())
      .filter(word => word.length > 0 && !fillerWords.includes(word))
      .map(word => word[0])
      .join('')
      .toLowerCase();
  };

  const collegeInitials = getInitials(collegeName);
  const universityInitials = universityName ? getInitials(universityName) : '';

  if (baseDomain === collegeInitials || (universityName && baseDomain === universityInitials)) {
    return true;
  }

  // 3. For dashed domains like "bits-pilani", check if all components are found in college/university name
  if (baseDomain.includes('-')) {
    const parts = baseDomain.split('-');
    const matchedAll = parts.every(part => part.length > 2 && (collegeLower.includes(part) || universityLower.includes(part)));
    if (matchedAll) return true;
  }

  return false;
};

export const UserAvatar = ({
  src,
  name = 'Student',
  className = 'w-8 h-8 rounded-full',
  alt
}) => {
  const [hasError, setHasError] = useState(false);

  const fallbackUrl = `https://ui-avatars.com/api/?name=${encodeURIComponent(name || 'Student')}&background=0ea5e9&color=fff&bold=true&size=128`;

  // Check if src is invalid or a broken dicebear URL
  const isValidSrc = src && typeof src === 'string' && src.trim().length > 0 && !src.includes('dicebear.com');
  const imageSrc = !hasError && isValidSrc ? src : fallbackUrl;

  return (
    <img
      src={imageSrc}
      alt={alt || name || 'User avatar'}
      className={`object-cover rounded-full flex-shrink-0 ${className}`}
      referrerPolicy="no-referrer"
      onError={(e) => {
        if (!hasError) {
          setHasError(true);
          e.currentTarget.src = fallbackUrl;
        }
      }}
    />
  );
};

