async function handler(req, res) {
  try {
    const { q } = req.query || {};
    if (!q) {
      res.setHeader('Content-Type', 'application/json');
      return res.status(200).json(POPULAR_COLLEGES);
    }

    const cleanQuery = q.trim().toLowerCase();
    if (cleanQuery.length < 2) {
      res.setHeader('Content-Type', 'application/json');
      return res.status(200).json(POPULAR_COLLEGES);
    }

    const results = [];
    const cleanIdRegex = /\s*\(Id:\s*[^)]+\)/gi;

    for (let i = 0; i < colleges.length; i++) {
      const item = colleges[i];
      const collegeNameRaw = item.college || '';
      const universityNameRaw = item.university || '';

      const collegeName = collegeNameRaw.replace(cleanIdRegex, '').trim();
      const universityName = universityNameRaw.replace(cleanIdRegex, '').trim();

      const state = item.state || '';
      const district = item.district || '';

      if (
        collegeName.toLowerCase().includes(cleanQuery) ||
        universityName.toLowerCase().includes(cleanQuery) ||
        state.toLowerCase().includes(cleanQuery) ||
        district.toLowerCase().includes(cleanQuery)
      ) {
        results.push({
          name: collegeName,
          university: universityName,
          state,
          district,
          location: district ? `${district}, ${state}` : state
        });

        if (results.length >= 50) {
          break;
        }
      }
    }

    res.setHeader('Content-Type', 'application/json');
    res.setHeader('Cache-Control', 's-maxage=86400, stale-while-revalidate=3600');
    return res.status(200).json(results);
  } catch (error) {
    console.error('Search colleges error:', error);
    return res.status(500).json({ error: 'Internal Server Error' });
  }
}

function useCountUp(target, duration = 2000, startOnView = true) {
  const [count, setCount] = useState(0);
  const [hasStarted, setHasStarted] = useState(false);
  const ref = useRef(null);

  const startCounting = useCallback(() => {
    if (hasStarted) return;
    setHasStarted(true);

    const startTime = performance.now();

    const step = (currentTime) => {
      const elapsed = currentTime - startTime;
      const progress = Math.min(elapsed / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      setCount(Math.floor(eased * target));

      if (progress < 1) {
        requestAnimationFrame(step);
      } else {
        setCount(target);
      }
    };

    requestAnimationFrame(step);
  }, [target, duration, hasStarted]);

  useEffect(() => {
    if (!startOnView || !ref.current) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          startCounting();
          observer.disconnect();
        }
      },
      { threshold: 0.1 }
    );

    observer.observe(ref.current);
    return () => observer.disconnect();
  }, [startOnView, startCounting]);

  return { count, ref };
}

function SEO({ title, description, image, type = 'website', noindex = false }) {
  const location = useLocation();

  // Enforce cohortnow.online as the preferred canonical domain
  const canonicalUrl = `https://www.cohortnow.online${location.pathname}`;

  useEffect(() => {
    // Helper utility to safely manage meta elements
    const updateMetaTag = (attribute, value, content) => {
      let element = document.querySelector(`meta[${attribute}="${value}"]`);
      if (!element) {
        element = document.createElement('meta');
        element.setAttribute(attribute, value);
        document.head.appendChild(element);
      }
      element.setAttribute('content', content);
    };

    // Helper utility to safely manage link elements
    const updateLinkTag = (rel, href) => {
      let element = document.querySelector(`link[rel="${rel}"]`);
      if (!element) {
        element = document.createElement('link');
        element.setAttribute('rel', rel);
        document.head.appendChild(element);
      }
      element.setAttribute('href', href);
    };

    // 1. Update document title (only when provided or on homepage)
    if (title || location.pathname === '/') {
      const defaultTitle = 'Cohort - Your Campus Social Media';
      const formattedTitle = title ? `${title} | Cohort` : defaultTitle;
      const finalTitle = location.pathname === '/' ? defaultTitle : formattedTitle;
      document.title = finalTitle;

      updateMetaTag('property', 'og:title', finalTitle);
      updateMetaTag('name', 'twitter:title', finalTitle);
    }

    // 2. Robots Indexing (Noindex private routes to protect sensitive student dashboard spaces)
    if (noindex) {
      updateMetaTag('name', 'robots', 'noindex, nofollow');
    } else {
      updateMetaTag('name', 'robots', 'index, follow');
    }

    // 3. Update description (only when provided or on homepage)
    if (description || location.pathname === '/') {
      const defaultDesc = 'Cohort is the social media for campus. A student community platform connecting college students with their campus communities, events, confessions, gossip, making friends, anonymous talks, and unfiltered takes.';
      const finalDesc = description || defaultDesc;
      updateMetaTag('name', 'description', finalDesc);
      updateMetaTag('property', 'og:description', finalDesc);
      updateMetaTag('name', 'twitter:description', finalDesc);
    }

    // 4. Update Canonical Link
    updateLinkTag('canonical', canonicalUrl);

    // 5. Open Graph Meta Tags
    updateMetaTag('property', 'og:url', canonicalUrl);
    updateMetaTag('property', 'og:type', type);
    updateMetaTag('property', 'og:site_name', 'Cohort');

    const defaultImage = 'https://cohortnow.online/og-image.png';
    const finalImage = image || defaultImage;
    updateMetaTag('property', 'og:image', finalImage);

    // 6. Twitter Card Meta Tags
    updateMetaTag('name', 'twitter:card', 'summary_large_image');
    updateMetaTag('name', 'twitter:image', finalImage);

  }, [title, description, image, type, noindex, location.pathname, canonicalUrl]);

  return null;
}

const handlePostJobSubmit = async (e) => {
    e.preventDefault();
    if (!newJob.company.trim() || !newJob.role.trim() || !newJob.desc.trim()) return;

    const bgColors = ['bg-red-500', 'bg-orange-500', 'bg-blue-600', 'bg-purple-600', 'bg-emerald-600'];
    const randomBg = bgColors[Math.floor(Math.random() * bgColors.length)];

    const jobData = {
      company: newJob.company.trim(),
      role: newJob.role.trim(),
      type: newJob.type,
      location: newJob.location.trim() || 'On-Campus / Remote',
      ctc: newJob.ctc.trim() || 'Best in Industry',
      minCgpa: Number(newJob.minCgpa) || 7.0,
      deadline: newJob.deadline || new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
      desc: newJob.desc.trim(),
      logoText: newJob.company.charAt(0).toUpperCase(),
      logoBg: randomBg,
      applied: false,
      postedBy: user?.name || user?.email?.split('@')[0] || 'Placement Cell',
      createdAt: new Date().toISOString()
    };

    try {
      const docRef = await addDoc(collection(db, 'placements'), jobData);
      const withId = { id: docRef.id, docId: docRef.id, ...jobData };
      setJobs([withId, ...jobs]);
      setIsPostJobOpen(false);
      setNewJob({ company: '', role: '', type: 'Full-Time', location: '', ctc: '', minCgpa: '7.0', deadline: '', desc: '' });
      showSuccess(`Drive for "${jobData.company}" posted successfully!`);
    } catch (e) {
      console.error('Failed to post placement drive:', e);
    }
  };

