const handleDeleteMsgForMe = async (msgId) => {
    if (!user?.uid || !msgId) return;
    const targetColl = isCollegeRoom ? 'community-messages' : `userCommunities/${selectedRoom.id}/messages`;
    try {
      await updateDoc(doc(db, targetColl, msgId), {
        deletedFor: arrayUnion(user.uid)
      });
      showSuccess('Message deleted for you 🗑️');
      setMsgToDeleteModal(null);
    } catch (e) { console.error(e); }
  };

const handleMarkAsRead = async (id) => {
    setList(prev => prev.map(notif => {
      if (notif.id === id) return { ...notif, read: true };
      return notif;
    }));

    const target = list.find(n => n.id === id);
    if (target && target.docId) {
      try {
        const docRef = doc(db, 'notifications', target.docId);
        await updateDoc(docRef, { read: true });
      } catch (e) {
        console.error('Failed to update read status:', e);
      }
    }
  };

export default function ScrollReveal({
  children,
  direction = 'up',
  delay = 0,
  duration = 0.6,
  className = '',
  once = true,
  threshold = 0.15,
}) {
  const variants = directionVariants[direction] || directionVariants.up;

  return (
    <motion.div
      initial="hidden"
      whileInView="visible"
      viewport={{ once, amount: threshold }}
      variants={{
        hidden: variants.hidden,
        visible: {
          ...variants.visible,
          transition: {
            duration,
            delay,
            ease: [0.25, 0.46, 0.45, 0.94],
          },
        },
      }}
      className={className}
    >
      {children}
    </motion.div>
  );
}

const handleGoogleVerify = async () => {
    setIsGoogleLoading(true);
    try {
      await loginWithGoogle();
      showSuccess('Google identity verified!');
      setForgotStep(2);
    } catch (err) {
      console.error(err);
      showError(err.message || 'Google verification failed. Please try again.');
    } finally {
      setIsGoogleLoading(false);
    }
  };

const handleChangePasswordSubmit = async (e) => {
    e.preventDefault();

    if (!oldPassword) {
      showError('Please enter your current (old) password.');
      return;
    }

    if (!newPassword || newPassword.length < 6) {
      showError('New password must be at least 6 characters long.');
      return;
    }

    if (newPassword !== confirmPassword) {
      showError('New password and confirm password do not match.');
      return;
    }

    setIsChangingPass(true);
    try {
      if (user?.email) {
        try {
          await login(user.email, oldPassword);
        } catch (authErr) {
          showError('Incorrect old password. If you forgot your password, click "Forgot old password?"');
          setIsChangingPass(false);
          return;
        }
      }

      await setPasswordForUser(newPassword);
      showSuccess('Password updated successfully! You can now log in using your new password.');
      setOldPassword('');
      setNewPassword('');
      setConfirmPassword('');
      setIsPasswordFormOpen(false);
    } catch (err) {
      console.error(err);
      showError(err.message || 'Failed to update password. Please try again.');
    } finally {
      setIsChangingPass(false);
    }
  };

