  const [submitSuccess, setSubmitSuccess] = useState(false);

  // New form configuration states
  const [submissionType, setSubmissionType] = useState('short'); // 'short' or 'long'
  const [isAnonymous, setIsAnonymous] = useState(true);
  const [authorName, setAuthorName] = useState('');

  // Newsletter state
  const [email, setEmail] = useState('');
  const [subscribed, setSubscribed] = useState(false);

  const handleShareStory = (article, e) => {
    if (e) e.stopPropagation();
    setSelectedShareStory({
      id: article.id,
      title: article.title,
      content: article.excerpt || article.content,
      text: article.excerpt || article.content,
      caption: article.title,
      author: { name: article.author },
      authorName: article.author,
      image: article.image || 'https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?q=80&w=800&auto=format&fit=crop'
    });
    setIsShareModalOpen(true);
  };

  // Auto scroll to form if link contains #submit-story-form or ?submit=true
  useEffect(() => {
    if (window.location.hash === '#submit-story-form' || window.location.search.includes('submit=true')) {
      const timer = setTimeout(() => {
        const el = document.getElementById('submit-story-form');
        if (el) {
          el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 250);
      return () => clearTimeout(timer);
    }
  }, []);

  // Handle claps
  const handleClap = async (id, e) => {
    e.stopPropagation();

    // Prevent excessive clapping or track locally
    const currentClaps = clappedArticles[id] || 0;
    if (currentClaps >= 10) return; // Cap at 10 claps per session

    setClappedArticles(prev => ({
      ...prev,
      [id]: currentClaps + 1
    }));

    try {
      const docRef = doc(db, 'uncutClaps', id);
      await setDoc(docRef, { count: increment(1) }, { merge: true });
    } catch (err) {
      console.error("Failed to update clap in Firestore:", err);
    }
  };

  // Submit anonymous story
  const handleSubmitStory = async (e) => {
    e.preventDefault();
    if (!draftTitle || !draftContent) return;

    setIsSubmittingStory(true);

    try {
      // 1. Log submission to database
      const submissionData = {
        title: draftTitle,
        category: draftCategory,
        content: draftContent,
        format: submissionType,
        isAnonymous: isAnonymous,
        author: isAnonymous ? 'Anonymous' : authorName,
        createdAt: serverTimestamp()
      };

      await addDoc(collection(db, 'uncutSubmissions'), submissionData);

      // 2. Send email in the background via Formsubmit AJAX endpoint (Zero setup, no key required)
      try {
        await fetch('https://formsubmit.co/ajax/cohortnow.online@gmail.com', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json'
          },
          body: JSON.stringify({
            _subject: `Cohort Uncut Draft: ${draftTitle}`,
            Title: draftTitle,
            Category: draftCategory,
            Format: submissionType === 'short' ? 'Short Story / Vibe Message' : 'Full Article / Long Story',
            Author: isAnonymous ? 'Anonymous' : authorName,
            Content: draftContent
          })
        });
      } catch (mailErr) {
        console.error("Email dispatch error:", mailErr);
      }

      setIsSubmittingStory(false);
      setSubmitSuccess(true);
      setDraftTitle('');
      setDraftContent('');
      setAuthorName('');
      setIsAnonymous(true);
      setSubmissionType('short');

      setTimeout(() => {
        setSubmitSuccess(false);
      }, 7000);
    } catch (err) {
      console.error("Error submitting uncut draft:", err);
      setIsSubmittingStory(false);
    }
  };

