export const UserAvatar = ({
  src,
  name = 'Student',
  className = 'w-8 h-8 rounded-full',
  alt
}) => {
  const [hasError, setHasError] = useState(false);

  const fallbackUrl = `https://ui-avatars.com/api/?name=${encodeURIComponent(name || 'Student')}&background=0ea5e9&color=fff&bold=true&size=128`;

  // Check if src is invalid or a broken dicebear URL
  const isValidSrc = src && typeof src === 'string' && src.trim().length > 0 && !src.includes('dicebear.com');
  const imageSrc = !hasError && isValidSrc ? src : fallbackUrl;

  return (
    <img
      src={imageSrc}
      alt={alt || name || 'User avatar'}
      className={`object-cover rounded-full flex-shrink-0 ${className}`}
      referrerPolicy="no-referrer"
      onError={(e) => {
        if (!hasError) {
          setHasError(true);
          e.currentTarget.src = fallbackUrl;
        }
      }}
    />
  );
};

const handleDeleteAccount = async () => {
    const confirmation = window.confirm(
      "WARNING: Are you sure you want to permanently delete your Cohort profile and account? This action is irreversible."
    );
    if (!confirmation) return;

    setIsDeleting(true);
    try {
      if (user?.uid) {
        // 1. Delete from Firestore users collection
        const userRef = doc(db, 'users', user.uid);
        await deleteDoc(userRef);
      }

      // 2. Delete from Firebase Auth
      const currentUser = auth.currentUser;
      if (currentUser) {
        await currentUser.delete();
      }

      // 3. Logout & redirect
      await logout();
      showSuccess('Your account was successfully deleted.');
      navigate('/');
    } catch (err) {
      console.error('Failed to delete account:', err);
      // Fallback: If delete requires re-login, log out anyway after deleting Firestore doc
      await logout();
      showSuccess('Your profile was removed.');
      navigate('/');
    } finally {
      setIsDeleting(false);
    }
  };

