const getRemainingTimeStr = (expiresAtMs) => {
    const diffSec = Math.max(0, Math.floor((expiresAtMs - Date.now()) / 1000));
    const hours = Math.floor(diffSec / 3600);
    const mins = Math.floor((diffSec % 3600) / 60);
    if (hours > 0) return `${hours}h ${mins}m left`;
    return `${mins}m left`;
  };

export const predictGenderFromName = (email) => {
  if (!email || typeof email !== 'string') return 'Neutral';

  const username = email.trim().toLowerCase().split('@')[0];
  if (!username) return 'Neutral';

  // Extract first name (split by dot, underscore, hyphen or numbers)
  const firstName = username.split(/[\._\-0-9]/)[0];
  if (!firstName || firstName.length < 2) return 'Neutral';

  const MALE_NAMES = new Set([
    'rahul', 'amit', 'abhishek', 'kushal', 'rohit', 'sachin', 'mohit', 'raj', 'deepak', 'sandeep',
    'sunil', 'anil', 'vishal', 'nikhil', 'karan', 'arjun', 'aakash', 'aditya', 'gaurav', 'manish',
    'vivek', 'harsh', 'ankit', 'ritesh', 'vikram', 'saurabh', 'pranav', 'shubham', 'rishabh', 'kartik',
    'madhav', 'varun', 'rishi', 'dev', 'raghav', 'kabir', 'yash', 'abhay', 'dhruv', 'sid',
    'siddharth', 'ayush', 'hardik', 'priyansh', 'aman', 'ritik', 'shiv', 'shivam', 'shubham', 'vijay',
    'ajay', 'sanjay', 'ram', 'shyam', 'aravind', 'anuj', 'mayank', 'prateek', 'tushar', 'gaurav',
    'rohan', 'kunal', 'pankaj', 'suresh', 'ramesh', 'dinesh', 'harish', 'mahesh', 'naresh', 'lokesh',
    'rakesh', 'vikas', 'vinay', 'ashok', 'alok', 'atul', 'arun', 'saurav', 'tarun', 'varun', 'gautam',
    'ravi', 'hari', 'shiva', 'sameer', 'aman', 'sahil', 'jatin'
  ]);

  const FEMALE_NAMES = new Set([
    'priya', 'sneha', 'neha', 'anjali', 'pooja', 'ritu', 'kavita', 'aarushi', 'shruti', 'aditi',
    'kirti', 'divya', 'pragya', 'preeti', 'swati', 'shreya', 'megha', 'tisha', 'tanvi', 'ishita',
    'ananya', 'disha', 'riya', 'rhea', 'khushi', 'muskan', 'sakshi', 'shalini', 'shivani', 'nisha',
    'jyoti', 'komal', 'pinky', 'sonal', 'payal', 'sheetal', 'kajal', 'rashmi', 'nishi', 'sonam',
    'renu', 'sapna', 'mamta', 'babita', 'gauri', 'diksha', 'rashi', 'taniya', 'anushka', 'deepika',
    'aliya', 'katrina', 'kareena', 'sushma', 'radha', 'aanchal', 'sweta', 'shweta', 'monika', 'mansi',
    'hema', 'rekha', 'jaya', 'sushmita', 'sunita', 'anita', 'geeta', 'seema', 'meena', 'asha',
    'lata', 'pallavi', 'poonam', 'prerna', 'richa', 'ridhima', 'shikha', 'tanu', 'diksha', 'alka'
  ]);

  const UNISEX_NAMES = new Set([
    'suman', 'krishna', 'kiran', 'simran', 'harpreet', 'gurpreet', 'jaspreet', 'simar', 'kripa', 'preet',
    'deep', 'sunny', 'bobby', 'ryan', 'taylor', 'alex', 'sam', 'robin'
  ]);

  // 1. Unisex overrides
  if (UNISEX_NAMES.has(firstName)) {
    return 'Neutral';
  }

  // 2. Direct Male names
  if (MALE_NAMES.has(firstName)) {
    return 'Male';
  }

  // 3. Direct Female names
  if (FEMALE_NAMES.has(firstName)) {
    return 'Female';
  }

  // 4. Suffix-based heuristics for typical Indian names
  if (firstName.endsWith('esh') || firstName.endsWith('ish') || firstName.endsWith('endra') || firstName.endsWith('jeet') || firstName.endsWith('preet') || firstName.endsWith('meet')) {
    return 'Male';
  }
  if (firstName.endsWith('ank') || firstName.endsWith('it') || firstName.endsWith('ant') || firstName.endsWith('eep') || firstName.endsWith('eet') || firstName.endsWith('ath') || firstName.endsWith('dev') || firstName.endsWith('raj')) {
    return 'Male';
  }
  if (firstName.endsWith('av') || firstName.endsWith('am') || firstName.endsWith('an') || firstName.endsWith('al') || firstName.endsWith('ar') || firstName.endsWith('ur') || firstName.endsWith('ut')) {
    return 'Male';
  }
  if (firstName.endsWith('ika') || firstName.endsWith('isha') || firstName.endsWith('anya') || firstName.endsWith('iti') || firstName.endsWith('ini') || firstName.endsWith('eta') || firstName.endsWith('iya') || firstName.endsWith('ee')) {
    return 'Female';
  }
  if (firstName.endsWith('a') || firstName.endsWith('i')) {
    return 'Female';
  }

  return 'Neutral';
};

export default function Search() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const inputRef = useRef(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [activeTab, setActiveTab] = useState('All');
  const [loading, setLoading] = useState(false);

  const [peopleResults, setPeopleResults] = useState([]);
  const [postsResults, setPostsResults] = useState([]);

  // Cmd+K / Ctrl+K keyboard shortcut listener
  useEffect(() => {
    const handleKeyDown = (e) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault();
        inputRef.current?.focus();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  // Read URL query parameter e.g. ?q=%23Cohort or ?hashtag=Cohort
  useEffect(() => {
    const qParam = searchParams.get('q') || searchParams.get('hashtag');
    if (qParam) {
      const decoded = decodeURIComponent(qParam);
      setSearchTerm(decoded);
      if (decoded.startsWith('#')) {
        setActiveTab('Posts');
      }
    }
  }, [searchParams]);

  // Search History State (persisted in localStorage)
  const [searchHistory, setSearchHistory] = useState(() => {
    try {
      const saved = localStorage.getItem('cohort_search_history');
      return saved ? JSON.parse(saved) : ['#Cohort', '#CampusLife', '@student', 'KIET'];
    } catch (e) {
      return ['#Cohort', '#CampusLife', '@student', 'KIET'];
    }
  });

  const debouncedQuery = useDebounce(searchTerm, 300);
  const tabs = ['All', 'Students', 'Posts'];

  // Add query to search history
  const addToHistory = (term) => {
    if (!term || !term.trim()) return;
    const clean = term.trim();
    setSearchHistory(prev => {
      const filtered = prev.filter(item => item.toLowerCase() !== clean.toLowerCase());
      const updated = [clean, ...filtered].slice(0, 10);
      try {
        localStorage.setItem('cohort_search_history', JSON.stringify(updated));
      } catch (e) {}
      return updated;
    });
  };

  // Remove single item from history
  const removeHistoryItem = (termToRemove, e) => {
    if (e) e.stopPropagation();
    setSearchHistory(prev => {
      const updated = prev.filter(item => item !== termToRemove);
      try {
        localStorage.setItem('cohort_search_history', JSON.stringify(updated));
      } catch (err) {}
      return updated;
    });
  };

  // Clear all search history
  const clearAllHistory = () => {
    setSearchHistory([]);
    try {
      localStorage.removeItem('cohort_search_history');
    } catch (e) {}
  };

  // Save term to history when debounced query executes
  useEffect(() => {
    if (debouncedQuery.trim().length >= 2) {
      addToHistory(debouncedQuery.trim());
    }
  }, [debouncedQuery]);

  // Perform search across Firestore users & posts
  useEffect(() => {
    const performSearch = async () => {
      if (!debouncedQuery.trim()) {
        setPeopleResults([]);
        setPostsResults([]);
        return;
      }

      setLoading(true);
      const rawTerm = debouncedQuery.trim().toLowerCase();
      const cleanTerm = rawTerm.replace(/^[@#]/, '').trim();
      const isHashtagSearch = rawTerm.startsWith('#');

      try {
        // Search Students / Users (skip if purely searching a hashtag)
        if (!isHashtagSearch) {
          const usersSnap = await getDocs(collection(db, 'users'));
          const foundPeople = [];
          let addedCohort = false;

          usersSnap.forEach(d => {
            const data = d.data();
            const nameMatch = data.name && data.name.toLowerCase().includes(cleanTerm);
            const usernameMatch = data.username && data.username.toLowerCase().includes(cleanTerm);
            const collegeMatch = data.college && data.college.toLowerCase().includes(cleanTerm);

            if (nameMatch || usernameMatch || collegeMatch) {
              const isCohortAccount =
                d.id === 'cohort_official' ||
                (data.username || '').toLowerCase() === 'cohort' ||
                (data.name || '').toLowerCase() === 'cohort' ||
                data.isOfficial === true;

              if (isCohortAccount) {
                if (!addedCohort) {
                  addedCohort = true;
                  foundPeople.push({
                    id: 'cohort_official',
                    uid: 'cohort_official',
                    name: 'Cohort',
                    username: 'cohort',
                    college: 'Cohort Official Platform',
                    isOfficial: true,
                    bio: data.bio || 'The official Cohort platform account. Connecting students across campuses.',
                    avatar: data.avatar || 'https://ui-avatars.com/api/?name=Cohort&background=9333ea&color=fff&bold=true&size=128'
                  });
                }
              } else {
                foundPeople.push({ id: d.id, uid: d.id, ...data });
              }
            }
          });
          setPeopleResults(foundPeople);
        } else {
          setPeopleResults([]);
        }

        // Search Feed Posts for matching content or hashtag
        const postsSnap = await getDocs(collection(db, 'posts'));
        const foundPosts = [];
        postsSnap.forEach(d => {
          const data = d.data();
          const content = (data.content || '').toLowerCase();
          const authorName = (data.author?.name || '').toLowerCase();

          const contentMatch = content.includes(rawTerm) || content.includes(cleanTerm);
          const authorMatch = authorName.includes(cleanTerm);

          if (contentMatch || authorMatch) {
            foundPosts.push({ id: d.id, docId: d.id, ...data });
          }
        });
        setPostsResults(foundPosts);
      } catch (err) {
        console.error('Search error:', err);
      } finally {
        setLoading(false);
      }
    };

    performSearch();
  }, [debouncedQuery]);

