                                       <div>
                                         <p className="text-[11.5px] font-bold text-white line-clamp-1 leading-tight">
                                           {msg.sharedPostData?.title || (msg.text?.split('\n')[0]?.replace(/^(📖\s*Shared Uncut Story:?|Shared post by)\s*/i, '') || 'Campus Story')}
