                                       >
                                         <span>{msg.isUncutStory || msg.sharedPostData?.url?.includes('/uncut') || msg.text?.includes('Uncut Story') ? 'Read Full Story' : 'View Post'}</span>
                                         <ArrowRight className="w-3 h-3 stroke-[2.5]" />
                                       </button>
                                     </div>
