                                         >
                                           <Users className="w-3.5 h-3.5" />
                                           <span>View Votes</span>
                                         </button>
                                       </div>
                                     </div>
                                   )}

                                   {/* Message Text (Hidden if it's a shared post or poll to prevent duplicate text) */}
