                                    >
                                      <InfinityIcon className="w-3.5 h-3.5" />
                                    </button>
                                  )}
                                  <button
                                    onClick={() => handleToggleStarMessage(msg)}
                                    className={`p-xs rounded-full hover:bg-neutral-200 dark:hover:bg-neutral-800 transition-colors ${
