          const docRef = doc(db, 'placements', targetJob.docId);
          await updateDoc(docRef, { applied: true });
        } catch (err) {
          console.error('Failed to update job application status in Firestore:', err);
        }
      }

      setApplyingJob(null);
      setResumeName('');
      setErrors({});
