        )}
      </AnimatePresence>

      {/* Apply Modal */}
      <Modal isOpen={!!applyingJob} onClose={() => setApplyingJob(null)} title={`Apply to ${applyingJob?.company}`} size="md">
        {applyingJob && (
          <form onSubmit={handleApplySubmit} className="space-y-lg">
