              value={newJob.ctc}
              onChange={(e) => setNewJob({ ...newJob, ctc: e.target.value })}
            />
            <Input
              label="Location"
              placeholder="e.g. Bangalore / Remote"
              value={newJob.location}
              onChange={(e) => setNewJob({ ...newJob, location: e.target.value })}
