    assert (
        result.output == "default: {'value': '/tmp/file', 'source': "
        f"{ParameterSource.DEFAULT!r}}}\nnodefault: None\n"
    )

    result = runner.invoke(cli, ["--default", "cli", "--nodefault", "also"])
    assert not result.exception
    assert (
        "default: {'value': 'cli', 'source': "
