void* pool_allocate(size_t size) {
    if (size == 0) {
        return NULL;
    }
    MemoryBlock* block = (MemoryBlock*)malloc(sizeof(MemoryBlock) + size);
    if (!block) {
        return NULL;
    }
    block->size = size;
    block->is_free = 0;
    block->next = NULL;
    return (void*)(block + 1);
}

