            items_list.erase(it->second);
            item_map.erase(it);
        }
        if (items_list.size() >= capacity) {
            auto oldest = items_list.back();
            item_map.erase(oldest.first);
            items_list.pop_back();
        }
        items_list.push_front({key, value});
        item_map[key] = items_list.begin();
    }
